VALUES ('138832ad-b064-4d52-8b7e-8a7ab9f0a47d', 'ALG.05', 1, 'numeric', 'Solve a system of three equations', 'Three numbers satisfy $x+y+z=10$. If $x=2$ and $y=3$, what is $z$?', '[]', '5', '10-2-3', '$2+3+z=10$, so $z=5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"z=10-2-3=5","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
