INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0af98f72-fbc5-4052-a089-f7cb82332730', 'ALG.05', 2, 'numeric', 'Word problem leading to a system: money and mixtures', 'Dina has 20 coins, all nickels and dimes, worth 140 cents. How many dimes does she have?', '[]', '8', '(140-5*20)/(10-5)', '$n+d=20$ and $5n+10d=140$. Multiply the first by 5: $5n+5d=100$. Subtract: $5d=40$, so $d=8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n+d=20, 5n+10d=140; 5d=40, d=8","run_id":"claude-code","at":"2026-10-19T07:04:01.247Z"}}', 'ai', NULL, NULL)
