INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0124d52d-61f5-406d-ad83-065351d39c8c', 'ALG.06', 1, 'choice', 'Percent increase and decrease', 'A price goes up from 50 dollars to 60 dollars. By what percent did it increase?', '["20%","10%","16.7%","120%"]', '20%', NULL, 'The price went up by 10 dollars. Compared with the starting price, $\frac{10}{50} = 20\%$.', 'checked', '{"lint":[],"solve":{"answer":"20%","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Increase 10 on 50: 10/50 = 20%.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
