INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('037b5ea5-1f57-4442-aca3-55219577f5de', 'ALG.06', 2, 'numeric', 'Mixture problems', 'Nuts that cost 4 dollars per kilogram are mixed with other nuts that cost 9 dollars per kilogram: 3 kg of the first and 2 kg of the second. What is the cost of the mixture per kilogram, in dollars?', '[]', '6', '(3*4+2*9)/5', 'The total cost is $3 \times 4 + 2 \times 9 = 12 + 18 = 30$ dollars for 5 kg. That is $30 \div 5 = 6$ dollars per kilogram.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3*4 + 2*9 = 30 dollars for 5 kg: 6 per kg.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a9c36c5-5f44-4cf6-abca-aaf926b28c48', 'ALG.06', 2, 'numeric', 'Mixture problems', 'A punch is 35% juice. How many liters of juice are in 8 liters of this punch?', '[]', '2.8', '8*0.35', '35% of 8 is $0.35 \times 8 = 2.8$ liters.', 'checked', '{"lint":[],"solve":{"answer":"2.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.35*8 = 2.8.","run_id":"claude-code","at":"2026-10-19T01:41:49.373Z"}}', 'ai', NULL, NULL)
