VALUES ('01c55970-1c6b-4f57-85f6-0c803bf4cdea', 'ALG.08', 2, 'numeric', 'Point-slope form', 'The line $y+4=3(x-2)$ crosses the $y$-axis at $(0, b)$. What is $b$?', '[]', '-10', '3*(0-2)-4', 'Put $x=0$: $y+4=3(-2)=-6$, so $y=-10$.', 'checked', '{"lint":[],"solve":{"answer":"-10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y=3x-6-4=3x-10, b=-10","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
