INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02a4ea26-01a2-462d-9cc1-dbdbbb4c9c1b', 'ALG.08', 2, 'choice', 'Using a line: points on it, horizontal and vertical lines, rates', 'Two points on a line are $(4, -1)$ and $(4, 9)$. What is the equation of the line?', '["$y=4$","$x=4$","$y=4x$","$x=9$"]', '$x=4$', NULL, 'Both points have $x=4$, so the line is vertical and its equation is $x=4$.', 'checked', '{"lint":[],"solve":{"answer":"$x=4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"same x=4: vertical line x=4","run_id":"claude-code","at":"2026-10-19T07:04:01.283Z"}}', 'ai', NULL, NULL)
