INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2043f142-a5ac-43b6-8bfd-a1c5e9a4ccbc', 'ALG.09', 1, 'choice', 'Absolute value inequalities', 'The solutions of $|x|<3$ are the numbers less than 3 units from $0$. Which inequality without absolute value says the same thing?', '["$-3<x<3$","$x<3$","$x<-3$ or $x>3$","$0<x<3$"]', '$-3<x<3$', NULL, '$|x|$ is the distance from $0$. A distance less than $3$ means $x$ is between $-3$ and $3$.', 'checked', '{"lint":[],"solve":{"answer":"$-3<x<3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-3<x<3","run_id":"claude-code","at":"2026-10-19T07:04:01.319Z"}}', 'ai', NULL, NULL)
