INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('061308a1-9d92-4370-b526-cca6571d13ca', 'ALG.09', 2, 'choice', 'Describe solutions in words and interval notation', 'A number $n$ satisfies $3<n\le 8$. Which statement is true?', '["$n$ can equal $3$ but cannot equal $8$.","$n$ can equal both $3$ and $8$.","$n$ can equal neither $3$ nor $8$.","$n$ can equal $8$ but cannot equal $3$."]', '$n$ can equal $8$ but cannot equal $3$.', NULL, 'The sign next to $3$ is $<$, so $3$ is not allowed. The sign next to $8$ is $\le$, so $8$ is allowed.', 'checked', '{"lint":[],"solve":{"answer":"$n$ can equal $8$ but cannot equal $3$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 excluded, 8 included","run_id":"claude-code","at":"2026-10-19T07:04:01.319Z"}}', 'ai', NULL, NULL)
