INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('026c6e74-4909-4489-b0b4-dc76e6cded97', 'ALG.10', 3, 'numeric', 'Counting and describing solutions', 'How many whole numbers $c$ from 1 to 20 make $x^2-9x+c=0$ have two whole-number solutions?', '[]', '4', NULL, 'We need two whole numbers adding to 9 and multiplying to $c$. The pairs are $(1,8)$, $(2,7)$, $(3,6)$, $(4,5)$ with products 8, 14, 18, 20; the pair $(0,9)$ gives $c=0$, which is outside the range. So 4 values of $c$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r+s=9, rs=c, whole numbers: (1,8)8, (2,7)14, (3,6)18, (4,5)20; (0,9) gives c=0, excluded. 4.","run_id":"claude-code","at":"2026-10-19T01:30:37.507Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0eef1b44-7807-408b-8785-586ce9980595', 'ALG.11', 1, 'choice', 'Use sum and difference of cubes', 'Which expression is equal to $(x+1)(x^2-x+1)$?', '["$x^3-1$","$x^3+3x^2+3x+1$","$x^3+1$","$x^3-x^2+x-1$"]', '$x^3+1$', NULL, 'Multiply out: $x\cdot x^2-x\cdot x+x+x^2-x+1=x^3+1$. This is the sum of cubes pattern.', 'checked', '{"lint":[],"solve":{"answer":"$x^3+1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+1)(x^2-x+1)=x^3+1.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
