VALUES ('064c3fba-efdb-458b-8af9-96fc36e7f898', 'ALG.11', 1, 'numeric', 'Factoring trick: xy + x + y + 1 = (x + 1)(y + 1)', 'Use $xy+x+y+1=(x+1)(y+1)$ to find $xy+x+y+1$ when $x=9$ and $y=19$.', '[]', '200', '10*20', '$(9+1)(19+1)=10\times20=200$. (Check: $171+9+19+1=200$.)', 'checked', '{"lint":[],"solve":{"answer":"200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10*20=200.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
