INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ee30f06-da70-48f1-9780-0e8555d0a9ad', 'ALG.11', 3, 'choice', 'Use a difference of squares to calculate', 'Which of these numbers is a factor of $87^2-83^2$?', '["19","23","29","17"]', '17', '17', '$87^2-83^2=(87-83)(87+83)=4\times170=680=2^3\times5\times17$. Of the choices, only 17 divides it.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(87-83)(87+83)=4*170=680=2^3*5*17. 17 divides; 23,29,19 do not.","run_id":"claude-code","at":"2026-10-19T01:30:37.544Z"}}', 'ai', NULL, NULL)
