VALUES ('28dcc7a8-ff80-408d-8742-fca3ef4ec463', 'ALG.12', 1, 'choice', 'Solving equations for a complex number', 'Solve $z+(2+3i)=7+5i$ for $z$.', '["$9+8i$","$5+8i$","$5+2i$","$-5-2i$"]', '$5+2i$', NULL, 'Subtract $2+3i$ from both sides: $z=(7-2)+(5-3)i=5+2i$.', 'checked', '{"lint":[],"solve":{"answer":"$5+2i$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"z=7+5i-2-3i=5+2i.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
