VALUES ('056c0d1a-cc20-45ad-bf99-4e16731bcee5', 'ALG.12', 3, 'numeric', 'Multi-step complex number expressions', 'Let $z=1+2i$. Find the value of $z^2-2z+5$.', '[]', '0', '0', '$z^2=1+4i+4i^2=-3+4i$ and $2z=2+4i$. Then $z^2-2z+5=(-3+4i)-(2+4i)+5=0$.', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"z^2=-3+4i; -2z=-2-4i; -3+4i-2-4i+5=0.","run_id":"claude-code","at":"2026-10-19T07:04:01.358Z"}}', 'ai', NULL, NULL)
