INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1889bac3-3a63-4702-8af3-7bbea609d8f2', 'ALG.13', 2, 'choice', 'Solving by completing the square', 'Complete the square to solve $x^2+4x-1=0$.', '["$x=-2\\pm\\sqrt{5}$","$x=2\\pm\\sqrt{5}$","$x=-2\\pm\\sqrt{3}$","$x=-4\\pm\\sqrt{5}$"]', '$x=-2\pm\sqrt{5}$', NULL, '$x^2+4x=1$. Add $4$ to both sides: $(x+2)^2=5$. So $x+2=\pm\sqrt5$, giving $x=-2\pm\sqrt5$.', 'checked', '{"lint":[],"solve":{"answer":"$x=-2\\pm\\sqrt{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2+4x+4=5: (x+2)^2=5, x=-2±√5.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
