INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1747dd94-06d9-4df9-ad70-861812d35201', 'ALG.13', 2, 'choice', 'Expressions in the solutions, complex solutions', 'If $r$ and $s$ are the solutions of $x^2-9x+20=0$, what is $\frac1r+\frac1s$?', '["$\\frac{9}{20}$","$\\frac{20}{9}$","$-\\frac{9}{20}$","$\\frac{1}{9}$"]', '$\frac{9}{20}$', NULL, '$\frac1r+\frac1s=\frac{r+s}{rs}=\frac{9}{20}$. (Check: the solutions are $4$ and $5$, and $\frac14+\frac15=\frac9{20}$.)', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{9}{20}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(r+s)/rs=9/20.","run_id":"claude-code","at":"2026-10-19T07:04:01.395Z"}}', 'ai', NULL, NULL)
