INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('007c01bd-0fa3-4514-9ca5-9d8df6633d77', 'ALG.16', 1, 'choice', 'Function notation and expressions like f(a+1)', 'A function $f$ takes a number, doubles it, and then adds 1. Which rule describes $f$?', '["$f(x)=2x+1$","$f(x)=2(x+1)$","$f(x)=x^2+1$","$f(x)=x+2$"]', '$f(x)=2x+1$', NULL, 'Doubling $x$ gives $2x$, and then adding 1 gives $2x+1$. The rule $2(x+1)$ would add 1 first.', 'checked', '{"lint":[],"solve":{"answer":"$f(x)=2x+1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Double then add 1: 2x+1","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
