INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('077d0bf2-24ab-4197-b57b-5c7cd370d37a', 'ALG.16', 1, 'choice', 'Evaluate a composition at a number', 'Let $f(x)=x+4$ and $g(x)=2x$. What is $f(g(5))$?', '["$18$","$19$","$14$","$9$"]', '$14$', '2*5+4', '$g(5)=10$, then $f(10)=14$. Applying them in the other order gives 18.', 'checked', '{"lint":[],"solve":{"answer":"$14$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"g(5)=10, f(10)=14","run_id":"claude-code","at":"2026-10-19T01:43:04.695Z"}}', 'ai', NULL, NULL)
