VALUES ('13e2f247-a8b4-4fff-85ed-a2c53ee3e625', 'ALG.17', 1, 'numeric', 'Lowest or highest point of a shifted graph', 'The graph of $y=|x-7|$ has its lowest point at $(a,0)$. What is $a$?', '[]', '7', NULL, '$|x-7|$ is $0$ when $x=7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"|x-7|=0 at x=7","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
