VALUES ('11dc9f8a-7689-4c7d-99df-a20d0dd9e008', 'ALG.17', 3, 'numeric', 'Find a point on a transformed graph', 'The point $(-2,6)$ is on the graph of $y=f(x)$. What is the $y$-coordinate of the point of the graph of $y=2f(-x)-3$ with $x=2$?', '[]', '9', '2*6-3', '$f(-2)=6$, so $y=2\cdot6-3=9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(-2)=6, y=2*6-3=9","run_id":"claude-code","at":"2026-10-19T01:43:04.733Z"}}', 'ai', NULL, NULL)
