INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e7aa3b4-39b6-4d3a-818b-36ea97b596c2', 'ALG.14', 1, 'choice', 'Find a maximum or minimum value', 'Which of these parabolas has a maximum value?', '["$y=x^2-4$","$y=-x^2+4$","$y=2x^2+1$","$y=(x-1)^2$"]', '$y=-x^2+4$', NULL, 'A parabola has a highest point (a maximum) when it opens downward, that is, when the number in front of $x^2$ is negative. Only $y=-x^2+4$ does.', 'checked', '{"lint":[],"solve":{"answer":"$y=-x^2+4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Negative leading coefficient opens down: -x^2+4 has max 4.","run_id":"claude-code","at":"2026-10-22T12:33:29.092Z"}}', 'ai', NULL, NULL)
