INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0244de52-c2ae-4398-9c03-74a2c9904b49', 'ALG.15', 1, 'choice', 'Test a value, and work backwards from a solution set', 'Which of these numbers is NOT a solution of $x^2-4x-5\le0$?', '["6","0","5","-1"]', '6', '6', '$x^2-4x-5=(x-5)(x+1)\le0$ for $-1\le x\le5$. The numbers 0, 5 and $-1$ are in this range; 6 is not: $36-24-5=7>0$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-5)(x+1)<=0: -1<=x<=5. 6 is outside.","run_id":"claude-code","at":"2026-10-22T12:33:29.129Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11dcf7a0-9fa4-4029-9904-ca8b48f8f5a0', 'ALG.15', 1, 'numeric', 'Test a value, and work backwards from a solution set', 'The inequality $(x-a)(x-7)<0$ has solutions $3<x<7$. What is $a$?', '[]', '3', NULL, 'The solutions lie between the roots, which are $a$ and 7. So $a=3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Solutions between the roots a and 7, so a=3.","run_id":"claude-code","at":"2026-10-22T12:33:29.129Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0abec3f9-16fc-407d-ad9f-f5d11e8629e8', 'ALG.15', 2, 'choice', 'Solve a rational inequality', 'A fraction has $x+4$ on top and $3-x$ on the bottom. For which values of $x$ is it defined and not negative?', '["$-4\\le x\\le3$","$x\\le-4$ or $x>3$","$-4\\le x<3$","$-3<x\\le4$"]', '$-4\le x<3$', NULL, 'For $-4<x<3$ the top is positive and the bottom ($3-x$) is positive, so the fraction is positive. At $x=-4$ it is 0, which counts. At $x=3$ it is undefined. For $x>3$ the bottom is negative and the top positive, so the fraction is negative. Answer: $-4\le x<3$.', 'checked', '{"lint":[],"solve":{"answer":"$-4\\le x<3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+4)/(3-x)>=0, x!=3. Both nonneg/pos: x>=-4 and x<3. Both neg: x<=-4 and x>3 impossible. So -4<=x<3.","run_id":"claude-code","at":"2026-10-22T12:33:29.129Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0de97ee1-256a-49f2-a498-c26592dca0fe', 'ALG.15', 2, 'choice', 'Inequalities that always hold, never hold or hold once', 'For how many integers $k$ from $-5$ to $5$ (including both ends) is $x^2+k\ge0$ true for every real number $x$?', '["5","11","6","7"]', '6', '6', '$x^2$ can be as small as 0, so we need $k\ge0$. The integers $0,1,2,3,4,5$ work: 6 values.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need k>=0 (take x=0). k=0..5: 6.","run_id":"claude-code","at":"2026-10-22T12:33:29.129Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0cd0afb4-5a72-430c-9b99-cab5502b3837', 'ALG.15', 2, 'numeric', 'Test a value, and work backwards from a solution set', 'The inequality $x^2+bx+c<0$ has the solutions $1<x<4$. Find $b+c$.', '[]', '-1', '-5+4', 'The roots are 1 and 4, so $x^2+bx+c=(x-1)(x-4)=x^2-5x+4$. Then $b=-5$, $c=4$, and $b+c=-1$.', 'checked', '{"lint":[],"solve":{"answer":"-1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-1)(x-4)=x^2-5x+4: b=-5, c=4, b+c=-1.","run_id":"claude-code","at":"2026-10-22T12:33:29.129Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('048275cc-c1dd-48e6-9fd3-5bbe474bcffb', 'ALG.15', 3, 'choice', 'Solve a rational inequality', 'For which values of $x$ is $\frac1x>x$?', '["$-1<x<1$","$x<-1$ or $0<x<1$","$x<-1$ or $x>1$","$0<x<1$"]', '$x<-1$ or $0<x<1$', NULL, 'Subtract $x$: $\frac{1-x^2}{x}>0$. The top is positive for $-1<x<1$ and the bottom for $x>0$. The fraction is positive when they agree: $0<x<1$ (both positive), or $x<-1$ (both negative). Check $x=-2$: $-\frac12>-2$ is true.', 'checked', '{"lint":[],"solve":{"answer":"$x<-1$ or $0<x<1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/x-x=(1-x^2)/x>0. Signs: x>1 -, 0<x<1 +, -1<x<0 -, x<-1 +. So x<-1 or 0<x<1.","run_id":"claude-code","at":"2026-10-22T12:33:29.129Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0001f1c7-620b-45bc-a049-4c021e3af02f', 'ALG.15', 3, 'choice', 'Inequalities that always hold, never hold or hold once', 'Which inequality is true for all real numbers $x$ and $y$?', '["$x^2+y^2>2xy$","$x^2+y^2\\le2xy$","$x^2-y^2\\ge0$","$x^2+y^2\\ge2xy$"]', '$x^2+y^2\ge2xy$', NULL, '$x^2+y^2-2xy=(x-y)^2\ge0$, so $x^2+y^2\ge2xy$ always. The strict version fails at $x=y$, and the other two fail for $x=1,y=0$ and $x=0,y=1$.', 'checked', '{"lint":[],"solve":{"answer":"$x^2+y^2\\ge2xy$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2+y^2-2xy=(x-y)^2>=0 always; strict fails at x=y; x^2-y^2>=0 fails (0,1); <= fails (1,0).","run_id":"claude-code","at":"2026-10-22T12:33:29.129Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('148aea1d-4926-4fb4-abae-2ee7c0ebbeb9', 'ALG.18', 1, 'choice', 'Multiplying polynomials', 'What is $(x - 2)(x + 2)$ multiplied out?', '["$x^2 + 4$","$x^2 - 2$","$x^2 - 4x + 4$","$x^2 - 4$"]', '$x^2 - 4$', NULL, 'The middle terms $-2x$ and $+2x$ cancel, leaving $x^2 - 4$.', 'checked', '{"lint":[],"solve":{"answer":"$x^2 - 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Difference of squares: x^2 - 4.","run_id":"claude-code","at":"2026-10-22T12:33:29.165Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('190012e7-c8cb-409f-a132-cce150e0a191', 'ALG.18', 1, 'choice', 'Evaluating a polynomial', 'If $p(x) = x^2 + 3x + 1$, what is $p(2)$?', '["11","9","12","8"]', '11', '2^2+3*2+1', '$p(2) = 4 + 6 + 1 = 11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"p(2) = 4 + 6 + 1 = 11.","run_id":"claude-code","at":"2026-10-22T12:33:29.165Z"}}', 'ai', NULL, NULL)
