INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2691df6e-85f8-43d2-b2b9-84162a5ae1ed', 'ALG.18', 3, 'numeric', 'The factor theorem', 'Find the sum of all numbers $k$ for which $x - k$ is a factor of $x^3 - 7x^2 + 14x - 8$.', '[]', '7', '1+2+4', 'Testing small values: the polynomial is 0 at $x = 1$ ($1 - 7 + 14 - 8$), at $x = 2$ ($8 - 28 + 28 - 8$) and at $x = 4$ ($64 - 112 + 56 - 8$). A cubic has at most 3 roots, so $k = 1, 2, 4$, and the sum is 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"p(1) = 1 - 7 + 14 - 8 = 0; dividing gives x^2 - 6x + 8 = (x-2)(x-4). Roots 1, 2, 4, so k in {1, 2, 4}, sum 7.","run_id":"claude-code","at":"2026-10-22T12:33:29.165Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('083b1f33-87c9-40b4-ba1e-cfeed5605638', 'ALG.18', 3, 'numeric', 'Roots of a polynomial', 'What is the sum of the positive roots of $x^4 - 5x^2 + 4$?', '[]', '3', '1+2', 'Factor: $x^4 - 5x^2 + 4 = (x^2 - 1)(x^2 - 4)$. The roots are $\pm 1$ and $\pm 2$. The positive ones are 1 and 2, with sum 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^4 - 5x^2 + 4 = (x^2-1)(x^2-4), roots +/-1, +/-2. Positive roots 1 and 2, sum 3.","run_id":"claude-code","at":"2026-10-22T12:33:29.165Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0995c19d-e55d-404a-94a3-345a47f3ae1c', 'ALG.19', 1, 'choice', 'Rational exponents', 'What is $9^{1/2}$?', '["3","9","4.5","81"]', '3', '3', 'The exponent $\frac{1}{2}$ means the square root. $9^{1/2} = \sqrt{9} = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9^(1/2) = sqrt(9) = 3.","run_id":"claude-code","at":"2026-10-22T12:33:29.203Z"}}', 'ai', NULL, NULL)
