VALUES ('10b667c6-c059-4429-9364-f9b9c7bc0b98', 'ALG.19', 1, 'choice', 'Rational exponents', 'Which expression is another way to write the cube root of $x$?', '["$x^3$","$3x$","$x^{1/3}$","$x^{-3}$"]', '$x^{1/3}$', NULL, 'A root is written as a fractional exponent: the cube root of $x$ is $x^{1/3}$.', 'checked', '{"lint":[],"solve":{"answer":"$x^{1/3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The cube root of x is x^(1/3).","run_id":"claude-code","at":"2026-10-22T12:33:29.203Z"}}', 'ai', NULL, NULL)
