INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f1ce80a-0991-4cbd-919a-4bd86a0c8226', 'ALG.19', 3, 'choice', 'Rules of exponents', 'How many digits does the number $2^{10} \cdot 5^{12}$ have when it is written out?', '["10","12","13","22"]', '12', '12', 'Pair ten 2s with ten 5s: $2^{10} \cdot 5^{10} = 10^{10}$. What is left is $5^2 = 25$, so the number is $25 \cdot 10^{10}$, which is 25 followed by ten zeros. That has $2 + 10 = 12$ digits.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^10 * 5^12 = (2*5)^10 * 5^2 = 25 * 10^10 = 250,000,000,000, which has 2 + 10 = 12 digits.","run_id":"claude-code","at":"2026-10-22T12:33:29.203Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
