INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1adc73f1-b557-49ad-8de3-5fe8f4d7a994', 'ALG.21', 1, 'choice', 'Arithmetic series: sums', 'What is the sum $5 + 9 + 13 + 17 + 21$?', '["65","13","26","55"]', '65', '5*13', 'There are 5 terms and their average is the middle term, 13. So the sum is $5 \cdot 13 = 65$.', 'checked', '{"lint":[],"solve":{"answer":"65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 terms, average (5+21)/2 = 13, sum 65.","run_id":"claude-code","at":"2026-10-22T12:33:29.275Z"}}', 'ai', NULL, NULL)
