INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d25a3bd-c8de-4352-a55a-328db0c193a3', 'ALG.21', 2, 'numeric', 'Arithmetic series: sums', 'How many terms of $1 + 3 + 5 + 7 + \cdots$ are needed to make a sum of 144?', '[]', '12', '12', 'The sum of the first $n$ odd numbers is $n^2$. Since $12^2 = 144$, we need $12$ terms.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum of first n odd numbers = n^2 = 144 -> n = 12.","run_id":"claude-code","at":"2026-10-22T12:33:29.275Z"}}', 'ai', NULL, NULL)
