INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08383ddb-66b0-4b52-9910-2fb843ba9bd8', 'ALG.21', 3, 'choice', 'Infinite geometric series', 'Which fraction in lowest terms equals the repeating decimal $0.\overline{27} = 0.272727\ldots$?', '["$\\frac{27}{100}$","$\\frac{3}{10}$","$\\frac{9}{37}$","$\\frac{3}{11}$"]', '$\frac{3}{11}$', NULL, 'The series is $\frac{27}{100} + \frac{27}{10000} + \cdots$, with ratio $\frac{1}{100}$. The sum is $\frac{27/100}{99/100} = \frac{27}{99} = \frac{3}{11}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{11}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"27/100 + 27/10000 + ... = (27/100)/(99/100) = 27/99 = 3/11.","run_id":"claude-code","at":"2026-10-22T12:33:29.275Z"}}', 'ai', NULL, NULL)
