INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04e058a5-23b1-474c-b59d-458435f61afc', 'ALG.21', 3, 'numeric', 'Sequences and series: rules, notation and applications', 'An arithmetic sequence and a geometric sequence both start with 2, and both have second term 6. How much bigger is the 5th term of the geometric sequence than the 5th term of the arithmetic sequence?', '[]', '144', '2*3^4-(2+4*4)', 'Arithmetic: $d = 4$, so the 5th term is $2 + 16 = 18$. Geometric: $r = 3$, so the 5th term is $2 \cdot 81 = 162$. The difference is $162 - 18 = 144$.', 'checked', '{"lint":[],"solve":{"answer":"144","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Arithmetic d = 4: 5th term 2 + 16 = 18. Geometric r = 3: 5th term 2*81 = 162. Difference 144.","run_id":"claude-code","at":"2026-10-22T12:33:29.275Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06e2310b-54d5-430e-b576-5d97c7e3550c', 'ALG.22', 1, 'choice', 'Nested expressions', 'Let $f(x)=2x+1$. What is $f(f(3))$?', '["$7$","$14$","$15$","$13$"]', '$15$', '2*(2*3+1)+1', '$f(3)=2\cdot3+1=7$. Then $f(7)=2\cdot7+1=15$.', 'checked', '{"lint":[],"solve":{"answer":"$15$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(3)=7, f(7)=15.","run_id":"claude-code","at":"2026-10-22T12:33:29.311Z"}}', 'ai', NULL, NULL)
