INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01bfed70-2715-4ab8-84b3-263abbd1572e', 'ALG.22', 1, 'numeric', 'Factoring to simplify arithmetic', 'Find the value of $99\times15$. (Hint: $99=100-1$.)', '[]', '1485', '100*15-15', '$99\times15=(100-1)\times15=1500-15=1485$.', 'checked', '{"lint":[],"solve":{"answer":"1485","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15*100-15=1485.","run_id":"claude-code","at":"2026-10-22T12:33:29.311Z"}}', 'ai', NULL, NULL)
