INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05424b3e-0876-4e96-a23e-6b1745cc89b7', 'ALG.22', 1, 'numeric', 'Factoring to simplify arithmetic', 'Find the value of $4.5^2-0.5^2$.', '[]', '20', '(4.5+0.5)*(4.5-0.5)', '$4.5^2-0.5^2=(4.5+0.5)(4.5-0.5)=5\cdot4=20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(4.5-0.5)(4.5+0.5)=4*5=20.","run_id":"claude-code","at":"2026-10-22T12:33:29.311Z"}}', 'ai', NULL, NULL)
