INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14f23860-0ad0-480e-8a31-456d10c39937', 'ALG.22', 2, 'choice', 'Symmetric expressions from the sum and product', 'Numbers $x$ and $y$ are not zero, with $x+y=5$ and $xy=3$. What is $\frac xy+\frac yx$?', '["$5/3$","$25/3$","$31/3$","$19/3$"]', '$19/3$', '(5^2-2*3)/3', '$\frac xy+\frac yx=\frac{x^2+y^2}{xy}$. Here $x^2+y^2=25-6=19$, so the value is $\frac{19}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"$19/3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x/y+y/x=(x^2+y^2)/(xy)=(25-6)/3=19/3. Real roots exist (disc 25-12>0).","run_id":"claude-code","at":"2026-10-22T12:33:29.311Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1eff5249-78e3-478c-8a86-79c6551b7be4', 'ALG.22', 2, 'choice', 'Telescoping sums and products', 'Which expression is equal to $\frac1{n(n+1)}$ for every positive integer $n$?', '["$\\frac1n-\\frac1{n+1}$","$\\frac1n+\\frac1{n+1}$","$\\frac1{n+1}-\\frac1n$","$\\frac1n-\\frac1{n-1}$"]', '$\frac1n-\frac1{n+1}$', NULL, '$\frac1n-\frac1{n+1}=\frac{(n+1)-n}{n(n+1)}=\frac1{n(n+1)}$. The others have the wrong sign or the wrong denominator.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac1n-\\frac1{n+1}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/n-1/(n+1)=(n+1-n)/(n(n+1))=1/(n(n+1)). Others negative, wrong, or undefined at n=1.","run_id":"claude-code","at":"2026-10-22T12:33:29.311Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('13a4e899-f661-41d0-ad78-6c7f401ae4fd', 'ALG.22', 2, 'numeric', 'Substitution to simplify', 'Find $x$ if $(x-3)^2+4(x-3)=21$ and $x>3$.', '[]', '6', NULL, 'Let $y=x-3$. Then $y^2+4y-21=(y+7)(y-3)=0$. Since $x>3$, $y$ is positive, so $y=3$ and $x=6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"u=x-3: u^2+4u-21=0, (u+7)(u-3)=0, u>0 so u=3, x=6. Check 9+12=21.","run_id":"claude-code","at":"2026-10-22T12:33:29.311Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12812a2e-264c-42d4-b72c-3917e6f20ab9', 'ALG.22', 3, 'choice', 'Telescoping sums and products', 'What is $\frac2{\sqrt1+\sqrt3}+\frac2{\sqrt3+\sqrt5}+\frac2{\sqrt5+\sqrt7}+\cdots+\frac2{\sqrt{47}+\sqrt{49}}$?', '["$7$","$5$","$6$","$12$"]', '$6$', '7-1', 'Multiply top and bottom of $\frac2{\sqrt n+\sqrt{n+2}}$ by $\sqrt{n+2}-\sqrt n$. The bottom becomes 2, so the term is $\sqrt{n+2}-\sqrt n$. The sum is $(\sqrt3-\sqrt1)+(\sqrt5-\sqrt3)+\cdots+(\sqrt{49}-\sqrt{47})=7-1=6$.', 'checked', '{"lint":[],"solve":{"answer":"$6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/(sqrt(2k-1)+sqrt(2k+1))=sqrt(2k+1)-sqrt(2k-1) (difference of radicands is 2). Telescopes: sqrt49-sqrt1=7-1=6.","run_id":"claude-code","at":"2026-10-22T12:33:29.311Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1390e293-05a9-4d31-9f9b-50136311ce2b', 'ALG.22', 3, 'choice', 'Telescoping sums and products', 'Since $(n+1)^2-n^2=2n+1$, we have $\frac{2n+1}{n^2(n+1)^2}=\frac1{n^2}-\frac1{(n+1)^2}$. Use this to find $\frac3{1\cdot4}+\frac5{4\cdot9}+\frac7{9\cdot16}+\frac9{16\cdot25}$.', '["$1$","$25/24$","$4/5$","$24/25$"]', '$24/25$', '1-1/25', 'The sum is $\left(1-\frac14\right)+\left(\frac14-\frac19\right)+\left(\frac19-\frac1{16}\right)+\left(\frac1{16}-\frac1{25}\right)=1-\frac1{25}=\frac{24}{25}$.', 'checked', '{"lint":[],"solve":{"answer":"$24/25$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Terms are n=1..4: (1-1/4)+(1/4-1/9)+(1/9-1/16)+(1/16-1/25)=1-1/25=24/25.","run_id":"claude-code","at":"2026-10-22T12:33:29.311Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
