INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('045000ee-31fd-4e3e-8aa0-f7a731b8b67d', 'BA2.03', 2, 'numeric', 'Addition stories and missing numbers', 'A library has 131 picture books on one shelf. It gets 58 more books on Monday and 42 more books on Tuesday. How many picture books does it have then?', '[]', '231', '131+58+42', '131 + 58 = 189. Then 189 + 42 = 231.', 'checked', '{"lint":[],"solve":{"answer":"231","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"131 + 58 + 42 = 131 + 100 = 231.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
