INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14d57a8b-3fba-40d5-9c57-0cf0a8b6624c', 'BA2.03', 3, 'numeric', 'Missing digits in a sum', 'The same digit goes in both boxes. $\square2 + \square9 = 91$ What digit is it?', '[]', '4', '4', 'The ones make 2 + 9 = 11, so 1 ten is regrouped. Tens: box + box + 1 = 9, so the two boxes make 8, and each box is 4. Check: 42 + 49 = 91.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ones 2 + 9 = 11, carry 1; tens 2d + 1 = 9, d = 4. 42 + 49 = 91.","run_id":"claude-code","at":"2026-10-19T01:32:17.207Z"}}', 'ai', NULL, NULL)
