INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12f1b793-e520-4e75-bf2b-97878ee80286', 'BA2.04', 1, 'choice', 'Checking subtraction with addition', 'Which subtraction sentence goes with $28 + 45 = 73$?', '["$28 - 45 = 73$","$73 - 45 = 45$","$45 - 73 = 28$","$73 - 28 = 45$"]', '$73 - 28 = 45$', NULL, '28 + 45 = 73 is in a family with 73 - 28 = 45 and 73 - 45 = 28. The other sentences are not true.', 'checked', '{"lint":[],"solve":{"answer":"$73 - 28 = 45$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"28 + 45 = 73 gives 73 - 28 = 45 (and 73 - 45 = 28).","run_id":"claude-code","at":"2026-10-19T01:32:17.247Z"}}', 'ai', NULL, NULL)
