INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0625b492-6737-4b8d-a080-f7993c1a47c8', 'BA2.04', 2, 'numeric', 'Subtraction as distance between numbers', 'Oakton is 616 kilometers from the airport. Stone Creek is 157 kilometers from the airport. How many kilometers farther from the airport is Oakton than Stone Creek?', '[]', '459', '616-157', 'Ones: 6 is less than 7, so regroup 1 from the next place: 16 - 7 = 9. Tens: 1 - 1 = 0, and 0 is less than 5, so regroup 1 from the next place: 10 - 5 = 5. Hundreds: 6 - 1 = 5, then 5 - 1 = 4. The difference is 459.', 'checked', '{"lint":[],"solve":{"answer":"459","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"616 - 157 = 459.","run_id":"claude-code","at":"2026-10-19T01:32:17.247Z"}}', 'ai', NULL, NULL)
