INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04e3cccb-2465-4176-a3b2-b492b1aaacef', 'BA2.04', 3, 'numeric', 'Subtraction as distance between numbers', 'A trail marker at the start of Dee''s walk reads 281. A marker at the end reads 438. How many units long was the walk?', '[]', '157', '438-281', 'The length is the difference between the markers: Ones: 8 - 1 = 7. Tens: 3 is less than 8, so regroup 1 from the next place: 13 - 8 = 5. Hundreds: 4 - 1 = 3, then 3 - 2 = 1. The difference is 157.', 'checked', '{"lint":[],"solve":{"answer":"157","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"438 - 281 = 157.","run_id":"claude-code","at":"2026-10-19T01:32:17.247Z"}}', 'ai', NULL, NULL)
