INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04ff6b8b-5c1f-46dc-b456-0baf1d63dda8', 'BA2.04', 3, 'numeric', 'Missing digits in a difference', '$8? - 34 > 50$ The ? is a digit. What is the smallest digit that can go in its place?', '[]', '5', '5', '8? - 34 is 46 + ?. To be greater than 50, ? must be at least 5: 46 + 5 = 51, which is more than 50. With 4 it makes 50, which is not more than 50.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need 8? > 84. 84-34=50 (not >), 85-34=51. Smallest 5.","run_id":"claude-code","at":"2026-10-19T01:32:17.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20d0885f-2f20-4df7-9287-7a38aa0b0346', 'BA2.05', 1, 'choice', 'Parentheses in expressions', 'Which expression has the same value as $25 - (8 + 5)$?', '["$25 - 8 + 5$","$25 + 8 - 5$","$25 + 8 + 5$","$25 - 8 - 5$"]', '$25 - 8 - 5$', NULL, 'Taking away 8 + 5 is the same as taking away 8 and then taking away 5. So 25 - (8 + 5) = 25 - 8 - 5.', 'checked', '{"lint":[],"solve":{"answer":"$25 - 8 - 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25-(8+5)=12. 25-8-5=12; others 28, 38, 22.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
