INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e03d90d-f61e-411a-85f1-bd7130b62259', 'BA2.05', 2, 'choice', 'Equal and unequal expressions', 'Which expression has the greatest value?', '["$41 + 6$","$69 - 6$","$1 + 57$","$86 - 5$"]', '$86 - 5$', NULL, 'Work out each one: 86 - 5 = 81; 41 + 6 = 47; 69 - 6 = 63; 1 + 57 = 58. The greatest is 81.', 'checked', '{"lint":[],"solve":{"answer":"$86 - 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"47, 81, 58, 63. Greatest 81.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
