INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e0c9f91-c3fe-47b7-930b-79381c1924b5', 'BA2.05', 3, 'numeric', 'Parentheses in expressions', 'Ned can write $37 - 13 - 4$ with parentheses as $(37 - 13) - 4$ or as $37 - (13 - 4)$. What is the difference between the two answers?', '[]', '8', '2*4', '(37 - 13) - 4 = 20. 37 - (13 - 4) = 28. The second is bigger by 28 - 20 = 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(37-13)-4=20; 37-(13-4)=37-9=28; difference 8.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
