VALUES ('0d765bab-d41c-437c-937e-91a1531d8c4e', 'BA2.05', 3, 'numeric', 'Equal and unequal expressions', 'Dee writes six expressions: $44 + 3$; $42 + (8 - 3)$; $45 + 2$; $42 + (9 - 4)$; $45 + (4 - 3)$; $(57 - 4) - 5$. How many of them are equal to 47?', '[]', '4', NULL, 'Work out each expression and count the ones equal to 47. There are 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"47; 47; 47; 47; 46; 48. Four.","run_id":"claude-code","at":"2026-10-19T01:31:31.155Z"}}', 'ai', NULL, NULL)
