VALUES ('06ad1e8e-f152-4d6f-b4b5-581f9f9321b2', 'BA2.06', 1, 'choice', 'Multi-step stories', 'Tray 1 has 15 muffins. Tray 2 has 4 more muffins than Tray 1. Then 8 muffins are sold. How many muffins are left?', '["18","26","34","42"]', '26', '15+15+4-8', 'Tray 2 has 15 + 4 = 19. Both trays: 15 + 19 = 34. After selling 8: 34 - 8 = 26.', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tray 2 has 19; 15+19=34; 34-8=26.","run_id":"claude-code","at":"2026-10-19T01:31:31.193Z"}}', 'ai', NULL, NULL)
