VALUES ('025663e7-7ce0-4c45-ac97-9c69d0f253f7', 'BA2.06', 2, 'choice', 'Working backwards', 'A tank lost 17 liters of water and then 20 liters were added. It now holds 49 liters. How many liters did it hold at first?', '["47","45","48","46"]', '46', '49-20+17', 'Undo adding 20: 49 - 20 = 29. Undo losing 17: 29 + 17 = 46.', 'checked', '{"lint":[],"solve":{"answer":"46","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"49-20=29, 29+17=46.","run_id":"claude-code","at":"2026-10-19T01:31:31.193Z"}}', 'ai', NULL, NULL)
