INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1624a884-71aa-476f-8ae3-bf147507d512', 'BA2.09', 1, 'choice', 'Odd or even sums and differences', 'Ben has 6 stickers. He gets some more and now has an odd number of stickers. Which number of new stickers could it be?', '["$2$","$4$","$3$","$8$"]', '$3$', NULL, '6 is even. Even plus odd is odd, but even plus even is even. So Ben must have got an odd number of stickers. Of these, only 3 is odd. (6 + 3 = 9.)', 'checked', '{"lint":[],"solve":{"answer":"$3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 is even; to get odd total, add an odd number: 3 (6+3=9).","run_id":"claude-code","at":"2026-10-19T01:26:38.753Z"}}', 'ai', NULL, NULL)
