INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15c752dd-b642-40d6-aaad-830d89bee212', 'BA2.11', 1, 'numeric', 'Subtracting with regrouping', 'What is $63 - 18$?', '[]', '45', '63-18', 'Ones: 3 is less than 8, so regroup 1 from the next place to make 13, and 13 - 8 = 5. Tens: 5 - 1 = 4. The difference is 45.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Regroup: 13-8=5; 5-1=4. 45.","run_id":"claude-code","at":"2026-10-19T01:36:32.355Z"}}', 'ai', NULL, NULL)
