INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06d4ccc0-7f08-462c-a002-0ba1dc437226', 'BA2.11', 2, 'choice', 'Missing digits in a sum', '$387 + 346 = 7\square3$ Which digit is hidden by the box?', '["4","2","5","3"]', '3', NULL, 'Add the two numbers: 387 + 346 = 733. So the full equation is 387 + 346 = 733, and the missing digit is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"387+346=733, box 3.","run_id":"claude-code","at":"2026-10-19T01:36:32.355Z"}}', 'ai', NULL, NULL)
