INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05a542e3-4c1d-4838-bc71-c31385736405', 'BA2.12', 1, 'numeric', 'Multi-step stories', 'A pencil costs 7 cents and an eraser costs 5 cents. Zoe buys 2 pencils and 1 eraser. How many cents does she spend?', '[]', '19', '7*2+5', '2 pencils cost 2 x 7 = 14 cents. Add the eraser: 14 + 5 = 19 cents.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x7=14, +5=19.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
