INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('027bf1b1-ea3f-4af5-a602-121213634860', 'BA2.12', 2, 'choice', 'Repeating patterns', 'Today is Thursday. What day of the week will it be 17 days from today?', '["Sunday","Monday","Saturday","Tuesday"]', 'Sunday', NULL, 'The days repeat every 7. 17 = 14 + 3. After 14 days it is Thursday again, and 3 more days later it is Sunday.', 'checked', '{"lint":[],"solve":{"answer":"Sunday","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"17 = 14 + 3. Thursday + 3 days = Sunday.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e2aa1c1-eadb-4bbf-a1cf-8df15b57eb72', 'BA2.12', 2, 'choice', 'Logic puzzles', 'Hal and Raj have 18 stickers together. Hal has 10 more stickers than Raj. How many stickers does Hal have?', '["14","4","8","19"]', '14', '(18+10)/2', 'If Hal gave away the 10 extra stickers, both would have the same: 18 - 10 = 8, so each would have 4. Then Hal has 4 + 10 = 14.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Raj = (18-10)/2 = 4, Hal = 14.","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
