INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00c9ab45-c3fd-4263-a67e-2e6e7b78382e', 'BA2.12', 3, 'numeric', 'Logic puzzles', 'Dee, Jo and Raj have 34 marbles in all. Jo has 2 more marbles than Raj. Dee has 3 more marbles than Jo. How many marbles does Raj have?', '[]', '9', '(34-7)/3', 'Imagine Jo and Dee each give away their extras. Jo gives 2, Dee gives 5. That removes 7 marbles, leaving 27. Now all three have the same number: 27 / 3 = 9. So Raj has 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Raj r, Jo r+2, Dee r+5: 3r+7=34, r=9. (9+11+14=34.)","run_id":"claude-code","at":"2026-10-19T01:36:32.391Z"}}', 'ai', NULL, NULL)
