VALUES ('049f668c-a795-462a-a6f0-bd8cbf75ea0d', 'BA3.02', 2, 'numeric', 'Finding a missing number in a skip-counting list', 'This list always goes up by the same amount: $4, \_\_, 22, 31$. What is the missing number?', '[]', '13', '4+9', '22 to 31 is 9 more, so the list goes up by 9. 4 + 9 = 13, and 13 + 9 = 22.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"22 to 31 is 9; 4 + 9 = 13, 13 + 9 = 22.","run_id":"claude-code","at":"2026-10-19T01:25:25.437Z"}}', 'ai', NULL, NULL)
