VALUES ('0576304b-26ed-442f-9cc9-dd9de414bf9a', 'BA3.03', 1, 'choice', 'Perimeter of rectangles and squares', 'A rectangle has two sides that are 7 units long and two sides that are 5 units long. What is its perimeter, in units?', '["12","35","24","17"]', '24', '7+7+5+5', 'Add all four sides: 7 + 7 + 5 + 5 = 24 units.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7+7+5+5 = 24.","run_id":"claude-code","at":"2026-10-19T01:25:25.476Z"}}', 'ai', NULL, NULL)
