VALUES ('07223b95-4b44-4d01-ad57-481a0d25ae4f', 'BA3.07', 2, 'choice', 'Solving a one-step multiplication or division equation', 'Which number makes $84 \div n = 7$ true?', '["77","91","12","588"]', '12', '84/7', '$84$ split into groups of $n$ gives 7, so $n = 84 \div 7 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"84 / 7 = 12.","run_id":"claude-code","at":"2026-10-19T01:24:30.515Z"}}', 'ai', NULL, NULL)
