INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('23f08013-b32f-451a-9c72-a613b088e8e5', 'BA4.02', 2, 'numeric', 'Missing digits, missing factors and multiplication word problems', 'A school buys 24 boxes of pencils with 36 pencils in each box. Then 100 pencils are given away. How many pencils are left?', '[]', '764', '24*36-100', '24 x 36 = 720 + 144 = 864. Then 864 - 100 = 764.', 'checked', '{"lint":[],"solve":{"answer":"764","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 x 36 = 864; 864 - 100 = 764.","run_id":"claude-code","at":"2026-10-19T01:26:44.107Z"}}', 'ai', NULL, NULL)
