VALUES ('03811d49-616a-4044-b140-544b72933e2c', 'BA4.03', 1, 'numeric', 'Evaluating expressions with exponents', 'Square the number 4, then add 3. What is the result?', '[]', '19', '4^2+3', 'Squaring 4 gives $4 \times 4 = 16$. Adding 3 gives 19.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4^2 = 16; 16 + 3 = 19.","run_id":"claude-code","at":"2026-10-19T01:28:36.749Z"}}', 'ai', NULL, NULL)
