INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a57d0fd-8eef-4ac0-a451-8457e9399d1d', 'BA4.06', 1, 'numeric', 'Truth-tellers and liars: several speakers', 'Each of Ann, Bo and Cy is a truth-teller or a liar. Ann says: "Bo is a liar." Bo says: "Cy is a liar." Cy says: "Ann and Bo are both liars." How many of the three are liars? (A truth-teller always tells the truth. A liar always lies.)', '[]', '2', '2', 'If Cy told the truth, Ann and Bo would both be liars. But then Ann would be a liar saying "Bo is a liar", which is true. That cannot happen. So Cy is a liar. Then "Cy is a liar" is true, so Bo is a truth-teller. Then "Bo is a liar" is false, so Ann is a liar. Liars: Ann and Cy, which is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ann T -> Bo L -> Cy T -> ''Ann and Bo both liars'' false, contradiction. Ann L -> Bo T -> Cy L; Cy''s claim false (Bo T), Ann''s claim false. Liars: Ann, Cy = 2.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d90018b-fe99-4cb7-8491-342141fb3a4f', 'BA4.06', 1, 'choice', 'Ordering people or things from clues', 'Four runners ran a race with no ties. Dan finished before Eve. Eve finished before Fay. Fay finished before Gil. Who finished last?', '["Dan","Eve","Gil","Fay"]', 'Gil', NULL, 'The order from first to last is Dan, Eve, Fay, Gil. So Gil finished last.', 'checked', '{"lint":[],"solve":{"answer":"Gil","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dan, Eve, Fay, Gil. Gil last.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
