INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a7c9cfc-a816-4934-928a-7ef71e32cb6d', 'BA4.06', 2, 'choice', 'Ordering people or things from clues', 'Five friends each ate a different number of cookies. Di ate the most. Ed ate fewer than Di but more than Ana. Ana ate more than Bo. Bo ate more than Cy. Who ate the second most?', '["Ana","Ed","Bo","Cy"]', 'Ed', NULL, 'From the most to the fewest: Di, Ed, Ana, Bo, Cy. So Ed ate the second most.', 'checked', '{"lint":[],"solve":{"answer":"Ed","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Di > Ed > Ana > Bo > Cy. Ed.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
