INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05622a24-e52e-40e5-8540-ee1df93be563', 'BA4.06', 2, 'numeric', 'Deciding what must be true', 'All of Ana''s pets are cats or dogs. She has exactly 3 pets and none of them is a dog. How many cats does Ana have?', '[]', '3', '3', 'Each pet is a cat or a dog. None is a dog, so all 3 are cats.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"No dogs, so all 3 are cats.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
