INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b61c230-3a26-40f2-ab81-3692dc8a2dbb', 'BA4.06', 2, 'choice', 'Matching, elimination and counting cases', 'Four tutors, Ann, Ben, Cy and Dee, teach on four different days, one tutor each day: Monday, Tuesday, Wednesday and Thursday. Ann teaches on an earlier day than Ben. Cy teaches the day right after Ben. Dee does not teach on Monday or Thursday. Who teaches on Tuesday?', '["Ann","Dee","Ben","Cy"]', 'Dee', NULL, 'Dee teaches on Tuesday or Wednesday. Ben has Ann before him and Cy right after him, so Ben is on Tuesday or Wednesday. If Ben is on Tuesday, Ann is on Monday, Cy on Wednesday and Dee is left with Thursday, which is not allowed. So Ben is on Wednesday, Cy on Thursday, Ann on Monday, and Dee on Tuesday.', 'checked', '{"lint":[],"solve":{"answer":"Dee","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dee Tue or Wed. Dee Wed leaves 1, 2, 4: Ben-Cy must be 1-2, Ann earlier impossible. Dee Tue: Ann Mon, Ben Wed, Cy Thu. Tuesday: Dee.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09e3a9ee-3103-44ef-8c93-883dcd88e18b', 'BA4.06', 3, 'numeric', 'Ordering with numbers and counting orders', 'Four runners, including Zed, race with no ties. In how many different orders can they finish if Zed does not finish last?', '[]', '18', '24-6', 'Four runners can finish in 4 × 3 × 2 × 1 = 24 orders. Zed is last in 3 × 2 × 1 = 6 of them. So 24 - 6 = 18.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 orders, 6 with Zed last: 18.","run_id":"claude-code","at":"2026-10-19T01:32:17.321Z"}}', 'ai', NULL, NULL)
