INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('227bae2e-7c9c-4ac7-9c7a-ca04ed404078', 'BA4.07', 2, 'choice', 'Prime factorization', 'Which is the prime factorization of 60?', '["$2^2 \\times 3 \\times 5$","$2 \\times 3 \\times 10$","$2^2 \\times 15$","$4 \\times 3 \\times 5$"]', '$2^2 \times 3 \times 5$', NULL, '60 = 4 x 15 = 2 x 2 x 3 x 5 = 2^2 x 3 x 5. In the others, 10, 15 and 4 are not prime.', 'checked', '{"lint":[],"solve":{"answer":"$2^2 \\times 3 \\times 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60 = 2x2x3x5 = 2^2 x 3 x 5. Others contain 10, 4 or 15, not prime.","run_id":"claude-code","at":"2026-10-19T01:16:45.913Z"}}', 'ai', NULL, NULL)
