INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ff7fa49-977b-4d05-809e-b7e2bbd62da2', 'BA4.07', 2, 'choice', 'Divisibility rules', 'Which number is divisible by 4?', '["$3{,}116$","$3{,}114$","$3{,}122$","$3{,}130$"]', '$3{,}116$', NULL, 'A number is divisible by 4 if its last two digits make a number divisible by 4. 16 is, but 14, 22 and 30 are not.', 'checked', '{"lint":[],"solve":{"answer":"$3{,}116$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Last two digits divisible by 4: 22 no, 30 no, 14 no, 16 yes.","run_id":"claude-code","at":"2026-10-19T01:16:45.913Z"}}', 'ai', NULL, NULL)
