INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d11572c-4299-47a1-b31c-c1262597fac8', 'BA4.08', 1, 'choice', 'Mixed numbers to improper fractions', 'A tray holds 3 whole cakes and one half of another cake. How many half-cakes is that altogether?', '["6","7","8","3"]', '7', '3*2+1', 'Each whole cake is 2 halves, so 3 cakes are 6 halves. Add the 1 half: 7 halves.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 cakes = 6 halves, plus 1 half = 7.","run_id":"claude-code","at":"2026-10-19T01:16:45.952Z"}}', 'ai', NULL, NULL)
