VALUES ('13028d97-7d8b-4e10-9828-c7c533993a32', 'BA4.10', 1, 'choice', 'Fraction stories', 'There is $\frac{1}{2}$ of a liter of juice in a jug. Ana drinks $\frac{1}{8}$ of a liter. How many liters are left?', '["$\\frac{1}{6}$","$\\frac{1}{3}$","$\\frac{5}{8}$","$\\frac{3}{8}$"]', '$\frac{3}{8}$', NULL, '1/2 = 4/8. So 4/8 - 1/8 = 3/8 of a liter.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/8 - 1/8 = 3/8.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
