INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09252cd3-0da3-487d-842f-fce01bc980c5', 'BA4.10', 2, 'choice', 'Subtracting fractions with unlike denominators', 'Which difference is the greatest?', '["$\\frac{5}{6} - \\frac{2}{3}$","$\\frac{3}{4} - \\frac{1}{2}$","$\\frac{7}{8} - \\frac{3}{4}$","$\\frac{2}{3} - \\frac{1}{2}$"]', '$\frac{3}{4} - \frac{1}{2}$', NULL, 'The differences are 3/4 - 1/2 = 1/4, 5/6 - 2/3 = 1/6, 7/8 - 3/4 = 1/8 and 2/3 - 1/2 = 1/6. The greatest is 1/4.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{4} - \\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/6, 1/8, 1/4, 1/6. Greatest 1/4 = 3/4 - 1/2.","run_id":"claude-code","at":"2026-10-19T01:30:24.858Z"}}', 'ai', NULL, NULL)
