VALUES ('0375b42b-06cf-4c35-8de4-df8466494919', 'BA5.01', 1, 'numeric', 'Volume of a box', 'A box is 2 cm long, 3 cm wide and 4 cm tall. What is its volume in cubic centimeters?', '[]', '24', '2*3*4', 'Multiply length, width and height: $2 \times 3 \times 4 = 24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 x 3 x 4 = 24.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
