INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('042ac7fd-c7b9-44b5-b026-31e1b2973f8b', 'BA5.01', 2, 'numeric', 'Volume of a box', 'A box is 5 cm wide, twice as long as it is wide, and 3 cm tall. What is its volume in cubic centimeters?', '[]', '150', '10*5*3', 'The length is $2 \times 5 = 10$ cm. Volume $= 10 \times 5 \times 3 = 150$.', 'checked', '{"lint":[],"solve":{"answer":"150","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length 10; 5 x 10 x 3 = 150.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
