INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('19a95590-d390-4aa2-bf1d-3eaaaeacb8e0', 'BA5.01', 2, 'numeric', 'Surface area of a box', 'An open box has no lid. It is 7 cm long, 5 cm wide and 3 cm tall. How many square centimeters of material make it?', '[]', '107', '7*5+2*7*3+2*5*3', 'Bottom: $7 \times 5 = 35$. Two long sides: $2 \times 21 = 42$. Two short sides: $2 \times 15 = 30$. Total $35 + 42 + 30 = 107$.', 'checked', '{"lint":[],"solve":{"answer":"107","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bottom 35 + two 7x3 sides 42 + two 5x3 sides 30 = 107.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
