INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11f357b7-af0a-4630-88f6-9aa46dfe3ff4', 'BA5.01', 3, 'choice', 'Volume of a box', 'One cube has edges of 3 cm. A second cube has edges twice as long. How many times as large as the first cube''s volume is the second cube''s volume?', '["8","2","4","6"]', '8', '216/27', 'The first volume is $3 \times 3 \times 3 = 27$. The second has edges of 6 cm: $6 \times 6 \times 6 = 216$. And $216 \div 27 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3^3 = 27, 6^3 = 216; 216 / 27 = 8.","run_id":"claude-code","at":"2026-10-19T01:36:23.597Z"}}', 'ai', NULL, NULL)
