INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('032f4c80-0f76-4378-b9ac-236ce83e4462', 'BA5.03', 1, 'choice', 'The distributive property', 'Each ticket costs $t$ dollars plus a 1-dollar fee. Buying 5 tickets costs $5(t + 1)$ dollars. Which expression means the same thing?', '["$5t + 1$","$t + 5$","$5t + 5$","$6t$"]', '$5t + 5$', NULL, 'Each of the 5 tickets has the fee, so $5(t + 1) = 5t + 5 \times 1 = 5t + 5$.', 'checked', '{"lint":[],"solve":{"answer":"$5t + 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5(t+1) = 5t + 5.","run_id":"claude-code","at":"2026-10-19T01:32:55.676Z"}}', 'ai', NULL, NULL)
