VALUES ('0c453a22-24a3-432a-afd0-97cc79eee762', 'BA5.04', 2, 'choice', 'Finding the range', 'Which list has the greatest range?', '["100, 101, 110","20, 25, 40","0, 5, 9","50, 52, 55"]', '20, 25, 40', NULL, 'The ranges are $40 - 20 = 20$, $110 - 100 = 10$, $9 - 0 = 9$ and $55 - 50 = 5$. The greatest is 20.', 'checked', '{"lint":[],"solve":{"answer":"20, 25, 40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ranges 5, 9, 20, 10.","run_id":"claude-code","at":"2026-10-19T01:32:55.716Z"}}', 'ai', NULL, NULL)
