INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10d58f44-9415-4ca3-a9e2-4887d5a0a3e4', 'BA5.05', 2, 'choice', 'Grouping stories (greatest common factor)', 'A gardener plants 30 tulips and 45 daisies in rows. Each row has only one kind of flower, and every row has the same number of flowers. What is the greatest number of flowers that each row can have?', '["5","90","75","15"]', '15', '15', 'The row length must divide both 30 and 45. The greatest is 15. That makes 2 rows of tulips and 3 rows of daisies.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Row size must divide 30 and 45: gcd 15.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
