INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e856def-9957-400d-a713-46218d67415c', 'BA5.05', 3, 'choice', 'Counting the factors of a number', 'Which of these numbers has exactly 3 factors?', '["12","27","35","49"]', '49', '49', '49 = 7 x 7, so its factors are 1, 7 and 49. 12 has 6 factors, 27 has 4 (1, 3, 9, 27) and 35 has 4 (1, 5, 7, 35).', 'checked', '{"lint":[],"solve":{"answer":"49","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"49 = 7^2: 1,7,49. 12:6, 27:4, 35:4.","run_id":"claude-code","at":"2026-10-19T01:35:32.467Z"}}', 'ai', NULL, NULL)
