INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('007e7f94-e5a2-4fea-ab6c-87896ebc0c56', 'BA5.11', 3, 'choice', 'Estimating a square root', 'What is the smallest whole number n for which $\sqrt{n}$ is greater than 12?', '["145","144","143","13"]', '145', '145', '12 times 12 is 144, and the square root of 144 is exactly 12. The next whole number is 145, whose square root is greater than 12.', 'checked', '{"lint":[],"solve":{"answer":"145","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt n>12 -> n>144, smallest 145","run_id":"claude-code","at":"2026-10-19T01:39:00.540Z"}}', 'ai', NULL, NULL)
