VALUES ('07fe6520-ec81-4165-85ed-bf03e932229d', 'BA5.12', 3, 'choice', 'Powers of powers', 'Which power of 2 is equal to $(4^2)^3$?', '["$2^{7}$","$2^{6}$","$2^{9}$","$2^{12}$"]', '$2^{12}$', NULL, '$4 = 2^2$, so $4^2 = 2^4$. Then $(2^4)^3 = 2^{12}$.', 'checked', '{"lint":[],"solve":{"answer":"$2^{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4^6=2^12","run_id":"claude-code","at":"2026-10-19T01:39:00.577Z"}}', 'ai', NULL, NULL)
