VALUES ('094acfc3-3680-4182-9351-a71644d5e403', 'BA5.12', 3, 'choice', 'The zero exponent', 'What is $(3^0 + 3^0 + 3^0)^2$?', '["3","81","9","27"]', '9', '9', '$3^0 = 1$, so the bracket is 1 + 1 + 1 = 3. Then $3^2 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1+1+1)^2=9","run_id":"claude-code","at":"2026-10-19T01:39:00.577Z"}}', 'ai', NULL, NULL)
