INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2395303c-c7ff-49f5-92d4-5301c092fc16', 'BA5.07', 1, 'numeric', 'Finding a term (the 10th, the 50th)', 'Rosa lays a garden path in sections. Section 1 uses 9 tiles, section 2 uses 13 tiles and section 3 uses 17 tiles. Each section uses 4 more tiles than the section before it. How many tiles does section 6 use?', '[]', '29', '9+4*5', 'Keep adding 4: section 4 uses 21 tiles, section 5 uses 25 tiles and section 6 uses 29 tiles.', 'checked', '{"lint":[],"solve":{"answer":"29","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9, 13, 17, 21, 25, 29. Section 6 = 9 + 5 x 4 = 29.","run_id":"claude-code","at":"2026-10-22T12:51:48.907Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('012dc6c7-5399-4c8d-ba1f-55089c7208db', 'BA5.08', 2, 'choice', 'Writing ratios (part-to-part and part-to-whole)', 'Red, blue and green are the only colors of the marbles in a bag. For every 2 red marbles there are 3 blue marbles and 5 green marbles. Which sentence is true?', '["3 out of every 10 marbles are green","5 out of every 7 marbles are green","2 out of every 5 marbles are red","5 out of every 10 marbles are green"]', '5 out of every 10 marbles are green', NULL, 'In every group of 2 red, 3 blue and 5 green marbles there are 2 + 3 + 5 = 10 marbles, and 5 of them are green. The other sentences are false: 3 of the 10 are blue, green is not 5 out of 7, and red is 2 out of 10, not 2 out of 5.', 'checked', '{"lint":[],"solve":{"answer":"5 out of every 10 marbles are green","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Red : blue : green = 2 : 3 : 5, total 10. Green is 5 of every 10 (true). Green 3 of 10 is false. Red is 2 of 10 = 1 of 5, not 2 of 5. Green to non-total 5 of 7 is false (5 of 10).","run_id":"claude-code","at":"2026-10-22T12:51:48.907Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('032d93a2-322c-4b60-bd1c-c10d6a8872bf', 'GEO.01', 1, 'choice', 'Naming angles', 'Which of these angles has its vertex at point $T$?', '["$\\angle TSU$","$\\angle SUT$","$\\angle TUS$","$\\angle STU$"]', '$\angle STU$', NULL, 'The vertex is the middle letter. In $\angle STU$ the middle letter is $T$. The others have $S$ or $U$ in the middle.', 'checked', '{"lint":[],"solve":{"answer":"$\\angle STU$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Middle letter is the vertex: STU has vertex T; SUT, TUS vertex U; TSU vertex S.","run_id":"claude-code","at":"2026-10-22T19:38:47.909Z"}}', 'ai', NULL, NULL)
