INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07505ce8-0d8d-469c-bf5a-68a4c8ac8092', 'GEO.02', 2, 'numeric', 'Interior angle sum of a polygon', 'A convex polygon has 12 sides. What do its interior angles add up to, in degrees?', '[]', '1800', '(12-2)*180', 'A polygon with $n$ sides has an angle sum of $(n-2)\times180$. With $n=12$ that is $10\times180=1800$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"1800","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(12 - 2)*180 = 1800.","run_id":"claude-code","at":"2026-10-22T12:33:29.347Z"}}', 'ai', NULL, NULL)
