INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0521844a-df62-433f-9c6d-41d11f12c7f4', 'GEO.02', 2, 'choice', 'Exterior angles and regular polygons', 'How many degrees is each interior angle of a regular octagon?', '["$120$","$140$","$45$","$135$"]', '$135$', '(8-2)*180/8', 'The interior angles add up to $(8-2)\times180=1080$ degrees. Each of the 8 equal angles is $1080\div8=135$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"$135$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exterior 360/8 = 45, interior 180 - 45 = 135.","run_id":"claude-code","at":"2026-10-22T12:33:29.347Z"}}', 'ai', NULL, NULL)
