INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09447877-98ce-4266-8d21-431f06e4612b', 'GEO.02', 3, 'choice', 'Exterior angle of a triangle', 'An exterior angle of a triangle measures $150^\circ$. The two interior angles that are not next to it are in the ratio $2:3$. What does the larger of them measure?', '["$90$","$60$","$150$","$75$"]', '$90$', '150*3/5', 'The two far interior angles add up to the exterior angle, $150^\circ$. In the ratio $2:3$ they are $60^\circ$ and $90^\circ$. The larger is 90 degrees.', 'checked', '{"lint":[],"solve":{"answer":"$90$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 parts = 150, 30 per part: 60 and 90. Larger 90.","run_id":"claude-code","at":"2026-10-22T12:33:29.347Z"}}', 'ai', NULL, NULL)
