INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a781496-1660-4291-9d02-2e4ef6806f1c', 'GEO.02', 3, 'choice', 'Interior angle sum of a polygon', 'A convex polygon gains one extra side and one extra corner. By how many degrees does the sum of its interior angles go up?', '["$360$","$90$","$180$","$540$"]', '$180$', '180', 'The sum is $(n-2)\times180$. With one more side it is $(n-1)\times180$, which is exactly $180^\circ$ more.', 'checked', '{"lint":[],"solve":{"answer":"$180$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(n - 1)*180 - (n - 2)*180 = 180.","run_id":"claude-code","at":"2026-10-22T12:33:29.347Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08fe6283-a43b-4bb7-85e4-f3adbc11530f', 'GEO.03', 1, 'numeric', 'Corresponding parts of congruent triangles', 'Triangle $ABC$ is congruent to triangle $DEF$, with $A$ matching $D$, $B$ matching $E$ and $C$ matching $F$. In triangle $ABC$, $AB = 7$, $BC = 10$ and $AC = 12$ centimeters. How long is $EF$, in centimeters?', '[]', '10', '10', 'Corresponding sides of congruent triangles are equal. Since $B$ matches $E$ and $C$ matches $F$, the side $EF$ matches $BC$, so $EF = 10$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"B matches E and C matches F, so EF corresponds to BC = 10.","run_id":"claude-code","at":"2026-10-22T12:51:57.202Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('096b4a3a-4870-4283-b7f5-459753fbb1c5', 'GEO.03', 1, 'choice', 'Equilateral triangles', 'Which statement is true for every equilateral triangle?', '["Exactly two of its angles are equal","All three of its angles are $60^\\circ$","One of its angles is a right angle","Its three angles add up to $360^\\circ$"]', 'All three of its angles are $60^\circ$', NULL, 'The three angles of an equilateral triangle are equal and add to $180^\circ$, so each is $60^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"All three of its angles are $60^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Every equilateral triangle has three 60 degree angles.","run_id":"claude-code","at":"2026-10-22T19:38:47.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('168a167f-a921-4ec9-bd7d-4bbd476616ea', 'GEO.03', 1, 'numeric', 'Using congruent triangles to find lengths and unknowns', 'Triangle $ABC$ is congruent to triangle $DEF$, with $A$ matching $D$, $B$ matching $E$ and $C$ matching $F$. If $AB = 2x + 1$ and $DE = 11$, what is $x$?', '[]', '5', '(11-1)/2', 'Matching sides are equal, so $2x + 1 = 11$. Then $2x = 10$ and $x = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x+1 = 11, x = 5.","run_id":"claude-code","at":"2026-10-22T19:38:47.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15d68b7c-666e-4224-869f-9007d4f99389', 'GEO.03', 2, 'numeric', 'Isosceles triangle: base angles', 'In triangle $ABC$, $AB = AC$ and $\angle B$ is twice as large as $\angle A$. How large is $\angle A$, in degrees?', '[]', '36', '180/5', '$\angle C = \angle B = 2\angle A$. The three angles are $\angle A$, $2\angle A$ and $2\angle A$, which add to $5\angle A = 180$. So $\angle A = 36^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"B = C = 2A: A + 4A = 180, A = 36.","run_id":"claude-code","at":"2026-10-22T19:38:47.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e3bf6f3-b0a1-4fa8-a805-f23426caa09b', 'GEO.03', 2, 'choice', 'Isosceles triangle: equal sides and perimeter', 'An isosceles triangle has one side of $5$ centimeters and another side of $12$ centimeters. What is its perimeter, in centimeters?', '["22","34","29","17"]', '29', '5+12+12', 'The equal sides cannot both be $5$, because $5 + 5 = 10$ is shorter than the $12$ side, so no triangle closes. So the sides are $5$, $12$ and $12$, and the perimeter is $5 + 12 + 12 = 29$.', 'checked', '{"lint":[],"solve":{"answer":"29","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5,5,12 fails triangle inequality; 12,12,5: 29.","run_id":"claude-code","at":"2026-10-22T19:38:47.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10b899bd-c221-41ec-9be4-954c17c1b89f', 'GEO.03', 2, 'choice', 'Facts that do not guarantee congruence', 'Which pair of triangles must be congruent?', '["Both have angles $40^\\circ$, $60^\\circ$ and $80^\\circ$","Both are isosceles with a $40^\\circ$ angle","Both have sides $5$ and $8$ and an angle of $50^\\circ$","Both have sides $4$, $5$ and $7$"]', 'Both have sides $4$, $5$ and $7$', NULL, 'Three equal sides give congruence by SSS. Equal angles alone do not fix the size. An isosceles triangle with a $40^\circ$ angle could have angles $40, 40, 100$ or $40, 70, 70$. Two sides and an angle not between them are not enough either.', 'checked', '{"lint":[],"solve":{"answer":"Both have sides $4$, $5$ and $7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same three sides: SSS. The 50 degree angle need not be between the 5 and 8.","run_id":"claude-code","at":"2026-10-22T19:38:47.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12285909-fe07-46c5-8ac4-4d66cc3fe538', 'GEO.03', 3, 'choice', 'Isosceles triangle: median, altitude and angle bisector', 'Triangle $ABC$ has $AB = AC$. The point $D$ lies on $BC$ with $\angle BAD = \angle CAD$, and $E$ is any point on segment $AD$. Which rule shows that triangle $ABE$ is congruent to triangle $ACE$?', '["SSS","SAS","ASA","AAS"]', 'SAS', NULL, 'The triangles have $AB = AC$, the equal angles $\angle BAE = \angle CAE$ at $A$ between those sides and the shared side $AE$. That is SAS. Nothing says $BE = CE$ yet, so SSS cannot be used.', 'checked', '{"lint":[],"solve":{"answer":"SAS","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB = AC, angle BAE = angle CAE, AE common: SAS.","run_id":"claude-code","at":"2026-10-22T19:38:47.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18309618-8cba-49aa-bd60-23ae1e2947fa', 'GEO.03', 3, 'choice', 'Facts that do not guarantee congruence', 'Two triangles each have a perimeter of $12$. Which statement is true?', '["They must be congruent triangles","They must have the same three angles","They can never be congruent","They may or may not be congruent"]', 'They may or may not be congruent', NULL, 'Two triangles with sides $3, 4, 5$ have perimeter $12$ and are congruent. A triangle with sides $4, 4, 4$ also has perimeter $12$ but is not congruent to them. So it can go either way.', 'checked', '{"lint":[],"solve":{"answer":"They may or may not be congruent","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"E.g. 4,4,4 and 3,4,5 both have perimeter 12; equal copies would be congruent.","run_id":"claude-code","at":"2026-10-22T19:38:47.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b1f749c-cef9-4c17-b9ea-69136a0ae24c', 'GEO.04', 1, 'choice', 'Area of a triangle', 'A right triangle has legs of $8$ inches and $5$ inches. What is its area, in square inches?', '["40","13","20","10"]', '20', '8*5/2', 'In a right triangle one leg can serve as the base and the other as the height. The area is $\frac{1}{2}\times 8\times 5=20$. (40 forgets the half, and 13 adds the legs.)', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Legs are base and height: A = (1/2)(8)(5) = 20.","run_id":"claude-code","at":"2026-10-22T12:33:29.384Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09776d5b-eb91-47c2-92fd-555122727744', 'GEO.04', 1, 'choice', 'Area of a parallelogram', 'To find the area of a parallelogram, you multiply its base by which length?', '["the slanted side that touches it","the height, at a right angle to it","the longer of the two diagonals","half of the whole perimeter"]', 'the height, at a right angle to it', NULL, 'The area is base times height, where the height is the distance between the base and the opposite side, measured at a right angle. The slanted side is longer than the height, so it gives too big an answer.', 'checked', '{"lint":[],"solve":{"answer":"the height, at a right angle to it","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area = base x perpendicular height.","run_id":"claude-code","at":"2026-10-22T12:33:29.384Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09ff8897-29a9-4e57-9f49-7a8ab626b3bf', 'GEO.04', 1, 'numeric', 'Area of a composite shape', 'A rectangle is $10$ cm long and $6$ cm wide. A corner piece $4$ cm by $3$ cm is cut off. What is the area of what is left, in square centimeters?', '[]', '48', '10*6-4*3', 'The rectangle has area 60 and the corner piece has area 12. What is left has area $60-12=48$.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60 - 12 = 48.","run_id":"claude-code","at":"2026-10-22T12:33:29.384Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('175c20d6-afae-430e-a053-c3c2db040c43', 'GEO.04', 2, 'choice', 'Area of a parallelogram', 'A parallelogram has a base of $10$ cm. Its slanted sides are $6$ cm long and its height is $5$ cm. What is its area, in square centimeters?', '["60","30","50","25"]', '50', '10*5', 'Area is base times height: $10\times 5=50$. The slanted side of 6 is not the height (it gives the wrong answer 60).', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = base x height = 10 x 5 = 50 (slanted side 6 is a distractor; 5 < 6 consistent).","run_id":"claude-code","at":"2026-10-22T12:33:29.384Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c056c9d-54e8-4f57-9ec1-f168c05691f0', 'GEO.04', 2, 'choice', 'Area of a trapezoid', 'A trapezoid has parallel sides of $10$ and $20$ units and an area of $150$ square units. What is its height?', '["5","7.5","15","10"]', '10', '2*150/(10+20)', 'The sum of the parallel sides is 30, and twice the area is 300, so the height is $300\div 30=10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"150 = (10+20)/2 x h = 15h, h = 10.","run_id":"claude-code","at":"2026-10-22T12:33:29.384Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('217e37ed-1ee6-4e29-a769-7112c2dd4eaf', 'GEO.04', 2, 'numeric', 'Perimeter and the area of rectangles', 'A rectangular field has an area of $150$ square meters and a width of $10$ meters. How many meters of fence are needed to go all the way around it?', '[]', '50', '2*(150/10+10)', 'The length is $150\div 10=15$ m. The fence is the perimeter, $2\times(15+10)=50$ m.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length 150/10 = 15; perimeter 2(15+10) = 50.","run_id":"claude-code","at":"2026-10-22T12:33:29.384Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('118d848e-35c9-494e-9b00-bfe0889ba0aa', 'GEO.04', 3, 'choice', 'Area of a trapezoid', 'A trapezoid has parallel sides of $8$ and $20$ and a height of $6$. One of its diagonals cuts it into two triangles. What is the area of the triangle that has the side of length $20$ as its base?', '["24","60","120","80"]', '60', '20*6/2', 'The triangle with base 20 has its third corner on the other parallel side, which is 6 away from the side of length 20. So its height is 6 and its area is $\frac{1}{2}\times 20\times 6=60$.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Either diagonal gives a triangle with base 20 and apex on the other parallel side, height 6: (1/2)(20)(6) = 60.","run_id":"claude-code","at":"2026-10-22T12:33:29.384Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08c57b4e-c696-4bb4-8f6f-698b6ece70c7', 'GEO.04', 3, 'numeric', 'Area of a composite shape', 'A square has sides of length $12$. The midpoints of its four sides are joined in order to make a smaller square (tilted). What is the area of the smaller square?', '[]', '72', '144-4*6*6/2', 'Joining the midpoints cuts off four corner triangles, each with legs 6 and 6, so each has area 18. The big square has area 144, so the smaller square has area $144-4\times 18=72$.', 'checked', '{"lint":[],"solve":{"answer":"72","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Midpoint square has half the area: 144/2 = 72.","run_id":"claude-code","at":"2026-10-22T12:33:29.384Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a086bd4-600c-4239-a77c-fe5922e39768', 'GEO.05', 1, 'numeric', 'AA similarity', 'Triangles $ABC$ and $DEF$ are similar, with $A$, $B$, $C$ matching $D$, $E$, $F$. In triangle $ABC$, $\angle A = 55^\circ$ and $\angle B = 65^\circ$. How many degrees is $\angle F$?', '[]', '60', '180-55-65', 'In triangle $ABC$, $\angle C = 180^\circ - 55^\circ - 65^\circ = 60^\circ$. Similar triangles have equal matching angles, and $F$ matches $C$, so $\angle F = 60^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angle F matches angle C = 180 - 55 - 65 = 60 degrees.","run_id":"claude-code","at":"2026-10-22T12:59:41.196Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1128b1e5-2d81-4428-a1df-aacb58efa234', 'GEO.05', 1, 'numeric', 'Corresponding sides and scale factor', 'A triangle has sides 6, 9 and 12. A similar triangle has a shortest side of 2. How long is the longest side of the similar triangle?', '[]', '4', '12*2/6', 'The shortest sides match: $6$ and $2$, so the scale factor is $2 \div 6 = \frac{1}{3}$. The longest side is $12 \times \frac{1}{3} = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Shortest 6 -> 2, scale 1/3; longest 12/3 = 4.","run_id":"claude-code","at":"2026-10-22T19:39:29.789Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ad9f72d-cac5-4871-8fcf-f5ad7ace7ed1', 'GEO.05', 1, 'numeric', 'Indirect measurement with similar triangles', 'Two ramps are similar right triangles. The first ramp rises 2 feet over a base of 10 feet. The second ramp has a base of 25 feet. How many feet does the second ramp rise?', '[]', '5', '2*25/10', 'The bases are in the ratio $25 : 10$, so the scale factor is $2.5$. The second ramp rises $2 \times 2.5 = 5$ feet.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rise/base: 2/10 = r/25 -> r = 5.","run_id":"claude-code","at":"2026-10-22T19:39:29.789Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08f13a19-624a-4b65-84e1-928ba660e7bd', 'GEO.05', 2, 'choice', 'AA similarity', 'In triangle $XYZ$, point $U$ is on $\overline{XY}$ and point $V$ is on $\overline{XZ}$, with $\overline{UV}$ parallel to $\overline{YZ}$. Which reason shows that triangle $XUV$ is similar to triangle $XYZ$?', '["They share $\\angle X$, and $\\angle XUV = \\angle XYZ$ because $\\overline{UV} \\parallel \\overline{YZ}$.","They share $\\angle X$, and $\\angle XUV = \\angle XZY$ because $\\overline{UV} \\parallel \\overline{YZ}$.","They share $\\angle X$, and $UV = YZ$ because parallel segments have equal length.","They share $\\angle X$, and $\\angle XUV = \\angle XVU$ because $\\overline{UV} \\parallel \\overline{YZ}$."]', 'They share $\angle X$, and $\angle XUV = \angle XYZ$ because $\overline{UV} \parallel \overline{YZ}$.', NULL, 'Because $\overline{UV} \parallel \overline{YZ}$, the corresponding angles at $U$ and $Y$ are equal. Together with the shared angle at $X$, that is two equal angles, so AA applies. The angle at $U$ matches the angle at $Y$, not the one at $Z$; parallel segments need not be equal; and $\angle XUV$ and $\angle XVU$ need not be equal.', 'checked', '{"lint":[],"solve":{"answer":"They share $\\angle X$, and $\\angle XUV = \\angle XYZ$ because $\\overline{UV} \\parallel \\overline{YZ}$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"UV || YZ makes angle XUV = angle XYZ (corresponding angles), and angle X is shared: AA. Option D pairs the wrong angles.","run_id":"claude-code","at":"2026-10-22T19:39:29.789Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0733f7cc-3bb6-48cd-b158-15dd0674a7d8', 'GEO.05', 2, 'choice', 'Areas of similar triangles', 'A triangular poster has a base of 20 cm and an area of 240 square centimeters. A copy is made, similar to the poster, with a base of 15 cm. What is the area of the copy, in square centimeters?', '["$180$","$120$","$90$","$135$"]', '$135$', '240*(15/20)^2', 'The scale factor is $15 \div 20 = \frac{3}{4}$, so the area is multiplied by $\frac{9}{16}$: $240 \times \frac{9}{16} = 135$. (Using the scale factor alone, $240 \times \frac{3}{4} = 180$, is a common mistake.)', 'checked', '{"lint":[],"solve":{"answer":"$135$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scale 15/20 = 3/4, area ratio 9/16: 240 x 9/16 = 135.","run_id":"claude-code","at":"2026-10-22T19:39:29.789Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('031c9b5d-e5d9-40da-b3ed-4578a11d5db2', 'GEO.05', 2, 'numeric', 'A line parallel to a side of a triangle', 'Segments $\overline{WY}$ and $\overline{XZ}$ cross at point $O$, and $\overline{WX}$ is parallel to $\overline{YZ}$. If $WO = 5$, $OY = 8$ and $XZ = 26$, what is $XO$?', '[]', '10', '26*5/13', 'Triangle $OWX$ is similar to triangle $OYZ$, so $\frac{XO}{OZ} = \frac{WO}{OY} = \frac{5}{8}$. Then $XZ = XO + OZ$ is 13 parts, with $XO$ being 5 of them: $XO = 26 \times \frac{5}{13} = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Triangle OWX ~ OYZ: XO/OZ = WO/OY = 5/8, XO = 26 x 5/13 = 10.","run_id":"claude-code","at":"2026-10-22T19:39:29.789Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20bbf06a-ab6a-467b-9ab4-5faf835dcd69', 'GEO.05', 3, 'numeric', 'Triangles that share an angle', 'In triangle $ABC$, $AB = 16$ and $AC = 12$. Point $D$ is on $\overline{AB}$ so that triangle $ADC$ is similar to triangle $ACB$, with $A$, $D$, $C$ matching $A$, $C$, $B$ in that order. What is $DB$?', '[]', '7', '16-12*12/16', 'Matching sides must have equal ratios: $\frac{AD}{AC} = \frac{AC}{AB}$. So $\frac{AD}{12} = \frac{12}{16}$, which gives $AD = 9$. Then $DB = AB - AD = 16 - 9 = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"ADC ~ ACB with A<->A, D<->C, C<->B: AD/AC = AC/AB, so AD = 12^2/16 = 9. D is on AB since 9 < 16. DB = 16 - 9 = 7.","run_id":"claude-code","at":"2026-10-22T12:59:41.196Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0733837a-6f8d-47c3-88bc-3b7a4ab8284b', 'GEO.05', 3, 'choice', 'Areas of similar triangles', 'A triangle is enlarged so that its perimeter becomes 1.5 times as long. The new triangle is similar to the old one. By what percent does the area increase?', '["50 percent","150 percent","125 percent","225 percent"]', '125 percent', NULL, 'The scale factor is 1.5, so the area is multiplied by $1.5^2 = 2.25$. The new area is 225 percent of the old one, which is an increase of 125 percent.', 'checked', '{"lint":[],"solve":{"answer":"125 percent","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scale 1.5, area x 2.25, increase 125 percent.","run_id":"claude-code","at":"2026-10-22T19:39:29.789Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c538c44-3010-4d14-9579-55696e408a74', 'GEO.06', 1, 'choice', '30-60-90 triangles', 'What is the ratio of the sides of a 30-60-90 triangle, in the order shortest side : longer leg : hypotenuse?', '["$1 : \\sqrt{3} : 2$","$1 : \\sqrt{2} : 2$","$1 : 1 : \\sqrt{2}$","$1 : 2 : \\sqrt{3}$"]', '$1 : \sqrt{3} : 2$', NULL, 'In a 30-60-90 triangle the hypotenuse is twice the shortest side, and the longer leg is $\sqrt{3}$ times the shortest side. So the ratio is $1 : \sqrt{3} : 2$.', 'checked', '{"lint":[],"solve":{"answer":"$1 : \\sqrt{3} : 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 : sqrt(3) : 2.","run_id":"claude-code","at":"2026-10-22T19:39:29.828Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10f84432-a0ba-4eb3-9610-1c7f85f09473', 'GEO.06', 1, 'choice', '30-60-90 triangles', 'The shortest side of a 30-60-90 triangle is 10 long. What is the perimeter of the triangle?', '["$30$","$30 + 10\\sqrt{3}$","$30\\sqrt{3}$","$10 + 10\\sqrt{3}$"]', '$30 + 10\sqrt{3}$', NULL, 'The sides are $10$, $10\sqrt{3}$ and $20$. The perimeter is $10 + 10\sqrt{3} + 20 = 30 + 10\sqrt{3}$.', 'checked', '{"lint":[],"solve":{"answer":"$30 + 10\\sqrt{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sides 10, 10 sqrt(3), 20; perimeter 30 + 10 sqrt(3).","run_id":"claude-code","at":"2026-10-22T19:39:29.828Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('144673cf-d2f8-4c44-9187-e8fcc807caef', 'GEO.06', 1, 'numeric', 'Right triangles in applications', 'A rectangular gate is 4 feet wide and 3 feet tall. A brace runs along a diagonal from one corner to the opposite corner. How long is the brace, in feet?', '[]', '5', '5', 'The brace is the hypotenuse of a right triangle with legs 4 and 3: $\sqrt{4^2 + 3^2} = \sqrt{25} = 5$ feet.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(16+9) = 5.","run_id":"claude-code","at":"2026-10-22T19:39:29.828Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03e1bb67-b76b-4025-bd09-74c7e4a2053c', 'GEO.06', 2, 'numeric', '45-45-90 triangles', 'A square has a diagonal of length 12. What is the area of the square?', '[]', '72', '12^2/2', 'The diagonal cuts the square into two 45-45-90 triangles, so a side $s$ satisfies $s\sqrt{2} = 12$. The area is $s^2 = \frac{12^2}{2} = \frac{144}{2} = 72$.', 'checked', '{"lint":[],"solve":{"answer":"72","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Side s with s*sqrt2 = 12, s^2 = 144/2 = 72. Area 72.","run_id":"claude-code","at":"2026-10-22T19:21:45.611Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('133b19e6-0fa0-43f1-93f4-493f9dee4cc8', 'GEO.06', 2, 'numeric', 'Pythagorean theorem: finding a leg', 'A right triangle has a hypotenuse of 29 and one leg of 21. What is the perimeter of the triangle?', '[]', '70', '29+21+20', 'The other leg is $\sqrt{29^2 - 21^2} = \sqrt{841 - 441} = \sqrt{400} = 20$. The perimeter is $29 + 21 + 20 = 70$.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Other leg sqrt(841-441) = 20; perimeter 21 + 20 + 29 = 70.","run_id":"claude-code","at":"2026-10-22T19:39:29.828Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('144c4346-71f6-4d06-9a80-7dd2ecefc7fe', 'GEO.06', 2, 'choice', '45-45-90 triangles', 'Each leg of a 45-45-90 triangle is 6 long. What is the perimeter of the triangle?', '["$18$","$12 + 12\\sqrt{2}$","$12 + 6\\sqrt{2}$","$6 + 6\\sqrt{2}$"]', '$12 + 6\sqrt{2}$', NULL, 'The hypotenuse is $6\sqrt{2}$. The perimeter is $6 + 6 + 6\sqrt{2} = 12 + 6\sqrt{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$12 + 6\\sqrt{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hypotenuse 6 sqrt(2); perimeter 12 + 6 sqrt(2).","run_id":"claude-code","at":"2026-10-22T19:39:29.828Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09fbe74d-454d-48e0-8be8-92ef7734b60c', 'GEO.06', 3, 'numeric', 'Pythagorean theorem: finding the hypotenuse', 'The hypotenuse of a right triangle is 17 long, and its two legs differ in length by 7. What is the perimeter of the triangle?', '[]', '40', '8+15+17', 'Let the legs be $x$ and $x + 7$. Then $x^2 + (x+7)^2 = 17^2$, which gives $2x^2 + 14x + 49 = 289$, so $x^2 + 7x - 120 = 0$, or $(x + 15)(x - 8) = 0$. Since $x$ is positive, $x = 8$. The legs are 8 and 15, so the perimeter is $8 + 15 + 17 = 40$.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Legs a and a+7: a^2 + (a+7)^2 = 289 -> 2a^2 + 14a - 240 = 0 -> a^2 + 7a - 120 = 0 -> (a+15)(a-8)=0, a=8. Legs 8, 15. Perimeter 8+15+17 = 40.","run_id":"claude-code","at":"2026-10-22T19:21:45.611Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b9a55db-59ca-43bb-95ad-0b97b30d82b9', 'GEO.06', 3, 'numeric', 'Right triangles in applications', 'A box is 4 cm long, 12 cm wide and 3 cm tall. How long is the longest straight line segment that fits inside the box, from one corner to the opposite corner, in centimeters?', '[]', '13', '13', 'The diagonal of the 4 by 12 bottom is $\sqrt{4^2 + 12^2} = \sqrt{160}$. The segment is the hypotenuse of a right triangle with that as one leg and the height 3 as the other: $\sqrt{160 + 9} = \sqrt{169} = 13$ cm. (In one step, $\sqrt{4^2 + 12^2 + 3^2} = 13$.)', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(16 + 144 + 9) = sqrt(169) = 13.","run_id":"claude-code","at":"2026-10-22T19:39:29.828Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1451736e-3fb3-465f-a88b-267c65738545', 'GEO.07', 1, 'choice', 'Medians and the centroid', 'The three medians of a triangle meet at the centroid. How does the centroid divide each median?', '["into two pieces in the ratio $2 : 1$, the longer piece next to the side","into two pieces in the ratio $2 : 1$, the longer piece next to the vertex","into two equal pieces, each half of the median","into two pieces in the ratio $3 : 1$, the longer piece next to the vertex"]', 'into two pieces in the ratio $2 : 1$, the longer piece next to the vertex', NULL, 'The centroid is two thirds of the way along every median, measured from the vertex. So the piece next to the vertex is twice the piece next to the opposite side. The other statements reverse the pieces, split the median in half, or use the wrong ratio.', 'checked', '{"lint":[],"solve":{"answer":"into two pieces in the ratio $2 : 1$, the longer piece next to the vertex","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Centroid is 2/3 of the way from vertex to midpoint: ratio 2:1, longer piece at the vertex.","run_id":"claude-code","at":"2026-10-22T19:24:42.964Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03b23095-8334-4003-a06d-c1e119893a2c', 'GEO.07', 1, 'numeric', 'Angle bisector theorem', 'In triangle $ABC$, point $D$ is on side $BC$ and $AD$ bisects angle $A$. If $AB = 6$, $AC = 9$ and $BD = 4$, what is $DC$?', '[]', '6', '4*9/6', 'By the angle bisector theorem, $\frac{BD}{DC} = \frac{AB}{AC}$. So $\frac{4}{DC} = \frac{6}{9}$, which gives $DC = \frac{4 \times 9}{6} = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angle bisector theorem: BD/DC = AB/AC = 6/9, so DC = 4 * 9/6 = 6.","run_id":"claude-code","at":"2026-10-22T19:24:42.964Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03c369c5-4a33-40e7-845c-5950764c6cf8', 'GEO.07', 1, 'choice', 'Angle bisectors', 'In triangle $ABC$, the line $AD$ bisects angle $A$ and angle $BAD$ measures $28^\circ$. What is the measure of angle $BAC$, in degrees?', '["28","14","62","56"]', '56', '2*28', 'The bisector makes two equal angles, so angle $BAC = 2 \cdot 28^\circ = 56^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"56","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"BAC = 2(28) = 56.","run_id":"claude-code","at":"2026-10-23T00:18:54.342Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08349bbd-bb98-474c-8b0c-81af3aa7c021', 'GEO.07', 2, 'choice', 'Angle bisectors', 'In triangle $ABC$, angle $A$ is $80^\circ$ and angle $B$ is $60^\circ$. The bisector of angle $C$ meets side $AB$ at $D$. What is the measure of angle $ACD$?', '["$40^\\circ$","$30^\\circ$","$50^\\circ$","$20^\\circ$"]', '$20^\circ$', NULL, 'Angle $C = 180 - 80 - 60 = 40$ degrees. The bisector cuts it into two angles of $20^\circ$, so angle $ACD = 20^\circ$. The $40^\circ$ is the whole angle $C$, the $30^\circ$ is half of angle $B$, and the $50^\circ$ is half of $180 - 80$.', 'checked', '{"lint":[],"solve":{"answer":"$20^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 180 - 80 - 60 = 40; ACD = 20.","run_id":"claude-code","at":"2026-10-22T19:24:42.964Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e583c5d-2e6a-4f33-95c4-af54626f1b7f', 'GEO.07', 2, 'numeric', 'The incenter and inradius', 'The incenter $I$ of triangle $ABC$ is the point where the angle bisectors meet. Angle $IAB$ is $25^\circ$ and angle $IBA$ is $35^\circ$. What is the measure of angle $ACB$, in degrees?', '[]', '60', '180-50-70', '$AI$ bisects angle $A$, so angle $A = 2 \times 25 = 50$ degrees. $BI$ bisects angle $B$, so angle $B = 2 \times 35 = 70$ degrees. Then angle $ACB = 180 - 50 - 70 = 60$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = 2*25 = 50, B = 2*35 = 70, C = 180 - 120 = 60.","run_id":"claude-code","at":"2026-10-22T19:24:42.964Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('009b3452-20f2-4e96-b942-b11b4250a725', 'GEO.07', 2, 'choice', 'Medians and the centroid', 'The medians $AD$ and $BE$ of triangle $ABC$ meet at $G$. The lengths $AG = 12$ and $BG = 10$ are given in centimeters. What is $DG + EG$, in centimeters?', '["22","11","33","5.5"]', '11', '12/2+10/2', 'The centroid cuts each median $2:1$, so $DG = \frac{1}{2} \cdot 12 = 6$ and $EG = \frac{1}{2} \cdot 10 = 5$. Then $DG + EG = 11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"DG = AG/2 = 6, EG = BG/2 = 5; sum 11.","run_id":"claude-code","at":"2026-10-23T00:18:54.342Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06fb2da2-4fdf-4c77-9638-c994c6cc99a8', 'GEO.07', 3, 'choice', 'The circumcenter', 'A triangle has sides of length 7, 8 and 12 centimeters. Where is its circumcenter?', '["inside the triangle","outside the triangle","at the midpoint of the longest side","at one of the vertices"]', 'outside the triangle', NULL, 'The circumcenter is inside an acute triangle, at the midpoint of the hypotenuse of a right triangle, and outside an obtuse triangle. Here $7^2 + 8^2 = 113$ is less than $12^2 = 144$, so the angle opposite the side of length 12 is obtuse, and the circumcenter is outside the triangle.', 'checked', '{"lint":[],"solve":{"answer":"outside the triangle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12^2 = 144 > 7^2 + 8^2 = 113, so the triangle is obtuse and the circumcenter lies outside. Triangle exists (7 + 8 > 12).","run_id":"claude-code","at":"2026-10-22T19:24:42.964Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0411abbc-09fb-4d99-95ce-405ba53fa438', 'GEO.07', 3, 'choice', 'Altitudes', 'A right triangle has legs of 6 centimeters and 8 centimeters. What is the sum of the lengths of its three altitudes, in centimeters?', '["14","18.8","24","23.6"]', '18.8', '6+8+6*8/10', 'Two altitudes are the legs, 6 and 8. The hypotenuse is 10 and the altitude to it is $\frac{6 \cdot 8}{10} = 4.8$. The sum is $6 + 8 + 4.8 = 18.8$.', 'checked', '{"lint":[],"solve":{"answer":"18.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Altitudes: legs 8 and 6, and to hypotenuse 48/10 = 4.8. Sum 18.8.","run_id":"claude-code","at":"2026-10-23T00:18:54.342Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1eb5ca99-b2a8-46d9-8753-4e2a71a3e157', 'GEO.08', 1, 'numeric', 'rectangle and square: diagonals, perimeter and area', 'A rectangle is 9 cm long and 12 cm wide. How long is its diagonal, in centimeters?', '[]', '15', '15', 'The diagonal is the hypotenuse of a right triangle with legs 9 and 12. Its length is $\sqrt{9^2 + 12^2} = \sqrt{225} = 15$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(81 + 144) = sqrt(225) = 15.","run_id":"claude-code","at":"2026-10-22T19:24:43.010Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11aa26cc-e6a4-4a8b-b022-de1b511462d0', 'GEO.08', 1, 'choice', 'rhombus: sides, diagonals and area', 'A rhombus has diagonals that are 6 cm and 8 cm long. What is its area, in square centimeters?', '["48","14","10","24"]', '24', '6*8/2', 'The area of a rhombus is half the product of its diagonals: $\frac{1}{2} \times 6 \times 8 = 24$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area = d1*d2/2 = 48/2 = 24.","run_id":"claude-code","at":"2026-10-22T19:24:43.010Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('245aace2-4cc1-42d9-b4b3-50b0dbc471ba', 'GEO.08', 1, 'choice', 'classifying quadrilaterals', 'A quadrilateral has four right angles. Which of these must it be?', '["a square","a rhombus","a kite","a rectangle"]', 'a rectangle', NULL, 'Four right angles make a rectangle. It need not be a square, because the sides may differ, and it need not be a rhombus or a kite.', 'checked', '{"lint":[],"solve":{"answer":"a rectangle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Four right angles: a rectangle (not necessarily a square).","run_id":"claude-code","at":"2026-10-23T00:18:54.382Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('121bab2d-6f13-47ce-9bef-faf792be948e', 'GEO.08', 2, 'choice', 'rhombus: sides, diagonals and area', 'In rhombus $ABCD$, angle $ABC$ measures $100^\circ$. The diagonal $AC$ is drawn. What is the measure of angle $BAC$, in degrees?', '["40","80","50","100"]', '40', '(180-100)/2', 'Adjacent angles of a rhombus add to $180^\circ$, so angle $BAD = 80^\circ$. A diagonal of a rhombus bisects its angles, so angle $BAC = 40^\circ$. (Also, triangle $ABC$ is isosceles, so angle $BAC = \frac{180^\circ - 100^\circ}{2}$.)', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Triangle ABC is isosceles (AB = BC): BAC = (180 - 100)/2 = 40.","run_id":"claude-code","at":"2026-10-23T00:18:54.382Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0dda64a1-9733-415e-b36b-0d5a1fb608ad', 'GEO.08', 2, 'numeric', 'trapezoid: area and midsegment', 'A trapezoid has an area of 90 square centimeters and a height of 6 centimeters. One of its parallel sides is 12 centimeters long. How long is the other parallel side, in centimeters?', '[]', '18', '2*90/6-12', '$\frac{1}{2}(12 + b) \cdot 6 = 90$, so $12 + b = 30$ and $b = 18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(12 + b)/2 x 6 = 90, b = 18.","run_id":"claude-code","at":"2026-10-23T00:18:54.382Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a25cf26-95d4-459a-8a4a-0b3418878dfe', 'GEO.08', 2, 'choice', 'kite: properties and area', 'The diagonals of a kite are perpendicular. One of them is twice as long as the other, and the area of the kite is 100 square centimeters. How long is the longer diagonal, in centimeters?', '["10","25","40","20"]', '20', '2*10', 'If the shorter diagonal is $d$, the area is $\frac{1}{2} \cdot d \cdot 2d = d^2 = 100$, so $d = 10$ and the longer diagonal is 20.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d(2d)/2 = 100, d = 10; longer 20.","run_id":"claude-code","at":"2026-10-23T00:18:54.382Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05bd80a1-2a27-42f1-97c7-9d40dd0ae43f', 'GEO.08', 3, 'numeric', 'kite: properties and area', 'In kite $ABCD$, $AB = AD$ and $CB = CD$. Angle $A$ measures $50^\circ$ and angle $B$ measures $100^\circ$. What is the measure of angle $C$, in degrees?', '[]', '110', '360-50-2*100', 'The kite is symmetric about diagonal $AC$, so angle $D$ equals angle $B$, which is $100^\circ$. The four angles add up to $360^\circ$, so angle $C = 360 - 50 - 100 - 100 = 110$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"110","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB = AD, CB = CD: angles B and D are equal, D = 100. C = 360 - 50 - 100 - 100 = 110.","run_id":"claude-code","at":"2026-10-22T19:24:43.010Z"}}', 'ai', NULL, NULL)
