INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d8d973a-cf8e-4400-839c-a024e10c4bed', 'GEO.08', 3, 'numeric', 'parallelogram: area', 'In parallelogram $ABCD$, $AB = 20$ and $AD = 13$ centimeters. The altitude from $D$ meets $AB$ at $E$, and $AE = 5$ centimeters. What is the area of the parallelogram, in square centimeters?', '[]', '240', '20*12', 'In right triangle $AED$, the height is $DE = \sqrt{13^2 - 5^2} = 12$. The area is $AB \cdot DE = 20 \cdot 12 = 240$.', 'checked', '{"lint":[],"solve":{"answer":"240","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"DE = sqrt(169 - 25) = 12; area = 20 x 12 = 240.","run_id":"claude-code","at":"2026-10-23T00:18:54.382Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1edec842-7c6d-4d13-b4b0-e78b15791627', 'GEO.09', 1, 'choice', 'Interior angle sum', 'What is the sum of the interior angles of a convex nonagon (a polygon with 9 sides), in degrees?', '["1260","1440","1620","1080"]', '1260', '180*(9-2)', 'The sum is $180(n-2)$ with $n = 9$, so $180 \times 7 = 1260$ degrees. Using $n - 1$ gives $1440$, using $n$ gives $1620$, and $1080$ is the sum for 8 sides.', 'checked', '{"lint":[],"solve":{"answer":"1260","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(9-2)*180 = 7*180 = 1260.","run_id":"claude-code","at":"2026-10-22T19:44:15.451Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15c8a14a-8933-45ce-a888-57a6e4e09ec1', 'GEO.09', 1, 'choice', 'Regular polygons', 'Which regular polygon has an interior angle of $90^\circ$ at every vertex?', '["a square","an equilateral triangle","a regular pentagon","a regular hexagon"]', 'a square', NULL, 'The interior angle of a regular polygon with $n$ sides is $180 - 360/n$. For $n = 4$ this is $90$. A triangle has $60^\circ$ angles, a pentagon $108^\circ$ and a hexagon $120^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"a square","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Interior 90 means exterior 90, n = 360/90 = 4: a square.","run_id":"claude-code","at":"2026-10-22T19:44:15.451Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('13547fef-4eac-47b5-9ee0-6771b8e9b8a0', 'GEO.09', 1, 'numeric', 'Regular polygons', 'A regular polygon has 10 sides, and each of its interior angles measures $144^\circ$. What do all of its interior angles add up to, in degrees?', '[]', '1440', '10*144', 'There are 10 equal angles, so the sum is $10 \times 144 = 1440$ degrees. This agrees with $180 \times (10 - 2) = 1440$.', 'checked', '{"lint":[],"solve":{"answer":"1440","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10*144 = 1440 (also (10-2)*180 = 1440).","run_id":"claude-code","at":"2026-10-22T19:44:15.451Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c7519a9-cb05-4df4-89e5-3a3aa09b070f', 'GEO.09', 2, 'choice', 'Exterior angles', 'The interior angles of a convex quadrilateral are $70^\circ$, $90^\circ$, $110^\circ$ and $90^\circ$. Which list gives its exterior angles, in the same order?', '["$70^\\circ, 90^\\circ, 110^\\circ, 90^\\circ$","$110^\\circ, 90^\\circ, 70^\\circ, 90^\\circ$","$290^\\circ, 270^\\circ, 250^\\circ, 270^\\circ$","$90^\\circ, 90^\\circ, 90^\\circ, 90^\\circ$"]', '$110^\circ, 90^\circ, 70^\circ, 90^\circ$', NULL, 'At each vertex the exterior angle is $180$ minus the interior angle: $110, 90, 70, 90$. These add up to $360$, as exterior angles must.', 'checked', '{"lint":[],"solve":{"answer":"$110^\\circ, 90^\\circ, 70^\\circ, 90^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exterior = 180 - interior: 110, 90, 70, 90.","run_id":"claude-code","at":"2026-10-22T19:44:15.451Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e2cf463-1a5e-41f5-b8db-2e99314f1127', 'GEO.09', 2, 'numeric', 'Exterior angles', 'A robot walks around the boundary of a convex polygon, turning left through the exterior angle at each corner. It makes turns of $75^\circ$, $75^\circ$ and $90^\circ$, and all its other turns are $40^\circ$. How many turns of $40^\circ$ does it make?', '[]', '3', '(360-(75+75+90))/40', 'The turns of a full trip around the polygon add up to $360^\circ$. The three known turns total $240$, which leaves $120$ for the $40^\circ$ turns. $120 \div 40 = 3$ turns.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total turning = 360. 360-(75+75+90) = 120; 120/40 = 3.","run_id":"claude-code","at":"2026-10-22T19:44:15.451Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ab908ca-1130-42bd-aa8a-fc329586b557', 'GEO.09', 2, 'choice', 'Diagonals', 'Which convex polygon has exactly 14 diagonals?', '["a hexagon (6 sides)","an octagon (8 sides)","a heptagon (7 sides)","a nonagon (9 sides)"]', 'a heptagon (7 sides)', NULL, 'The number of diagonals of an $n$-sided polygon is $\frac{n(n-3)}{2}$. For 7 sides this is $\frac{7 \times 4}{2} = 14$. The other shapes have 9, 20 and 27 diagonals.', 'checked', '{"lint":[],"solve":{"answer":"a heptagon (7 sides)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n(n-3)/2 = 14 gives n(n-3) = 28, n = 7 (heptagon). Hexagon 9, octagon 20, nonagon 27.","run_id":"claude-code","at":"2026-10-22T19:44:15.451Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01f8fc54-b3a6-4d8e-8800-514e46d9a63d', 'GEO.09', 3, 'numeric', 'Area of a regular hexagon', 'Regular hexagon $ABCDEF$ has an area of 90 square units. Segments $BD$, $DF$ and $FB$ are drawn, forming triangle $BDF$. What is the area of triangle $BDF$, in square units?', '[]', '45', '90/2', 'Let each side of the hexagon be $s$. The hexagon has area $6 \cdot \frac{s^2\sqrt{3}}{4}$. Triangle $BDF$ is equilateral with side $s\sqrt{3}$, so its area is $\frac{3s^2\sqrt{3}}{4}$, which is half the hexagon. So its area is $90 \div 2 = 45$.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Triangle BDF is equilateral with side s sqrt3, area (sqrt3/4)(3s^2) = (3 sqrt3/4) s^2, exactly half the hexagon''s (3 sqrt3/2) s^2. 90 / 2 = 45.","run_id":"claude-code","at":"2026-10-22T12:48:17.133Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('022569a3-f08e-4901-bfe0-afd44de53323', 'GEO.09', 3, 'numeric', 'Interior angle sum', 'One interior angle of a convex polygon is left out. All the other interior angles add up to $1750^\circ$. What does the left-out angle measure, in degrees?', '[]', '50', '1800-1750', 'The full sum is a multiple of $180$, and the missing angle is more than $0$ and less than $180$ because the polygon is convex. So the full sum is between $1750$ and $1930$. The only multiple of $180$ there is $1800$, so the missing angle is $1800 - 1750 = 50$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The full sum is a multiple of 180 above 1750 by between 0 and 180: 1800 (n=12). Left-out angle = 50.","run_id":"claude-code","at":"2026-10-22T19:44:15.451Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('064fc520-9780-4c7f-a870-506b9012cbe7', 'GEO.10', 1, 'choice', 'Angles from the sides: the largest angle is opposite the longest side', 'In triangle $XYZ$, $XY = 5$, $YZ = 5$ and $ZX = 8$. Which statement is true?', '["$\\angle X$ is the largest angle","$\\angle Z$ is the largest angle","$\\angle Y$ is the largest angle","$\\angle X$ is larger than $\\angle Z$"]', '$\angle Y$ is the largest angle', NULL, 'The longest side is $ZX=8$, and the angle opposite it is $\angle Y$, so $\angle Y$ is the largest. The sides $XY$ and $YZ$ are equal, so the angles opposite them, $\angle Z$ and $\angle X$, are equal.', 'checked', '{"lint":[],"solve":{"answer":"$\\angle Y$ is the largest angle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"ZX = 8 is the longest side, opposite angle Y, so angle Y is the largest. XY = YZ, so angles X and Z are equal (option 1 false).","run_id":"claude-code","at":"2026-10-22T12:51:57.239Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f482bcc-614a-4269-9259-785423aca2d7', 'GEO.10', 1, 'numeric', 'Sides from the angles: the longest side is opposite the largest angle', 'In triangle $ABC$, $\angle A < \angle B < \angle C$. The sides $AB$, $BC$ and $CA$ have lengths 5 cm, 7 cm and 9 cm in some order. What is the length of $BC$, in centimeters?', '[]', '5', '5', 'The shortest side is opposite the smallest angle. The smallest angle is $\angle A$, and the side opposite it is $BC$, so $BC$ is the shortest side, $5$ cm.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angle A smallest, so the side opposite it, BC, is the shortest: 5.","run_id":"claude-code","at":"2026-10-22T19:44:15.492Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a5d5018-fe2a-4e94-9bca-d66ab12a29eb', 'GEO.10', 1, 'choice', 'Distances and routes', 'Towns $A$, $B$ and $C$ do not lie on one straight line. The straight road from $A$ to $B$ is 5 km long and the straight road from $B$ to $C$ is 6 km long. Which could be the straight-line distance from $A$ to $C$?', '["3 km","11 km","12 km","1 km"]', '3 km', NULL, 'The direct distance from $A$ to $C$ is less than the trip through $B$, which is $5 + 6 = 11$ km, and more than the difference $6 - 5 = 1$ km. Only 3 km is between $1$ and $11$. A distance of 11 km or 1 km would need the three towns to be on one line, and 12 km is longer than the trip through $B$.', 'checked', '{"lint":[],"solve":{"answer":"3 km","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Not collinear, so strict triangle inequality: 6-5 < AC < 6+5, i.e. 1 < AC < 11. 12 too big, 11 and 1 would need collinear towns, 3 works.","run_id":"claude-code","at":"2026-10-23T00:30:06.000Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17456379-c674-4865-84fe-0e9d86160623', 'GEO.10', 2, 'choice', 'Whole-number third sides', 'Two sides of a triangle are 5 cm and 12 cm, and the third side is a whole number of centimeters. Which of these lengths is NOT possible for the third side?', '["6","8","12","16"]', '6', NULL, 'The third side must be greater than $12 - 5 = 7$ and less than $12 + 5 = 17$. The lengths $8$, $12$ and $16$ are in that range. The length $6$ is not.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 < x < 17: 6 is not possible.","run_id":"claude-code","at":"2026-10-22T19:44:15.492Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1845f655-bc00-4a2a-a337-ff922d9b468e', 'GEO.10', 2, 'numeric', 'Whole-number third sides', 'An isosceles triangle has whole-number side lengths and a perimeter of 20. How many different triangles are possible? Triangles with the same three side lengths count as one.', '[]', '4', '4', 'Let the two equal sides be $a$, so the third side is $20 - 2a$. It must be positive, so $a < 10$, and the two equal sides must be longer than it, so $2a > 20 - 2a$ and $a > 5$. So $a = 6, 7, 8, 9$, giving triangles $6,6,8$; $7,7,6$; $8,8,4$; $9,9,2$. That is $4$ triangles.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Legs a, base 20-2a with 0 < 20-2a < 2a -> 5 < a < 10: (6,6,8), (7,7,6), (8,8,4), (9,9,2). 4.","run_id":"claude-code","at":"2026-10-22T19:44:15.492Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('24bceb08-27e9-4d0b-8854-da9c594dc995', 'GEO.10', 2, 'choice', 'Triangle inequality with algebraic sides', 'A triangle has sides of lengths 8, $2x$ and 12. Which describes all the possible values of $x$?', '["$4 < x < 20$","$4 < x < 10$","$2 < x < 10$","$2 < x < 20$"]', '$2 < x < 10$', NULL, 'The side $2x$ must be greater than $12 - 8 = 4$ and less than $12 + 8 = 20$. Dividing by $2$ gives $2 < x < 10$. The option $4 < x < 20$ describes $2x$, not $x$.', 'checked', '{"lint":[],"solve":{"answer":"$2 < x < 10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 < 2x < 20 -> 2 < x < 10.","run_id":"claude-code","at":"2026-10-22T19:44:15.492Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15bb0ee6-5cf7-46ad-9619-c8fe103500bd', 'GEO.10', 3, 'choice', 'Can three lengths form a triangle?', 'Which statement is true for every positive number $x$, about three sticks of lengths $x$, $x$ and $2x$?', '["They can never form a triangle","They always form a triangle","They form a triangle only when $x$ is greater than 2","They form a triangle only when $x$ is a whole number"]', 'They can never form a triangle', NULL, 'The two shorter sticks add up to $x + x = 2x$, which equals the longest stick and is never greater than it. So the sticks would lie flat along a line, whatever $x$ is.', 'checked', '{"lint":[],"solve":{"answer":"They can never form a triangle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + x = 2x, not greater than 2x: never a triangle.","run_id":"claude-code","at":"2026-10-22T19:44:15.492Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08930a35-a876-486c-bfe9-23053f6dc08d', 'GEO.10', 3, 'choice', 'Triangle inequality with algebraic sides', 'A triangle has sides of lengths $x$, $14 - x$ and 14. Which statement is true?', '["No such triangle exists for any value of $x$","A triangle exists for every $x$ with $0 < x < 14$","A triangle exists only when $x = 7$","A triangle exists for every $x$ with $7 < x < 14$"]', 'No such triangle exists for any value of $x$', NULL, 'The first two sides add up to $x + (14 - x) = 14$, which equals the third side and is never greater than it. So the three lengths can never form a triangle.', 'checked', '{"lint":[],"solve":{"answer":"No such triangle exists for any value of $x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + (14 - x) = 14 is never greater than 14, so no triangle exists.","run_id":"claude-code","at":"2026-10-22T19:44:15.492Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ae2ba7d-93f6-4364-bbad-4d1d506f163e', 'GEO.11', 1, 'choice', 'Area of a circle', 'A circular rug has a diameter of 10 feet. What is its area, in square feet?', '["$25\\pi$","$100\\pi$","$10\\pi$","$50\\pi$"]', '$25\pi$', NULL, 'The radius is $10 \div 2 = 5$ feet, so the area is $\pi r^2 = 25\pi$ square feet. ($100\pi$ uses the diameter as the radius, and $10\pi$ is the circumference.)', 'checked', '{"lint":[],"solve":{"answer":"$25\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r = 5, area = 25*pi.","run_id":"claude-code","at":"2026-10-22T12:59:41.236Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0133b2bc-16a7-4c34-83e3-d74aadb03c2e', 'GEO.11', 1, 'choice', 'Area of a circle', 'A circle has a radius of 3 meters. What is its area, in square meters?', '["$9\\pi$","$6\\pi$","$3\\pi$","$18\\pi$"]', '$9\pi$', NULL, 'The area is $\pi r^2 = \pi \times 3^2 = 9\pi$ square meters. ($6\pi$ is the circumference, not the area.)', 'checked', '{"lint":[],"solve":{"answer":"$9\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = pi(3^2) = 9pi.","run_id":"claude-code","at":"2026-10-22T19:45:14.053Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('008d1a4e-ce0f-4b8d-aacd-58223a8e696e', 'GEO.11', 1, 'numeric', 'Tangent lines', 'From a point $P$ outside a circle, two tangent segments $\overline{PA}$ and $\overline{PB}$ touch the circle at $A$ and $B$. If $PA = 9$ cm, how long is $PB$, in centimeters?', '[]', '9', '9', 'Tangent segments drawn from the same outside point to a circle are equal in length, so $PB = PA = 9$ cm.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tangent segments from an external point are equal: PB = PA = 9.","run_id":"claude-code","at":"2026-10-22T19:45:14.053Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e015c10-7ad3-449f-9c00-053c006cc61c', 'GEO.11', 2, 'numeric', 'Circumference', 'Circle $A$ has a circumference three times as large as the circumference of circle $B$. Circle $B$ has a radius of 5 cm. What is the radius of circle $A$, in centimeters?', '[]', '15', '5*3', 'Circumference is proportional to radius ($C = 2\pi r$), so tripling the circumference triples the radius: $3 \times 5 = 15$ cm.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Circumference is proportional to radius: r_A = 3(5) = 15.","run_id":"claude-code","at":"2026-10-22T19:45:14.053Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21635d03-dadc-46f6-b75a-930feff01b20', 'GEO.11', 2, 'choice', 'Sectors', 'A circle has an area of $84\pi$ square centimeters. A sector of the circle has an area of $14\pi$ square centimeters. What is the measure of its central angle, in degrees?', '["$60$","$30$","$120$","$14$"]', '$60$', '14/84*360', 'The sector is $\frac{14\pi}{84\pi} = \frac{1}{6}$ of the circle, so its central angle is $\frac{1}{6} \times 360 = 60$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"$60$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14pi/84pi = 1/6 of 360 = 60.","run_id":"claude-code","at":"2026-10-22T19:45:14.053Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('173532a7-7e37-42f8-bc4b-46bde541eace', 'GEO.11', 2, 'choice', 'Tangent lines', 'The line $PT$ is tangent at $T$ to a circle with center $O$, and $\angle TOP = 40^\circ$. What is the measure of $\angle OPT$, in degrees?', '["$40$","$140$","$50$","$90$"]', '$50$', '90-40', 'The radius $OT$ is perpendicular to the tangent, so $\angle OTP = 90^\circ$. The angles of triangle $OTP$ add to $180^\circ$: $\angle OPT = 180 - 90 - 40 = 50^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"$50$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angle OTP = 90, so angle OPT = 180 - 90 - 40 = 50.","run_id":"claude-code","at":"2026-10-22T19:45:14.053Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b8b58e5-ba8b-4ab3-8635-986802811a3a', 'GEO.11', 3, 'choice', 'Area of a circle', 'Two circles have radii 3 and 4. A third circle has an area equal to the sum of the areas of the first two. What is the radius of the third circle?', '["$5$","$7$","$3.5$","$25$"]', '$5$', NULL, 'The areas are $9\pi$ and $16\pi$, with sum $25\pi$. So $\pi r^2 = 25\pi$ and $r = 5$. (Radii do not simply add, and 25 is the radius squared.)', 'checked', '{"lint":[],"solve":{"answer":"$5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9pi + 16pi = 25pi, r = 5.","run_id":"claude-code","at":"2026-10-22T19:45:14.053Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08d9f876-d377-4474-b7a8-d490f0bbf0ef', 'GEO.11', 3, 'choice', 'Sectors', 'Two diameters of a circle of radius 8 cross at an angle of $60^\circ$. They cut the circle into four sectors: two with central angle $60^\circ$ and two with central angle $120^\circ$. What is the combined area of the two sectors with central angle $60^\circ$, in square centimeters?', '["$\\frac{32\\pi}{3}$","$\\frac{128\\pi}{3}$","$32\\pi$","$\\frac{64\\pi}{3}$"]', '$\frac{64\pi}{3}$', NULL, 'The circle has area $64\pi$. Each $60^\circ$ sector is $\frac{1}{6}$ of it, $\frac{64\pi}{6}$, so the two together are $\frac{64\pi}{3}$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{64\\pi}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each 60-degree sector = (1/6)(64pi); two = 64pi/3.","run_id":"claude-code","at":"2026-10-22T19:45:14.053Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('035f0bf8-5dbc-49ee-8934-05074ddd5046', 'GEO.12', 1, 'numeric', 'Inscribed quadrilaterals', 'Quadrilateral ABCD is inscribed in a circle, which means all four of its vertices are on the circle. If $\angle A = 100^\circ$, what is the measure, in degrees, of $\angle C$, the angle opposite A?', '[]', '80', '180-100', 'Opposite angles of an inscribed quadrilateral add up to $180^\circ$. So $\angle C = 180 - 100 = 80$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Opposite angles of a cyclic quadrilateral sum to 180: 180 - 100 = 80.","run_id":"claude-code","at":"2026-10-22T19:21:45.650Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1fb5a368-e624-4102-9298-bc7ab3f8266f', 'GEO.12', 1, 'numeric', 'Tangents: tangent-chord angle and tangent-radius', 'Line PT is tangent at the point T to a circle with center O, and $\angle OPT = 35^\circ$. What is the measure, in degrees, of $\angle POT$?', '[]', '55', '90-35', 'A tangent is perpendicular to the radius at the point of tangency, so $\angle OTP = 90^\circ$. The angles of triangle OPT add up to $180^\circ$, so $\angle POT = 180 - 90 - 35 = 55$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Radius OT is perpendicular to the tangent, so angle OTP = 90; angle POT = 180 - 90 - 35 = 55.","run_id":"claude-code","at":"2026-10-22T19:21:45.650Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f9b05de-a7b0-4f86-b7c0-d0cac591250f', 'GEO.12', 1, 'numeric', 'Angles formed by secants and tangents outside a circle', 'Two secants meet at a point $P$ outside a circle. Between them they cut off a far arc of $150^\circ$ and a near arc of $50^\circ$. What is the measure of the angle at $P$, in degrees?', '[]', '50', '(150-50)/2', 'The angle is half the difference of the far and near arcs: $\frac{150 - 50}{2} = 50^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(150 - 50)/2 = 50.","run_id":"claude-code","at":"2026-10-22T19:45:14.102Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0863b755-a12a-4d49-9161-a0b94115fcf7', 'GEO.12', 2, 'choice', 'Inscribed quadrilaterals', 'Quadrilateral ABCD is inscribed in a circle. Its angle $\angle A$ measures $(2x)^\circ$ and the opposite angle $\angle C$ measures $(x + 30)^\circ$. What is the measure, in degrees, of $\angle A$?', '["$100$","$50$","$80$","$60$"]', '$100$', '100', 'Opposite angles of an inscribed quadrilateral add up to $180^\circ$: $2x + (x + 30) = 180$, so $3x = 150$ and $x = 50$. Then $\angle A = 2(50) = 100$ degrees. (50 is $x$, 80 is $\angle C$, and 60 comes from wrongly setting the two angles equal.)', 'checked', '{"lint":[],"solve":{"answer":"$100$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x + (x + 30) = 180 -> x = 50; angle A = 100 (C = 80).","run_id":"claude-code","at":"2026-10-22T19:21:45.650Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a5a85df-be31-4178-8f2c-bcdd9ee124ef', 'GEO.12', 2, 'choice', 'Central angles and arcs', 'A regular octagon $ABCDEFGH$ is inscribed in a circle. What is the measure, in degrees, of arc $AC$ that contains $B$?', '["$45$","$135$","$90$","$180$"]', '$90$', '2*360/8', 'The 8 vertices split the circle into 8 equal arcs of $360 \div 8 = 45^\circ$. Arc $AC$ is made of arcs $AB$ and $BC$, so it measures $2 \times 45 = 90^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"$90$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each arc 360/8 = 45; arc AC through B = 90.","run_id":"claude-code","at":"2026-10-22T19:45:14.102Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b5b719d-9e83-403b-aebc-94b84fadffe9', 'GEO.12', 2, 'choice', 'Angles formed by secants and tangents outside a circle', 'Two tangents from a point $P$ outside a circle touch it at $A$ and $B$, and $\angle APB = 40^\circ$. What is the measure of the minor arc $AB$, in degrees?', '["$40$","$140$","$70$","$220$"]', '$140$', '180-40', 'With minor arc $m$ and major arc $360 - m$: $40 = \frac{(360 - m) - m}{2} = 180 - m$, so $m = 140^\circ$. (The major arc is $220^\circ$.)', 'checked', '{"lint":[],"solve":{"answer":"$140$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angle P = 180 - minor arc, so minor arc = 140 (major 220, (220-140)/2 = 40).","run_id":"claude-code","at":"2026-10-22T19:45:14.102Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06dc9f18-ef8c-49c2-b1b7-4666901e4090', 'GEO.12', 3, 'numeric', 'Tangents: tangent-chord angle and tangent-radius', 'A circle has center O and radius 6. Point P is outside the circle with OP = 10, and PT is tangent to the circle at T. How long is PT?', '[]', '8', '8', 'The tangent PT is perpendicular to the radius OT, so triangle OTP has a right angle at T, with hypotenuse $OP = 10$ and leg $OT = 6$. Then $PT^2 = 10^2 - 6^2 = 64$, so $PT = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"OT perpendicular to PT: PT = sqrt(100 - 36) = 8.","run_id":"claude-code","at":"2026-10-22T19:21:45.650Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17ba960c-d272-44eb-a6e2-6fffda76c500', 'GEO.12', 3, 'numeric', 'Central angles and arcs', 'Twelve points are equally spaced around a circle and numbered 1 to 12 in order. What is the measure, in degrees, of the smaller central angle between the center-to-point segments for point 3 and point 8?', '[]', '150', '5*30', 'Neighboring points are $360 \div 12 = 30^\circ$ apart. From point 3 to point 8 is 5 steps, which is $5 \times 30 = 150^\circ$. (Going the other way is 7 steps, $210^\circ$, which is larger.)', 'checked', '{"lint":[],"solve":{"answer":"150","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 steps of 30 degrees = 150.","run_id":"claude-code","at":"2026-10-22T19:45:14.102Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16b25ba0-8e7f-4f73-bceb-4e7e6e3fcaec', 'GEO.13', 1, 'choice', 'Intersecting chords', 'In a circle, chord $AB$ and chord $CD$ cross at the point $P$. The pieces of the first chord are $AP = 2$ and $PB = 9$, and $CP = 6$. What is the length of $PD$?', '["$5$","$3$","$12$","$27$"]', '$3$', '2*9/6', 'The products of the pieces are equal: $AP \cdot PB = CP \cdot PD$, so $2 \cdot 9 = 6 \cdot PD$ and $PD = \frac{18}{6} = 3$. (5 adds and subtracts instead of multiplying, 12 is $AP \cdot CP$, and 27 is $PB \cdot CP \div AP$.)', 'checked', '{"lint":[],"solve":{"answer":"$3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AP*PB = CP*PD: 2*9 = 18 = 6*PD, PD = 3.","run_id":"claude-code","at":"2026-10-22T19:28:49.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('23c6e5d9-5167-486a-969f-8b0d5edcb9dd', 'GEO.13', 1, 'numeric', 'Tangent and secant from a point', 'From a point $P$ outside a circle, the tangent segment $PT$ has length 6. A line through $P$ meets the circle at $A$ and then at $B$, with $PA = 4$. What is $PB$?', '[]', '9', '6*6/4', 'A tangent and a secant from one point satisfy $PT^2 = PA \cdot PB$. So $36 = 4 \cdot PB$ and $PB = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tangent-secant: PT^2 = PA*PB: 36 = 4*PB, PB = 9.","run_id":"claude-code","at":"2026-10-22T19:28:49.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('100a10af-d7b8-4fc2-9e15-2f352bf2e2f2', 'GEO.13', 1, 'numeric', 'Power of a point: radii, centers and mixed uses', 'The point $P$ is the center of a circle of radius 7. Two chords $AB$ and $CD$ both pass through $P$. What is $AP \cdot PB$?', '[]', '49', '7*7', 'A chord through the center is a diameter, so $P$ is the middle of $AB$ and $AP = PB = 7$. The product is $7 \cdot 7 = 49$. (It is the same for every chord through $P$, as the chord rule says.)', 'checked', '{"lint":[],"solve":{"answer":"49","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P is the center, so AP = PB = 7 (radii), AP*PB = 49 (power = r^2).","run_id":"claude-code","at":"2026-10-22T19:28:49.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0477b57a-6aef-4b3a-b6c6-fb69a6f97799', 'GEO.13', 2, 'choice', 'Two secants from a point', 'The point $P$ is outside a circle. A line from $P$ meets the circle at $A$ and then at $B$, with $PA = 5$ and $PB = 9$. A second line from $P$ meets it at $C$ and then at $D$, with $PC = 3$. What is the length of the chord $CD$?', '["$15$","$9$","$18$","$12$"]', '$12$', '5*9/3-3', '$PA \cdot PB = 45 = PC \cdot PD = 3 \cdot PD$, so $PD = 15$. The chord is $CD = 15 - 3 = 12$. (15 is $PD$ itself.)', 'checked', '{"lint":[],"solve":{"answer":"$12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5*9 = 45 = 3*PD, PD = 15, CD = 12.","run_id":"claude-code","at":"2026-10-23T00:22:07.967Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b507370-eede-45a1-a644-41aa8435fbc5', 'GEO.13', 2, 'numeric', 'Power of a point: radii, centers and mixed uses', 'A circle has radius 8 and center $O$, and the point $P$ is 17 from $O$. A line from $P$ meets the circle at $A$ and then at $B$, with $PA = 9$. What is $PB$?', '[]', '25', '(17*17-8*8)/9', 'The product is $(17 - 8)(17 + 8) = 9 \cdot 25 = 225$, the same for every line from $P$. So $9 \cdot PB = 225$ and $PB = 25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Power = 289 - 64 = 225 = 9*PB, PB = 25 (line through center).","run_id":"claude-code","at":"2026-10-23T00:22:07.967Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01e88036-5201-4174-b8b3-9f04f8667c4f', 'GEO.13', 2, 'numeric', 'Setting up the equation with an unknown length', 'Chords $AB$ and $CD$ cross at $P$ inside a circle. $AB = 12$ and $AP$ is shorter than $PB$. Also $CP = 4$ and $PD = 5$. How long is $AP$?', '[]', '2', '2', 'Let $AP = x$, so $PB = 12 - x$. Then $x(12 - x) = 4 \cdot 5 = 20$. Since $2 \cdot 10 = 20$, the pieces are 2 and 10, and the shorter one is $AP = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a(12 - a) = 20, a = 2 or 10; AP shorter so 2.","run_id":"claude-code","at":"2026-10-23T00:22:07.967Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01ce6565-2a37-49df-bcb6-9e5c68c4fe6b', 'GEO.13', 3, 'numeric', 'Intersecting chords', 'Chords $AB$ and $CD$ of a circle are perpendicular and cross at $P$. $AP = 2$, $PB = 8$ and $CP = 4$. What is the area of the quadrilateral $ACBD$, whose corners in order are $A$, $C$, $B$, $D$?', '[]', '40', '1/2*10*8', '$CP \cdot PD = AP \cdot PB = 16$, so $PD = 4$ and $CD = 8$. Also $AB = 10$. A quadrilateral with perpendicular diagonals has area $\frac{1}{2} \cdot AB \cdot CD = \frac{1}{2} \cdot 10 \cdot 8 = 40$.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"PD = 16/4 = 4. AB = 10, CD = 8, perpendicular diagonals of ACBD: area = 10*8/2 = 40.","run_id":"claude-code","at":"2026-10-23T00:22:07.967Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00c46f56-f2b5-48ff-b8ba-8beb6b4a9f8a', 'GEO.13', 3, 'numeric', 'Tangent and secant from a point', 'A tangent from the point $P$ touches a circle at $T$. A line from $P$ meets the circle at $A$ and then at $B$. $PT = 6$, $PA = 4$ and $TA = 5$. Triangles $PTA$ and $PBT$ are similar. How long is $TB$?', '[]', '7.5', '5*6/4', '$PT^2 = PA \cdot PB$ gives $PB = 9$. In the similar triangles $PTA$ and $PBT$, $\frac{TB}{TA} = \frac{PT}{PA}$, so $TB = 5 \cdot \frac{6}{4} = 7.5$.', 'checked', '{"lint":[],"solve":{"answer":"7.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"PTA ~ PBT (P-P, T-B, A-T): PT/PB = TA/BT = PA/PT = 4/6. PB = 9, TB = 5*6/4 = 7.5.","run_id":"claude-code","at":"2026-10-23T00:22:07.967Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ce03f30-4c4e-43d1-95c1-48ac31fec31d', 'GEO.14', 1, 'numeric', 'Volume of a rectangular box', 'A box is 5 cm long, 4 cm wide and 3 cm tall. What is its volume in cubic centimeters?', '[]', '60', '5*4*3', 'Volume = length x width x height = 5 x 4 x 3 = 60.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = 5 x 4 x 3 = 60.","run_id":"claude-code","at":"2026-10-22T19:28:03.719Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ceacab0-26fe-49d0-acaf-a961ef1f742f', 'GEO.14', 1, 'choice', 'Volume of a prism', 'A prism has a base that is a right triangle with legs 6 cm and 8 cm. The distance between its two triangular faces is 5 cm. What is its volume in cubic centimeters?', '["240","60","19","120"]', '120', '6*8/2*5', 'The base area is half of 6 x 8 = 24. Volume = base area x distance between the bases = 24 x 5 = 120.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base area = (1/2)(6)(8) = 24. V = 24 x 5 = 120.","run_id":"claude-code","at":"2026-10-22T19:28:03.719Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02c0559c-a852-4b3d-ac25-e95b09cdbe0b', 'GEO.14', 1, 'choice', 'Volume of a pyramid', 'A pyramid and a prism have the same base and the same height. The prism has a volume of 90 cubic centimeters. What is the volume of the pyramid, in cubic centimeters?', '["30","45","60","270"]', '30', '90/3', 'A pyramid holds one third of the volume of the prism with the same base and height: $90 \div 3 = 30$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One third of 90 = 30.","run_id":"claude-code","at":"2026-10-23T00:09:35.346Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09b6e083-4e5b-43de-a8c0-1d57951e07c6', 'GEO.14', 2, 'numeric', 'Diagonal of a box', 'A box is 8 cm long, 9 cm wide and 12 cm tall. How long, in centimeters, is the diagonal from one corner of the box to the opposite corner?', '[]', '17', '17', '$\sqrt{8^2 + 9^2 + 12^2} = \sqrt{64 + 81 + 144} = \sqrt{289} = 17$.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(64+81+144)=sqrt289=17.","run_id":"claude-code","at":"2026-10-23T00:09:35.346Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('205ba8e9-a524-4f87-8a70-9a3eadd5ac16', 'GEO.14', 2, 'choice', 'Diagonal of a box', 'A box is 2 inches by 10 inches by 11 inches. How long, in inches, is the longest straight rod that fits inside the box?', '["23","225","15","14"]', '15', NULL, 'The longest rod lies along the space diagonal: $\sqrt{2^2 + 10^2 + 11^2} = \sqrt{4 + 100 + 121} = \sqrt{225} = 15$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Space diagonal sqrt(4+100+121)=15.","run_id":"claude-code","at":"2026-10-23T00:09:35.346Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('237d9a46-bbd8-4476-821e-089d5fc9f9a9', 'GEO.14', 2, 'choice', 'Scaling and water-level problems', 'Every edge of a box is made half as long. By what factor does the volume of the box multiply?', '["$\\frac{1}{2}$","$\\frac{1}{4}$","$\\frac{1}{6}$","$\\frac{1}{8}$"]', '$\frac{1}{8}$', NULL, 'Length, width and height are each halved, so the volume is multiplied by $\frac{1}{2} \times \frac{1}{2} \times \frac{1}{2} = \frac{1}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1/2)^3=1/8.","run_id":"claude-code","at":"2026-10-23T00:09:35.346Z"}}', 'ai', NULL, NULL)
