INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1188cfac-e886-4af4-8df4-38af61bc61f6', 'GEO.14', 3, 'numeric', 'Surface area of a rectangular box', 'A box is twice as long as it is wide and is 3 cm tall. Its volume is 54 cubic centimeters. What is its surface area in square centimeters?', '[]', '90', '2*(6*3+6*3+3*3)', 'With width w, length 2w: volume = 2w x w x 3 = 6w^2 = 54, so w = 3 and the length is 6. The faces are 6x3 = 18, 6x3 = 18 and 3x3 = 9, each twice: 2 x 45 = 90.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"w(2w)(3) = 54, w^2 = 9, w = 3, l = 6. SA = 2(18 + 18 + 9) = 90.","run_id":"claude-code","at":"2026-10-22T19:28:03.719Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0aa284dc-9056-4bab-97fc-01a0ac5948d8', 'GEO.14', 3, 'choice', 'Surface area of a prism', 'A prism has a base that is a right triangle with sides 3 cm, 4 cm and 5 cm. The distance between its two triangular faces is 10 cm. What is its total surface area in square centimeters?', '["132","120","60","144"]', '132', '2*(3*4/2)+(3+4+5)*10', 'The two triangles have area 1/2 x 3 x 4 = 6 each, giving 12. The three rectangles have areas 3x10, 4x10 and 5x10, which add to (3 + 4 + 5) x 10 = 120. Total = 132.', 'checked', '{"lint":[],"solve":{"answer":"132","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two triangles: 2 x 6 = 12. Rectangles: (3 + 4 + 5) x 10 = 120. Total 132.","run_id":"claude-code","at":"2026-10-22T19:28:03.719Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e6a4481-65a2-415a-8cb6-87957f201daa', 'GEO.15', 1, 'choice', 'Cylinder volume', 'A soup can is a cylinder with radius 3 inches and height 4 inches. What is its volume, in cubic inches?', '["$24\\pi$","$12\\pi$","$144\\pi$","$36\\pi$"]', '$36\pi$', NULL, 'The volume is $\pi r^2 h = \pi \times 3^2 \times 4 = 36\pi$. The value $24\pi$ is the area of the curved side, $12\pi$ forgets to square the radius, and $144\pi$ squares $r \times h$.', 'checked', '{"lint":[],"solve":{"answer":"$36\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = pi x 9 x 4 = 36 pi.","run_id":"claude-code","at":"2026-10-22T12:48:17.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b8520ab-e54a-4d98-b865-c939e4103d3c', 'GEO.15', 1, 'choice', 'Cone surface area', 'A cone has a base of radius 6 centimeters and a slant height of 10 centimeters. What is the area of its curved surface, without the base, in square centimeters?', '["$120\\pi$","$60\\pi$","$360\\pi$","$16\\pi$"]', '$60\pi$', NULL, 'The area of the curved surface is $\pi r \ell = \pi \times 6 \times 10 = 60\pi$. The value $120\pi$ doubles it, $360\pi$ squares the radius, and $16\pi$ adds the radius and the slant height.', 'checked', '{"lint":[],"solve":{"answer":"$60\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"pi*6*10 = 60pi.","run_id":"claude-code","at":"2026-10-23T00:07:24.447Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('037a86d7-3092-4710-89c8-1d65ec3ab535', 'GEO.15', 1, 'choice', 'Combining and reversing', 'The radius of a cylinder is doubled and its height stays the same. By what number is its volume multiplied?', '["2","8","6","4"]', '4', '2^2', 'The volume is $\pi r^2 h$. Doubling $r$ multiplies $r^2$ by $2^2 = 4$, and $h$ does not change, so the volume is multiplied by 4. Doubling would be right if the height were doubled instead.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V proportional to r^2: factor 4.","run_id":"claude-code","at":"2026-10-23T00:07:24.447Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('214b3d41-9886-4e01-bf3c-2e79a2add953', 'GEO.15', 2, 'choice', 'Cone volume', 'A cone has a base with diameter 14 centimeters and a height of 12 centimeters. What is its volume, in cubic centimeters?', '["$588\\pi$","$196\\pi$","$784\\pi$","$168\\pi$"]', '$196\pi$', NULL, 'The radius is 7. The volume is $\frac{1}{3}\pi \times 49 \times 12 = 196\pi$. The value $588\pi$ forgets the $\frac{1}{3}$, $784\pi$ uses the diameter as the radius, and $168\pi$ is $\pi d h$.', 'checked', '{"lint":[],"solve":{"answer":"$196\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r=7; (1/3)pi*49*12 = 196pi.","run_id":"claude-code","at":"2026-10-23T00:07:24.447Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1eee33b0-3e32-43ce-802b-4f951c13a0a2', 'GEO.15', 2, 'choice', 'Cone surface area', 'A solid cone has a base of radius 9 centimeters and a height of 12 centimeters. What is its total surface area, including the base, in square centimeters?', '["$135\\pi$","$189\\pi$","$216\\pi$","$162\\pi$"]', '$216\pi$', NULL, 'The slant height is $\sqrt{81 + 144} = 15$. The curved surface has area $\pi \times 9 \times 15 = 135\pi$ and the base has area $81\pi$. The total is $216\pi$. The value $135\pi$ leaves out the base, $189\pi$ uses the height 12 instead of the slant height, and $162\pi$ counts the base twice.', 'checked', '{"lint":[],"solve":{"answer":"$216\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"l = sqrt(81+144)=15; 81pi + 135pi = 216pi.","run_id":"claude-code","at":"2026-10-23T00:07:24.447Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ca16d24-3b0e-445c-8c92-f709cb9db5f9', 'GEO.15', 2, 'numeric', 'Combining and reversing', 'A solid metal cylinder has radius 3 centimeters and height 10 centimeters. A hole with radius 1 centimeter is drilled straight through its whole height, along its axis. The volume of metal left can be written as $k\pi$ cubic centimeters. What is $k$?', '[]', '80', '3^2*10-1^2*10', 'The whole cylinder has volume $\pi \times 9 \times 10 = 90\pi$. The hole is a cylinder of radius 1 and height 10, with volume $10\pi$. The metal left has volume $90\pi - 10\pi = 80\pi$, so $k = 80$.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"pi*9*10 - pi*1*10 = 80pi.","run_id":"claude-code","at":"2026-10-23T00:07:24.447Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('091a3295-bb0d-4554-96f7-894fa67460e8', 'GEO.15', 3, 'numeric', 'Cylinder volume', 'Cylinder $A$ has radius 4 centimeters and height 9 centimeters. Cylinder $B$ has the same volume as $A$ but is only 4 centimeters tall. What is the radius of $B$, in centimeters?', '[]', '6', NULL, 'Cylinder $A$ has volume $\pi \times 16 \times 9 = 144\pi$. For $B$, $\pi r^2 \times 4 = 144\pi$, so $r^2 = 36$ and $r = 6$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: pi*16*9 = 144pi; r^2*4 = 144 -> r=6.","run_id":"claude-code","at":"2026-10-23T00:07:24.447Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08029a2b-967c-4028-b729-7cc0f99b81c5', 'GEO.15', 3, 'choice', 'Cone volume', 'A right triangle has legs of 4 centimeters and 9 centimeters. It is spun all the way around its 4 centimeter leg, which sweeps out a cone. What is the volume of the cone, in cubic centimeters?', '["$48\\pi$","$324\\pi$","$144\\pi$","$108\\pi$"]', '$108\pi$', NULL, 'Spinning around the 4 centimeter leg makes that leg the height and the 9 centimeter leg the radius. The volume is $\frac{1}{3}\pi \times 81 \times 4 = 108\pi$. The value $48\pi$ comes from spinning around the 9 centimeter leg instead, $324\pi$ forgets the $\frac{1}{3}$, and $144\pi$ forgets the $\frac{1}{3}$ in the other case.', 'checked', '{"lint":[],"solve":{"answer":"$108\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Axis is the 4 cm leg: height 4, radius 9; (1/3)pi*81*4 = 108pi.","run_id":"claude-code","at":"2026-10-23T00:07:24.447Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1191a685-d062-48e7-9fd1-d46f748348af', 'GEO.16', 1, 'numeric', 'Translations', 'A translation takes the point $(2, 3)$ to the point $(7, 1)$. The same translation takes the point $(10, 4)$ to a new point. What is the y-coordinate of the new point?', '[]', '2', '4+(1-3)', 'The translation changes the y-coordinate by $1-3=-2$, and the x-coordinate by $7-2=5$. So $(10,4)$ goes to $(15,2)$, and its y-coordinate is $2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Translation vector (7 - 2, 1 - 3) = (5, -2). (10, 4) goes to (15, 2). y-coordinate 2.","run_id":"claude-code","at":"2026-10-22T12:51:57.274Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('070af40b-40cc-4d7e-abc2-e0b5a9da28ed', 'GEO.16', 1, 'numeric', 'Reflections', 'The point $(-5, 7)$ is reflected across the x-axis. What is the sum of the x-coordinate and the y-coordinate of its image?', '[]', '-12', '-5-7', 'The image is $(-5,-7)$, because reflecting across the x-axis changes the sign of the y-coordinate. The sum is $-5+(-7)=-12$.', 'checked', '{"lint":[],"solve":{"answer":"-12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-5, 7) to (-5, -7). Sum -12.","run_id":"claude-code","at":"2026-10-22T12:51:57.274Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1027c1f2-8fb9-4750-b363-825f3a889211', 'GEO.16', 1, 'choice', 'Reflections', 'The point $(-6, 2)$ is reflected across the y-axis. What is its image?', '["$(-6, -2)$","$(6, -2)$","$(2, -6)$","$(6, 2)$"]', '$(6, 2)$', NULL, 'A reflection across the y-axis changes the sign of the x-coordinate and leaves the y-coordinate alone: $(-6, 2) \to (6, 2)$. The point $(-6, -2)$ is the reflection across the x-axis, and $(6, -2)$ changes both signs.', 'checked', '{"lint":[],"solve":{"answer":"$(6, 2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Across y-axis: (x,y)->(-x,y): (6,2).","run_id":"claude-code","at":"2026-10-23T00:09:35.310Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12e4411a-acea-4fd6-93b2-4dfd318bd90a', 'GEO.16', 2, 'choice', 'Combining transformations', 'The point $(2, 1)$ is first translated $3$ units up, and then the result is reflected across the x-axis. Where does it end up?', '["$(2, 2)$","$(2, 4)$","$(2, -4)$","$(-2, 4)$"]', '$(2, -4)$', NULL, 'Moving $3$ units up takes $(2,1)$ to $(2,4)$. Reflecting across the x-axis then gives $(2,-4)$. (Doing the two steps in the other order would give $(2,2)$, so the order matters.)', 'checked', '{"lint":[],"solve":{"answer":"$(2, -4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2, 1) up 3 to (2, 4), reflect across x-axis to (2, -4).","run_id":"claude-code","at":"2026-10-22T12:51:57.274Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c5c9726-008e-4207-964f-a5095cecbc4d', 'GEO.16', 2, 'numeric', 'Translations', 'The triangle with corners $(0, 0)$, $(4, 0)$ and $(0, 3)$ is translated by the rule $(x, y) \to (x - 2, y + 7)$. What is the sum of the coordinates of the image of the corner $(4, 0)$?', '[]', '9', '(4-2)+(0+7)', 'The corner $(4, 0)$ goes to $(4 - 2,\ 0 + 7) = (2, 7)$. The sum is $2 + 7 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(4,0)->(2,7); sum 9.","run_id":"claude-code","at":"2026-10-23T00:09:35.310Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a4e37c0-29d8-4b13-a8aa-76caefa08093', 'GEO.16', 2, 'numeric', 'Combining transformations', 'The point $(1, 2)$ is rotated $90^\circ$ counterclockwise about the origin, and the result is moved $3$ units to the right. What is the sum of the coordinates of the final point?', '[]', '2', '(-2+3)+1', 'The turn takes $(1, 2)$ to $(-2, 1)$. Moving 3 units right gives $(1, 1)$, and the sum is $2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1,2)->(-2,1)->(1,1); sum 2.","run_id":"claude-code","at":"2026-10-23T00:09:35.310Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('079e4d82-d4d8-46ad-950f-22ac5bc4af71', 'GEO.16', 3, 'choice', 'Identifying a transformation', 'A triangle with corners $(1, 2)$, $(3, 2)$ and $(1, 5)$ is transformed into a triangle with corners $(-2, 1)$, $(-2, 3)$ and $(-5, 1)$, in matching order. Which transformation was it?', '["A rotation of $90^\\circ$ clockwise about the origin","A rotation of $90^\\circ$ counterclockwise about the origin","A reflection across the line $y = x$","A reflection across the y-axis"]', 'A rotation of $90^\circ$ counterclockwise about the origin', NULL, 'A $90^\circ$ counterclockwise turn takes $(x,y)$ to $(-y,x)$: $(1,2)\to(-2,1)$, $(3,2)\to(-2,3)$ and $(1,5)\to(-5,1)$, which matches. A clockwise turn would give $(2,-1)$ for the first corner, a reflection across $y=x$ would give $(2,1)$, and a reflection across the y-axis would give $(-1,2)$.', 'checked', '{"lint":[],"solve":{"answer":"A rotation of $90^\\circ$ counterclockwise about the origin","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Test (x, y) to (-y, x): (1,2) to (-2,1), (3,2) to (-2,3), (1,5) to (-5,1). All match: 90 degrees counterclockwise about the origin. Clockwise would give (2,-1); y = x reflection gives (2,1); y-axis reflection gives (-1,2).","run_id":"claude-code","at":"2026-10-22T12:51:57.274Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f0bf689-33e0-4ba7-80fb-0eddfca3d2ad', 'GEO.16', 3, 'numeric', 'Identifying a transformation', 'The rule $(x, y) \to (4 - x,\ 2 - y)$ describes a rotation of $180^\circ$ about a point $(a, b)$. What is $a + b$?', '[]', '3', '4/2+2/2', 'A half turn about $(a, b)$ takes $(x, y)$ to $(2a - x,\ 2b - y)$. Matching the rule gives $2a = 4$ and $2b = 2$, so $(a, b) = (2, 1)$ and $a + b = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Centre is midpoint of P and image: (2,1); sum 3.","run_id":"claude-code","at":"2026-10-23T00:09:35.310Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f257208-e82b-4a93-ab49-d979b374632f', 'GEO.17', 1, 'numeric', 'Distance between points', 'Point $A$ is at $(1, 2)$ and point $B$ is at $(4, 6)$. What is the distance $AB$?', '[]', '5', '((4-1)^2+(6-2)^2)/5', 'Going from $A$ to $B$ you move $4 - 1 = 3$ across and $6 - 2 = 4$ up. By the Pythagorean theorem, $AB = \sqrt{3^2 + 4^2} = \sqrt{25} = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"dx = 3, dy = 4, AB = sqrt(9+16) = 5.","run_id":"claude-code","at":"2026-10-22T12:59:41.277Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11bd3537-2bc8-4cf7-823a-7e05a07e04cf', 'GEO.17', 1, 'numeric', 'Slope', 'What is the slope of the line through the points $(2, 7)$ and $(6, 3)$?', '[]', '-1', '(3-7)/(6-2)', 'Slope is rise over run: $\frac{3 - 7}{6 - 2} = \frac{-4}{4} = -1$. The line goes down as you move right, so the slope is negative.', 'checked', '{"lint":[],"solve":{"answer":"-1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3-7)/(6-2) = -4/4 = -1.","run_id":"claude-code","at":"2026-10-22T12:59:41.277Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0030598b-2454-4f34-b030-cb13fb8ec0b2', 'GEO.17', 1, 'choice', 'Equations of lines', 'Which of these points lies on the line $y = 3x - 5$?', '["$(2, 1)$","$(1, 2)$","$(2, -1)$","$(3, 14)$"]', '$(2, 1)$', NULL, 'At $x = 2$ the line has $y = 3(2) - 5 = 1$, so $(2, 1)$ is on it. For $(1, 2)$ the line gives $-2$, for $(2, -1)$ it gives $1$, and for $(3, 14)$ it gives $4$.', 'checked', '{"lint":[],"solve":{"answer":"$(2, 1)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=1: y=-2 (no); x=2: y=1 so (2,1) yes, (2,-1) no; x=3: y=4 not 14.","run_id":"claude-code","at":"2026-10-23T00:09:47.384Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00ee54f7-cea5-4d9f-8fee-8839be3e454b', 'GEO.17', 2, 'numeric', 'Equations of lines', 'What is the slope of the line $3x + 4y = 24$?', '[]', '-3/4', '-3/4', 'Solve for $y$: $4y = -3x + 24$, so $y = -\frac{3}{4}x + 6$. The slope is $-\frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"-3/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y=-3/4 x+6; slope -3/4.","run_id":"claude-code","at":"2026-10-23T00:09:47.384Z"}}', 'ai', NULL, NULL)
