INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('192570bc-7024-424f-bf6e-9262227d1793', 'GEO.17', 2, 'numeric', 'Equations of circles', 'A circle with its center at the origin passes through the point $(-5, 12)$. Its equation is $x^2 + y^2 = k$. What is $k$?', '[]', '169', '25+144', '$k = (-5)^2 + 12^2 = 25 + 144 = 169$.', 'checked', '{"lint":[],"solve":{"answer":"169","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k=25+144=169.","run_id":"claude-code","at":"2026-10-23T00:09:47.384Z"}}', 'ai', NULL, NULL)
