INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05117f60-239e-43fc-b545-c13d729c73b7', 'GEO.17', 3, 'numeric', 'Slope', 'A line with slope $-\frac{5}{2}$ passes through $(4, 5)$ and crosses the $x$-axis at $(a, 0)$. What is $a$?', '[]', '6', '4+5*2/5', 'From $(4, 5)$ the line falls $5$ units to reach the axis. Each $2$ units to the right lowers it by $5$, so it moves right $2$ units: $a = 4 + 2 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0-5=-5/2(a-4) -> a-4=2 -> a=6.","run_id":"claude-code","at":"2026-10-23T00:09:47.384Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0352cc42-9730-4b57-805c-f846fa7ade8d', 'GEO.17', 3, 'choice', 'Equations of lines', 'Which is an equation of the perpendicular bisector of the segment from $(1, 3)$ to $(5, 7)$?', '["$y = x + 2$","$y = -x + 8$","$y = -x + 4$","$y = -x + 12$"]', '$y = -x + 8$', NULL, 'The midpoint is $(3, 5)$. The segment has slope $1$, so the bisector has slope $-1$ and $5 = -3 + b$ gives $b = 8$. (The others are the line through the two points, and the perpendicular lines through each end.)', 'checked', '{"lint":[],"solve":{"answer":"$y = -x + 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Midpoint (3,5), segment slope 1, perpendicular -1: y=-x+8.","run_id":"claude-code","at":"2026-10-23T00:09:47.384Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e5c5784-c40e-47bc-a573-e48e34902a89', 'GEO.18', 1, 'numeric', 'Sine, cosine and tangent as side ratios', 'A right triangle has legs $6$ and $8$ and hypotenuse $10$. Angle $A$ is opposite the leg of length $6$. What is $\tan A$?', '[]', '3/4', '6/8', 'Tangent is opposite over adjacent: $\tan A = \frac{6}{8} = \frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"3/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"tan A = opposite/adjacent = 6/8 = 3/4.","run_id":"claude-code","at":"2026-10-23T00:09:47.422Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0bf75506-7060-4262-a5d5-9fda233461dd', 'GEO.18', 1, 'numeric', 'Exact values at 30, 45 and 60 degrees', 'What is the value of $\tan 45^\circ$?', '[]', '1', '1', 'In a right triangle with a $45^\circ$ angle the two legs are equal, so opposite over adjacent is $1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"tan45=1.","run_id":"claude-code","at":"2026-10-23T00:09:47.422Z"}}', 'ai', NULL, NULL)
