INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c3ce36c-6a83-4bc2-bf7e-e32cf3ed294c', 'GEO.18', 1, 'numeric', 'Law of Cosines', 'Two sides of a triangle are both $7$ long, and the angle between them is $60^\circ$. How long is the third side?', '[]', '7', '7', '$c^2 = 49 + 49 - 2(7)(7)\cos 60^\circ = 98 - 49 = 49$, so $c = 7$. (The triangle is equilateral.)', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Equilateral (isosceles with 60): 49+49-49=49, side 7.","run_id":"claude-code","at":"2026-10-23T00:09:47.422Z"}}', 'ai', NULL, NULL)
