INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12377e87-8375-4fe2-aafa-4fe6ebcda26d', 'GEO.18', 2, 'numeric', 'Sine, cosine and tangent as side ratios', 'A right triangle has legs $3$ and $4$. Let $A$ be one of its acute angles. What is $\sin A \cdot \cos A$?', '[]', '12/25', '3/5*4/5', 'The hypotenuse is $5$. One acute angle has $\sin = \frac{3}{5}$ and $\cos = \frac{4}{5}$, and the other has them swapped, so the product is $\frac{12}{25}$ either way.', 'checked', '{"lint":[],"solve":{"answer":"12/25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3/5)(4/5)=12/25 either angle.","run_id":"claude-code","at":"2026-10-23T00:09:47.422Z"}}', 'ai', NULL, NULL)
