INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2880738c-6372-410f-8c73-5f211968e03a', 'GEO.18', 2, 'choice', 'Using a trig ratio to find a side', 'You stand $30$ meters from the base of a tower on level ground, and the angle of elevation to its top is $30^\circ$. How tall is the tower, in meters?', '["$15$","$30\\sqrt{3}$","$20\\sqrt{3}$","$10\\sqrt{3}$"]', '$10\sqrt{3}$', NULL, 'The height is $30\tan 30^\circ = 30 \times \frac{\sqrt{3}}{3} = 10\sqrt{3}$ meters. ($15$ uses $\sin$, $30\sqrt{3}$ uses $\tan 60^\circ$, and $20\sqrt{3}$ is the slanted distance to the top.)', 'checked', '{"lint":[],"solve":{"answer":"$10\\sqrt{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 tan30 = 30/sqrt3 = 10sqrt3.","run_id":"claude-code","at":"2026-10-23T00:09:47.422Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f89388a-4f31-4f8b-9a56-5abdcdd4d547', 'GEO.18', 2, 'numeric', 'Exact values at 30, 45 and 60 degrees', 'A student multiplies $\tan 60^\circ$ by $\cos 30^\circ$. What is the product, written as a fraction?', '[]', '3/2', '3/2', '$\tan 60^\circ = \sqrt{3}$ and $\cos 30^\circ = \frac{\sqrt{3}}{2}$. The product is $\sqrt{3} \times \frac{\sqrt{3}}{2} = \frac{3}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"3/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"tan60 = sqrt3, cos30 = sqrt3/2. Product = 3/2.","run_id":"claude-code","at":"2026-10-23T00:30:06.000Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('076b3ec3-7ce8-4bd2-894e-1400bd98364f', 'GEO.18', 3, 'numeric', 'Sine, cosine and tangent as side ratios', 'A right triangle has hypotenuse $26$ and an acute angle $A$ with $\tan A = \frac{5}{12}$. What is the radius of the circle inside the triangle that touches all three sides?', '[]', '4', '(10+24-26)/2', 'The legs are $10$ and $24$ (ratio $5 : 12$, hypotenuse $26$). For a right triangle, the inradius is $\frac{a + b - c}{2} = \frac{10 + 24 - 26}{2} = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Legs 10,24, hyp 26; r=(10+24-26)/2=4.","run_id":"claude-code","at":"2026-10-23T00:09:47.422Z"}}', 'ai', NULL, NULL)
