INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06653c65-118e-46f7-9449-01b8b82be31d', 'GEO.18', 3, 'numeric', 'Law of Cosines', 'A parallelogram has sides $7$ and $8$ and one angle of $60^\circ$. How long is its longer diagonal?', '[]', '13', NULL, 'The longer diagonal is opposite the $120^\circ$ angle. Use $\cos 120^\circ = -\frac{1}{2}$: $d^2 = 49 + 64 - 2(7)(8)\left(-\frac{1}{2}\right) = 113 + 56 = 169$, so $d = 13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Longer diagonal opposite 120: 49+64+56=169; 13.","run_id":"claude-code","at":"2026-10-23T00:09:47.422Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04c713dc-e7bd-48e4-ab65-6891e1aa5c39', 'GEO.19', 1, 'choice', 'Using areas', 'A triangle has area 24, and one of its sides is 8 long. How long is the altitude drawn to that side?', '["$3$","$12$","$6$","$192$"]', '$6$', '2*24/8', 'Area $= \frac{1}{2} \cdot \text{base} \cdot \text{height}$, so $24 = \frac{1}{2} \cdot 8 \cdot h = 4h$ and $h = 6$. (3 forgets the factor of $\frac{1}{2}$, and 192 multiplies instead of dividing.)', 'checked', '{"lint":[],"solve":{"answer":"$6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 = 8h/2, h = 6.","run_id":"claude-code","at":"2026-10-22T19:28:49.749Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('022001be-d7d1-412e-891d-3ca477ba6554', 'GEO.19', 1, 'choice', 'Drawing a helpful line (altitude, radius, diagonal)', 'A rhombus has sides of length 5 and a shorter diagonal of length 6. How long is its longer diagonal?', '["$4$","$7$","$10$","$8$"]', '$8$', '8', 'The diagonals of a rhombus cross at right angles and cut each other in half. One half-diagonal is 3, so the other half is $\sqrt{5^2 - 3^2} = 4$, and the longer diagonal is 8. (4 is only half of it.)', 'checked', '{"lint":[],"solve":{"answer":"$8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Diagonals bisect at right angles: halves 3 and 4 with side 5, longer diagonal 8.","run_id":"claude-code","at":"2026-10-23T00:22:08.003Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01520ecc-71fe-4e55-a66d-23cf4beb15d5', 'GEO.19', 1, 'choice', 'Using the Pythagorean theorem cleverly', 'Which set of three lengths can be the sides of a right triangle?', '["$8$, $9$, $13$","$6$, $8$, $11$","$9$, $12$, $15$","$5$, $10$, $12$"]', '$9$, $12$, $15$', NULL, 'A right triangle needs $a^2 + b^2 = c^2$ with $c$ the longest. $9^2 + 12^2 = 225 = 15^2$ works. The others give $145 \ne 169$, $100 \ne 121$ and $125 \ne 144$.', 'checked', '{"lint":[],"solve":{"answer":"$9$, $12$, $15$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"81 + 144 = 225 = 15^2. Others: 25+100 != 144, 64+81 != 169, 36+64 != 121.","run_id":"claude-code","at":"2026-10-23T00:22:08.003Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2020b49f-6fa9-4713-b1c9-f0ecc5e64c38', 'GEO.19', 2, 'numeric', 'Using areas', 'Triangle $ABC$ has area 60. The point $D$ is on side $BC$ with $BD : DC = 2 : 3$. What is the area of triangle $ABD$?', '[]', '24', '60*2/5', 'Triangles $ABD$ and $ADC$ have the same height from $A$ to line $BC$, so their areas are in the ratio of their bases, $2 : 3$. Triangle $ABD$ has $\frac{2}{5}$ of the area: $60 \cdot \frac{2}{5} = 24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same height from A: area ABD = 60 * 2/5 = 24.","run_id":"claude-code","at":"2026-10-22T19:28:49.749Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d409e90-f562-42cd-8983-4c85b78d43b5', 'GEO.19', 2, 'numeric', 'Similar triangles and parallel lines', 'A girl 1.5 meters tall stands 4 meters from the base of a lamp post. Her shadow is 2 meters long, so the tip of the shadow is 6 meters from the base of the post. How tall is the lamp post, in meters?', '[]', '4.5', '1.5*6/2', 'The girl and her shadow, and the post and the line from its base to the shadow tip, make similar right triangles. So $\frac{\text{post}}{6} = \frac{1.5}{2}$, which gives a height of $4.5$ meters.', 'checked', '{"lint":[],"solve":{"answer":"4.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Similar triangles from shadow tip: H/6 = 1.5/2, H = 4.5.","run_id":"claude-code","at":"2026-10-23T00:22:08.003Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05b7cb4b-03c1-4b72-a5b0-3a84aa037029', 'GEO.19', 2, 'numeric', 'Angle chasing and reasoning about a figure', 'In triangle $ABC$, $AB = AC$ and $\angle BAC = 100^\circ$. The point $D$ is on $BC$ with $BD = BA$. What is $\angle CAD$, in degrees?', '[]', '30', '100-(180-40)/2', '$\angle B = \angle C = 40^\circ$. Triangle $BAD$ has $BA = BD$, so $\angle BAD = \frac{180 - 40}{2} = 70$. Then $\angle CAD = 100 - 70 = 30$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"B = C = 40. Triangle ABD isosceles with BA = BD and apex 40: BAD = 70. CAD = 100 - 70 = 30.","run_id":"claude-code","at":"2026-10-23T00:22:08.003Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01b40e6a-a91f-4d31-9ff0-02ba1bf860ad', 'GEO.19', 3, 'choice', 'Drawing a helpful line (altitude, radius, diagonal)', 'A circle has radius 25. Two parallel chords of lengths 14 and 40 lie on the same side of the center. How far apart are they?', '["$39$","$17$","$9$","$26$"]', '$9$', '24-15', 'The chord of length 14 is $\sqrt{625 - 49} = 24$ from the center, and the chord of length 40 is $\sqrt{625 - 400} = 15$ from it. On the same side, they are $24 - 15 = 9$ apart. (39 is the distance if they were on opposite sides.)', 'checked', '{"lint":[],"solve":{"answer":"$9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distances sqrt(625 - 49) = 24 and sqrt(625 - 400) = 15; apart 9.","run_id":"claude-code","at":"2026-10-23T00:22:08.003Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
