VALUES ('060e700e-bab9-4b6a-9464-0e726cad143f', 'NC26.1.ANR.7', 1, 'choice', 'True or false equation', 'One of these equations is not true. Which one is it?', '["$4 = 4$","$2 + 2 = 4$","$5 = 4 + 1$","$3 + 1 = 5$"]', '$3 + 1 = 5$', NULL, '$3 + 1$ is 4, and 4 is not 5, so $3 + 1 = 5$ is not true. The other three are true.', 'checked', '{"lint":[],"solve":{"answer":"$3 + 1 = 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 = 4 true; 4 + 1 = 5 true; 2 + 2 = 4 true; 3 + 1 = 4, not 5, so false.","run_id":"claude-code","at":"2026-10-22T12:46:59.582Z"}}', 'ai', NULL, NULL)
