VALUES ('0ca1e79a-6652-457e-8673-454948061297', 'NC26.2.ANR.4', 2, 'numeric', 'Subtract 100 from a number within 1,000', 'A farm has 640 eggs. It sells 100 of them. How many eggs are left?', '[]', '540', '640-100', '$640 - 100 = 540$: 6 hundreds become 5 hundreds, and the other digits stay the same.', 'checked', '{"lint":[],"solve":{"answer":"540","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"640 - 100 = 540.","run_id":"claude-code","at":"2026-10-22T13:01:53.075Z"}}', 'ai', NULL, NULL)
