INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b2a0f7c-7bb6-4915-89e3-282671619e35', 'NC26.2.ANR.4', 2, 'choice', 'Mix of adding and subtracting 10 and 100', 'Which of these is NOT equal to 450?', '["$350 + 100$","$460 - 10$","$550 - 100$","$440 - 10$"]', '$440 - 10$', NULL, '350 + 100 = 450, 460 - 10 = 450 and 550 - 100 = 450. But 440 - 10 = 430, so it is not equal to 450.', 'checked', '{"lint":[],"solve":{"answer":"$440 - 10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"550-100=450; 460-10=450; 440-10=430; 350+100=450. Not equal: 440 - 10.","run_id":"claude-code","at":"2026-10-22T19:32:45.684Z"}}', 'ai', NULL, NULL)
