INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12508828-4c3a-4996-b93b-9a96e4f77fe2', 'NC26.2.ANR.4', 3, 'numeric', 'Mix of adding and subtracting 10 and 100', 'Leo starts with 453. He takes away 100. Then he adds 10. What number does he end with?', '[]', '363', '453-100+10', '$453 - 100 = 353$. Then $353 + 10 = 363$.', 'checked', '{"lint":[],"solve":{"answer":"363","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"453 - 100 = 353; 353 + 10 = 363.","run_id":"claude-code","at":"2026-10-22T13:01:53.075Z"}}', 'ai', NULL, NULL)
