INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('169d9e46-e8f0-40ff-817f-e1a1c0dadee3', 'NC26.2.ANR.4', 3, 'choice', 'Find the missing number in a fact within 20', 'Which number sentence can be used to find the ? in $7 + ? = 16$?', '["$16 + 7 = ?$","$16 - 7 = ?$","$? - 16 = 7$","$? - 7 = 16$"]', '$16 - 7 = ?$', NULL, 'The ? and 7 make 16, so the ? is what is left when 7 is taken away from 16: 16 - 7 = 9. The other sentences would find 23.', 'checked', '{"lint":[],"solve":{"answer":"$16 - 7 = ?$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 + ? = 16 means ? = 16 - 7.","run_id":"claude-code","at":"2026-10-22T19:32:45.684Z"}}', 'ai', NULL, NULL)
