INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('19199907-27b0-4bfd-891c-76d1b5924eea', 'NC26.2.ANR.5', 1, 'choice', 'Use place-value strategies to add or subtract', 'Ana finds $57 - 20$. Which steps are right?', '["Take away 2 ones. That leaves 5 tens and 5 ones, which is 55.","Take away 2 from each digit. That leaves 3 tens and 5 ones, which is 35.","Take away 2 tens. That leaves 3 tens and 7 ones, which is 37.","Add 2 tens. That makes 7 tens and 7 ones, which is 77."]', 'Take away 2 tens. That leaves 3 tens and 7 ones, which is 37.', NULL, '20 is 2 tens, so take away 2 tens from the 5 tens. The 7 ones do not change. That leaves 3 tens and 7 ones, which is 37.', 'checked', '{"lint":[],"solve":{"answer":"Take away 2 tens. That leaves 3 tens and 7 ones, which is 37.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"57 - 20: subtract 2 tens from 5 tens leaves 3 tens; ones stay 7; 37. Other options add, subtract ones, or subtract from both digits (wrong).","run_id":"claude-code","at":"2026-10-23T00:30:38.580Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
