VALUES ('16c6298e-94d1-4dc8-ac41-d8f266353a35', 'NC26.2.ANR.5', 3, 'choice', 'One-step word problem with the start, change or difference unknown', 'Leon had 100 pages to read. After reading some, he had 38 pages left. How many pages did he read?', '["138","52","62","72"]', '62', '100-38', '$100 - 38 = 62$. Check: $62 + 38 = 100$.', 'checked', '{"lint":[],"solve":{"answer":"62","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100-38=62.","run_id":"claude-code","at":"2026-10-22T19:35:39.674Z"}}', 'ai', NULL, NULL)
