VALUES ('0f1bc52e-7d09-4466-a39a-65a18892f985', 'NC26.2.ANR.6', 1, 'choice', 'Telling whether a number sentence is true', 'Which sentence tells the truth?', '["$9 - 4 = 5$","$9 - 4 = 6$","$9 - 4 = 13$","$9 - 4 = 4$"]', '$9 - 4 = 5$', NULL, '$9 - 4 = 5$, so that sentence is true. The others have a different number after the equal sign.', 'checked', '{"lint":[],"solve":{"answer":"$9 - 4 = 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9-4=5, so 9-4=5 is true.","run_id":"claude-code","at":"2026-10-22T19:35:39.717Z"}}', 'ai', NULL, NULL)
