INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2aae9fc0-f66a-4bd0-a7e3-384a734fb175', 'NC26.2.ANR.6', 2, 'numeric', 'Finding the unknown in a story', 'Lena had some beads. She gave 15 beads to Sam. Now Lena has 39 beads. How many beads did Lena have at first?', '[]', '54', '39+15', 'The sentence is ? - 15 = 39. Go back: 39 + 15 = 54. Check: 54 - 15 = 39.', 'checked', '{"lint":[],"solve":{"answer":"54","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"? - 15 = 39, so ? = 39 + 15 = 54.","run_id":"claude-code","at":"2026-10-22T12:58:18.828Z"}}', 'ai', NULL, NULL)
