INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a892c10-2282-44b8-a516-9f63f9028eb4', 'NC26.2.ANR.6', 2, 'choice', 'Finding the unknown with expressions on both sides', 'Which number goes in the ? so that $27 + 3 = ? + 10$ is true?', '["30","20","40","17"]', '20', '27+3-10', '$27 + 3 = 30$. Then $20 + 10 = 30$, so the ? is $20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"27+3=30; 20+10=30. ?=20.","run_id":"claude-code","at":"2026-10-22T19:35:39.717Z"}}', 'ai', NULL, NULL)
