VALUES ('07a1dd53-5688-4339-83a8-e5b08cf4ff02', 'NC26.2.ANR.6', 2, 'numeric', 'Finding the unknown with expressions on both sides', 'What number goes in the ? to make this true? $70 - 25 = 20 + ?$', '[]', '25', '70-25-20', '$70 - 25 = 45$. Then $45 - 20 = 25$, so the ? is $25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"70-25=45; 45-20=25.","run_id":"claude-code","at":"2026-10-22T19:35:39.717Z"}}', 'ai', NULL, NULL)
