INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06744263-96d0-40ea-b329-38ba97ef4396', 'NC26.2.ANR.7', 1, 'choice', 'Explain why a strategy works', 'Which statement is true?', '["Taking 138 away from 462 gives the same answer as taking 462 away from 138.","Adding 138 to 462 gives a bigger total than adding 462 to 138.","Adding 138 to 462 gives a smaller total than adding 462 to 138.","Adding 138 to 462 gives the same total as adding 462 to 138."]', 'Adding 138 to 462 gives the same total as adding 462 to 138.', NULL, 'Numbers can be added in any order and the total stays the same. Both ways give 600. Subtraction does not work that way.', 'checked', '{"lint":[],"solve":{"answer":"Adding 138 to 462 gives the same total as adding 462 to 138.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Addition is commutative: 138+462 = 462+138 = 600. Subtraction is not.","run_id":"claude-code","at":"2026-10-22T19:40:34.720Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
