INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01ee59eb-f0c6-4810-8c0e-d5c8d6da45d4', 'NC26.2.ANR.7', 2, 'numeric', 'Add with a mental strategy', 'Zoe finds $53 + 29$ by adding 30 to 53 and then taking away 1. What is the sum of 53 and 29?', '[]', '82', '53+30-1', '53 + 30 = 83. 29 is 1 less than 30, so take away 1: 83 - 1 = 82.', 'checked', '{"lint":[],"solve":{"answer":"82","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"53 + 30 = 83; 83 - 1 = 82. Check 53 + 29 = 82.","run_id":"claude-code","at":"2026-10-22T12:47:46.479Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('13ecc2b2-4586-422d-a337-d565899aacf3', 'NC26.2.ANR.7', 3, 'numeric', 'Add three two-digit numbers', 'Find the sum: $58 + 67 + 49$.', '[]', '174', '58+67+49', '58 + 67 = 125. Then 125 + 49 = 174.', 'checked', '{"lint":[],"solve":{"answer":"174","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"58+67=125, 125+49=174.","run_id":"claude-code","at":"2026-10-22T19:40:34.720Z"}}', 'ai', NULL, NULL)
