VALUES ('021f584f-3f9b-46aa-addf-3bb52fc668e3', 'NC26.2.SGMR.1', 3, 'choice', 'Count sides, vertices and angles', 'Which pair of shapes has 9 straight sides in all?', '["a triangle and a hexagon","a square and a hexagon","a pentagon and a pentagon","a triangle and a pentagon"]', 'a triangle and a hexagon', NULL, 'Triangle and hexagon: 3 + 6 = 9. Square and hexagon: 4 + 6 = 10. Two pentagons: 5 + 5 = 10. Triangle and pentagon: 3 + 5 = 8.', 'checked', '{"lint":[],"solve":{"answer":"a triangle and a hexagon","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3+6=9. Others: 10,10,8.","run_id":"claude-code","at":"2026-10-22T19:40:34.760Z"}}', 'ai', NULL, NULL)
