INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b6a9052-a480-4710-a4f3-757047d9f5fb', 'NC26.2.SGMR.2', 3, 'choice', 'Partition a whole into 2, 3 or 4 equal shares', 'Which way cuts a rectangle into 4 equal shares?', '["Cut it in half, then cut each half in half","Cut it in half, then cut only one half in half","Cut it in half, then cut each half in 3","Cut it in 3 equal parts, then cut one part in half"]', 'Cut it in half, then cut each half in half', NULL, 'Cutting each of 2 equal halves in half makes 4 equal shares. The other ways make parts of different sizes.', 'checked', '{"lint":[],"solve":{"answer":"Cut it in half, then cut each half in half","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Halving each half gives 4 equal shares; the others give unequal or 6 shares.","run_id":"claude-code","at":"2026-10-22T19:43:59.781Z"}}', 'ai', NULL, NULL)
