INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08b68e1f-0bfa-48bf-bb21-b5afa2d46772', 'NC26.2.SGMR.2', 3, 'numeric', 'Equal shares can look different', 'A square is made of 16 small squares, 4 in each row and 4 rows. Ana cuts it into fourths by separating the 4 rows. Bo cuts it into fourths as four squares of 2 rows and 2 columns. How many small squares are in one fourth?', '[]', '4', '16/4', '16 small squares in 4 equal fourths is 4 in each, whichever way it is cut.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"16 squares in 4 equal fourths: 4 each, both ways.","run_id":"claude-code","at":"2026-10-22T19:43:59.781Z"}}', 'ai', NULL, NULL)
