INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06998f0f-49f7-4ac9-8969-b95b835e7320', 'NC26.2.SGMR.3', 2, 'numeric', 'Measure with a ruler or meter stick', 'Ana wants to cut a ribbon that is 18 centimeters long. She lines up one end of the ribbon at the 7 centimeter mark on a ruler. At which centimeter mark should the other end of the ribbon be?', '[]', '25', '7+18', 'The ribbon starts at the 7 mark and is 18 centimeters long, so it ends 18 marks farther along. $7 + 18 = 25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Start at 7, length 18: 7+18 = 25. (The other direction would be negative, so 25 is the only answer.)","run_id":"claude-code","at":"2026-10-23T00:30:38.580Z"}}', 'ai', NULL, NULL)
