INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05e0fb7e-c9de-4b95-8972-9e05ed0d3b1d', 'NC26.2.RD.2', 2, 'choice', 'Use a graph to draw and check conclusions', 'A bar graph shows the pets in a class. The Dogs bar reaches 9, Cats reach 7, Fish reach 4 and Birds reach 2. Each child has one pet. Which conclusion does the graph show?', '["Fish are more common than cats in the class.","Birds are the most common pet in the class.","The class has 20 pets in all, one each.","Dogs are the most common pet in the class."]', 'Dogs are the most common pet in the class.', NULL, 'Dogs have the tallest bar, at 9. Fish (4) are fewer than cats (7), birds (2) are the fewest, and the total is 9 + 7 + 4 + 2 = 22, not 20.', 'checked', '{"lint":[],"solve":{"answer":"Dogs are the most common pet in the class.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dogs 9 most; total is 22, not 20.","run_id":"claude-code","at":"2026-10-23T00:09:24.162Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02a026d1-e99b-487f-9ed3-e3f692244635', 'NC26.2.RD.2', 2, 'choice', 'Make a graph from data (rows and bars)', 'Lisa has this data: Plums 4, Figs 6, Dates 5. She makes a bar graph. Which bar is the tallest?', '["the Plums bar","the Figs bar","the Dates bar","all the bars are the same height"]', 'the Figs bar', NULL, 'Figs has the greatest number, 6, so its bar is tallest.', 'checked', '{"lint":[],"solve":{"answer":"the Figs bar","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Figs 6 is largest.","run_id":"claude-code","at":"2026-10-23T00:09:24.162Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12899cf2-4db0-406b-89ad-38ee5539a6c6', 'NC26.2.RD.2', 3, 'numeric', 'Collect and count data (up to 30 data points)', 'Dev asks 18 children which pet they have and writes each answer: dog, cat, dog, fish, cat, dog, dog, cat, bird, dog, cat, fish, dog, cat, dog, bird, cat, dog. How many children have a pet that is not a dog and not a cat?', '[]', '4', '18-8-6', 'Count the dogs: 8. Count the cats: 6. That leaves $18 - 8 - 6 = 4$ children: 2 with a fish and 2 with a bird.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Count the 18 answers: dog at 1,3,6,7,10,13,15,18 = 8; cat at 2,5,8,11,14,17 = 6; fish at 4,12 = 2; bird at 9,16 = 2. 8+6+2+2 = 18. Not dog and not cat: 2 + 2 = 4.","run_id":"claude-code","at":"2026-10-22T13:01:53.151Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ca537a8-c4a5-46b4-910d-c996be269024', 'NC26.2.RD.2', 3, 'choice', 'Collect and count data (up to 30 data points)', 'Gus writes 30 answers in a tally chart. He counts A as 11, B as 9 and C as 7, which is 27 in all. What should he do?', '["make the graph now, since 27 is close enough","add 3 to the A tally without counting again","change the C tally to 10 without counting again","count the tally marks again, since 27 is not 30"]', 'count the tally marks again, since 27 is not 30', NULL, 'There should be 30 answers, but the tallies add to 11 + 9 + 7 = 27. Something was missed, so he should count again.', 'checked', '{"lint":[],"solve":{"answer":"count the tally marks again, since 27 is not 30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total must be 30; recount.","run_id":"claude-code","at":"2026-10-23T00:09:24.162Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2551ac9a-359b-470c-af14-8182ed3d0b7f', 'NC26.3.ANR.1', 1, 'numeric', 'Equivalent forms: regroup place values', '$1{,}000$ is the same as how many hundreds?', '[]', '10', '1000/100', 'Ten hundreds make one thousand: $10 \times 100 = 1{,}000$. So 1,000 is 10 hundreds.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1,000 / 100 = 10 hundreds.","run_id":"claude-code","at":"2026-10-17T19:22:04.066Z"}}', 'ai', NULL, NULL)
