INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1061a6b8-9ae3-4718-bb96-509083ebbfae', 'NC26.3.ANR.1', 2, 'numeric', 'Write a number from its places', 'Ana makes a number with digit cards. She puts the 6 in the tens place, the 2 in the thousands place, the 9 in the ones place and the 4 in the hundreds place. What number does she make?', '[]', '2469', '2*1000+4*100+6*10+9', 'Thousands 2, hundreds 4, tens 6, ones 9. Reading from the thousands place to the ones place gives 2,469.', 'checked', '{"lint":[],"solve":{"answer":"2469","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Thousands 2, hundreds 4, tens 6, ones 9: 2,469.","run_id":"claude-code","at":"2026-10-17T19:22:04.066Z"}}', 'ai', NULL, NULL)
