INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('036ab577-9a9e-4cfe-a637-f78375cb3e3d', 'NC26.3.ANR.2', 1, 'numeric', 'Find the unknown in a story', 'Ravi had 40 trading cards. A friend gave him some more, and now he has 70 cards. How many cards did his friend give him?', '[]', '30', '70-40', 'The friend gave him the extra cards. Think $40 + ? = 70$, so $? = 70 - 40 = 30$. Check: $40 + 30 = 70$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40 + ? = 70, ? = 30.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
