INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('041a8d75-3e91-44c0-b585-19ab720421f7', 'NC26.3.ANR.2', 2, 'choice', 'Subtract with regrouping', 'What is $631 - 274$?', '["443","367","457","357"]', '357', '631-274', 'Ones: trade a ten, $11 - 4 = 7$. Tens: now 2 tens, so trade a hundred, $12 - 7 = 5$. Hundreds: now 5 hundreds, $5 - 2 = 3$. The answer is 357. Check: $357 + 274 = 631$.', 'checked', '{"lint":[],"solve":{"answer":"357","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"631 - 274 = 631 - 275 + 1 = 356 + 1 = 357. Check 274 + 357 = 631.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('036aa129-800e-4713-8788-29cd72b3fcb1', 'NC26.3.ANR.2', 2, 'choice', 'Subtract with regrouping', 'What is $520 - 178$?', '["342","458","352","442"]', '342', '520-178', 'Ones: $0 - 8$, so trade: 5 hundreds, 1 ten, 10 ones becomes 4 hundreds, 11 tens, 10 ones. Ones: $10 - 8 = 2$. Tens: $11 - 7 = 4$. Hundreds: $4 - 1 = 3$. The answer is 342. Check: $342 + 178 = 520$.', 'checked', '{"lint":[],"solve":{"answer":"342","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"520 - 178 = 520 - 180 + 2 = 340 + 2 = 342.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1491e6c1-f963-430e-8648-8ac20c825897', 'NC26.3.ANR.2', 3, 'numeric', 'Subtract in a story (take away or compare)', 'A concert hall has 905 seats. There are 487 people in the hall, and every person is sitting in a seat. How many seats are empty?', '[]', '418', '905-487', 'Subtract: $905 - 487$. Trade so that 9 hundreds, 0 tens, 5 ones becomes 8 hundreds, 9 tens, 15 ones. Ones: $15 - 7 = 8$. Tens: $9 - 8 = 1$. Hundreds: $8 - 4 = 4$. The answer is 418. Check: $418 + 487 = 905$.', 'checked', '{"lint":[],"solve":{"answer":"418","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"905 - 487 = 905 - 500 + 13 = 405 + 13 = 418. Check 487 + 418 = 905.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
