VALUES ('063146f7-b172-4d1a-886a-2194a294a5e8', 'NC26.3.ANR.3', 2, 'numeric', 'Equal-groups word problems', 'A pizza is cut into 8 slices. How many slices are there in 4 pizzas?', '[]', '32', '4*8', '4 pizzas with 8 slices each: $4 \times 8 = 32$ slices.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 8 = 32.","run_id":"claude-code","at":"2026-10-17T19:20:12.112Z"}}', 'ai', NULL, NULL)
