INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('039c76fe-ee80-4ed0-9677-dcc299f0e85f', 'NC26.3.ANR.4', 1, 'choice', 'Make equal groups: find the number of groups', 'Leo has 21 books. He puts 3 books on each shelf. How many shelves does he use?', '["18","7","24","63"]', '7', '21/3', 'The number of shelves is $21 \div 3 = 7$. Check: $7 \times 3 = 21$. The other choices come from subtracting (18), adding (24), or multiplying (63).', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"21 / 3 = 7 shelves.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
