INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('059deb3a-4233-4762-afd3-5f44625ae818', 'NC26.3.ANR.4', 3, 'choice', 'Use a multiplication fact to divide (fact families)', 'Which equation is NOT from the same fact family as $6 \times 9 = 54$?', '["$54 \\div 3 = 18$","$9 \\times 6 = 54$","$54 \\div 9 = 6$","$54 \\div 6 = 9$"]', '$54 \div 3 = 18$', NULL, 'The fact family uses only 6, 9 and 54: $6 \times 9 = 54$, $9 \times 6 = 54$, $54 \div 6 = 9$ and $54 \div 9 = 6$. The equation $54 \div 3 = 18$ is true, but it uses 3 and 18, so it belongs to a different family.', 'checked', '{"lint":[],"solve":{"answer":"$54 \\div 3 = 18$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Family of 6, 9, 54: 54/9 = 6, 54/6 = 9, 9 x 6 = 54. 54 / 3 = 18 is true but uses 3 and 18, not in the family.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
