INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0306b508-1937-4375-94ae-d34da9f8b6aa', 'NC26.3.ANR.6', 2, 'choice', 'Check whether an answer is reasonable', 'Rosa found that $502 - 198 = 304$. To check, she rounded each number to the nearest hundred and found $500 - 200 = 300$. What can Rosa say about her answer?', '["It is not reasonable, because 304 is not equal to 300.","It is not reasonable, because the estimate should be 500.","It is reasonable, because 304 is close to the estimate of 300.","It is not reasonable, because 502 should not be rounded."]', 'It is reasonable, because 304 is close to the estimate of 300.', NULL, 'An estimate is not expected to match exactly. Since 304 is very close to the estimate of 300, Rosa''s answer is reasonable.', 'checked', '{"lint":[],"solve":{"answer":"It is reasonable, because 304 is close to the estimate of 300.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Estimate 500 - 200 = 300; 304 is close to 300, so the answer is reasonable. (Exact 502 - 198 = 304 is correct.)","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05fbbcb2-d4a3-4f70-9b91-168e8fc01e41', 'NC26.3.ANR.6', 3, 'choice', 'Choose the equation or expression for a story', 'Jo has 3 bags with 8 marbles in each bag. He gives away $g$ marbles and has 17 marbles left. Which equation matches the story?', '["$3 + 8 - g = 17$","$3 \\times 8 + g = 17$","$3 \\times 8 - g = 17$","$8 - 3 \\times g = 17$"]', '$3 \times 8 - g = 17$', NULL, 'Jo starts with $3 \times 8$ marbles, gives away $g$, and has 17 left: $3 \times 8 - g = 17$.', 'checked', '{"lint":[],"solve":{"answer":"$3 \\times 8 - g = 17$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 8 = 24 marbles, gives away g, 17 left: 3 x 8 - g = 17 (g = 7).","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00e67e5f-a6c3-4718-8d17-2a35908ba46b', 'NC26.3.ANR.6', 3, 'numeric', 'Find a missing amount in a two-step story', 'Sam had some stickers. He got 6 more stickers and then gave 4 stickers to his sister. Now he has 20 stickers. How many stickers did Sam have at the start?', '[]', '18', '20+4-6', 'Work backward. Before giving 4 away he had $20 + 4 = 24$. Before getting 6 more he had $24 - 6 = 18$ stickers.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"s + 6 - 4 = 20, so s + 2 = 20, s = 18. Check: 18 + 6 = 24, 24 - 4 = 20.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0203aaf6-9455-4787-bb00-27e9ff86e94b', 'NC26.3.ANR.7', 1, 'choice', 'Unit fraction: one equal part of a whole', 'A square sheet of paper is folded into 4 equal parts. Which fraction names one of the parts?', '["$\\frac{4}{1}$","$\\frac{1}{3}$","$\\frac{3}{4}$","$\\frac{1}{4}$"]', '$\frac{1}{4}$', NULL, 'The whole is split into 4 equal parts, so one part is $\frac{1}{4}$. The fraction $\frac{3}{4}$ names three of the parts.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 equal parts, one part = 1/4.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
