INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08b41bfd-6a9b-487e-b603-1fa82f670049', 'NC26.3.ANR.7', 1, 'numeric', 'Build a fraction from unit fractions', 'A fraction is made of 3 pieces that are each $\frac{1}{4}$ of a whole. What fraction is it? Write your answer like 1/2.', '[]', '3/4', '3*(1/4)', '3 pieces that are each $\frac{1}{4}$ make $\frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"3/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 pieces of 1/4 = 3/4.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
