INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03f55e31-32f6-4b31-8100-0ac18f0c8851', 'NC26.3.SGMR.1', 3, 'choice', 'Parallel lines', 'Lines p, q and r are three different lines on one flat page. Line p is parallel to line q, and line r is parallel to line q. What is true about lines p and r?', '["They are perpendicular.","They are parallel.","They cross at one point.","They make an acute angle."]', 'They are parallel.', NULL, 'Lines that are each parallel to the same line all run in the same direction. So p and r never meet: they are parallel to each other.', 'checked', '{"lint":[],"solve":{"answer":"They are parallel.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two different lines both parallel to q on one plane are parallel to each other.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05c5ac13-ff6c-4d60-8960-218981dfef21', 'NC26.3.SGMR.1', 3, 'numeric', 'Right, acute and obtuse angles', 'Mina marks 10 angles in a drawing. 2 of them are right angles. There are 3 times as many acute angles as right angles. All the other angles are obtuse. How many angles are obtuse?', '[]', '2', '10-2-3*2', 'There are $3 \times 2 = 6$ acute angles. The right and acute angles together make $2 + 6 = 8$ angles. The other $10 - 8 = 2$ angles are obtuse.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Right 2, acute 3 x 2 = 6, obtuse 10 - 2 - 6 = 2.","run_id":"claude-code","at":"2026-10-18T03:30:59.017Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('114c9634-f93f-43fc-9070-431baa3ed104', 'NC26.3.SGMR.2', 1, 'choice', 'Elapsed time: find how long', 'The school bus left at 8:05 and arrived at 8:30. How many minutes did the bus ride take?', '["35","30","25","5"]', '25', '30-5', 'From 8:05 to 8:30 is $30 - 5 = 25$ minutes. Adding the minutes gives 35, and using only one time gives 30 or 5.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8:05 to 8:30 is 30 - 5 = 25 minutes.","run_id":"claude-code","at":"2026-10-17T19:22:21.483Z"}}', 'ai', NULL, NULL)
