INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1064bc33-0730-448e-bc56-1eb48a0bb125', 'NC26.3.SGMR.2', 1, 'choice', 'Read a clock to the minute', 'On a clock, the hour hand points exactly at the 5 and the minute hand points exactly at the 12. What time is it?', '["12:05","5:00","5:12","5:30"]', '5:00', NULL, 'The minute hand on the 12 means 0 minutes past the hour. The hour hand on the 5 means it is 5 o''clock: 5:00.', 'checked', '{"lint":[],"solve":{"answer":"5:00","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Minute hand on 12 means o''clock; hour hand exactly at 5: 5:00.","run_id":"claude-code","at":"2026-10-17T19:22:21.483Z"}}', 'ai', NULL, NULL)
