INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b739ba1-4c1e-4246-9fa4-43ee0c399162', 'NC26.3.SGMR.3', 1, 'numeric', 'Area of a rectangle or square by multiplying side lengths', 'A rectangular poster is 3 feet wide and 6 feet tall. What is its area in square feet?', '[]', '18', '3*6', 'Multiply the two side lengths: $3 \times 6 = 18$ square feet.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 6 = 18 square feet.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
