INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('005ea449-5fee-4fb4-baac-eddb98faa9f6', 'NC26.3.SGMR.3', 3, 'numeric', 'Area of a rectangle or square by multiplying side lengths', 'A kitchen floor is 9 feet by 7 feet. A bathroom floor is 5 feet by 6 feet. How many more square feet is the area of the kitchen floor than the area of the bathroom floor?', '[]', '33', '9*7-5*6', 'The kitchen floor is $9 \times 7 = 63$ square feet. The bathroom floor is $5 \times 6 = 30$ square feet. The difference is $63 - 30 = 33$ square feet.', 'checked', '{"lint":[],"solve":{"answer":"33","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Kitchen 9 x 7 = 63; bathroom 5 x 6 = 30; 63 - 30 = 33.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
