INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e36194a-687f-40fe-a783-fe6fc1855f43', 'NC26.3.RD.1', 1, 'choice', 'Plan and carry out data collection', 'Rosa will ask her classmates to choose a favorite pet. What can she use to keep count while she asks?', '["a clock","a ruler","a tally chart","a thermometer"]', 'a tally chart', NULL, 'A tally chart lets Rosa make one mark for each answer as she goes, then count the marks.', 'checked', '{"lint":[],"solve":{"answer":"a tally chart","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A tally chart keeps count of choices as they are made.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
