INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00228252-4a1a-42a6-8469-31bf1eabd625', 'NC26.3.RD.1', 3, 'choice', 'Pose a question that data can answer', 'Which question would give different answers from different students, so collecting data makes sense?', '["How many days are in a week?","How many sides does a triangle have?","What is 6 times 7?","How many brothers and sisters does each student in our class have?"]', 'How many brothers and sisters does each student in our class have?', NULL, 'Students can have different numbers of brothers and sisters, so data is needed. The other questions have the same answer for everyone.', 'checked', '{"lint":[],"solve":{"answer":"How many brothers and sisters does each student in our class have?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only the number of siblings varies from student to student; the others have one fixed answer.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
