VALUES ('07f8bc88-e4e1-4b96-9ae0-e2f1ead39f9f', 'NC26.4.ANR.2', 1, 'numeric', 'Subtract multi-digit numbers with the standard algorithm', 'How much is $28{,}600$ minus $4{,}200$?', '[]', '24400', '28600-4200', 'No regrouping is needed: 28,600 - 4,200 = 24,400.', 'checked', '{"lint":[],"solve":{"answer":"24400","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"28,600 - 4,200 = 24,400.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
