VALUES ('0118315d-4ef9-44aa-8892-c1dfdf33435b', 'NC26.4.ANR.3', 2, 'choice', 'Multi-digit products', 'What is $1{,}236 \times 4$?', '["$4{,}844$","$4{,}934$","$4{,}244$","$4{,}944$"]', '$4{,}944$', NULL, '$6 \times 4 = 24$, $30 \times 4 = 120$, $200 \times 4 = 800$ and $1{,}000 \times 4 = 4{,}000$. Add: $24 + 120 + 800 + 4{,}000 = 4{,}944$.', 'checked', '{"lint":[],"solve":{"answer":"$4{,}944$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1,000x4 = 4,000; 200x4 = 800; 30x4 = 120; 6x4 = 24. Total 4,944.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
