INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f0d1100-229f-4951-b70a-4f110288f94c', 'NC26.4.ANR.4', 2, 'numeric', 'Equation with a letter: solve a two-step equation', 'Solve for $y$: $y \div 4 + 7 = 15$.', '[]', '32', '(15-7)*4', 'Take away 7: $15 - 7 = 8$, so $y \div 4 = 8$. Then $y = 8 \times 4 = 32$. Check: $32 \div 4 + 7 = 15$.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y / 4 = 15 - 7 = 8; y = 32.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04fa1e85-4bff-4e0e-90a1-1e150b60e987', 'NC26.4.ANR.4', 2, 'choice', 'Equation with a letter: solve a two-step equation', 'What is the value of $k$ in $4 \times k - 10 = 30$?', '["5","40","10","30"]', '10', '(30+10)/4', 'Undo the subtraction: $30 + 10 = 40$, so $4 \times k = 40$ and $k = 10$. Check: $4 \times 10 - 10 = 30$. The choice 5 subtracts 10 instead of adding it, and 40 stops before dividing.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4k = 40; k = 10.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0675363b-70e6-4f35-a985-cd0d31dc9a1a', 'NC26.4.ANR.4', 3, 'choice', 'Two-step problem: multiply, then add or subtract', 'A bakery bakes 24 trays of rolls with 36 rolls on each tray. It sells 750 rolls. How many rolls are left?', '["114","864","786","60"]', '114', '24*36-750', 'The bakery bakes $24 \times 36 = 864$ rolls. After selling 750, $864 - 750 = 114$ rolls are left. The choice 864 forgets to subtract, 786 adds 36 to 750, and 60 adds 24 and 36.', 'checked', '{"lint":[],"solve":{"answer":"114","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 x 36 = 720 + 144 = 864; 864 - 750 = 114.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0123532d-8088-4ff3-92ad-10e75a037048', 'NC26.4.ANR.4', 3, 'choice', 'Equation with a letter: choose the equation for a story', 'Jin has 3 bags with $m$ marbles in each bag and 9 loose marbles. He has 36 marbles in all. Which equation does NOT match this story?', '["$3 \\times m + 9 = 36$","$36 - 9 = 3 \\times m$","$36 - 3 \\times m = 9$","$3 \\times m = 36 + 9$"]', '$3 \times m = 36 + 9$', NULL, 'The story says $3 \times m + 9 = 36$. The equations $36 - 9 = 3 \times m$ and $36 - 3 \times m = 9$ say the same thing in other ways. But $3 \times m = 36 + 9$ adds the loose marbles instead of taking them away.', 'checked', '{"lint":[],"solve":{"answer":"$3 \\times m = 36 + 9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3m + 9 = 36 gives m = 9. 36 - 9 = 3m and 36 - 3m = 9 are equivalent. 3m = 36 + 9 gives m = 15: does not match.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('23a9f273-45bb-4aca-8e14-5f5f5d0330b7', 'NC26.4.ANR.5', 1, 'choice', 'Recognize equivalent fractions', 'Which fraction is another name for one half?', '["$\\frac{4}{8}$","$\\frac{1}{4}$","$\\frac{2}{3}$","$\\frac{5}{8}$"]', '$\frac{4}{8}$', NULL, 'One half is 1 out of 2 equal parts. Multiplying both numbers by 4 gives $\frac{4}{8}$, which is also one half. The other fractions are not half of a whole.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{4}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/8 = 1/2. 1/4, 5/8, 2/3 are not 1/2.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06d46aea-3a7d-4813-bcac-96e599ab1720', 'NC26.4.ANR.5', 1, 'choice', 'Order fractions', 'A pizza is cut into pieces that are $\frac{1}{2}$, $\frac{1}{8}$ and $\frac{1}{4}$ of the whole. Which list shows the pieces from biggest to smallest?', '["$\\frac{1}{8}$, $\\frac{1}{4}$, $\\frac{1}{2}$","$\\frac{1}{4}$, $\\frac{1}{2}$, $\\frac{1}{8}$","$\\frac{1}{8}$, $\\frac{1}{2}$, $\\frac{1}{4}$","$\\frac{1}{2}$, $\\frac{1}{4}$, $\\frac{1}{8}$"]', '$\frac{1}{2}$, $\frac{1}{4}$, $\frac{1}{8}$', NULL, 'Each fraction is one piece. Halves are the biggest pieces, then fourths, then eighths. From greatest to least: $\frac{1}{2}$, $\frac{1}{4}$, $\frac{1}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2}$, $\\frac{1}{4}$, $\\frac{1}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: 1/2 + 1/4 + 1/8 = 7/8, so these three pieces cannot be the whole pizza; reads fine if other pieces exist. Answer unaffected.","work":"Unit fractions, biggest to smallest: 1/2, 1/4, 1/8.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15ee49d7-c41b-406b-9b84-e929eac338ec', 'NC26.4.ANR.5', 1, 'numeric', 'Place value in decimals', 'In the number 0.63, which digit is in the tenths place?', '[]', '6', NULL, 'The first digit after the decimal point is the tenths place. In 0.63 that digit is 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.63: 6 tenths, 3 hundredths. Tenths digit 6.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
