INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c1445e9-c9f9-4b0d-814b-501bbef53f08', 'NC26.4.ANR.5', 2, 'choice', 'Compare fractions with the same denominator or numerator', 'Which statement is true when the top numbers are the same?', '["$\\frac{4}{8} > \\frac{4}{6}$","$\\frac{3}{5} < \\frac{3}{4}$","$\\frac{5}{12} > \\frac{5}{10}$","$\\frac{1}{3} < \\frac{1}{5}$"]', '$\frac{3}{5} < \frac{3}{4}$', NULL, 'With the same top number, the fraction with the smaller bottom number is greater because its pieces are larger. Fifths are smaller than fourths, so $\frac{3}{5} < \frac{3}{4}$. Each of the other three statements points the wrong way.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{5} < \\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same numerator: smaller denominator is bigger. 4/8 < 4/6 (false), 3/5 < 3/4 (true), 5/12 < 5/10 (false), 1/3 > 1/5 (false).","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0edc2180-b126-49f2-9d33-c349cf002ce8', 'NC26.4.ANR.5', 2, 'numeric', 'Order decimals', 'Which is the least of 0.3, 0.29 and 0.31? Type that number.', '[]', '0.29', '0.29', 'Write them in hundredths: 30, 29 and 31 hundredths. The least is 29 hundredths, 0.29.', 'checked', '{"lint":[],"solve":{"answer":"0.29","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.30, 0.29, 0.31 -> least 0.29.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
