INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b387f31-c20a-4a21-86e1-e4b552ff4801', 'NC26.4.ANR.6', 1, 'numeric', 'Add or subtract fractions in a story', 'Kai walks $\frac{3}{10}$ mile to the library and then $\frac{4}{10}$ mile to the park. How many miles does he walk in all?', '[]', '7/10', '3/10+4/10', 'Add the distances: $\frac{3}{10} + \frac{4}{10} = \frac{7}{10}$ mile.', 'checked', '{"lint":[],"solve":{"answer":"7/10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/10 + 4/10 = 7/10 mile.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
