INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0151cad5-a5f6-4996-ad90-528cfb62f0a9', 'NC26.4.ANR.6', 3, 'choice', 'Explain fraction operations', 'Which statement about the sum $\frac{3}{5} + \frac{4}{5}$ is true?', '["The sum is $\\frac{7}{10}$.","The sum is less than 1.","The sum is greater than 1.","The sum is $\\frac{12}{5}$."]', 'The sum is greater than 1.', NULL, '$\frac{3}{5} + \frac{4}{5} = \frac{7}{5}$, because the numerators add and the denominator stays 5. Since 7 fifths is more than 5 fifths, the sum is greater than 1.', 'checked', '{"lint":[],"solve":{"answer":"The sum is greater than 1.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/5 + 4/5 = 7/5 > 1.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('030c165a-b31b-4d71-af99-5da5f8636577', 'NC26.4.ANR.7', 1, 'numeric', 'Find the rule of a number pattern', 'The numbers in a pattern are 7, 14, 21, 28. Each number is how much more than the number before it?', '[]', '7', '14-7', '14 - 7 = 7, 21 - 14 = 7 and 28 - 21 = 7. Each number is 7 more.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14-7=7, 21-14=7, 28-21=7.","run_id":"claude-code","at":"2026-10-17T19:20:19.061Z"}}', 'ai', NULL, NULL)
