VALUES ('0ca01820-056f-4ff4-9765-4185f8a4b11a', 'NC26.4.SGMR.4', 2, 'numeric', 'Find a missing side from the area', 'A rectangular parking lot has an area of 480 square yards and a width of 8 yards. What is its length in yards?', '[]', '60', '480/8', '$480 \div 8 = 60$ yards.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length = 480 / 8 = 60 yards.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
