INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0130589f-3297-4f3e-9ddd-d68ace2cca78', 'NC26.4.SGMR.4', 2, 'choice', 'Choose area or perimeter for the situation', 'Tom tiles the floor of a rectangular bathroom that is 8 feet long and 5 feet wide. Each tile covers 1 square foot and each box holds 10 tiles. How many boxes does he need to cover the floor exactly?', '["40","13","50","4"]', '4', '8*5/10', 'The floor is $8 \times 5 = 40$ square feet, so he needs 40 tiles. $40 \div 10 = 4$ boxes.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area = 8 x 5 = 40 tiles. Boxes = 40 / 10 = 4.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
