INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0efaf739-7597-43ce-a013-23c25c7a341d', 'NC26.4.SGMR.4', 2, 'choice', 'Perimeter of a rectilinear figure', 'An L-shaped garden has six sides. Going around the edge, they measure 8 m, 3 m, 5 m, 4 m, 3 m and 7 m. What is its perimeter in meters?', '["30","27","36","60"]', '30', '8+3+5+4+3+7', 'Add all six sides: $8 + 3 + 5 + 4 + 3 + 7 = 30$ meters. 27 leaves out a side, and 36 is the area of the garden.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Check shape: 8 = 5 + 3 and 7 = 3 + 4, consistent. Perimeter = 8 + 3 + 5 + 4 + 3 + 7 = 30 m.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
