INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29dc6a0a-5e0a-409d-8d34-1bea7f859e6b', 'NC26.4.RD.1', 2, 'numeric', 'Mode', 'Students were asked how many siblings they have. 0 siblings: 4 students. 1 sibling: 9 students. 2 siblings: 7 students. 3 siblings: 2 students. What is the mode of the number of siblings?', '[]', '1', '1', 'The greatest frequency is 9, for 1 sibling, so the mode is 1.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Most students (9) have 1 sibling; mode 1.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
