INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('115ea441-39a2-4a24-b973-41b2c8c9c9ab', 'NC26.4.RD.1', 3, 'numeric', 'Double bar graph: compare two data sets', 'A double bar graph shows how many girls and how many boys joined four clubs. Girls: art 9, chess 12, drama 7, music 10. Boys: art 11, chess 8, drama 7, music 13. How many more boys than girls joined the four clubs in all?', '[]', '1', '(11+8+7+13)-(9+12+7+10)', 'Boys: $11 + 8 + 7 + 13 = 39$. Girls: $9 + 12 + 7 + 10 = 38$. The difference is $39 - 38 = 1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Girls 9 + 12 + 7 + 10 = 38; boys 11 + 8 + 7 + 13 = 39; 39 - 38 = 1.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('113fa276-5c0e-472a-87b0-67450ba3fb67', 'NC26.5.ANR.1', 1, 'choice', 'Write an expression for a described calculation', 'Which expression means "add 5 and 2, then multiply the result by 3"?', '["$5 + 2 \\times 3$","$(5 + 2) \\times 3$","$5 \\times 3 + 2$","$5 + 2 + 3$"]', '$(5 + 2) \times 3$', NULL, 'The adding happens first, so $5 + 2$ goes inside parentheses and the result is multiplied by 3: $(5 + 2) \times 3$. Without parentheses, the multiplication would be done first.', 'checked', '{"lint":[],"solve":{"answer":"$(5 + 2) \\times 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Add 5 and 2 first needs parentheses: (5 + 2), then times 3: (5 + 2) x 3 = 21.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00388d18-11de-470d-b37b-8b0006542752', 'NC26.5.ANR.1', 1, 'choice', 'Write an expression for a described calculation', 'Which expression shows "multiply 4 by 6, then add 7"?', '["$4 \\times 6 + 7$","$4 \\times (6 + 7)$","$(4 + 6) \\times 7$","$4 + 6 \\times 7$"]', '$4 \times 6 + 7$', NULL, 'Multiplying 4 by 6 gives $4 \times 6$, and then adding 7 gives $4 \times 6 + 7$. Because the multiplication comes first anyway, no parentheses are needed.', 'checked', '{"lint":[],"solve":{"answer":"$4 \\times 6 + 7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiply 4 by 6 gives 4 x 6, then add 7: 4 x 6 + 7 (order of operations does the product first).","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0783a17c-95ed-4b15-aa43-a055dfdc8339', 'NC26.5.ANR.1', 1, 'numeric', 'Commutative property', 'Mia knows that $17 \times 24$ equals 408. What is the value of $24 \times 17$?', '[]', '408', '17*24', 'Changing the order of the factors does not change the product. So $24 \times 17 = 17 \times 24 = 408$.', 'checked', '{"lint":[],"solve":{"answer":"408","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Commutative: 24 x 17 = 17 x 24 = 408. (Check 17 x 24 = 340 + 68 = 408.)","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('045524bc-fab6-424a-b604-9e385f95712e', 'NC26.5.ANR.1', 2, 'numeric', 'Associative property of addition', 'What number goes in the box to make the equation true? $12 + (8 + 15) = (12 + \square) + 15$', '[]', '8', NULL, 'Numbers can be grouped in a different way without changing a sum. On the right, 12 is now added to the first number of the pair, which is 8. So the box is 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Associative property: 12 + (8 + 15) = (12 + 8) + 15, so the box is 8. Check: 35 = 35.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2852333b-1361-4684-9de5-766d14ae5b14', 'NC26.5.ANR.1', 2, 'choice', 'Interpret an expression without calculating', 'Maya uses $4 \times 6 + 2 \times 3$ for the cost of 4 notebooks at 6 dollars each and 2 pens at 3 dollars each. What does $2 \times 3$ stand for?', '["The cost of the 4 notebooks","The cost of the 2 pens","The cost of all the items","The number of items bought"]', 'The cost of the 2 pens', NULL, 'The part $2 \times 3$ is 2 pens at 3 dollars each, so it is the cost of the 2 pens.', 'checked', '{"lint":[],"solve":{"answer":"The cost of the 2 pens","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 pens at 3 dollars each: 2 x 3 is the cost of the 2 pens.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21665b95-b736-4a34-85f7-625440aa9a58', 'NC26.5.ANR.1', 2, 'choice', 'Find the mistake in an evaluation', 'Kofi says that $4 + 6 \times 5$ equals 50. What did he do?', '["He multiplied 4 and 6 first, then added 5","He multiplied 6 and 5 first, then subtracted 4","He added 4 and 6 first, then multiplied by 5","He added all three numbers"]', 'He added 4 and 6 first, then multiplied by 5', NULL, 'Adding first gives $(4 + 6) \times 5 = 50$, which is Kofi''s answer. The correct way is to multiply first: $6 \times 5 = 30$, then $4 + 30 = 34$.', 'checked', '{"lint":[],"solve":{"answer":"He added 4 and 6 first, then multiplied by 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Correct value 4 + 30 = 34. 50 = (4 + 6) x 5, so he added 4 and 6 first. B gives 29, C 26, D 15.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('037a88e1-019e-482d-b4df-d3a8b1e0c3bc', 'NC26.5.ANR.1', 3, 'numeric', 'Evaluate an expression with parentheses and two other operations', 'Find the value of $2 \times (15 - 6) + 4 \times 3$.', '[]', '30', '2*(15-6)+4*3', 'Parentheses first: $15 - 6 = 9$. Then multiply: $2 \times 9 = 18$ and $4 \times 3 = 12$. Then add: $18 + 12 = 30$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 - 6 = 9; 2 x 9 = 18; 4 x 3 = 12; 18 + 12 = 30.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05e9a6f8-d6fb-4ea0-ac09-f9cc7abc1f72', 'NC26.5.ANR.1', 3, 'choice', 'Distributive property', 'Which expression is NOT equal to $7 \times 18$?', '["$7 \\times 20 - 7 \\times 2$","$7 \\times 9 \\times 2$","$70 + 56$","$7 \\times 10 + 8$"]', '$7 \times 10 + 8$', NULL, '$7 \times 18 = 126$. Also $7 \times 20 - 7 \times 2 = 140 - 14 = 126$, $7 \times 9 \times 2 = 63 \times 2 = 126$, and $70 + 56 = 126$. But $7 \times 10 + 8 = 78$, because the 7 was not multiplied by the 8.', 'checked', '{"lint":[],"solve":{"answer":"$7 \\times 10 + 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 x 18 = 126. 7 x 9 x 2 = 126; 7 x 10 + 8 = 78 (not equal); 70 + 56 = 126; 140 - 14 = 126.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('127212fd-3d19-4e5f-83ca-aa78221c3967', 'NC26.5.ANR.2', 1, 'choice', 'Expanded form of a number', 'Which is $2{,}561$ in expanded form?', '["$2{,}000 + 50 + 6 + 1$","$200 + 500 + 60 + 1$","$2{,}000 + 500 + 60 + 1$","$2{,}000 + 500 + 600 + 1$"]', '$2{,}000 + 500 + 60 + 1$', NULL, 'The digit 2 is worth 2,000, the 5 is worth 500, the 6 is worth 60 and the 1 is worth 1. So $2{,}561 = 2{,}000 + 500 + 60 + 1$.', 'checked', '{"lint":[],"solve":{"answer":"$2{,}000 + 500 + 60 + 1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Easy for Grade 5 (four-digit expanded form, earlier-grade work); fine as a warm-up.","work":"2,561 = 2,000 + 500 + 60 + 1.","run_id":"claude-code","at":"2026-10-17T19:23:26.729Z"}}', 'ai', NULL, NULL)
