INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d827764-029d-4fca-b37e-aa6fbbc828e4', 'NC26.5.ANR.2', 2, 'choice', 'Order decimals', 'Which list shows 1.2, 1.02, 1.002 and 1.21 in order from greatest to least?', '["1.21, 1.2, 1.02, 1.002","1.002, 1.02, 1.2, 1.21","1.21, 1.02, 1.2, 1.002","1.2, 1.21, 1.02, 1.002"]', '1.21, 1.2, 1.02, 1.002', NULL, 'All have 1 one. Write them with three places: 1.200, 1.020, 1.002 and 1.210. From greatest to least: 1.210, 1.200, 1.020, 1.002.', 'checked', '{"lint":[],"solve":{"answer":"1.21, 1.2, 1.02, 1.002","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.210 > 1.200 > 1.020 > 1.002.","run_id":"claude-code","at":"2026-10-17T19:23:26.729Z"}}', 'ai', NULL, NULL)
