INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c9ab94c-85c8-41a5-841a-6bb5b7b78252', 'NC26.5.ANR.2', 2, 'choice', 'Compare whole numbers up to the millions', 'Which number is greater than $2{,}345{,}678$?', '["$2{,}354{,}000$","$2{,}345{,}000$","$2{,}335{,}999$","$2{,}099{,}999$"]', '$2{,}354{,}000$', NULL, 'All the numbers have 2 millions, so compare place by place. $2{,}354{,}000$ and $2{,}345{,}678$ both have 3 hundred thousands, but then 5 ten thousands beats 4 ten thousands. So $2{,}354{,}000$ is greater. The others are less: $2{,}345{,}000$ has fewer hundreds, $2{,}335{,}999$ has only 3 ten thousands and $2{,}099{,}999$ has only 0 hundred thousands.', 'checked', '{"lint":[],"solve":{"answer":"$2{,}354{,}000$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2,354,000 vs 2,345,678: ten thousands 5 > 4, so greater. The others are smaller (2,099,999; 2,345,000; 2,335,999).","run_id":"claude-code","at":"2026-10-17T19:23:26.729Z"}}', 'ai', NULL, NULL)
