INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21481961-bdd0-4352-9a06-3b9dd3995c10', 'NC26.5.ANR.3', 1, 'choice', 'Divide a four-digit number by a one-digit number', 'What is $4{,}800 \div 6$?', '["80","8,000","8","800"]', '800', '4800/6', '$48 \div 6 = 8$. $4{,}800$ is 48 hundreds, so $4{,}800 \div 6 = 800$.', 'checked', '{"lint":[],"solve":{"answer":"800","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4,800 / 6 = 800 (6 x 800 = 4,800).","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
