VALUES ('139326a9-4278-4fb2-9caa-d2057d1c9cc8', 'NC26.5.ANR.4', 2, 'choice', 'Solve a two-step problem with decimals', 'Maya buys 2 books that cost 6.75 dollars each. She pays with a 20-dollar bill. How many dollars of change does she get?', '["6.5","13.5","13.25","33.5"]', '6.5', '20-2*6.75', 'The books cost $2 \times 6.75 = 13.50$ dollars. Change: $20 - 13.50 = 6.50$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"6.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 x 6.75 = 13.50; 20 - 13.50 = 6.50 dollars.","run_id":"claude-code","at":"2026-10-17T20:08:27.980Z"}}', 'ai', NULL, NULL)
