VALUES ('0e0abfac-baf7-48b2-bcae-e4a5411d92d9', 'NC26.5.ANR.4', 2, 'choice', 'Reason about decimal operations', 'The sum of 4.6 and a number is 7.15. What is the number?', '["3.55","2.55","11.75","2.65"]', '2.55', '7.15-4.6', 'The number is $7.15 - 4.60 = 2.55$. (Check: $4.60 + 2.55 = 7.15$.)', 'checked', '{"lint":[],"solve":{"answer":"2.55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7.15 - 4.60 = 2.55 (check 4.6 + 2.55 = 7.15).","run_id":"claude-code","at":"2026-10-17T20:08:27.980Z"}}', 'ai', NULL, NULL)
