INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e87307b-9710-4add-b1bc-94add4359828', 'NC26.5.ANR.5', 1, 'numeric', 'Divide a unit fraction by a whole number', 'Divide $\frac{1}{2}$ by 3.', '[]', '1/6', '1/2/3', 'Split $\frac{1}{2}$ into 3 equal parts. Each part is $\frac{1}{6}$, since 6 of those parts make a whole. So $\frac{1}{2}$ $\div 3 = \frac{1}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"1/6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 ÷ 3 = 1/2 × 1/3 = 1/6. Check: 3 × 1/6 = 1/2.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14ad7c18-5971-4b5f-8253-2ddd10674c25', 'NC26.5.ANR.5', 2, 'choice', 'Subtract fractions with unlike denominators', 'Kim had $\frac{3}{4}$ of a tank of gas. After a trip she had $\frac{1}{5}$ of a tank left. What fraction of a tank did she use?', '["$\\frac{19}{20}$","$\\frac{11}{20}$","$\\frac{1}{2}$","$\\frac{4}{20}$"]', '$\frac{11}{20}$', NULL, 'A common denominator is 20. $\frac{3}{4}$ = $\frac{15}{20}$ and $\frac{1}{5}$ = $\frac{4}{20}$. She used $\frac{15}{20} - \frac{4}{20}$ = $\frac{11}{20}$ of a tank.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{11}{20}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Used = 3/4 - 1/5 = 15/20 - 4/20 = 11/20.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20a817df-5991-47a4-9fd7-51f7124d62d1', 'NC26.5.ANR.5', 2, 'choice', 'Add and subtract mixed numbers with unlike denominators', 'A baker used $3\frac{2}{3}$ cups of flour for bread and $2\frac{3}{4}$ cups of flour for rolls. How many cups of flour did the baker use in all?', '["$5\\frac{5}{7}$","$6\\frac{1}{12}$","$6\\frac{5}{12}$","$5\\frac{5}{12}$"]', '$6\frac{5}{12}$', NULL, 'Add the wholes: $3 + 2 = 5$. Add the fractions: $\frac{2}{3} + \frac{3}{4}$ = $\frac{8}{12} + \frac{9}{12}$ = $\frac{17}{12}$ = $1\frac{5}{12}$. Then $5 + 1$ and $\frac{5}{12}$ gives $6\frac{5}{12}$. The choice $5\frac{5}{12}$ forgets to carry the extra whole.', 'checked', '{"lint":[],"solve":{"answer":"$6\\frac{5}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Wholes 3+2 = 5; fractions 2/3+3/4 = 8/12+9/12 = 17/12 = 1 5/12. Total 6 5/12 cups.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d0b7399-1dc9-4dfb-8335-cdf96182734f', 'NC26.5.ANR.5', 2, 'choice', 'Estimate and compare sums and differences using benchmark fractions', 'Which of these sums is greater than 1?', '["$\\frac{1}{2} + \\frac{1}{3}$","$\\frac{3}{4} + \\frac{1}{6}$","$\\frac{2}{3} + \\frac{3}{8}$","$\\frac{1}{5} + \\frac{3}{4}$"]', '$\frac{2}{3} + \frac{3}{8}$', NULL, '$\frac{2}{3} + \frac{3}{8}$ = $\frac{16}{24} + \frac{9}{24}$ = $\frac{25}{24}$, which is more than 1. The other sums are $\frac{5}{6}$, $\frac{11}{12}$ and $\frac{19}{20}$, all less than 1.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{3} + \\frac{3}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3+3/8 = 16/24+9/24 = 25/24 > 1. 1/5+3/4 = 19/20. 3/4+1/6 = 11/12. 1/2+1/3 = 5/6. Only the first exceeds 1.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0286ec1f-4f70-47ce-88e9-1559358f3325', 'NC26.5.ANR.5', 3, 'numeric', 'Multiply a whole number by a fraction', 'Mia multiplied a whole number by $\frac{3}{4}$ and got 18. What whole number did she multiply?', '[]', '24', '18/(3/4)', '18 is 3 fourths of the number, so one fourth is $18 \div 3 = 6$. The whole number is 4 fourths: $4 \times 6 = 24$. Check: $\frac{3}{4}$ of 24 is 18.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n × 3/4 = 18, so 1/4 of n = 6 and n = 24. Check: 24 × 3/4 = 18.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0092327f-3e47-41e9-aa02-fce37b622051', 'NC26.5.ANR.5', 3, 'numeric', 'Multiply a fraction by a fraction', 'Multiply $\frac{5}{8} \times \frac{12}{25}$ and write the product in simplest form.', '[]', '3/10', '5/8*12/25', '$\frac{5}{8} \times \frac{12}{25}$ = $\frac{60}{200}$. Divide the top and bottom by 20 to get $\frac{3}{10}$.', 'checked', '{"lint":[],"solve":{"answer":"3/10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/8 × 12/25 = 60/200 = 3/10.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02f1eb28-8065-4823-ac37-c2319936dc94', 'NC26.5.ANR.6', 1, 'choice', 'Generate a multiplying pattern from a rule', 'Dev writes a pattern that starts at 5 and multiplies by 2 each time. Which list shows his pattern?', '["5, 10, 15, 20","5, 7, 9, 11","5, 10, 20, 40","5, 25, 125, 625"]', '5, 10, 20, 40', NULL, 'Start at 5 and double each time: 5, 10, 20, 40. The list (5, 10, 15, 20) adds 5; the list (5, 7, 9, 11) adds 2; and the list (5, 25, 125, 625) multiplies by 5.', 'checked', '{"lint":[],"solve":{"answer":"5, 10, 20, 40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5, 10, 20, 40 (each doubled).","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03e549cb-9c9b-422d-ab61-69d997f7bb24', 'NC26.5.ANR.6', 1, 'choice', 'Decide whether a number is in a pattern, and find its position', 'Which number is in the pattern 5, 10, 15, 20, ...?', '["35","32","41","23"]', '35', '5*7', 'The pattern counts by 5s: 5, 10, 15, 20, 25, 30, 35. Only 35 is on the list; 32, 41 and 23 do not end in 0 or 5.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The pattern is the multiples of 5. 35 = 5 x 7 is one; 23, 41, 32 are not.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
