INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('065e33e2-f690-4b50-84d6-8aaae3cfb3cf', 'NC26.5.SGMR.2', 1, 'numeric', 'Find a missing corner of a shape', 'Three corners of a square are $(2, 2)$, $(6, 2)$ and $(6, 6)$. What is the x-coordinate of the fourth corner?', '[]', '2', '2', 'The fourth corner is above $(2, 2)$ and level with $(6, 6)$, so it is $(2, 6)$. Its x-coordinate is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square of side 4 with corners (2,2), (6,2), (6,6); fourth is (2, 6). x = 2.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
