VALUES ('1b768401-6480-4c81-ab05-323ab7048748', 'NC26.5.SGMR.3', 1, 'choice', 'Convert measurements given as decimals or fractions', 'A bag of oats has a mass of 1.5 kilograms. What is its mass in grams? (1 kilogram = 1,000 grams)', '["150","15","1,005","1,500"]', '1,500', '1.5*1000', '$1.5 \times 1{,}000 = 1{,}500$ grams: 1,000 grams for the first kilogram and 500 for the half.', 'checked', '{"lint":[],"solve":{"answer":"1,500","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.5 kg x 1,000 = 1,500 g.","run_id":"claude-code","at":"2026-10-17T19:22:28.446Z"}}', 'ai', NULL, NULL)
