INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06dbb7d2-60e7-4ee5-94b2-6e144c5b8565', 'NC26.5.SGMR.4', 2, 'numeric', 'Understand volume and cubic units', 'A solid made of unit cubes has a volume of 40 cubic units. It has 5 layers that are all the same size. How many cubes are in each layer?', '[]', '8', '40/5', 'The 40 cubes are shared equally among 5 layers: $40 \div 5 = 8$ cubes in each layer.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40 / 5 layers = 8 cubes per layer.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
