INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10694f9b-495b-4d7b-9c01-58dcfb61739a', 'NC26.5.SGMR.4', 3, 'choice', 'Volume in a real-world problem', 'A pit that is 9 meters long, 5 meters wide and 2 meters deep must be filled with soil. One truck carries 15 cubic meters of soil. How many truckloads fill the pit exactly?', '["3","16","6","1,350"]', '6', '9*5*2/15', 'The pit holds $9 \times 5 \times 2 = 90$ cubic meters. Then $90 \div 15 = 6$ truckloads. Using only the base area gives 3, and adding the measurements gives 16.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 x 5 x 2 = 90 cubic m; 90 / 15 = 6 truckloads.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
