INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b8b4339-2502-4d0a-8109-41291317cc52', 'NC26.6.RPR.1', 1, 'numeric', 'Unit ratio (amount per 1)', 'Mia walks 8 miles in 2 hours at a steady pace. How many miles does she walk in 1 hour?', '[]', '4', '8/2', 'Divide the distance by the time: $8 \div 2 = 4$ miles in 1 hour.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 / 2 = 4 miles.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
