INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02c06148-10ad-47e2-a780-229e0e242883', 'NC26.6.RPR.1', 2, 'numeric', 'Unit ratio (amount per 1)', 'A 5-pound bag of rice costs 12 dollars. How many dollars does 1 pound of rice cost?', '[]', '2.4', '12/5', 'Divide the cost by the number of pounds: $12 \div 5 = 2.4$ dollars for 1 pound.', 'checked', '{"lint":[],"solve":{"answer":"2.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 / 5 = 2.4 dollars.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
