INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('035352be-1b48-4da9-b5a6-83a28b7766f5', 'NC26.6.RPR.1', 3, 'choice', 'Writing a ratio in different notations', 'The ratio of blue tiles to red tiles is 5 to 8. Which pair shows this ratio in two different ways?', '["$5 : 8$ and $\\frac{5}{8}$","$5 : 8$ and $\\frac{8}{5}$","5 to 8 and $8 : 5$","$5 : 13$ and $\\frac{5}{8}$"]', '$5 : 8$ and $\frac{5}{8}$', NULL, 'Blue is first, so the ratio is $5 : 8$, which can also be written $\frac{5}{8}$ or "5 to 8". The other pairs reverse the order in one of the two ways or use 13, the total number of tiles.', 'checked', '{"lint":[],"solve":{"answer":"$5 : 8$ and $\\frac{5}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Blue to red 5 to 8 = 5 : 8 = 5/8. Others reverse or use the total.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0138d8ea-6f08-4d10-9630-a1be87a7238c', 'NC26.6.RPR.1', 3, 'numeric', 'Unit ratio (amount per 1)', 'Pete reads 45 pages in $1\frac{1}{2}$ hours at a steady pace. How many pages does he read in 1 hour?', '[]', '30', '45/1.5', 'In $\frac{1}{2}$ hour he reads $45 \div 3 = 15$ pages, since $1\frac{1}{2}$ hours is 3 half-hours. In 1 hour (2 half-hours) he reads $2 \times 15 = 30$ pages. Or $45 \div 1\frac{1}{2} = 30$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45 / (3/2) = 45 x 2/3 = 30 pages.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('028534ed-eed0-40d6-baf6-cbf887fbd676', 'NC26.6.RPR.2', 1, 'choice', 'Finding a part: percent of a quantity', 'A box has 200 marbles. 25% of the marbles are red. How many marbles are red?', '["50","8","25","175"]', '50', '200*25/100', '25% is one fourth, so $200 \div 4 = 50$ marbles are red. (8 divides 200 by 25, 25 just repeats the percent, and 175 subtracts 25 from 200.)', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25% of 200 = 200/4 = 50.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0dc8c318-c4ae-4ebe-9837-b7563a6bf72e', 'NC26.6.RPR.2', 1, 'choice', 'Finding a part: percent of a quantity', 'There are 50 apples in a basket. 20% of them are green. How many apples are green?', '["30","2.5","70","10"]', '10', '50*20/100', '20% of 50 is $\frac{20}{100} \times 50 = 10$ apples. (30 subtracts 20 from 50, 2.5 divides 50 by 20, and 70 adds.)', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20% of 50 = 50/5 = 10.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08534bd2-3d41-4424-8944-c41f3ae6a579', 'NC26.6.RPR.2', 1, 'choice', 'Finding the percent from a part and a whole', 'A pizza is cut into 4 equal slices. Amy eats 1 slice. What percent of the pizza does Amy eat?', '["4%","75%","25%","1%"]', '25%', NULL, '1 slice out of 4 is $\frac{1}{4} = \frac{25}{100}$, which is 25%. (75% is the part left over.)', 'checked', '{"lint":[],"solve":{"answer":"25%","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4 = 25%.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1633c6ed-129d-471c-bba9-64ad7801c162', 'NC26.6.RPR.2', 2, 'choice', 'Independent and dependent variables', 'A plant is 5 centimeters tall and grows 2 centimeters each day. The equation $h = 5 + 2d$ gives its height $h$, in centimeters, after $d$ days. Which statement is correct?', '["The height $h$ is the independent variable, because it is the larger number.","The number of days $d$ is the dependent variable, because it changes each day.","The height $h$ is the dependent variable, because it depends on the number of days.","Both $h$ and $d$ are independent variables, because both can be any number."]', 'The height $h$ is the dependent variable, because it depends on the number of days.', NULL, 'The height is found from the number of days, so the height $h$ depends on $d$. That makes $h$ the dependent variable and $d$ the independent variable.', 'checked', '{"lint":[],"solve":{"answer":"The height $h$ is the dependent variable, because it depends on the number of days.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"h = 5 + 2d: d (days) is chosen/independent; h depends on d, so h is the dependent variable. Other options give wrong roles or wrong reasons.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b21eba2-8a54-43e1-be93-ddb3f711a0cd', 'NC26.6.RPR.2', 2, 'numeric', 'Double number line or graph of a ratio', 'The graph of a ratio relationship between feet of ribbon and its cost in dollars contains the points (3, 12) and (5, 20), written as (feet, dollars). What is the cost, in dollars, of 8 feet of ribbon?', '[]', '32', '8*12/3', 'From the point (3, 12), each foot costs $12 \div 3 = 4$ dollars (the point (5, 20) agrees). So 8 feet cost $8 \times 4 = 32$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12/3 = 4 and 20/5 = 4 dollars per foot. 8 x 4 = 32.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e560cd2-b3bd-4091-bedd-818d2f2dd4c7', 'NC26.6.RPR.2', 2, 'numeric', 'Independent and dependent variables', 'The equation $c = 12 + 3n$ gives the cost $c$, in dollars, of renting skates for $n$ hours: a fee of 12 dollars plus 3 dollars for each hour. What is the cost, in dollars, for 5 hours?', '[]', '27', '12+3*5', 'Put $n = 5$ into the equation: $c = 12 + 3 \times 5 = 12 + 15 = 27$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"c = 12 + 3 x 5 = 12 + 15 = 27.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07f8fcda-ed91-4839-82b5-72d5c3486b15', 'NC26.6.RPR.2', 3, 'choice', 'Ratio table: finding a missing value', 'A ratio table shows that 6 muffins use 4 cups of flour. How many cups of flour are used to make 21 muffins?', '["14","19","31.5","126"]', '14', '4*21/6', '3 muffins use 2 cups, and 21 muffins is 7 groups of 3 muffins, so $7 \times 2 = 14$ cups. (19 adds 15 to both numbers, 31.5 inverts the ratio, and 126 multiplies 6 by 21.)', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 muffins : 4 cups = 3 : 2. 21 = 7 x 3, so 7 x 2 = 14 cups.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('085cd431-f94f-4ada-9a78-87c33abbbd97', 'NC26.6.RPR.2', 3, 'choice', 'Finding the whole from a part and a percent', 'Only 6% of the seats in a theater are empty. There are 9 empty seats. How many seats does the theater have?', '["54","1.5","15","150"]', '150', '9/6*100', '6% of the seats is 9, so 1% is $9 \div 6 = 1.5$ seats. All the seats, 100%, is $1.5 \times 100 = 150$.', 'checked', '{"lint":[],"solve":{"answer":"150","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 is 6%, so 1% = 1.5, 100% = 150.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1505d3cb-e3ab-41e2-8e3a-2843cc43e002', 'NC26.6.ANR.1', 1, 'numeric', 'Greatest common factor of two numbers', 'What is the largest number that divides evenly into both 9 and 27?', '[]', '9', NULL, '9 divides evenly into 9 ($9 \div 9 = 1$) and into 27 ($27 \div 9 = 3$). No larger number divides 9 evenly, so the answer is 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 divides 27, so GCF(9, 27) = 9.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35cff7a2-ed32-40e0-8dfa-16d1d0385993', 'NC26.6.ANR.1', 1, 'choice', 'Least common multiple of two numbers', 'Which is the least common multiple of 3 and 9?', '["27","18","3","9"]', '9', '9', '9 is a multiple of 3 ($3 \times 3 = 9$) and of 9, and no smaller number is a multiple of 9. So the least common multiple is 9. (27 and 18 are common multiples, but not the least. 3 is not a multiple of 9.)', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 is a multiple of 3, so LCM = 9.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e6ad400-1055-46d5-84b1-0bb7f0a503c7', 'NC26.6.ANR.1', 1, 'choice', 'Reading and evaluating exponent form', 'What is the value of $2^4$?', '["8","6","16","32"]', '16', '2^4', '$2^4$ means 4 factors of 2: $2 \times 2 \times 2 \times 2 = 16$. (8 is $2 \times 4$, 6 is $2 + 4$, and 32 is five factors of 2.)', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^4 = 2 x 2 x 2 x 2 = 16.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('13ab46d2-f001-4bab-a704-17ae9749c087', 'NC26.6.ANR.1', 2, 'choice', 'Prime factorization in exponent form', 'Carlos writes 36 as a product of primes in exponent form. Which is his answer?', '["$2^2 \\times 3^2$","$2^2 \\times 9$","$6^2$","$2 \\times 3^3$"]', '$2^2 \times 3^2$', NULL, '$36 = 2 \times 2 \times 3 \times 3 = 2^2 \times 3^2$. The expression $2^2 \times 9$ uses 9 and $6^2$ uses 6, which are not prime, and $2 \times 3^3 = 54$.', 'checked', '{"lint":[],"solve":{"answer":"$2^2 \\times 3^2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36 = 2 x 2 x 3 x 3 = 2^2 x 3^2. 6 and 9 are not prime; 2 x 3^3 = 54.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
