INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('035a9424-31c6-4115-b558-524f954b358a', 'NC26.6.ANR.1', 2, 'numeric', 'Prime factorization in exponent form', 'The prime factorization of 40 is $2^a \times 5$. What is the value of $a$?', '[]', '3', NULL, '$40 = 2 \times 2 \times 2 \times 5 = 2^3 \times 5$, so $a = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40 = 8 x 5 = 2^3 x 5, a = 3.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02518ec9-d7b0-42bf-9c4c-02a3f00e2cff', 'NC26.6.ANR.1', 2, 'choice', 'Reading and evaluating exponent form', 'Which comparison of $2^5$ and $5^2$ is true?', '["$2^5$ is equal to $5^2$","$2^5$ is less than $5^2$","$2^5$ is equal to 10","$2^5$ is greater than $5^2$"]', '$2^5$ is greater than $5^2$', NULL, '$2^5 = 2 \times 2 \times 2 \times 2 \times 2 = 32$ and $5^2 = 5 \times 5 = 25$. So $2^5$ is greater. Swapping the base and the exponent changes the value.', 'checked', '{"lint":[],"solve":{"answer":"$2^5$ is greater than $5^2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^5 = 32, 5^2 = 25. 32 > 25.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a01415c-29ac-4e00-bc74-2bac18256a2c', 'NC26.6.ANR.1', 3, 'choice', 'Using prime factorizations to find the GCF or LCM', 'Maria says that the greatest common factor of $2^2 \times 5^2$ and $2^3 \times 5$ is $2^3 \times 5^2$. Which statement is correct?', '["She is correct; the GCF is $2^3 \\times 5^2$","She found the least common multiple; the GCF is $2^3 \\times 5$","She found the least common multiple; the GCF is $2 \\times 5$","She found the least common multiple; the GCF is $2^2 \\times 5$"]', 'She found the least common multiple; the GCF is $2^2 \times 5$', NULL, 'The greatest common factor uses the smaller power of each shared prime: $2^2$ and $5^1$, so the GCF is $2^2 \times 5 = 20$. Maria used the larger powers, which gives the least common multiple, $2^3 \times 5^2 = 200$.', 'checked', '{"lint":[],"solve":{"answer":"She found the least common multiple; the GCF is $2^2 \\times 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^3 x 5^2 takes highest powers, the LCM (200). GCF takes lowest: 2^2 x 5 = 20.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('037b2ebd-861d-4509-80c8-bfb8c59b91bb', 'NC26.6.ANR.1', 3, 'numeric', 'Relating factors and multiples', 'A whole number is a multiple of 12 and is also a factor of 60. It is greater than 12. What is the number?', '[]', '60', NULL, 'The factors of 60 are 1, 2, 3, 4, 5, 6, 10, 12, 15, 20, 30 and 60. Of these, the multiples of 12 are 12 and 60, so the number greater than 12 is 60.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiples of 12 above 12: 24, 36, 48, 60. Of these only 60 divides 60.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06aa967b-343f-4ef4-8613-503c44502717', 'NC26.6.ANR.2', 1, 'numeric', 'Subtracting fractions and mixed numbers', 'Subtract $1\frac{1}{4}$ from $3\frac{3}{4}$. What is the difference?', '[]', '2 1/2', '(3+3/4)-(1+1/4)', 'Subtract the whole numbers: 3 - 1 = 2. Subtract the fractions: $\frac{3}{4} - \frac{1}{4} = \frac{2}{4} = \frac{1}{2}$. The difference is $2\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"2 1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 3/4 - 1 1/4 = 2 2/4 = 2 1/2.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01d62d6f-238a-4754-8b7c-7f4c3f4af498', 'NC26.6.ANR.2', 1, 'choice', 'Interpreting a quotient', 'Think about $6 \div \frac{1}{2}$. Which statement is true?', '["The answer is less than 6, because halves are smaller than wholes","The answer is 3, because half of 6 is 3","The answer is greater than 6, because each whole holds 2 halves","The answer is 6, because the top number of $\\frac{1}{2}$ is 1"]', 'The answer is greater than 6, because each whole holds 2 halves', NULL, 'Each whole holds 2 halves, so 6 wholes hold 12 halves. $6 \div \frac{1}{2} = 12$, which is greater than 6.', 'checked', '{"lint":[],"solve":{"answer":"The answer is greater than 6, because each whole holds 2 halves","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 / (1/2) = 12, which is greater than 6 because each whole contains 2 halves. The other statements give 6, 3, or ''less than 6'', all false.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d56e1f2-5778-41c8-b2ee-5ddce38a54bb', 'NC26.6.ANR.2', 1, 'choice', 'One-step fraction word problem', 'A pan holds $\frac{3}{4}$ liter of water when it is full. Nia fills $\frac{1}{3}$ of the pan. How many liters of water are in the pan?', '["$\\frac{1}{4}$","$1\\frac{1}{12}$","$2\\frac{1}{4}$","$\\frac{5}{12}$"]', '$\frac{1}{4}$', NULL, '"$\frac{1}{3}$ of" the pan means multiply: $\frac{3}{4} \times \frac{1}{3} = \frac{3}{12} = \frac{1}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/3 of 3/4 liter = 1/3 x 3/4 = 3/12 = 1/4 liter.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('003fd45f-4963-4c70-82ee-70a1d13dd8db', 'NC26.6.ANR.2', 2, 'numeric', 'Subtracting fractions and mixed numbers', 'Find the difference: $4\frac{1}{2} - 1\frac{2}{3}$.', '[]', '2 5/6', '(4+1/2)-(1+2/3)', '$4\frac{1}{2} = 4\frac{3}{6}$ and $1\frac{2}{3} = 1\frac{4}{6}$. Regroup: $4\frac{3}{6} = 3\frac{9}{6}$. Then $3\frac{9}{6} - 1\frac{4}{6} = 2\frac{5}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"2 5/6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 1/2 = 4 3/6 = 3 9/6; 1 2/3 = 1 4/6; 3 9/6 - 1 4/6 = 2 5/6.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04b100eb-1084-4a7f-80b3-32e5bad401d2', 'NC26.6.ANR.2', 2, 'choice', 'Multiplying fractions', 'What is $\frac{5}{12} \times \frac{9}{10}$?', '["$\\frac{25}{54}$","$\\frac{14}{22}$","$\\frac{3}{8}$","$\\frac{1}{2}$"]', '$\frac{3}{8}$', NULL, 'Cancel 5 with 10 (leaving 1 and 2) and 9 with 12 (leaving 3 and 4). The product is $\frac{3}{8}$. Check: $\frac{5}{12} \times \frac{9}{10} = \frac{45}{120} = \frac{3}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/12 x 9/10 = 45/120 = 3/8.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08093b59-dd7e-49b3-849c-61a2e3040200', 'NC26.6.ANR.2', 2, 'choice', 'One-step fraction word problem', 'A rope is $6\frac{1}{2}$ meters long. A piece $2\frac{3}{4}$ meters long is cut off. How long is the rest of the rope?', '["$3\\frac{3}{4}$","$4\\frac{1}{4}$","$9\\frac{1}{4}$","$3\\frac{1}{4}$"]', '$3\frac{3}{4}$', NULL, '$6\frac{1}{2} = \frac{26}{4}$ and $2\frac{3}{4} = \frac{11}{4}$. Then $\frac{26}{4} - \frac{11}{4} = \frac{15}{4} = 3\frac{3}{4}$ meters.', 'checked', '{"lint":[],"solve":{"answer":"$3\\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 1/2 = 6 2/4 = 5 6/4; 5 6/4 - 2 3/4 = 3 3/4 meters.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1704b7e4-98fa-42db-935e-d971ff24a971', 'NC26.6.ANR.2', 3, 'choice', 'Multiplying mixed numbers', 'Which is the product $5\frac{1}{3} \times 2\frac{5}{8}$?', '["$10\\frac{5}{24}$","$7\\frac{23}{24}$","14","$10\\frac{2}{3}$"]', '14', '(5+1/3)*(2+5/8)', '$5\frac{1}{3} = \frac{16}{3}$ and $2\frac{5}{8} = \frac{21}{8}$. Then $\frac{16}{3} \times \frac{21}{8} = 2 \times 7 = 14$ after cancelling 8 into 16 and 3 into 21.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 1/3 = 16/3, 2 5/8 = 21/8; 16/3 x 21/8 = 336/24 = 14.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16e529fe-0313-43a2-8042-8edad4a40ab9', 'NC26.6.ANR.2', 3, 'choice', 'Interpreting a quotient', 'Which of these is NOT a situation that $\frac{2}{3} \div \frac{1}{6}$ describes?', '["How many $\\frac{1}{6}$-meter pieces can be cut from a rope $\\frac{2}{3}$ meter long?","A $\\frac{2}{3}$-liter bottle is shared equally by 6 people. How much does each person get?","$\\frac{2}{3}$ of a pizza is cut into slices that are each $\\frac{1}{6}$ of the whole pizza. How many slices?","How many $\\frac{1}{6}$-cup scoops fit in $\\frac{2}{3}$ cup of rice?"]', 'A $\frac{2}{3}$-liter bottle is shared equally by 6 people. How much does each person get?', NULL, 'The other three ask how many $\frac{1}{6}$s fit in $\frac{2}{3}$, which is $\frac{2}{3} \div \frac{1}{6} = 4$. Sharing $\frac{2}{3}$ among 6 people is $\frac{2}{3} \div 6 = \frac{1}{9}$.', 'checked', '{"lint":[],"solve":{"answer":"A $\\frac{2}{3}$-liter bottle is shared equally by 6 people. How much does each person get?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rope pieces, pizza slices of 1/6 each, and 1/6-cup scoops all ask how many 1/6s are in 2/3 (= 4). Sharing 2/3 liter among 6 people is 2/3 / 6 = 1/9, not 2/3 / (1/6).","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
