INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00554097-87ff-4d19-a167-d60e5c56f883', 'NC26.6.ANR.3', 3, 'numeric', 'Multi-step decimal word problem', 'A tank holds 45.6 liters. It already has 9.6 liters in it. A hose adds 2.4 liters each minute. How many minutes does it take to fill the tank?', '[]', '15', '(45.6-9.6)/2.4', 'Space left: $45.6 - 9.6 = 36$ liters. Time: $36 \div 2.4 = 360 \div 24 = 15$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Still needed 45.6 - 9.6 = 36 L; 36 / 2.4 = 360 / 24 = 15 minutes.","run_id":"claude-code","at":"2026-10-17T20:21:50.263Z"}}', 'ai', NULL, NULL)
