INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f69cb11-cf2f-4cbd-8474-f217b37ebc42', 'NC26.6.ANR.4', 2, 'numeric', 'Integers in context', 'A diver''s depth changed by $-18$ meters in 3 equal steps. What was the change in each step, in meters?', '[]', '-6', '-18/3', 'Share the total change equally: $-18 \div 3 = -6$ meters per step.', 'checked', '{"lint":[],"solve":{"answer":"-6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-18 / 3 = -6.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
