VALUES ('04c04b92-133e-4ef6-bd03-7fdc7b5fbff5', 'NC26.6.ANR.4', 3, 'choice', 'Adding integers', 'Which pair of integers has a sum of $-4$?', '["$-11$ and $-7$","$11$ and $-7$","$-11$ and $7$","$11$ and $7$"]', '$-11$ and $7$', NULL, '$-11 + 7 = -4$. The other pairs give $-18$, $4$ and $18$.', 'checked', '{"lint":[],"solve":{"answer":"$-11$ and $7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-11+(-7) = -18; 11+7 = 18; 11+(-7) = 4; -11+7 = -4.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
