VALUES ('047324e7-bee3-4597-8325-73eb3978a9d8', 'NC26.6.ANR.5', 1, 'choice', 'Equivalent forms of fractions, mixed numbers and decimals', 'Which mixed number is equal to $\frac{7}{4}$?', '["$1\\frac{1}{4}$","$3\\frac{1}{4}$","$1\\frac{3}{4}$","$4\\frac{3}{7}$"]', '$1\frac{3}{4}$', NULL, '$7 \div 4 = 1$ with a remainder of 3, so $\frac{7}{4} = 1\frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"$1\\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7/4 = 4/4 + 3/4 = 1 3/4.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
