VALUES ('008a593e-d473-4a0a-a0cf-2ffb580d035f', 'NC26.6.ANR.5', 2, 'numeric', 'Absolute value', 'Find the value of $|-9| - |-4|$.', '[]', '5', '9-4', '$|-9| = 9$ and $|-4| = 4$, so $9 - 4 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"|-9| - |-4| = 9 - 4 = 5.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
