INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04b497ea-5378-4c59-922f-f5a715923c27', 'NC26.6.ANR.5', 3, 'choice', 'Absolute value and distance from zero', 'Which number has the greatest absolute value?', '["$-9$","$12$","$14$","$-15$"]', '$-15$', '-15', 'The absolute values are 9, 12, 15 and 14. The greatest is 15, which belongs to $-15$, because $-15$ is the farthest from zero.', 'checked', '{"lint":[],"solve":{"answer":"$-15$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Absolute values 15, 14, 12, 9. Greatest is |-15| = 15.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
