INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08d5f4f8-fb54-439d-a76f-6bc1c62dd3d9', 'NC26.6.ANR.6', 1, 'choice', 'Whole-number exponents', 'Which expression shows $7 \times 7 \times 7$ written with an exponent?', '["$3^7$","$7 \\times 3$","$7^3$","$7 + 3$"]', '$7^3$', NULL, 'The factor 7 appears 3 times, so the base is 7 and the exponent is 3: $7^3$. The expression $3^7$ would mean 3 used 7 times.', 'checked', '{"lint":[],"solve":{"answer":"$7^3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Three factors of 7 is 7^3.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
