INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('295914b4-e071-48ac-a841-c74a3c1edff4', 'NC26.6.ANR.6', 2, 'numeric', 'Order of operations', 'Evaluate $48 \div 6 + 2 \times 7$.', '[]', '22', '48/6+2*7', 'Do the division and the multiplication first: $48 \div 6 = 8$ and $2 \times 7 = 14$. Then add: $8 + 14 = 22$.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"48 / 6 = 8; 2 x 7 = 14; 8 + 14 = 22.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
