INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10f31594-8560-4643-9851-fbdef31917af', 'NC26.6.ANR.6', 3, 'choice', 'Order of operations', 'Which expression has the same value as $2 + 3 \times 4^2$?', '["$5 \\times 16$","$2 + 3 \\times 16$","$2 + 12^2$","$(2 + 12)^2$"]', '$2 + 3 \times 16$', NULL, '$4^2 = 16$, so $2 + 3 \times 4^2 = 2 + 3 \times 16 = 2 + 48 = 50$. The other expressions equal 80, 146 and 196.', 'checked', '{"lint":[],"solve":{"answer":"$2 + 3 \\times 16$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 + 3 x 16 = 50. Options: 2 + 3 x 16 = 50; 5 x 16 = 80; 2 + 144 = 146; 14^2 = 196. Only the first matches.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f7bb04f-9baa-4cdf-89c8-4acc3e3be755', 'NC26.6.ANR.6', 3, 'numeric', 'Equivalent expressions and properties', 'Simplify $5y + 3 + 2y + 9$ to the form $ay + b$. What is $a + b$?', '[]', '19', '5+2+3+9', 'Combine the like terms: $5y + 2y = 7y$ and $3 + 9 = 12$. So the expression is $7y + 12$, and $a + b = 7 + 12 = 19$.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5y + 2y = 7y, 3 + 9 = 12; 7y + 12; a + b = 19.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d2e359d-fc41-4bad-a8a4-016456b25e03', 'NC26.6.ANR.7', 1, 'numeric', 'Solving a one-step multiplication equation', 'Solve $6n = 48$.', '[]', '8', '48/6', 'Divide both sides by 6: $n = 48 \div 6 = 8$. Check: $6 \times 8 = 48$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n = 48 / 6 = 8.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
