INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09444dbf-74ba-42f5-af53-5557fbde302a', 'NC26.6.ANR.7', 1, 'choice', 'Checking a solution by substitution', 'Which equation is true when $x = 5$?', '["$x + 3 = 2$","$x + 3 = 8$","$x - 3 = 8$","$3x = 8$"]', '$x + 3 = 8$', NULL, 'Put 5 in place of $x$: $5 + 3 = 8$ is true. The others give $5 + 3 = 8 \ne 2$, $5 - 3 = 2 \ne 8$ and $3 \times 5 = 15 \ne 8$.', 'checked', '{"lint":[],"solve":{"answer":"$x + 3 = 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 5: 5 - 3 = 2, 15, 8, 5 + 3 = 8. Only x + 3 = 8 is true.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1547d543-e5d5-466a-94b0-ddae46b481ef', 'NC26.6.ANR.7', 1, 'numeric', 'Solutions and graphs of inequalities', 'How many of the numbers 2, 5, 8 and 11 are solutions of $x > 6$?', '[]', '2', '2', 'Only numbers greater than 6 are solutions. The numbers 8 and 11 are greater than 6, but 2 and 5 are not. So 2 of the numbers are solutions.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 and 11 are greater than 6; 2 and 5 are not. Two.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a66804b-8cb7-4aed-979b-18fb2e503301', 'NC26.6.ANR.7', 2, 'choice', 'Checking a solution by substitution', 'Ana, Ben and Cara each test a value in the equation $x + 8 = 20$. Ana tries 28, Ben tries 12 and Cara tries 160. Who found a solution?', '["Only Ana","Only Cara","All three of them","Only Ben"]', 'Only Ben', NULL, 'Test each value: $28 + 8 = 36$, $12 + 8 = 20$ and $160 + 8 = 168$. Only Ben''s value, 12, makes the equation true.', 'checked', '{"lint":[],"solve":{"answer":"Only Ben","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"28 + 8 = 36, 12 + 8 = 20, 160 + 8 = 168. Only Ben''s 12 works.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('085c0277-6dc9-43dc-ad93-7fd519229b46', 'NC26.6.ANR.7', 2, 'numeric', 'Writing and solving an equation from a story', 'A baker makes 8 equal batches of muffins and bakes 96 muffins in all. How many muffins are in each batch?', '[]', '12', '96/8', 'Let $m$ be the number in each batch. Then $8m = 96$, so $m = 96 \div 8 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8m = 96, m = 12.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
