INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09de2a05-8f71-408c-8694-8787f982afd1', 'NC26.6.ANR.7', 2, 'numeric', 'Writing and solving an equation from a story', 'After a discount of 12 dollars, a jacket costs 38 dollars. What was the price of the jacket before the discount, in dollars?', '[]', '50', '38+12', 'Let $p$ be the price before the discount. Then $p - 12 = 38$, so $p = 38 + 12 = 50$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"p - 12 = 38, p = 50.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
