INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('042ed66c-66c2-4aa7-9eed-c7c3aa60738d', 'NC26.6.ANR.7', 3, 'choice', 'Solving multiplication and division equations', 'Which equation has the same solution as $6x = 54$?', '["$x \\div 3 = 3$","$x - 6 = 54$","$x + 6 = 54$","$9x = 54$"]', '$x \div 3 = 3$', NULL, '$6x = 54$ gives $x = 9$. For $x \div 3 = 3$, multiplying both sides by 3 gives $x = 9$ too. The other equations have the solutions 60, 48 and 6.', 'checked', '{"lint":[],"solve":{"answer":"$x \\div 3 = 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x = 54 gives 9. Options: 60, 6, 9, 48. x / 3 = 3 gives 9.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1797fb6d-1cc4-4eaf-9d34-2ca8a538cf6a', 'NC26.6.SGMR.1', 1, 'numeric', 'Area of a triangle from its base and height', 'A triangular flag has a base of 8 inches and a height of 5 inches. What is the area of the flag in square inches?', '[]', '20', '1/2*8*5', 'The area of a triangle is half of the base times the height. Half of 8 times 5 is $\frac{1}{2} \times 8 \times 5 = 20$ square inches.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = 1/2 x 8 x 5 = 20.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fe10f1c-4b3a-4b41-8fa2-8d07d3c1bdd0', 'NC26.6.SGMR.1', 1, 'choice', 'Finding a missing base or height from the area', 'A triangle has a base of 10 centimeters and an area of 35 square centimeters. Which equation can be used to find its height $h$, in centimeters?', '["$10 \\times h = 35$","$\\frac{1}{2} \\times 10 \\times h = 35$","$\\frac{1}{2} \\times (10 + h) = 35$","$10 + h = 35$"]', '$\frac{1}{2} \times 10 \times h = 35$', NULL, 'The area of a triangle is $\frac{1}{2} \times$ base $\times$ height, so $\frac{1}{2} \times 10 \times h = 35$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2} \\times 10 \\times h = 35$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area = 1/2 x base x height: 1/2 x 10 x h = 35 (h = 7).","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('188b9cc4-cd35-4506-a63b-02549d190fe7', 'NC26.6.SGMR.1', 1, 'choice', 'Solving area problems in context', 'Which unit is best for measuring the area of a classroom floor?', '["Meters","Square meters","Cubic meters","Square millimeters"]', 'Square meters', NULL, 'Area is measured in square units. A classroom floor is large, so square meters fit. Meters measure length, cubic meters measure volume, and square millimeters are far too small.', 'checked', '{"lint":[],"solve":{"answer":"Square meters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area needs square units; a floor is meters-sized, so square meters.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0506e162-8fbd-47ff-a191-f2143f41b178', 'NC26.6.SGMR.1', 2, 'numeric', 'Area of a parallelogram from its base and height', 'The base of a parallelogram is 15 meters. Its height is 4 meters less than its base. What is the area of the parallelogram in square meters?', '[]', '165', '15*(15-4)', 'The height is $15 - 4 = 11$ meters. Area $= 15 \times 11 = 165$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"165","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Height = 15 - 4 = 11. Area = 15 x 11 = 165.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('301321f3-00f1-4f43-90e8-9e3172533693', 'NC26.6.SGMR.1', 2, 'numeric', 'Area of a composite figure made of rectangles', 'A picture frame is a rectangle 14 inches long and 10 inches wide. The opening in the middle is a rectangle 10 inches long and 6 inches wide. What is the area of the frame itself, not counting the opening, in square inches?', '[]', '80', '14*10-10*6', 'The whole rectangle has area $14 \times 10 = 140$. The opening has area $10 \times 6 = 60$. The frame is $140 - 60 = 80$ square inches.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14 x 10 - 10 x 6 = 140 - 60 = 80.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2784738e-95b2-4133-a0dd-e963a64af755', 'NC26.6.SGMR.1', 2, 'choice', 'Choosing the right measurements and checking an answer', 'A triangle has sides of 13 cm, 14 cm and 15 cm. The height drawn to the 14 cm side is 12 cm. What is the area of the triangle in square centimeters?', '["84","168","91","105"]', '84', '1/2*14*12', 'Use the 14 cm side as the base, since the 12 cm height goes to that side: $\frac{1}{2} \times 14 \times 12 = 84$ square centimeters. The other sides are slanted and are not heights.', 'checked', '{"lint":[],"solve":{"answer":"84","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 14, height 12: 1/2 x 14 x 12 = 84. The 13 and 15 sides are distractors.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05732ff8-b231-4abd-8358-76b9dd5b9e79', 'NC26.6.SGMR.1', 3, 'numeric', 'Area of a polygon made of a rectangle and a triangle', 'A lot is shaped like a rectangle with a triangle attached along one of its 10-meter sides. The rectangle is 10 meters by 6 meters. The triangle has a base of 10 meters and a height of 4 meters. What is the total area of the lot in square meters?', '[]', '80', '10*6+1/2*10*4', 'Rectangle: $10 \times 6 = 60$. Triangle: $\frac{1}{2} \times 10 \times 4 = 20$. Total: $60 + 20 = 80$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle 10 x 6 = 60. Triangle 1/2 x 10 x 4 = 20. Total 80.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('090abdf1-f7aa-4bc9-aa91-34ad6402891a', 'NC26.6.SGMR.1', 3, 'numeric', 'Composing and decomposing shapes', 'A rectangular sheet is 20 centimeters long and 12 centimeters wide. A right triangle with legs of 5 centimeters and 4 centimeters is cut off each of the four corners. What is the area of the sheet that is left, in square centimeters?', '[]', '200', '20*12-4*(1/2*5*4)', 'The sheet has area $20 \times 12 = 240$. Each corner triangle has area $\frac{1}{2} \times 5 \times 4 = 10$, and four of them take away 40. What is left is $240 - 40 = 200$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sheet 20 x 12 = 240; each corner 1/2 x 5 x 4 = 10, four = 40; 240 - 40 = 200. Corners fit (5+5 <= 12, 4+4 <= 20).","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d92e64c-2c78-4ee1-8ba9-04e791b619a2', 'NC26.6.SGMR.2', 1, 'choice', 'Naming the quadrant or axis of a point', 'Which of these ordered pairs names a point in Quadrant II? Quadrant I is where both coordinates are positive, and the quadrants are numbered I, II, III, IV going counterclockwise from there.', '["$(5, 2)$","$(-5, 2)$","$(-5, -2)$","$(5, -2)$"]', '$(-5, 2)$', NULL, 'Quadrant II has a negative x-coordinate and a positive y-coordinate. Only $(-5, 2)$ has that pattern.', 'checked', '{"lint":[],"solve":{"answer":"$(-5, 2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Quadrant II needs x < 0 and y > 0: only (-5, 2).","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03420a97-58d4-4735-9fb9-f4fd5570b50c', 'NC26.6.SGMR.2', 1, 'numeric', 'Distance between points that share a coordinate', 'Maya walks along a grid line from $(1, 5)$ to $(8, 5)$. Each unit of the grid is one block. How many blocks does she walk?', '[]', '7', '8-1', 'The y-coordinates are both 5, so she walks along a horizontal line. The distance is $8 - 1 = 7$ blocks.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same y: 8 - 1 = 7.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
