INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0987499b-4690-481c-bb61-48c68213dd1d', 'NC26.6.SGMR.2', 2, 'numeric', 'Perimeter of a polygon on the coordinate plane', 'A fence goes all the way around a rectangular yard. On a map grid, the corners of the yard are $(-4, 1)$, $(3, 1)$, $(3, -5)$ and $(-4, -5)$, and each grid unit is 1 meter. How many meters of fence are needed?', '[]', '26', '2*((3+4)+(1+5))', 'The yard is $3 - (-4) = 7$ meters wide and $1 - (-5) = 6$ meters tall. The fence is $2 \times (7 + 6) = 26$ meters long.', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length 3 - (-4) = 7; width 1 - (-5) = 6. Perimeter 2 x (7 + 6) = 26.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00df58fb-d5e9-4148-b2c2-e2f74dd7f687', 'NC26.6.SGMR.2', 2, 'numeric', 'Finding a missing vertex or a point from conditions', 'Point $P$ is at $(-4, 2)$. It is on the same horizontal line as point $M$, and $P$ is 9 units to the right of $M$. What is the x-coordinate of $M$?', '[]', '-13', '-4-9', '$M$ is 9 units to the left of $P$, so subtract 9 from the x-coordinate: $-4 - 9 = -13$.', 'checked', '{"lint":[],"solve":{"answer":"-13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"M is 9 left of P: -4 - 9 = -13.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('066a227c-c165-43df-a25b-03eeae5d5229', 'NC26.6.SGMR.2', 3, 'numeric', 'Reflecting a point across the x-axis or the y-axis', 'When the point $(a, b)$ is reflected across the y-axis, the new point is $(-2, 7)$. What is the value of $a + b$?', '[]', '9', '2+7', 'Reflecting across the y-axis changes the sign of the x-coordinate, so $a = 2$. The y-coordinate does not change, so $b = 7$. Then $a + b = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(a, b) -> (-a, b) = (-2, 7): a = 2, b = 7. a + b = 9.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07d7cf5c-cc17-47f9-8fc5-db1d21790d61', 'NC26.6.SGMR.2', 3, 'choice', 'Finding a missing vertex or a point from conditions', 'Two vertices of a rectangle are at $(-2, 1)$ and $(4, 1)$. The rectangle has an area of 24 square units, and its other two vertices are below these. Which pair gives the other two vertices?', '["$(-2, 5)$ and $(4, 5)$","$(-2, -3)$ and $(4, -3)$","$(-2, -7)$ and $(4, -7)$","$(-2, -2)$ and $(4, -2)$"]', '$(-2, -3)$ and $(4, -3)$', NULL, 'The known side is $4 - (-2) = 6$ units long, so the height is $24 \div 6 = 4$. Going down 4 from $y = 1$ gives $y = -3$. The pair at $y = 5$ is above the side.', 'checked', '{"lint":[],"solve":{"answer":"$(-2, -3)$ and $(4, -3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Width 4 - (-2) = 6; height 24 / 6 = 4; below: y = 1 - 4 = -3. (-2,-3) and (4,-3).","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0466f841-ed3a-4a4f-88fe-f599cfc0ce42', 'NC26.6.SGMR.3', 1, 'choice', 'Naming the solid a net folds into', 'Which solid can be made by folding a net of 6 squares that are all the same size?', '["Square pyramid","Triangular prism","Triangular pyramid","Cube"]', 'Cube', NULL, 'A cube has 6 faces and every face is a square the same size as the others. A square pyramid has only one square and 4 triangles, and the other two solids have triangular faces.', 'checked', '{"lint":[],"solve":{"answer":"Cube","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 congruent squares fold into a cube.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b05a481-a47a-49d3-8de2-1bff7c6de47b', 'NC26.6.SGMR.3', 1, 'choice', 'Surface area of a cube', 'Each face of a cube has an area of 9 square inches. What is the surface area of the cube, in square inches?', '["54","36","27","81"]', '54', '6*9', 'A cube has 6 faces that all have the same area, so the surface area is $6 \times 9 = 54$ square inches. Using 4 faces would give 36, and 81 is $9 \times 9$.', 'checked', '{"lint":[],"solve":{"answer":"54","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 9 = 54.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('24c9246a-281d-41d6-9346-d8f6fcae8891', 'NC26.6.SGMR.3', 1, 'numeric', 'Surface area of a rectangular prism', 'A small box is 5 centimeters long, 3 centimeters wide and 2 centimeters tall. How many square centimeters of paper cover the whole box?', '[]', '62', '2*(5*3+5*2+3*2)', 'The faces are $5 \times 3 = 15$, $5 \times 2 = 10$ and $3 \times 2 = 6$ square centimeters, each twice. The surface area is $2 \times (15 + 10 + 6) = 2 \times 31 = 62$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"62","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(5x3 + 5x2 + 3x2) = 2(15 + 10 + 6) = 62.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0418a2ab-43c3-441d-bbea-7596e5bf3049', 'NC26.6.SGMR.3', 2, 'choice', 'Surface area of a rectangular prism', 'A classroom is 8 meters long, 6 meters wide and 3 meters tall. The four walls will be painted. What is the total area of the walls, in square meters? (Ignore doors and windows.)', '["132","180","84","42"]', '84', NULL, 'Two walls are $8 \times 3 = 24$ square meters each and two walls are $6 \times 3 = 18$ square meters each. The total is $2 \times 24 + 2 \times 18 = 48 + 36 = 84$ square meters. The number 132 also counts the ceiling, 180 counts all six faces, and 42 counts only one wall of each size.', 'checked', '{"lint":[],"solve":{"answer":"84","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Walls: 2(8x3) + 2(6x3) = 48 + 36 = 84.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ddfb663-92c7-4c52-b0c9-07f15f33e477', 'NC26.6.SGMR.3', 2, 'numeric', 'Volume of a rectangular prism with whole-number edges', 'A moving box is 50 centimeters long, 30 centimeters wide and 40 centimeters tall. What is its volume, in cubic centimeters?', '[]', '60000', '50*30*40', 'Volume is length times width times height: $50 \times 30 \times 40 = 1500 \times 40 = 60{,}000$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"60000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50 x 30 x 40 = 60,000.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0907239f-9236-4d9d-a316-323d3ee0f445', 'NC26.6.SGMR.3', 2, 'choice', 'Surface area of a rectangular prism', 'A closed box has a square base that measures 4 centimeters on each side. The box is 9 centimeters tall. What is its surface area in square centimeters?', '["144","176","160","104"]', '176', '4*4*2+4*4*9', 'The top and bottom are each $4 \times 4 = 16$, together 32. The four sides are each $4 \times 9 = 36$, together 144. The total is $32 + 144 = 176$ square centimeters. Leaving out the top and bottom gives 144, and counting only one of them gives 160.', 'checked', '{"lint":[],"solve":{"answer":"176","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two square faces: 2 x 16 = 32. Four side faces 4 x 9 = 36 each: 144. Total 176.","run_id":"claude-code","at":"2026-10-18T03:30:03.757Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ab94c9f-9f3c-4415-b60c-111f6751b461', 'NC26.6.SGMR.3', 3, 'numeric', 'Surface area of a cube', 'A cube-shaped tank has no lid. Each edge is 3 meters long. How many square meters of glass are needed for its bottom and four sides?', '[]', '45', '5*3^2', 'Each face is $3 \times 3 = 9$ square meters. The bottom and four sides make 5 faces, so the glass needed is $5 \times 9 = 45$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bottom + 4 sides = 5 faces x 9 = 45.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
