INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('066c93c7-64d3-4af2-a71a-84fdec2f37af', 'NC26.7.RPR.1', 2, 'numeric', 'Write and use an equation y = kx', 'A canoe rental costs the same amount for each hour. The cost $c$, in dollars, for $h$ hours is $c = 6.5h$. Jo pays 52 dollars. For how many hours does Jo rent the canoe?', '[]', '8', '52/6.5', 'Put $c = 52$ into the equation: $52 = 6.5h$, so $h = 52 \div 6.5 = 8$ hours.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"52 = 6.5h, h = 8.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09c4edf2-4426-4aa5-8aed-4978be69dab0', 'NC26.7.RPR.1', 2, 'choice', 'Compare proportional relationships', 'Plant A grows 12 cm in 4 weeks. Plant B grows $h$ cm in $w$ weeks, where $h = 2.5w$. Plant C grows 7 cm in 2 weeks. All grow at constant rates. Which plant grows the least each week?', '["Plant A","Plant B","Plant C","All three grow equally fast"]', 'Plant B', NULL, 'Plant A grows $12 \div 4 = 3$ cm a week, Plant B grows 2.5 cm a week and Plant C grows $7 \div 2 = 3.5$ cm a week. Plant B grows the least.', 'checked', '{"lint":[],"solve":{"answer":"Plant B","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 12/4 = 3 cm/wk. B: 2.5 cm/wk. C: 7/2 = 3.5 cm/wk. Least is B.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04282769-46d8-432a-af30-84eea38b747b', 'NC26.7.RPR.1', 3, 'numeric', 'Constant of proportionality from a table or ordered pairs', 'A table for a proportional relationship lists $y = 11.2$ when $x = 2$, $y = 28$ when $x = 5$ and $y = 44.8$ when $x = 8$. What is the constant of proportionality?', '[]', '5.6', '11.2/2', '$k = 11.2 \div 2 = 5.6$. Check: $28 \div 5 = 5.6$ and $44.8 \div 8 = 5.6$.', 'checked', '{"lint":[],"solve":{"answer":"5.6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"11.2/2 = 5.6, 28/5 = 5.6, 44.8/8 = 5.6.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('037ef9e9-9410-47f5-a8eb-9055ac151f21', 'NC26.7.RPR.1', 3, 'choice', 'Interpret a point of a proportional relationship in context', 'The point $(1.5, 9)$ is on the graph of a proportional relationship between the hours $x$ and the gallons $y$ of water a pump moves. Which statement is true?', '["The pump moves 9 gallons each hour","The pump moves 13.5 gallons each hour","The pump moves 6 gallons each hour","The pump moves 1.5 gallons each hour"]', 'The pump moves 6 gallons each hour', NULL, '1.5 hours move 9 gallons, so each hour the pump moves $9 \div 1.5 = 6$ gallons. (13.5 is $1.5 \times 9$.)', 'checked', '{"lint":[],"solve":{"answer":"The pump moves 6 gallons each hour","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9/1.5 = 6 gallons per hour.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0290d825-7aa1-42d5-a027-f71f7e254a50', 'NC26.7.RPR.2', 1, 'numeric', 'Sales tax and tip', 'Leo''s family has a meal that costs 50 dollars and leaves a tip of 10% of the cost. How many dollars is the tip?', '[]', '5', '50*0.1', '10% of 50 is $50 \times 0.10 = 5$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.10 x 50 = 5.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08c2ea06-4094-4393-8b5a-febafff54474', 'NC26.7.RPR.2', 1, 'numeric', 'Markup and discount', 'A shop buys a lamp for 20 dollars and marks up the price by 50% of the cost. How many dollars is the markup?', '[]', '10', '20*0.5', '50% of 20 is $20 \times 0.5 = 10$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.50 x 20 = 10.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
