INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1bfbc96d-f145-49fd-892a-6904979b3d5e', 'NC26.7.ANR.1', 1, 'choice', 'Solve a problem with rational numbers', 'Ana owes her brother 12 dollars. She pays back $\frac{1}{3}$ of what she owes. How much does she still owe, in dollars?', '["4","8","16","36"]', '8', '12-12/3', '$\frac{1}{3}$ of 12 is 4, so she pays back 4 dollars and still owes $12 - 4 = 8$ dollars. (4 is the amount she paid back.)', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"She pays 1/3 x 12 = 4; still owes 12 - 4 = 8 dollars.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05ef7489-7773-45bb-b407-6690d2d78658', 'NC26.7.ANR.1', 2, 'choice', 'Add and subtract fractions and mixed numbers', 'What is $3\frac{1}{3} - 1\frac{3}{4}$?', '["2 5/12","1 5/12","1 7/12","2 7/12"]', '1 7/12', '10/3-7/4', '$3\frac{1}{3} = \frac{40}{12}$ and $1\frac{3}{4} = \frac{21}{12}$. The difference is $\frac{19}{12} = 1\frac{7}{12}$. (2 5/12 subtracts the smaller fraction from the larger.)', 'checked', '{"lint":[],"solve":{"answer":"1 7/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10/3 - 7/4 = 40/12 - 21/12 = 19/12 = 1 7/12.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('13b05b3a-4c39-47d0-8b52-2323feabe1e1', 'NC26.7.ANR.1', 2, 'numeric', 'Multiply and divide fractions and mixed numbers', 'Find $-\frac{4}{9} \div \frac{2}{3}$.', '[]', '-2/3', '-4/9/(2/3)', 'Multiply by the reciprocal: $-\frac{4}{9} \times \frac{3}{2} = -\frac{12}{18} = -\frac{2}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"-2/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-4/9 x 3/2 = -12/18 = -2/3.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
