INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0da4a7f8-e9d2-4921-8802-2b496805510a', 'NC26.7.ANR.1', 2, 'choice', 'Check reasonableness by estimating', 'Lena adds $\frac{7}{8} + \frac{9}{10}$ and gets $\frac{16}{18}$. Which statement shows why her answer is not reasonable?', '["The sum of two fractions must be a whole number, and $\\frac{16}{18}$ is not.","Each fraction is close to 1, so the sum should be close to 2, but $\\frac{16}{18}$ is less than 1.","Fractions are added by multiplying, so the sum should be $\\frac{63}{80}$.","Her answer is greater than 1, but each of the two fractions is less than 1."]', 'Each fraction is close to 1, so the sum should be close to 2, but $\frac{16}{18}$ is less than 1.', NULL, '$\frac{7}{8}$ and $\frac{9}{10}$ are each a little less than 1, so their sum is a little less than 2. The answer $\frac{16}{18}$ is less than 1, which cannot be right. (The correct sum is $\frac{71}{40}$.)', 'checked', '{"lint":[],"solve":{"answer":"Each fraction is close to 1, so the sum should be close to 2, but $\\frac{16}{18}$ is less than 1.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7/8 and 9/10 are each close to 1, so the sum is close to 2 (exact 1 31/40), but 16/18 < 1. A is false (sums need not be whole), B is wrong (fractions are not added by multiplying), C is false (16/18 is less than 1). D is correct.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0af598a9-f169-4c9f-8a71-020501851feb', 'NC26.7.ANR.1', 3, 'choice', 'Check reasonableness by estimating', 'Which is the best estimate of $\frac{-39.8 \times 2.1}{4.2}$?', '["-20","-80","20","-200"]', '-20', '-20', 'Round: $-39.8 \approx -40$ and $2.1 \approx 2$, and $4.2 \approx 4$. Then $\frac{-40 \times 2}{4} = -20$. The answer is negative, and about 20 in size.', 'checked', '{"lint":[],"solve":{"answer":"-20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.1/4.2 = 1/2, so value = -39.8/2 = -19.9, about -20. Estimate: -40 x 2 / 4 = -20.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b9b7f7e-b1d3-4cbc-816c-e8596a000b97', 'NC26.7.ANR.1', 3, 'numeric', 'Multiply and divide integers', 'Evaluate $\frac{(-12)(-5)}{-15}$.', '[]', '-4', '(-12*-5)/-15', 'The top is $(-12)(-5) = 60$. Then $60 \div (-15) = -4$.', 'checked', '{"lint":[],"solve":{"answer":"-4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-12)(-5) = 60; 60 / (-15) = -4.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10a7e9dc-50c1-4418-90af-d831f516b62c', 'NC26.7.ANR.2', 1, 'numeric', 'Combine like terms', 'A square has sides that each measure $x$ units. Its perimeter is $x + x + x + x$, which is equivalent to $kx$. What is the value of $k$?', '[]', '4', '1+1+1+1', 'Adding $x$ four times gives 4 groups of $x$, which is $4x$. So k = 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + x + x + x = 4x; k = 4.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07177cda-9476-4ef5-8fc1-4f865881f8b6', 'NC26.7.ANR.2', 1, 'numeric', 'Distribute and combine like terms', 'The expression $2(x + 1) + 3x$ simplifies to $ax + 2$. What is the value of $a$?', '[]', '5', '2+3', 'Distribute: $2(x + 1) = 2x + 2$. Then $2x + 2 + 3x = 5x + 2$. So a = 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x + 2 + 3x = 5x + 2; a = 5.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05109b40-938f-4079-bb8e-b2de35c310c0', 'NC26.7.ANR.2', 1, 'numeric', 'Use the distributive property to write an equivalent expression', 'The expression $3(x + 4)$ is equivalent to $3x + \square$. What number goes in the box?', '[]', '12', '3*4', 'Multiply each part inside the parentheses by 3: $3(x + 4) = 3 \times x + 3 \times 4 = 3x + 12$. The number in the box is 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x+4)=3x+12.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1af77eb0-1121-43fb-9766-bcdbe28f7624', 'NC26.7.ANR.2', 2, 'choice', 'Expand with the distributive property', 'Which expression, written without parentheses, gives the area of a rectangle that is 5 units wide and $(x - 2)$ units long?', '["$5x - 2$","$5x - 10$","$5x + 10$","$x - 10$"]', '$5x - 10$', NULL, 'Area is width times length: $5(x - 2)$. Distribute the 5: $5x - 10$.', 'checked', '{"lint":[],"solve":{"answer":"$5x - 10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5(x - 2) = 5x - 10.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f3e784c-4555-4405-8f8d-e50b37eb838b', 'NC26.7.ANR.2', 2, 'choice', 'Name the property of operations', 'Which property is shown by $(x + 3) + 5 = x + (3 + 5)$?', '["Commutative property of addition","Distributive property","Identity property of addition","Associative property of addition"]', 'Associative property of addition', NULL, 'The numbers stay in the same order, but the grouping (which two are added first) changes. That is the associative property of addition.', 'checked', '{"lint":[],"solve":{"answer":"Associative property of addition","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Grouping changes, order does not: associative property of addition.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1fbfa277-da32-4a30-9a51-0f1e85ec5b6a', 'NC26.7.ANR.2', 2, 'choice', 'Add and subtract linear expressions', 'Which expression is equivalent to $(7x + 5) - (2x + 3)$?', '["$5x + 8$","$9x + 8$","$5x + 2$","$5x - 2$"]', '$5x + 2$', NULL, 'Subtract each term of the second expression: $7x - 2x = 5x$ and $5 - 3 = 2$. So the result is $5x + 2$. (5x + 8 adds the 3 instead of subtracting it.)', 'checked', '{"lint":[],"solve":{"answer":"$5x + 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7x + 5 - 2x - 3 = 5x + 2.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('109e2fb4-78d1-409c-9d44-abf53749af99', 'NC26.7.ANR.2', 3, 'choice', 'Write a total in context as one simplified expression', 'Tickets to a show cost $t$ dollars each, and every purchase has a 2-dollar service fee. Mia buys 3 tickets and Sam buys 4 tickets, in separate purchases. Which expression is equivalent to the total they pay together, in dollars?', '["$7t + 2$","$12t + 4$","$7t + 4$","$7t$"]', '$7t + 4$', NULL, 'Mia pays $3t + 2$ and Sam pays $4t + 2$. Together: $(3t + 2) + (4t + 2) = 7t + 4$. Each of the two purchases has its own fee, so the fees add to 4.', 'checked', '{"lint":[],"solve":{"answer":"$7t + 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mia pays 3t + 2, Sam pays 4t + 2 (each purchase has its own fee). Total = 7t + 4.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17496d80-0622-4e35-9512-663b5fe3ce89', 'NC26.7.ANR.2', 3, 'numeric', 'Add and subtract linear expressions', 'The expression $(3x - 4) - 2(x - 5)$ is equivalent to $ax + b$. What is the value of $a + b$?', '[]', '7', '3-2-4+10', 'Distribute -2: $-2(x - 5) = -2x + 10$. Then $3x - 4 - 2x + 10 = x + 6$, so a = 1, b = 6 and a + b = 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x - 4 - 2x + 10 = x + 6; a + b = 1 + 6 = 7.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0284d377-fca5-4ad9-a396-d9a06385b196', 'NC26.7.ANR.3', 1, 'numeric', 'Solve a two-step equation', 'What value of $x$ makes $2x + 7 = 19$ true?', '[]', '6', '(19-7)/2', 'Subtract 7 from both sides: $2x = 12$. Divide both sides by 2: $x = 6$. Check: $2 \times 6 + 7 = 19$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x = 19 - 7 = 12; x = 6.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2bbdffde-e471-4e10-90a6-337b7dea0179', 'NC26.7.ANR.3', 1, 'choice', 'Write an inequality from a situation', 'Each book weighs $w$ pounds. A box can hold no more than 25 pounds. Which inequality shows that 3 books fit in the box?', '["$3w \\ge 25$","$w + 3 \\le 25$","$3w \\le 25$","$3w > 25$"]', '$3w \le 25$', NULL, 'Three books weigh $3 \times w = 3w$ pounds. The total must be no more than 25, so $3w \le 25$. (w + 3 adds 3 pounds instead of multiplying.)', 'checked', '{"lint":[],"solve":{"answer":"$3w \\le 25$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 books weigh 3w; no more than 25: 3w <= 25.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e8d91dd-4ffb-4e11-a102-6681a84efa25', 'NC26.7.ANR.3', 1, 'choice', 'Choose an equation or an inequality', 'A video rental costs a 2 dollar fee plus 3 dollars for each day $d$. Rae pays exactly 14 dollars. Which can be used to find the number of days?', '["The inequality $3d + 2 < 14$","The equation $3d + 2 = 14$","The inequality $3d + 2 > 14$","The equation $3(d + 2) = 14$"]', 'The equation $3d + 2 = 14$', NULL, 'Rae pays exactly 14 dollars, so the cost $3d + 2$ must equal 14. Use the equation $3d + 2 = 14$. (An inequality would allow other amounts, and 3(d + 2) charges the fee 3 times.)', 'checked', '{"lint":[],"solve":{"answer":"The equation $3d + 2 = 14$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exactly 14 dollars: equation. 2 fee + 3 per day: 3d + 2 = 14 (d = 4).","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05703b48-942d-4406-83f7-a5316572714c', 'NC26.7.ANR.3', 2, 'choice', 'Solve a two-step inequality', 'What are all the solutions of $2x + 7 > 15$?', '["$x > 11$","$x > 6$","$x < 4$","$x > 4$"]', '$x > 4$', NULL, 'Subtract 7: $2x > 8$. Divide by 2: $x > 4$. Dividing by a positive number keeps the direction of the inequality.', 'checked', '{"lint":[],"solve":{"answer":"$x > 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x > 8, x > 4.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0820bc50-3d92-4ccd-9d3a-c22d8273650a', 'NC26.7.ANR.3', 2, 'numeric', 'Write and solve an equation from a situation', 'Twice a number, decreased by 7, equals 15. What is the number?', '[]', '11', '(15+7)/2', 'Write the sentence as an equation: $2n - 7 = 15$. Add 7: $2n = 22$. Divide by 2: $n = 11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2n - 7 = 15; 2n = 22; n = 11.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08bc2323-c1b6-404a-aa65-27d9d34b400a', 'NC26.7.ANR.3', 2, 'choice', 'Decide whether a value is a solution', 'Which number is a solution of $2x - 3 \le 7$?', '["6","5","8","10"]', '5', '5', 'Test each number. For 5: $2 \times 5 - 3 = 7$, and 7 is less than or equal to 7, so 5 works. For 6, 8 and 10 the left side is 9, 13 and 17, which are greater than 7.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x <= 10; x <= 5. Of 8, 6, 10, 5 only 5 works.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a7e2fec-7415-486d-af99-397cd401ab9b', 'NC26.7.ANR.3', 3, 'choice', 'Solve an equation with parentheses', 'Which value of $x$ is the solution of $4(x + 3) - 6 = 22$?', '["1","6.25","4","7"]', '4', '(22+6)/4-3', 'Add 6 to both sides: $4(x + 3) = 28$. Divide by 4: $x + 3 = 7$. Subtract 3: $x = 4$. (6.25 forgets to multiply the 3 by 4, 1 subtracts 6 instead of adding it, and 7 forgets to subtract 3.)', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(x + 3) = 28; x + 3 = 7; x = 4.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('091fd383-e3fe-4432-ba73-06b09c08e1ec', 'NC26.7.ANR.3', 3, 'numeric', 'Solve an equation with parentheses', 'Solve for $x$: $2(x - 1.5) = 5$.', '[]', '4', '5/2+1.5', 'Divide both sides by 2: $x - 1.5 = 2.5$. Add 1.5: $x = 4$. Check: $2(4 - 1.5) = 2 \times 2.5 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x - 1.5 = 2.5; x = 4.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c6386e2-123a-4248-b64f-10a57ba7bbbb', 'NC26.7.SGMR.1', 1, 'numeric', 'Area of a triangle', 'A triangle has a base of 10 centimeters and a height of 6 centimeters. What is its area, in square centimeters?', '[]', '30', '10*6/2', 'Area of a triangle $= \frac{1}{2} \times \text{base} \times \text{height} = \frac{1}{2} \times 10 \times 6 = 30$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = (1/2)(10)(6) = 30.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('180e6a0e-261c-43d9-9360-1f335dcd3570', 'NC26.7.SGMR.1', 1, 'choice', 'Area of a circle', 'A circle has a radius of 6 centimeters. Which expression gives its area, in square centimeters?', '["$2 \\times \\pi \\times 6$","$\\pi \\times 6^2$","$\\pi \\times 12^2$","$\\pi \\times 6$"]', '$\pi \times 6^2$', NULL, 'The area of a circle is $\pi r^2$. With $r = 6$ this is $\pi \times 6^2$.', 'checked', '{"lint":[],"solve":{"answer":"$\\pi \\times 6^2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = pi r^2 = pi x 6^2.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15c4bc6d-c055-41aa-97ed-a24825ea0453', 'NC26.7.SGMR.1', 1, 'choice', 'Area of a circle', 'A round pond has a diameter of 20 meters. Use 3.14 for $\pi$. What is the area of the water''s surface, in square meters?', '["314","1256","62.8","31.4"]', '314', '3.14*(20/2)^2', 'The radius is half the diameter: 20 $\div$ 2 = 10 meters. Area = $3.14 \times 10 \times 10 = 314$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"314","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r = 10. A = 3.14 x 100 = 314.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01311a2b-8c50-417a-9273-c34f374ab49e', 'NC26.7.SGMR.1', 2, 'numeric', 'Area of a composite figure by subtraction', 'A rectangular garden is 12 meters long and 9 meters wide. A rectangular pond that is 4 meters by 3 meters sits inside the garden. How many square meters of the garden are not covered by the pond?', '[]', '96', '12*9-4*3', 'Garden: $12 \times 9 = 108$ square meters. Pond: $4 \times 3 = 12$ square meters. Not covered: $108 - 12 = 96$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"96","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Garden 12 x 9 = 108; pond 4 x 3 = 12. 108 - 12 = 96.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('089b76a1-b38c-4e0e-9b45-45cea26c8b57', 'NC26.7.SGMR.1', 2, 'choice', 'Pi as the ratio of circumference to diameter', 'Four students each measured a round object: the distance around it and the distance across it (its diameter). Whose measurements fit what we know about $\pi$?', '["Around 20 cm, across 10 cm","Around 31 cm, across 10 cm","Around 40 cm, across 10 cm","Around 62 cm, across 10 cm"]', 'Around 31 cm, across 10 cm', NULL, 'The distance around should be about 3.14 times the distance across. For a diameter of 10 cm that is about 31.4 cm, so 31 cm fits. The others are about 2, 4 and 6 times the diameter.', 'checked', '{"lint":[],"solve":{"answer":"Around 31 cm, across 10 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ratios around/across: 2, 4, 6.2, 3.1. Only 3.1 is close to pi.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c300280-2c5e-4497-ac41-737e78423f67', 'NC26.7.SGMR.1', 2, 'choice', 'Area of a figure with a part removed', 'A metal washer is a circle with a radius of 10 millimeters, with a circle of radius 4 millimeters cut out of its center. Use 3.14 for $\pi$. What is the area of the metal, in square millimeters?', '["263.76","113.04","364.24","50.24"]', '263.76', '3.14*10^2 - 3.14*4^2', 'Big circle: $3.14 \times 10^2 = 314$. Hole: $3.14 \times 4^2 = 50.24$. Metal: 314 $-$ 50.24 = 263.76 square millimeters.', 'checked', '{"lint":[],"solve":{"answer":"263.76","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3.14 x (100 - 16) = 3.14 x 84 = 263.76.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12066343-6637-4c66-8a37-6135a7cc7817', 'NC26.7.SGMR.1', 3, 'numeric', 'Area of a parallelogram or trapezoid', 'A trapezoid has an area of 70 square centimeters and a height of 7 centimeters. One of its parallel sides is 6 centimeters long. How long is the other parallel side, in centimeters?', '[]', '14', '2*70/7 - 6', 'Area = $\frac{1}{2} \times$ (sum of parallel sides) $\times$ height, so the sum of the parallel sides is $2 \times 70 \div 7 = 20$ centimeters. The other side is 20 $-$ 6 = 14 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"70 = 1/2 (6 + b) x 7, so 6 + b = 20, b = 14.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d5f5c47-70d1-4105-8a34-d1aa5b357a75', 'NC26.7.SGMR.1', 3, 'numeric', 'Area of a parallelogram or trapezoid', 'A parallelogram has an area of 91 square inches and a base of 13 inches. A rectangle has the same height as the parallelogram, and its base is 5 inches longer than the parallelogram''s base. What is the area of the rectangle, in square inches?', '[]', '126', '(13+5)*(91/13)', 'Height of the parallelogram = 91 $\div$ 13 = 7 inches. The rectangle''s base is 13 + 5 = 18 inches, so its area is 18 $\times$ 7 = 126 square inches.', 'checked', '{"lint":[],"solve":{"answer":"126","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Height = 91 / 13 = 7. Rectangle base = 13 + 5 = 18. Area = 18 x 7 = 126.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c0391ce-1839-47ce-999d-fd1d4dc216ba', 'NC26.7.SGMR.2', 1, 'numeric', 'Volume from base area and height', 'The base of a right prism has an area of 12 square centimeters. The prism is 7 centimeters tall. What is its volume in cubic centimeters?', '[]', '84', '12*7', 'A right prism is the base layer repeated for the whole height. Volume = area of base $\times$ height = $12 \times 7 = 84$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"84","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = base area x height = 12 x 7 = 84.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20d43f73-4c41-4fda-8a5f-9939435162a7', 'NC26.7.SGMR.2', 1, 'choice', 'Surface area of a rectangular prism or cube', 'A box is 6 cm long, 2 cm wide and 3 cm high. Which expression gives its total surface area, in square centimeters?', '["$6 \\times 2 \\times 3$","$6 \\times 2 + 6 \\times 3 + 2 \\times 3$","$2(6 + 2 + 3)$","$2(6 \\times 2) + 2(6 \\times 3) + 2(2 \\times 3)$"]', '$2(6 \times 2) + 2(6 \times 3) + 2(2 \times 3)$', NULL, 'The box has three pairs of faces: $6 \times 2$, $6 \times 3$ and $2 \times 3$. Surface area is the sum of all six faces, so each product is counted twice.', 'checked', '{"lint":[],"solve":{"answer":"$2(6 \\times 2) + 2(6 \\times 3) + 2(2 \\times 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Three pairs of faces: 2(lw) + 2(lh) + 2(wh).","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d344b5d-df95-4404-8c1b-457cb2b8f5da', 'NC26.7.SGMR.2', 1, 'numeric', 'Unknown dimension from volume or surface area', 'A can has a circular base with an area of 78.5 square centimeters. The can holds 628 cubic centimeters. How tall is the can, in centimeters?', '[]', '8', '628/78.5', 'Volume = base area $\times$ height, so height = 628 $\div$ 78.5 = 8 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"628 / 78.5 = 8.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06409297-a2de-43ba-9170-9153976a344e', 'NC26.7.SGMR.2', 2, 'choice', 'Surface area of a rectangular prism or cube', 'A gift box is 12 cm long, 8 cm wide and 5 cm high. How many square centimeters of wrapping paper cover the whole box exactly, with no overlap?', '["480","196","392","312"]', '392', '2*(12*8+12*5+8*5)', 'Top and bottom: 2 $\times$ 12 $\times$ 8 = 192. Front and back: 2 $\times$ 12 $\times$ 5 = 120. Two sides: 2 $\times$ 8 $\times$ 5 = 80. Total = 392 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"392","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(12x8 + 12x5 + 8x5) = 2(96 + 60 + 40) = 392.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d9debfa-628c-4417-ad39-774b62ee591b', 'NC26.7.SGMR.2', 2, 'numeric', 'Surface area of a composite solid', 'A cylinder with a radius of 2 cm and a height of 5 cm stands on the top face of a cube with edges of 6 cm. Use 3.14 for $\pi$. What is the surface area of the combined solid, including the bottom of the cube, in square centimeters?', '[]', '278.8', '6*6^2 + 2*3.14*2*5', 'The circle where the cylinder touches the cube is hidden, but the top of the cylinder is a circle of the same size, so the flat surfaces total the same as the cube alone: 6 $\times$ $6^2$ = 216. The curved side of the cylinder adds 2 $\times$ 3.14 $\times$ 2 $\times$ 5 = 62.8. Total = 278.8 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"278.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cube 6 x 36 = 216 (the circle hidden on its top is replaced by the cylinder''s top). Add cylinder side 2 x 3.14 x 2 x 5 = 62.8. Total 278.8.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('107276a0-2944-4f20-816c-cb701f10560a', 'NC26.7.SGMR.2', 2, 'choice', 'How changing dimensions changes volume', 'A cube has a volume of 8 cubic centimeters. Every edge is made 3 times as long. What is the volume of the new cube, in cubic centimeters?', '["216","72","24","35"]', '216', '8*27', 'Each of the three lengths is multiplied by 3, so the volume is multiplied by 3 $\times$ 3 $\times$ 3 = 27. New volume = 8 $\times$ 27 = 216 cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"216","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Edge 2 becomes 6; 6^3 = 216 (or 8 x 27).","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14c4381e-4d5b-45e3-84d5-efd8b9a3310c', 'NC26.7.SGMR.2', 3, 'numeric', 'Surface area of a cylinder', 'A closed cylindrical tank has a radius of 2 meters and a height of 5 meters. Its whole outside is painted with paint that costs 3 dollars per square meter. Use 3.14 for $\pi$. How many dollars does the paint cost?', '[]', '263.76', '(2*3.14*2^2 + 2*3.14*2*5)*3', 'Ends: 2 $\times$ 3.14 $\times$ $2^2$ = 25.12. Curved side: 2 $\times$ 3.14 $\times$ 2 $\times$ 5 = 62.8. Surface area = 87.92 square meters. Cost = 87.92 $\times$ 3 = 263.76 dollars.', 'checked', '{"lint":[],"solve":{"answer":"263.76","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ends 2 x 3.14 x 4 = 25.12. Side 2 x 3.14 x 2 x 5 = 62.8. Total 87.92. Cost 87.92 x 3 = 263.76.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('044540df-be75-4969-a1ea-89045af5faf7', 'NC26.7.SGMR.2', 3, 'numeric', 'Volume of a composite solid', 'A building is a rectangular prism 12 m long, 8 m wide and 6 m tall. Its roof is a triangular prism 12 m long, with triangular ends that have a base of 8 m and a height of 3 m. A chimney shaped like a 2 m by 2 m by 3 m box stands on the roof. What is the volume of the building, roof and chimney together, in cubic meters?', '[]', '732', '12*8*6 + 1/2*8*3*12 + 2*2*3', 'Rectangular part: 12 $\times$ 8 $\times$ 6 = 576. Roof: $\frac{1}{2} \times 8 \times 3 \times 12 = 144$. Chimney: 2 $\times$ 2 $\times$ 3 = 12. Total = 576 + 144 + 12 = 732 cubic meters.', 'checked', '{"lint":[],"solve":{"answer":"732","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: a box cannot stand flat on a sloped roof without part of it overlapping the roof; the intended reading (just add 12) is clear at this grade.","work":"Building 12 x 8 x 6 = 576. Roof 1/2 x 8 x 3 x 12 = 144. Chimney 2 x 2 x 3 = 12. Total 732.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00ec38cc-a3eb-4dd0-81a8-644a9433a54f', 'NC26.7.SGMR.3', 1, 'numeric', 'Vertical angles with expressions (equation)', 'Two vertical angles measure $(x + 12)^\circ$ and $40^\circ$. What is $x$?', '[]', '28', '40-12', 'Vertical angles are equal, so $x + 12 = 40$ and $x = 28$.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertical angles equal: x + 12 = 40, x = 28.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
