INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01dcc5ef-2ec9-4121-b9eb-ee4091c109a6', 'NC26.7.SGMR.3', 2, 'numeric', 'Supplementary angles and straight lines with expressions (equation)', 'An angle measures $(2x + 6)^\circ$ and its supplement measures $(4x - 18)^\circ$. What is the measure of the angle in degrees?', '[]', '70', '2*32+6', 'The angles add up to 180: $(2x + 6) + (4x - 18) = 180$, so $6x - 12 = 180$, $6x = 192$ and $x = 32$. The angle is $2 \times 32 + 6 = 70$ degrees (and its supplement is 110).', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x - 12 = 180, x = 32. Angle = 2(32) + 6 = 70 (supplement 110).","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02834243-e4ef-49c2-8a35-b7bdd0631d16', 'NC26.7.SGMR.3', 2, 'choice', 'Vertical angles with expressions (equation)', 'Angle 1 and angle 3 are vertical angles. Angle 1 measures $(2x + 18)^\circ$ and angle 3 measures $(5x - 24)^\circ$. What is the measure of angle 1 in degrees?', '["14","46","134","28"]', '46', '2*14+18', 'Vertical angles are equal: $2x + 18 = 5x - 24$, so $3x = 42$ and $x = 14$. Angle 1 is $2 \times 14 + 18 = 46$ degrees. The choice 14 is just $x$, 134 is the supplement, and 28 is $2x$.', 'checked', '{"lint":[],"solve":{"answer":"46","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x + 18 = 5x - 24, 3x = 42, x = 14. Angle 1 = 28 + 18 = 46.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1277938b-bbd7-485a-a746-09462d5f22c5', 'NC26.7.SGMR.3', 2, 'choice', 'Choose the equation for an unknown angle', 'The complement of an angle is three times the angle. If the angle measures $x^\circ$, which equation can be used to find $x$?', '["$x + 3x = 180$","$3x = 90$","$x + 3x = 90$","$x + 3 = 90$"]', '$x + 3x = 90$', NULL, 'The complement measures $3x$, and an angle and its complement add up to 90. So $x + 3x = 90$.', 'checked', '{"lint":[],"solve":{"answer":"$x + 3x = 90$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Complement = 3x, angle + complement = 90: x + 3x = 90 (x = 22.5).","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1901c4ee-ce31-4b2b-9b15-119524c42204', 'NC26.7.SGMR.3', 3, 'choice', 'Vertical angles: find the measure', 'Two lines cross. One pair of vertical angles has a sum of $146^\circ$. What is the measure, in degrees, of each of the other two angles?', '["73","107","34","214"]', '107', '180-146/2', 'Each angle of the first pair is $146 \div 2 = 73$ degrees. An angle next to it is $180 - 73 = 107$ degrees, and the other pair are vertical angles with the same measure. The choice 73 is one of the first pair, 34 is $180 - 146$, and 214 is $360 - 146$.', 'checked', '{"lint":[],"solve":{"answer":"107","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertical pair equal, each 146/2 = 73. Each of the other two = 180 - 73 = 107.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09f2dbd7-2059-446a-8432-e1e46e6598f7', 'NC26.7.SGMR.3', 3, 'numeric', 'Vertical angles with expressions (equation)', 'Two lines cross. One angle measures $(3x + 10)^\circ$ and its vertical angle measures $(5x - 20)^\circ$. What is the sum of the measures of the other two angles in degrees?', '[]', '250', '360-2*(3*15+10)', 'Vertical angles are equal: $3x + 10 = 5x - 20$, so $30 = 2x$ and $x = 15$. Each of these angles is $3 \times 15 + 10 = 55$ degrees. The four angles add up to 360, so the other two add up to $360 - 2 \times 55 = 250$ degrees. (Each is $180 - 55 = 125$.)', 'checked', '{"lint":[],"solve":{"answer":"250","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + 10 = 5x - 20, x = 15. Angle = 55. Others each 125, sum 250 (= 360 - 110).","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08349673-5ad4-4f5f-85de-6f3662a7340c', 'NC26.7.RD.1', 1, 'numeric', 'Theoretical probability of one event', 'A bag has 3 red marbles, 5 blue marbles and 2 green marbles. One marble is drawn at random. What is the probability that it is green? Write your answer as a fraction.', '[]', '1/5', '2/10', 'There are $3 + 5 + 2 = 10$ marbles and 2 of them are green. The probability is $\frac{2}{10} = \frac{1}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"1/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 marbles, 2 green: 2/10 = 1/5.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17c74c95-420c-4856-a07e-46ad7354aeab', 'NC26.7.RD.1', 1, 'numeric', 'Using a tree diagram', 'In a tree diagram for a game, the first branch "win" has probability $\frac{3}{4}$. From the end of that branch, the second branch "win again" has probability $\frac{1}{2}$. What is the probability of the path win, then win again? Write your answer as a fraction.', '[]', '3/8', '3/4*1/2', 'To find the probability of a path, multiply the probabilities along its branches: $\frac{3}{4} \times \frac{1}{2} = \frac{3}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"3/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiply along the path: 3/4 x 1/2 = 3/8.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1517cd4e-d0f7-418c-a628-7a156046f75c', 'NC26.7.RD.1', 1, 'choice', 'Compound events without replacement', 'Three tickets labeled A, B and C are in a hat. Two tickets are drawn one after the other, and the first ticket is NOT put back. How many different ordered outcomes are there?', '["9","3","5","6"]', '6', '3*2', 'There are 3 choices for the first ticket and then 2 left for the second, so $3 \times 2 = 6$ outcomes: AB, AC, BA, BC, CA, CB. (9 would be right only if the first ticket were put back.)', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 choices for first, 2 for second: 3 x 2 = 6 (AB, AC, BA, BC, CA, CB).","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0bfd3d3e-0069-479a-8a9b-1a974eb26467', 'NC26.7.RD.1', 2, 'choice', 'Using a table of outcomes', 'When two fair six-sided dice are rolled and the numbers are added, which sum is the most likely?', '["6","12","7","9"]', '7', '7', 'In the table of all 36 outcomes, a sum of 7 appears 6 times, more than any other sum. A sum of 6 appears 5 times, a sum of 9 appears 4 times, and a sum of 12 appears only once.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 7 has 6 ways, more than any other sum (6 and 8 have 5, 9 has 4, 12 has 1).","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02e394d7-6722-4a51-ae01-25a329e50829', 'NC26.7.RD.1', 2, 'numeric', 'Compound events without replacement', 'A basket holds 4 apples and 2 pears. Pia takes two pieces of fruit, one after the other, without looking and without putting the first one back. What is the probability that both are pears? Write your answer as a fraction.', '[]', '1/15', '2/6*1/5', 'The first piece is a pear with probability $\frac{2}{6}$. Then 1 pear is left among 5 pieces, so the second is a pear with probability $\frac{1}{5}$. Both pears: $\frac{2}{6} \times \frac{1}{5} = \frac{2}{30} = \frac{1}{15}$.', 'checked', '{"lint":[],"solve":{"answer":"1/15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 fruits, 2 pears: 2/6 x 1/5 = 2/30 = 1/15.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f48f429-a553-4957-bda9-de194d47eec0', 'NC26.7.RD.1', 2, 'numeric', 'Expected results and the effect of more trials', 'On a spinner, the probability of landing on green is $\frac{3}{10}$. If the spinner is spun 250 times, about how many times would you expect it to land on green?', '[]', '75', '3/10*250', 'The expected number is the probability times the number of spins: $\frac{3}{10} \times 250 = 75$.', 'checked', '{"lint":[],"solve":{"answer":"75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/10 x 250 = 75.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1bce1a22-b1a6-4e61-b7cb-357ba686f096', 'NC26.7.RD.1', 3, 'choice', 'Compound event with unequal outcomes', 'A spinner lands on red with probability $\frac{1}{2}$, on blue with probability $\frac{1}{3}$ and on green with probability $\frac{1}{6}$. A fair coin is flipped and the spinner is spun. What is the probability of getting tails and a spinner color that is not red?', '["1/2","1/4","1/6","1/12"]', '1/4', '1/2*(1/3+1/6)', 'The chance of tails is $\frac{1}{2}$. The chance the spinner is not red is $\frac{1}{3} + \frac{1}{6} = \frac{1}{2}$. Both together: $\frac{1}{2} \times \frac{1}{2} = \frac{1}{4}$. (1/6 leaves out green, and 1/12 leaves out blue.)', 'checked', '{"lint":[],"solve":{"answer":"1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(tails) = 1/2. P(not red) = 1/3 + 1/6 = 1/2. Independent: 1/2 x 1/2 = 1/4.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f6ed2e9-b4cd-4c38-bed1-baab6698ae4c', 'NC26.7.RD.1', 3, 'numeric', 'Probability when outcomes are not equally likely', 'A weighted die lands on 6 with probability $\frac{1}{3}$. The other five faces are equally likely to come up. What is the probability of rolling a 2? Write your answer as a fraction.', '[]', '2/15', '(1-1/3)/5', 'The five other faces share the remaining probability $1 - \frac{1}{3} = \frac{2}{3}$ equally. Each gets $\frac{2}{3} \div 5 = \frac{2}{15}$.', 'checked', '{"lint":[],"solve":{"answer":"2/15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Other five faces share 1 - 1/3 = 2/3; each 2/3 / 5 = 2/15.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0556a0c3-e214-4048-8f3f-1e33424b526b', 'NC26.7.RD.2', 1, 'choice', 'Write or choose a question that compares two groups', 'Ana wants to compare how long seventh graders and eighth graders read each week. Which question compares these two groups?', '["How many minutes did Ana spend reading during the last week?","How many minutes does a typical seventh grader read in one week?","Do seventh graders read more minutes each week than eighth graders?","What is the title of the longest book that an eighth grader has read?"]', 'Do seventh graders read more minutes each week than eighth graders?', NULL, 'A comparison question names both groups and the same measurement for each. Only the first question asks about reading time for both seventh graders and eighth graders.', 'checked', '{"lint":[],"solve":{"answer":"Do seventh graders read more minutes each week than eighth graders?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only ''Do seventh graders read more minutes each week than eighth graders?'' involves both groups and compares them.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00f53cc2-abde-42bd-aae0-c8f99c689624', 'NC26.7.RD.2', 1, 'choice', 'Write or choose a question that compares two groups', 'Which question compares two groups?', '["Are soccer team members taller, on average, than swim team members?","How tall is the person who coaches the soccer team at our school?","How many students are on the swim team and on the soccer team?","What is the typical height of the students on the soccer team?"]', 'Are soccer team members taller, on average, than swim team members?', NULL, 'The correct question measures the same thing (height) for two groups and asks how they compare. The question about the typical height of the soccer team asks about one group only.', 'checked', '{"lint":[],"solve":{"answer":"Are soccer team members taller, on average, than swim team members?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Comparing heights of soccer vs swim team members compares two groups. Counting members of both is a total, not a comparison of a variable.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b8571e8-849c-48f9-bbcf-681bc6f7f53d', 'NC26.7.RD.2', 1, 'choice', 'Simulate a sample with random numbers or a device', 'Which tool could be used to simulate choosing at random among exactly 6 equally likely choices?', '["a fair coin","a spinner with 5 equal sections","a fair six-sided number cube","a deck of 8 different cards"]', 'a fair six-sided number cube', NULL, 'A number cube has 6 faces that are equally likely, one for each choice. A coin has 2 outcomes, the spinner 5, and the deck 8.', 'checked', '{"lint":[],"solve":{"answer":"a fair six-sided number cube","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A fair six-sided cube gives 6 equally likely outcomes; coin 2, spinner 5, cards 8.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1379e58e-3b90-4020-abae-494bfe478a60', 'NC26.7.RD.2', 2, 'choice', 'Spot a biased sample', 'To find out how all 500 students at a school feel about a new music class, a survey is given to 100 students as they leave a band concert. Why might the results be biased?', '["100 students is too few for any survey to be fair","Students at a band concert are more likely to like music than other students","The survey should have been given to teachers instead","The students were asked as they left, not as they arrived"]', 'Students at a band concert are more likely to like music than other students', NULL, 'A sample is biased when some members of the population are more likely to be chosen or to answer a certain way. People at a band concert probably like music more than the average student. A sample of 100 out of 500 is large enough, and when they were asked does not matter.', 'checked', '{"lint":[],"solve":{"answer":"Students at a band concert are more likely to like music than other students","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The sample is drawn from concert-goers, who are more likely to favour music: selection bias.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1bcf2080-0633-4e24-a449-776040e3688e', 'NC26.7.RD.2', 2, 'numeric', 'Spot and explain bias in a sample', 'A school wants to know the favorite music of all its students. Four plans for choosing 30 students are listed. A: ask the 30 students in the school band. B: choose 30 names at random from the list of all students. C: ask the first 30 students who volunteer after an announcement. D: use a computer to pick 30 student ID numbers at random. How many of the four plans are likely to give a biased sample?', '[]', '2', '2', 'Plan A is biased because band students may like different music from other students. Plan C is biased because volunteers may have stronger opinions than other students. Plans B and D give every student the same chance. So 2 plans are likely to be biased.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A (band members) biased; C (volunteers) biased; B and D random. 2 biased.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1936c87a-8e31-42ea-a75e-c0fbbf97db03', 'NC26.7.RD.2', 2, 'choice', 'Judge a conclusion drawn from a sample', 'A random sample of 50 students from a school of 1,000 students finds that 30 ride the bus. Which statement is the best conclusion?', '["Exactly 600 of the 1,000 students ride the bus every day.","Only 30 students at the school ride the bus.","Fewer than half of the students ride the bus.","About 600 of the 1,000 students probably ride the bus."]', 'About 600 of the 1,000 students probably ride the bus.', NULL, '$\frac{30}{50} = 60\%$ of the sample ride the bus, so about 60% of 1,000, or 600, probably do. A sample gives an estimate, not an exact count.', 'checked', '{"lint":[],"solve":{"answer":"About 600 of the 1,000 students probably ride the bus.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30/50 = 60%; 0.6 x 1000 = about 600, an estimate not exact.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d94f7f5-c46b-4c86-991e-fc8716a27e58', 'NC26.7.RD.2', 3, 'choice', 'Why a random sample represents a population, and how samples vary', 'Which statement about random samples is correct?', '["A random sample always has exactly the same percents as the population does.","A sample can, by chance, differ from the population in the share of a group.","A random sample can never include members from a large group in the population.","A random sample is always biased, even when chance picks the members."]', 'A sample can, by chance, differ from the population in the share of a group.', NULL, 'Because chance picks the members, a sample can have somewhat more or fewer members of a group than the population has. That is why estimates from samples are approximate.', 'checked', '{"lint":[],"solve":{"answer":"A sample can, by chance, differ from the population in the share of a group.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"By chance a random sample can differ from the population in a group''s share; the other statements are false.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0608a313-5390-498a-93f0-ecdc43d0c829', 'NC26.7.RD.2', 3, 'numeric', 'Simulate a sample with random numbers or a device', 'Eli numbers the 24 students in his class from 01 to 24. To choose a random sample of 3 students, he reads random two-digit numbers: 47, 12, 88, 05, 12, 31, 19, 22. He skips any number that is not from 01 to 24 and any number he has already chosen. What is the sum of the numbers of the three students chosen?', '[]', '36', '12+5+19', '47 is too big, so skip it. 12 is chosen. 88 is too big. 05 is chosen. 12 is a repeat, so skip it. 31 is too big. 19 is chosen, which makes three students. The sum is $12 + 5 + 19 = 36$.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"47 skip; 12 chosen; 88 skip; 05 chosen; 12 repeat skip; 31 skip; 19 chosen (3 found). Sum 12 + 5 + 19 = 36.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1341ba47-d7f9-4c5f-9b6c-cdf0b8a6b635', 'NC26.7.RD.3', 1, 'numeric', 'Compare the centers of two distributions', 'Ravi practiced piano for 15, 20, 25, 30, 35 minutes on five days. Lena practiced for 25, 30, 35, 40, 45 minutes on five days. How many minutes greater is Lena''s mean practice time than Ravi''s?', '[]', '10', '(25+30+35+40+45)/5-(15+20+25+30+35)/5', 'Ravi''s mean is (15 + 20 + 25 + 30 + 35) / 5 = 125 / 5 = 25 minutes. Lena''s mean is (25 + 30 + 35 + 40 + 45) / 5 = 175 / 5 = 35 minutes. The difference is 35 - 25 = 10 minutes.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ravi: 15+20+25+30+35=125, mean 25. Lena: 25+30+35+40+45=175, mean 35. 35-25=10.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0700ab9d-6219-44b9-8656-f4b9c0079160', 'NC26.7.RD.3', 1, 'numeric', 'Read a stem-and-leaf plot', 'A stem-and-leaf plot shows the number of seconds students took to run a lap. The row for stem 3 has leaves 0, 2, 5. The row for stem 4 has leaves 1, 1, 7, 9. The row for stem 5 has leaves 2, 6. How many students are shown?', '[]', '9', '3+4+2', 'Each leaf is one student. Stem 3 has 3 leaves, stem 4 has 4 leaves and stem 5 has 2 leaves, so 3 + 4 + 2 = 9 students.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Leaves 3+4+2=9.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b7517f1-ff67-4f7f-b89b-98e31c5be05a', 'NC26.7.RD.3', 1, 'numeric', 'Read a box plot from its five-number summary', 'A box plot of the minutes students took to get to school has a minimum of 5, a first quartile of 12, a median of 18, a third quartile of 27 and a maximum of 41. What is the interquartile range, the length of the box?', '[]', '15', '27-12', 'The interquartile range is the third quartile minus the first quartile: 27 - 12 = 15 minutes.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"27-12=15.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('027cec05-910a-4bdf-8e47-4dd6a0fd59f4', 'NC26.7.RD.3', 2, 'numeric', 'Compare the spread of two distributions', 'Plot A has dots at 12, 12, 13, 15, 18. Plot B has dots at 10, 14, 14, 15, 16, 22. The range of Plot B is how many times the range of Plot A?', '[]', '2', '(22-10)/(18-12)', 'The range of A is 18 - 12 = 6. The range of B is 22 - 10 = 12. Since 12 / 6 = 2, the range of B is 2 times the range of A.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range A 18-12=6; range B 22-10=12; 12/6=2.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fa35108-282c-4483-8bc3-19d29bba6c6e', 'NC26.7.RD.3', 2, 'choice', 'Describe the shape of a distribution', 'A dot plot shows how many books 14 students read last month: 5 dots at 1, 4 dots at 2, 3 dots at 3, 1 dot at 7 and 1 dot at 9. Which describes the shape?', '["Most values are low, with a tail stretching toward the high values.","Most values are high, with a tail stretching toward the low values.","The values are balanced evenly on both sides of the center.","The values form two clusters of equal size."]', 'Most values are low, with a tail stretching toward the high values.', NULL, 'The tallest stacks are at the low values 1, 2 and 3, and a few dots trail off toward 7 and 9. A tail toward the high values is called skewed to the right.', 'checked', '{"lint":[],"solve":{"answer":"Most values are low, with a tail stretching toward the high values.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Most dots at 1-3, a few far out at 7 and 9: right tail toward high values.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a72d6f5-9723-4e70-932d-3936258980b8', 'NC26.7.RD.3', 2, 'choice', 'Draw a conclusion the data support', 'Group A walked between 4 and 12 thousand steps a day, with a median of 8. Group B walked between 5 and 13 thousand steps a day, with a median of 9. A student says, "Every person in Group B walks more than every person in Group A." Which reply is best?', '["No: Group A''s greatest value, 12, is greater than Group B''s least value, 5.","Yes: Group B has the greater median, 9, so all of its values are greater.","Yes: Group B''s greatest value, 13, is greater than Group A''s greatest value, 12.","No: both groups have a range of 8, so the two groups must be identical."]', 'No: Group A''s greatest value, 12, is greater than Group B''s least value, 5.', NULL, 'The claim is about every person, so one counterexample is enough. Group A has a value of 12, which is more than Group B''s least value of 5. So some person in Group A walks more than some person in Group B, and the claim is not supported. A greater median or a greater maximum does not mean every value is greater, and equal ranges do not make two groups identical.', 'checked', '{"lint":[],"solve":{"answer":"No: Group A''s greatest value, 12, is greater than Group B''s least value, 5.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ranges overlap (A up to 12, B from 5), so someone in A may walk more than someone in B. The correct reply cites that overlap.","run_id":"claude-code","at":"2026-10-18T03:28:53.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0568f81b-53aa-4063-94cf-70c3f23bd3f5', 'NC26.7.RD.3', 3, 'choice', 'Compare the centers of two distributions', 'Each choice shows two small data sets, A and B. In which choice is the median of B exactly 3 greater than the median of A?', '["A: 2, 5, 11 and B: 3, 6, 18","A: 1, 6, 8 and B: 2, 4, 11","A: 6, 2, 9 and B: 4, 5, 8","A: 2, 5, 9 and B: 3, 8, 9"]', 'A: 2, 5, 9 and B: 3, 8, 9', NULL, 'For A: 2, 5, 9 and B: 3, 8, 9 the medians are 5 and 8, which differ by 3. For A: 2, 5, 11 and B: 3, 6, 18 the means differ by 3 (6 and 9), but the medians are 5 and 6. For A: 1, 6, 8 and B: 2, 4, 11 the greatest values differ by 3, but the medians are 6 and 4. For A: 6, 2, 9 and B: 4, 5, 8 the lists are not in order; the true medians are 6 and 5.', 'checked', '{"lint":[],"solve":{"answer":"A: 2, 5, 9 and B: 3, 8, 9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: medians 5 and 8, diff 3. B: 6 and 4. C: A sorted 2,6,9 median 6; B 4,5,8 median 5. D: 5 and 6. Only first choice works.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0815b226-e008-4721-a586-ec4fef019561', 'NC26.7.RD.3', 3, 'choice', 'Read a stem-and-leaf plot', 'Two teams'' points in nine games are shown in a back-to-back stem-and-leaf plot. Team X: stem 3 has leaves 2, 6, 8; stem 4 has leaves 0, 1, 5, 5, 7; stem 5 has leaf 2. Team Y: stem 3 has leaf 1; stem 4 has leaves 4, 6; stem 5 has leaves 0, 3, 5, 7, 8, 9. A stem of 3 and a leaf of 2 means 32. Which statement is true?', '["Team X''s median is 12 greater than Team Y''s median.","Team Y''s median is 12 greater than Team X''s median.","Team X has the greater range of the two teams.","Both teams have the same median."]', 'Team Y''s median is 12 greater than Team X''s median.', NULL, 'Team X''s scores in order: 32, 36, 38, 40, 41, 45, 45, 47, 52, so the median is 41 and the range is 20. Team Y''s: 31, 44, 46, 50, 53, 55, 57, 58, 59, so the median is 53 and the range is 28. Y''s median is 53 - 41 = 12 greater, and Y has the greater range.', 'checked', '{"lint":[],"solve":{"answer":"Team Y''s median is 12 greater than Team X''s median.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X: 32,36,38,40,41,45,45,47,52, median 41, range 20. Y: 31,44,46,50,53,55,57,58,59, median 53, range 28. Y median 12 greater.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18debec1-7fef-4be2-a8fd-957f38873649', 'NC26.7.RD.4', 1, 'numeric', 'Find the mean absolute deviation', 'The mean of the data 3, 5, 9, 11 is 7. What is the mean absolute deviation (MAD) of the data?', '[]', '3', '(16+8+8+16)/16', 'The distances from the mean 7 are 4, 2, 2 and 4. Their mean is (4 + 2 + 2 + 4) / 4 = 12 / 4 = 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distances from 7: 4,2,2,4, sum 12; 12/4=3.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('135040fa-41c4-456e-9d06-00c6dea459d2', 'NC26.7.RD.4', 1, 'numeric', 'Describe the effect of an extreme value', 'The data set 10, 12, 13, 15 has a range of 5. A new value, 40, is added. What is the range of the data set now?', '[]', '30', '40-10', 'The new value is the greatest, so the range is 40 - 10 = 30. One extreme value raised the range from 5 to 30.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40-10 = 30.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('019a2c74-39c9-47c9-bfd0-1482a9381d7f', 'NC26.7.RD.4', 1, 'numeric', 'Describe the effect of an extreme value', 'The data set 22, 25, 27, 30, 31, 78 has an extreme value, 78. By how much does the range decrease if 78 is removed?', '[]', '47', '(78-22)-(31-22)', 'With 78 the range is 78 - 22 = 56. Without it the greatest value is 31, so the range is 31 - 22 = 9. The range decreases by 56 - 9 = 47.', 'checked', '{"lint":[],"solve":{"answer":"47","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"With 78: 78-22=56. Without: 31-22=9. Decrease 47.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
