INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ba38a15-c2c2-414b-aabd-59350a4bc42b', 'NC26.7.RD.4', 2, 'choice', 'Find the interquartile range', 'The data set 6, 8, 9, 12, 14, 17, 19, 25 is in order. What are its first and third quartiles?', '["8 and 17","9 and 17","6 and 25","8.5 and 18"]', '8.5 and 18', NULL, 'There are 8 values, so each half has 4. The lower half 6, 8, 9, 12 has median (8 + 9) / 2 = 8.5, which is Q1. The upper half 14, 17, 19, 25 has median (17 + 19) / 2 = 18, which is Q3. (6 and 25 are the least and greatest values.)', 'checked', '{"lint":[],"solve":{"answer":"8.5 and 18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6,8,9,12 | 14,17,19,25: Q1=(8+9)/2=8.5, Q3=(17+19)/2=18.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c66872a-d916-45d6-af96-18e7b1914dfa', 'NC26.7.RD.4', 2, 'numeric', 'Find the mean absolute deviation', 'Find the mean absolute deviation (MAD) of the data 12, 15, 9, 18 and 6.', '[]', '3.6', '(0+15+15+30+30)/25', 'The mean is 60 / 5 = 12. The distances from 12 are 0, 3, 3, 6 and 6, which add to 18. The MAD is 18 / 5 = 3.6.', 'checked', '{"lint":[],"solve":{"answer":"3.6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 60, mean 12. Distances 0,3,3,6,6 = 18; 18/5 = 3.6.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0718805a-2ee8-48b3-a0bf-866281c60873', 'NC26.7.RD.4', 2, 'choice', 'Compare two data sets using center and spread', 'Class 1''s test scores have a median of 78 and an IQR of 6. Class 2''s test scores have a median of 82 and an IQR of 16. Which statement is correct?', '["Class 2''s scores are typically higher, and they vary less.","Class 1''s scores are typically higher, and they vary more.","Class 1''s scores are typically higher, but they vary less.","Class 2''s scores are typically higher, but they vary more."]', 'Class 2''s scores are typically higher, but they vary more.', NULL, 'The median of Class 2 (82) is greater than that of Class 1 (78), so its scores are typically higher. The IQR of Class 2 (16) is greater than that of Class 1 (6), so its middle half is more spread out: its scores vary more.', 'checked', '{"lint":[],"solve":{"answer":"Class 2''s scores are typically higher, but they vary more.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Class 2 median 82 > 78 (typically higher) and IQR 16 > 6 (varies more).","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0baf79a5-681b-49ef-8d0f-9740724297c7', 'NC26.7.RD.4', 3, 'numeric', 'Compare two sets using IQR', 'Set X is 3, 5, 6, 8, 9, 12, 14, 17. Set Y is 10, 11, 12, 13, 14, 15, 16, 17. How much greater is the interquartile range of Set X than the interquartile range of Set Y?', '[]', '3.5', '((12+14)/2-(5+6)/2)-((15+16)/2-(11+12)/2)', 'Set X: the lower half is 3, 5, 6, 8 with first quartile $(5 + 6) \div 2 = 5.5$. The upper half is 9, 12, 14, 17 with third quartile $(12 + 14) \div 2 = 13$. IQR = $13 - 5.5 = 7.5$. Set Y: the lower half is 10, 11, 12, 13 with first quartile 11.5. The upper half is 14, 15, 16, 17 with third quartile 15.5. IQR = $15.5 - 11.5 = 4$. The difference is $7.5 - 4 = 3.5$.', 'checked', '{"lint":[],"solve":{"answer":"3.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X: lower 3, 5, 6, 8 -> Q1 5.5; upper 9, 12, 14, 17 -> Q3 13; IQR 7.5. Y: lower 10-13 -> 11.5; upper 14-17 -> 15.5; IQR 4. Difference 3.5.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('093da897-6232-4f79-829e-427b8391b539', 'NC26.7.RD.4', 3, 'numeric', 'Compare two data sets using center and spread', 'Plot R has 2 dots at 3, 6 dots at 5 and 2 dots at 7. Plot S has 4 dots at 3, 2 dots at 5 and 4 dots at 7. Both plots have a mean of 5. The MAD of Plot S is how many times the MAD of Plot R?', '[]', '2', '((20+20+20+20+0+0+20+20+20+20)/100)/((20+20+0+0+0+0+0+0+20+20)/100)', 'Plot R: the distances from 5 are 2 (twice), 0 (six times) and 2 (twice), which add to 8, so MAD = 8 / 10 = 0.8. Plot S: 2 (four times), 0 (twice) and 2 (four times), which add to 16, so MAD = 16 / 10 = 1.6. Since 1.6 / 0.8 = 2, the MAD of S is 2 times the MAD of R.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"R: distances 2*2 + 6*0 + 2*2 = 8, MAD 0.8. S: 4*2 + 2*0 + 4*2 = 16, MAD 1.6. 1.6/0.8 = 2.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f953a86-767d-4d42-a7e8-ea5ff5321ee5', 'NC26.7.RD.5', 1, 'choice', 'Compare the IQRs of two groups', 'Group A has an IQR of 6 and Group B has an IQR of 11. Which statement must be true?', '["The middle half of Group A''s values is more spread out than the middle half of Group B''s","The median of Group B is 5 greater than the median of Group A","Group B has 5 more values than Group A","The middle half of Group B''s values is more spread out than the middle half of Group A''s"]', 'The middle half of Group B''s values is more spread out than the middle half of Group A''s', NULL, 'The IQR measures how spread out the middle half of the data is. A larger IQR means more spread, so the middle half of Group B (IQR 11) is more spread out than that of Group A (IQR 6). The IQR says nothing about the medians or the number of values.', 'checked', '{"lint":[],"solve":{"answer":"The middle half of Group B''s values is more spread out than the middle half of Group A''s","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"IQR measures the spread of the middle half; 11>6 so B''s middle half is more spread. Says nothing about count or median.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0031c807-d824-4893-b641-c6c4052acda9', 'NC26.7.RD.5', 1, 'choice', 'Describe the shape of a distribution', 'Test scores: 70, 72, 73, 74, 75, 76, 77, 79, 20. Which statement describes the score of 20?', '["It is the median of the scores","It is an outlier, far below the other scores","It is in the cluster where most scores are","It is the score that occurs most often"]', 'It is an outlier, far below the other scores', NULL, 'Eight of the nine scores are between 70 and 79, forming a cluster. The score of 20 is far from that cluster, so it is an outlier. It is not the median (the median is 74) and it occurs only once.', 'checked', '{"lint":[],"solve":{"answer":"It is an outlier, far below the other scores","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"All other scores are 70-79; 20 is far below them: an outlier. No mode; median is 74.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07496a24-a48d-48e2-8799-942b57797475', 'NC26.7.RD.5', 1, 'choice', 'Reflect on sampling and sample size', 'A student wants to compare the lunch preferences of sixth graders and eighth graders at her school. Which is the best way to choose the students to ask?', '["Choose students at random from each grade''s list","Ask only her friends in each grade","Ask only the students in her own class","Ask the first five students to arrive each morning in each grade"]', 'Choose students at random from each grade''s list', NULL, 'A random sample gives every student in the grade an equal chance of being asked, so it is likely to represent the whole grade. Friends, classmates or early arrivers may all differ from the rest of the grade.', 'checked', '{"lint":[],"solve":{"answer":"Choose students at random from each grade''s list","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A random sample from each grade''s list is representative; the others are convenience samples.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03f80deb-1d6d-4edf-815d-1e3dffed9d6c', 'NC26.7.RD.5', 2, 'choice', 'Describe centre and spread together', 'Group A has a median score of 78 and an IQR of 6. Group B has a median score of 78 and an IQR of 18. Which statement is correct?', '["Group B scored higher, since its IQR is greater","The typical scores are about the same, but A''s scores vary more","The typical scores are about the same, but B''s scores vary more","Group A''s typical score is lower, since its IQR is smaller"]', 'The typical scores are about the same, but B''s scores vary more', NULL, 'The medians are equal, so the typical scores are the same. The IQR measures spread, and B''s IQR is greater, so B''s scores vary more. A greater IQR does not mean a higher score.', 'checked', '{"lint":[],"solve":{"answer":"The typical scores are about the same, but B''s scores vary more","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same medians, so typical scores alike; B''s IQR 18 > 6, so B varies more.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00e7232c-23b6-41b8-a473-5741b644ef08', 'NC26.7.RD.5', 2, 'choice', 'Compare the mean absolute deviations of two groups', 'Group 1 has the values 18, 19, 20, 21, 22. Group 2 has the values 10, 15, 20, 25, 30. Both groups have a mean of 20. Which group has the smaller MAD?', '["Group 2, because its values are closer to the mean on average","Neither, because the groups have the same mean, so their MADs are equal","Group 1, because its values are closer to the mean on average","Group 2, because its data have the greater range"]', 'Group 1, because its values are closer to the mean on average', NULL, 'Group 1 distances from 20: 2, 1, 0, 1, 2, so the MAD is 6 / 5 = 1.2. Group 2 distances from 20: 10, 5, 0, 5, 10, so the MAD is 30 / 5 = 6. Group 1 has the smaller MAD because its values sit closer to the mean. Equal means do not mean equal MADs.', 'checked', '{"lint":[],"solve":{"answer":"Group 1, because its values are closer to the mean on average","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Group 1 deviations 2,1,0,1,2 -> MAD 1.2; Group 2 deviations 10,5,0,5,10 -> MAD 6. Group 1 smaller.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09d10498-2ba1-416f-ae7b-1583d4dfec44', 'NC26.7.RD.5', 2, 'choice', 'Draw a conclusion the data support', 'Maya chose a random sample of 30 sixth graders and a random sample of 30 seventh graders at her school. The sixth graders slept a mean of 9.4 hours a night and the seventh graders slept a mean of 8.6 hours. Which conclusion is best supported?', '["Every seventh grader at the school sleeps less than every sixth grader","Seventh graders at the school probably sleep less than sixth graders on average","All seventh graders in the country sleep exactly 8.6 hours","Growing older makes students need less sleep"]', 'Seventh graders at the school probably sleep less than sixth graders on average', NULL, 'Random samples let us make a careful statement about the whole grades at that school: the seventh graders probably sleep less on average, with some chance variation. The data cannot show that every student differs, cannot describe other schools, and cannot explain why the difference exists.', 'checked', '{"lint":[],"solve":{"answer":"Seventh graders at the school probably sleep less than sixth graders on average","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Random samples of 30 support a tentative inference about the school''s grades; not causation, not the country, not every student.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b19757b-49b9-434b-9731-af397f0f04a5', 'NC26.7.RD.5', 3, 'choice', 'Communicate a comparison in words', 'A student writes: "Team A is better because its mean score is 5 higher." Team A''s MAD is 20 and Team B''s MAD is 3. What should the report add?', '["Nothing more: the means alone show which team is better","That Team A''s scores vary much more than Team B''s, since the MADs are 20 and 3","That Team A is more consistent, since its MAD is larger","That Team B scored more in total, since its MAD is smaller"]', 'That Team A''s scores vary much more than Team B''s, since the MADs are 20 and 3', NULL, 'A comparison of centres alone leaves out how spread out the scores are. Team A''s MAD of 20 is far larger than Team B''s MAD of 3, so A''s scores vary a lot and its mean is not very typical of its games. A larger MAD means less consistent, and the MAD does not tell us anything about total scores.', 'checked', '{"lint":[],"solve":{"answer":"That Team A''s scores vary much more than Team B''s, since the MADs are 20 and 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A difference of 5 is small against A''s MAD of 20; the report should note A''s far greater variability.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('072c6387-2267-4e3b-8a69-378d0438a0af', 'NC26.7.RD.5', 3, 'numeric', 'Compare the variability of two groups with the IQR', 'Two groups of students timed how many minutes they took to finish a puzzle. Group A: 3, 7, 9, 12, 17, 20. Group B: 10, 12, 13, 15, 17, 19. Each list is in order. The quartiles are the medians of the lower half and the upper half of the data. The IQR of Group A is how many times the IQR of Group B?', '[]', '2', '(17-7)/(17-12)', 'Group A: the lower half is 3, 7, 9 so Q1 = 7, and the upper half is 12, 17, 20 so Q3 = 17. The IQR is 17 - 7 = 10. Group B: the lower half is 10, 12, 13 so Q1 = 12, and the upper half is 15, 17, 19 so Q3 = 17. The IQR is 17 - 12 = 5. Then 10 / 5 = 2, so the IQR of Group A is 2 times the IQR of Group B.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Group A (6 values): lower half 3, 7, 9 -> Q1 = 7; upper half 12, 17, 20 -> Q3 = 17; IQR = 10. Group B: lower half 10, 12, 13 -> Q1 = 12; upper half 15, 17, 19 -> Q3 = 17; IQR = 5. Ratio 10 / 5 = 2.","run_id":"claude-code","at":"2026-10-17T18:41:51.098Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('084c344b-7ea5-4dd8-bc0a-7dfe6b9bf52e', 'NC26.8.ANFR.1', 1, 'numeric', 'Find the whole numbers that satisfy an inequality with the variable on both sides', 'What is the greatest whole number $x$ that makes $4x - 5 < x + 7$ true?', '[]', '3', '12/3-1', 'Subtract $x$ from both sides: $3x - 5 < 7$. Add 5: $3x < 12$. Divide by 3: $x < 4$. The greatest whole number less than 4 is 3. Check: for $x = 3$, $4(3) - 5 = 7$ and $3 + 7 = 10$, and $7 < 10$. For $x = 4$ both sides equal 11, so 4 does not work.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x - 5 < x + 7 -> 3x < 12 -> x < 4. Greatest whole number below 4 is 3. Check x=3: 7 < 10 true; x=4: 11 < 11 false.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06583071-f2d6-4107-9231-93bf5262947a', 'NC26.8.ANFR.1', 1, 'numeric', 'Solve an equation that needs the distributive property', 'Solve: $4(x + 1) = 2x + 12$', '[]', '4', '(8)/(2)', 'Simplify each side: $4x + 4 = 2x + 12$. Move the $x$ terms to one side and the numbers to the other: $2x = 8$. Divide both sides by $2$: $x = 4$. Check: with $x = 4$ both sides equal $20$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x + 4 = 2x + 12 -> 2x = 8 -> x = 4. Check: 20 = 20.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('031686c6-8c13-4962-9c3b-c1a77711db45', 'NC26.8.ANFR.1', 1, 'choice', 'Solve an equation that needs the distributive property', 'Which equation is the result of using the distributive property on the left side of $4(2x - 3) = x + 5$?', '["$8x - 3 = x + 5$","$8x + 12 = x + 5$","$8x - 12 = x + 5$","$2x - 12 = x + 5$"]', '$8x - 12 = x + 5$', NULL, 'The 4 multiplies both terms inside the parentheses: $4(2x - 3) = 4 \cdot 2x - 4 \cdot 3 = 8x - 12$. So the equation becomes $8x - 12 = x + 5$. The other choices multiply only one of the terms, change a sign, or multiply the wrong term.', 'checked', '{"lint":[],"solve":{"answer":"$8x - 12 = x + 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(2x - 3) = 8x - 12; right side unchanged.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d8da1cf-3986-4006-9479-e564c0e96021', 'NC26.8.ANFR.1', 2, 'choice', 'Solve an equation that needs the distributive property', 'Which value of $x$ is the solution of $2(3x + 1) = 4(x + 4)$?', '["$\\frac{15}{2}$","$1$","$9$","$7$"]', '$7$', '14/2', 'Simplify each side: $6x + 2 = 4x + 16$. Move the $x$ terms to one side and the numbers to the other: $2x = 14$. Divide both sides by $2$: $x = 7$. Check: with $x = 7$ both sides equal $44$. The wrong choices come from multiplying only some terms: $\frac{15}{2}$ forgets to multiply the 1 by 2, and $1$ forgets to multiply the 4 by 4.', 'checked', '{"lint":[],"solve":{"answer":"$7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x + 2 = 4x + 16 -> 2x = 14 -> x = 7. Check: 44 = 44.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11ffa26c-aecd-4408-919d-6654f58abb11', 'NC26.8.ANFR.1', 2, 'numeric', 'Solve an equation after combining like terms', 'Solve: $5x - 3 + 2x = 4 - x + 17$', '[]', '3', '(24)/(8)', 'Simplify each side: $7x - 3 = -x + 21$. Move the $x$ terms to one side and the numbers to the other: $8x = 24$. Divide both sides by $8$: $x = 3$. Check: with $x = 3$ both sides equal $18$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7x - 3 = 21 - x -> 8x = 24 -> x = 3. Check: 18 = 18.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1546e754-c16b-4c48-8003-498806fc5d80', 'NC26.8.ANFR.1', 2, 'numeric', 'Solve an equation with fraction or decimal coefficients', 'Solve for $x$: $1.5x - 2.4 = 0.3x + 3.6$', '[]', '5', '(6)/(6/5)', 'Move the $x$ terms to one side and the numbers to the other: $1.2x = 6$. Divide both sides by $1.2$: $x = 5$. Check: with $x = 5$ both sides equal $5.1$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.2x = 6 -> x = 5. Check: 5.1 = 5.1.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
