INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14d752f3-c15a-4f04-b710-da21f5b1d7e3', 'NC26.8.ANFR.4', 2, 'choice', 'Compare and order real numbers', 'Which list has $\sqrt{5}$, $2.4$ and $\frac{5}{2}$ in order from least to greatest?', '["$2.4,\\ \\sqrt{5},\\ \\frac{5}{2}$","$\\frac{5}{2},\\ 2.4,\\ \\sqrt{5}$","$\\sqrt{5},\\ \\frac{5}{2},\\ 2.4$","$\\sqrt{5},\\ 2.4,\\ \\frac{5}{2}$"]', '$\sqrt{5},\ 2.4,\ \frac{5}{2}$', NULL, '$\sqrt{5}$ is about $2.24$ (since $2.2^2 = 4.84$), $2.4$ is $2.4$, and $\frac{5}{2} = 2.5$. So the order is $\sqrt{5},\ 2.4,\ \frac{5}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt{5},\\ 2.4,\\ \\frac{5}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(5) about 2.236 (2.2^2 = 4.84, 2.3^2 = 5.29); 2.4; 5/2 = 2.5. Order: sqrt(5), 2.4, 5/2.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03a2954b-c016-48bb-9849-25ab241fcf92', 'NC26.8.ANFR.4', 3, 'numeric', 'Estimate an irrational number to the nearest tenth', 'Which whole number $n$ has a square root closest to 6.7?', '[]', '45', NULL, '$6.7^2 = 44.89$, which is closest to the whole number 45. Check: $\sqrt{45} \approx 6.708$, while $\sqrt{44} \approx 6.633$.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6.7^2 = 44.89. sqrt(45) is about 6.708 (0.008 off); sqrt(44) is about 6.633 (0.067 off). n = 45.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('097855fc-d3f0-4219-b481-599670ae5cec', 'NC26.8.ANFR.4', 3, 'numeric', 'Approximate an expression with pi', 'Use 3.14 for $\pi$. A pizza shop sells a 12-inch pizza and a 16-inch pizza, where each size is the diameter. How many more square inches of pizza are in the larger one?', '[]', '87.92', '3.14*(8^2-6^2)', 'The radii are 6 and 8 inches. The areas are $3.14 \times 6^2 = 113.04$ and $3.14 \times 8^2 = 200.96$ square inches. The difference is $200.96 - 113.04 = 87.92$.', 'checked', '{"lint":[],"solve":{"answer":"87.92","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Radii 6 and 8. Areas 3.14 x 36 = 113.04 and 3.14 x 64 = 200.96. Difference = 87.92 (= 3.14 x 28).","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05add28c-8739-42b7-9eb0-7d77f8edda8b', 'NC26.8.ANFR.5', 1, 'choice', 'Solve x squared equals a positive number', 'Which choice shows all the solutions of $x^2 = 49$?', '["$x = 7$ and $x = -7$","$x = 7$ only","$x = -7$ only","$x = 24.5$"]', '$x = 7$ and $x = -7$', NULL, 'Both $7 \times 7 = 49$ and $(-7) \times (-7) = 49$, so $x = 7$ and $x = -7$ are both solutions.', 'checked', '{"lint":[],"solve":{"answer":"$x = 7$ and $x = -7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7^2 = 49 and (-7)^2 = 49, so x = 7 and x = -7.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09af7667-a9eb-4b06-ab15-4effc55b46dd', 'NC26.8.ANFR.5', 1, 'numeric', 'Multiply powers with the same base', 'If $4^3 \times 4^2 = 4^n$, what is $n$?', '[]', '5', '3+2', 'Add the exponents: $4^3 \times 4^2 = 4^{3+2} = 4^5$, so $n = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4^3 x 4^2 = 4^(3+2) = 4^5, so n = 5.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
