INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e0013c9-49a8-47da-93df-3afeea0fe792', 'NC26.8.ANFR.5', 3, 'numeric', 'Use zero and negative exponents', 'Add $2^{-2} + 2^{-1}$. Write the sum as a fraction.', '[]', '3/4', '2^-2+2^-1', '$2^{-2} = \frac{1}{4}$ and $2^{-1} = \frac{1}{2} = \frac{2}{4}$. The sum is $\frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"3/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^-2 + 2^-1 = 1/4 + 1/2 = 1/4 + 2/4 = 3/4.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
