INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d10ee45-9a58-4fa4-9ff8-1326e6b2e4b8', 'NC26.8.SGMR.1', 1, 'numeric', 'Find a missing value from a transformation', 'The point $(k, 4)$ is reflected across the $y$-axis. Its image is $(-6, 4)$. What is the value of $k$?', '[]', '6', '6', 'A reflection across the $y$-axis changes the sign of the $x$-coordinate. The image has $x = -6$, so the original had $x = 6$. Therefore $k = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(k, 4) -> (-k, 4) = (-6, 4), so k = 6.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
