INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f9cd53d-5754-40e1-a438-9cfe64cf27d1', 'NC26.8.SGMR.1', 2, 'numeric', 'Reflect a point across an axis', 'The point (-6, 5) is reflected across the $y$-axis. How many units apart are the point and its image?', '[]', '12', '6+6', 'The image is (6, 5). Both points are 6 units from the $y$-axis, on opposite sides, so they are $6 + 6 = 12$ units apart.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-6, 5) -> (6, 5). Same y, distance |6 - (-6)| = 12.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
