INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05dc5bf1-fcad-40ff-9d7f-efb9dd34ecb7', 'NC26.8.SGMR.1', 2, 'numeric', 'Reflect a polygon', 'A rectangle has vertices (2, 1), (6, 1), (6, 4) and (2, 4). It is reflected across the $x$-axis. What is the greatest $y$-coordinate among the vertices of the image?', '[]', '-1', '-1', 'The image has vertices (2, -1), (6, -1), (6, -4), (2, -4). The $y$-coordinates are -1, -1, -4, -4, and the greatest is -1.', 'checked', '{"lint":[],"solve":{"answer":"-1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Across x-axis, negate y: y-values 1 and 4 become -1 and -4. Greatest is -1.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
