INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('034d3e13-f524-48b2-8768-6b6278b026fc', 'NC26.8.SGMR.1', 3, 'choice', 'Work backwards from the image', 'A point is rotated $90^\circ$ clockwise about the origin and then moved 3 units down. It ends at (-2, -5). What was the original point?', '["(-2, 2)","(5, -2)","(8, -2)","(2, -2)"]', '(2, -2)', NULL, 'Undo the move: up 3 from (-2, -5) gives (-2, -2). That is the point after rotating, so rotate back $90^\circ$ counterclockwise with $(x, y) \to (-y, x)$: (2, -2). Check: rotating (2, -2) clockwise gives (-2, -2), and moving 3 down gives (-2, -5).', 'checked', '{"lint":[],"solve":{"answer":"(2, -2)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Undo 3 down: (-2, -2). CW (y, -x) = (-2, -2): y = -2, x = 2. Original (2, -2). Check: (2,-2) -> (-2,-2) -> (-2,-5).","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07f40c14-d6fe-47e2-8244-7f458fab3efd', 'NC26.8.SGMR.1', 3, 'numeric', 'Find a missing value from a transformation', 'A translation follows the rule $(x, y) \to (x + a, y - 2a)$. It moves the point (3, 5) to the point (7, -3). What is the value of $a$?', '[]', '4', '7-3', 'Look at the $x$-coordinate: $3 + a = 7$, so $a = 4$. Check the $y$-coordinate: $5 - 2(4) = -3$. It matches.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 + a = 7 gives a = 4; check 5 - 2(4) = -3. a = 4.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c191b56-ab12-4a5d-9540-ae986dd5c12d', 'NC26.8.SGMR.2', 1, 'choice', 'What a dilation keeps and what it changes', 'Sides AB and DC of a quadrilateral are parallel. The quadrilateral is dilated with a scale factor of 3. Which statement about the image sides A''B'' and D''C'' is true?', '["A''B'' and D''C'' are perpendicular.","A''B'' and D''C'' meet at a point.","A''B'' and D''C'' are parallel only if the scale factor is 1.","A''B'' and D''C'' are parallel."]', 'A''B'' and D''C'' are parallel.', NULL, 'A dilation keeps angles, so parallel lines stay parallel, whatever the scale factor is.', 'checked', '{"lint":[],"solve":{"answer":"A''B'' and D''C'' are parallel.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dilations take lines to parallel lines, so parallel sides stay parallel for any scale factor.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1815797a-ce41-4911-865f-f8f47fa83f71', 'NC26.8.SGMR.2', 1, 'numeric', 'Find an unknown side using the scale factor', 'One side of a triangle is 6 cm long. The triangle is dilated with a scale factor of 5. How long is the matching side of the image, in centimeters?', '[]', '30', '6*5', 'Multiply by the scale factor: $6 \times 5 = 30$ cm.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 * 5 = 30.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
