INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a6ba20b-9226-4945-a6ae-407f1e724f99', 'NC26.8.SGMR.2', 2, 'choice', 'Dilate twice in a row', 'The point (2, 3) is dilated about the origin with a scale factor of 2. The image is then dilated about the origin with a scale factor of 3. What is the $x$-coordinate of the final image?', '["7","6","12","10"]', '12', '2*2*3', 'After the first dilation: $(4, 6)$. After the second: $(12, 18)$. The $x$-coordinate is 12. (The two factors multiply: $2 \times 3 = 6$, and $2 \times 6 = 12$.)', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2,3) -> (4,6) -> (12,18). x = 12.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
