INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('069a417e-cdda-4003-bad9-30a2de92976c', 'NC26.K.RD.2', 3, 'numeric', 'Compare the categories of a graph', 'A picture graph shows the pets children have. Each picture stands for 1 child. Dogs: 7. Cats: 2. Fish: 5. Birds: 3. How many kinds of pet have more than 4 pictures?', '[]', '2', NULL, 'Look at each kind of pet. Dogs have 7, which is more than 4. Fish have 5, which is more than 4. Cats have 2 and birds have 3, which are not more than 4. Two kinds of pet have more than 4 pictures, so the answer is $2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Kinds with more than 4 pictures: Dogs 7 (yes), Cats 2 (no), Fish 5 (yes), Birds 3 (no). That is 2 kinds.","run_id":"claude-code","at":"2026-10-22T19:25:06.955Z"}}', 'ai', NULL, NULL)
