INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('088db34d-f96b-440b-8b0e-7cc433092145', 'NC26.M1.RMM.1', 1, 'choice', 'Build a model from a situation or data', 'A pottery studio charges 30 dollars to register plus 12 dollars for each class. Which equation gives the total cost $C$ after $n$ classes?', '["$C = 12 + 30n$","$C = 42n$","$C = 30 + 12n$","$C = 30n + 12$"]', '$C = 30 + 12n$', NULL, 'The 30 dollar registration is paid once. The 12 dollar fee is paid for each of the $n$ classes, so the total is $30 + 12n$.', 'checked', '{"lint":[],"solve":{"answer":"$C = 30 + 12n$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fixed 30 plus 12 per class: C = 30 + 12n.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05edecb1-7dbd-4862-872b-6542b614e545', 'NC26.M1.RMM.1', 1, 'choice', 'Choose the model that fits the data', 'At $x = 0, 1, 2, 3$ the values of $y$ are 5, 7, 9, 11. Which model fits all four values?', '["$y = 5 \\times 2^x$","$y = 5x + 2$","$y = 5 + 2x$","$y = 7x - 2$"]', '$y = 5 + 2x$', NULL, 'The value goes up by 2 each time, starting at 5, so $y = 5 + 2x$. Check $x = 3$: $5 + 6 = 11$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 5 + 2x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Start 5, +2 each step: y = 5 + 2x. Check 5x+2: 2 at x=0 no; 7x-2: -2 no; 5*2^x: 5,10 no.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('30eacbca-0b1d-4a41-86a1-c5d741dead98', 'NC26.M1.RMM.1', 2, 'choice', 'Identify the assumptions of a model', 'A model for a trip says the time is $t = \frac{d}{50}$ hours for a distance of $d$ miles. Which real-world factor does this model ignore?', '["The total length of the trip in miles, which the model uses","The assumed speed of 50 miles per hour on the whole trip","Traffic and stops that slow the average speed","The units of the distance"]', 'Traffic and stops that slow the average speed', NULL, 'The model assumes a steady 50 miles per hour, so it ignores anything that changes the speed, such as traffic and stops.', 'checked', '{"lint":[],"solve":{"answer":"Traffic and stops that slow the average speed","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d/50 assumes constant 50 mph; ignores traffic and stops. Other options are things the model uses.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d6d0e58-48a7-496d-9a7b-75169ea52785', 'NC26.M1.RMM.1', 2, 'numeric', 'Explain what a model''s parts mean', 'In the model $N = 250(1.06)^t$, $N$ is the number of members after $t$ years. By what percent does the membership grow each year?', '[]', '6', '6', 'The factor 1.06 means 100% of last year plus 6% more, so the membership grows 6% each year.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.06 -> 6% growth.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f2592f1-b82b-4b1b-b27d-19445d487411', 'NC26.M1.RMM.1', 2, 'choice', 'Choose the model that fits the data', 'At $x = 0, 1, 2, 3$ the values of $y$ are 0, 5, 8, 9. Which model fits all four values?', '["$y = 5x$","$y = x^2 + 4x$","$y = 5 \\times 2^x - 5$","$y = -x^2 + 6x$"]', '$y = -x^2 + 6x$', NULL, 'The differences 5, 3, 1 drop by 2 each time, which suggests a quadratic with $-x^2$. Check: $-1 + 6 = 5$, $-4 + 12 = 8$, $-9 + 18 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"$y = -x^2 + 6x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-x^2 + 6x: 0, 5, 8, 9. Check x^2+4x: 12 at x=2; 5x: 10; 5*2^x - 5: 15.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a0c1101-26e0-45c7-ba83-21d1c12751f8', 'NC26.M1.RMM.1', 3, 'numeric', 'Build a model from a situation or data', 'A kayak rental costs 22 dollars for 2 hours and 34 dollars for 4 hours, and the cost is linear in the number of hours. What would 7 hours cost, in dollars?', '[]', '52', '22+6*(7-2)', 'The cost rises $34 - 22 = 12$ dollars for 2 extra hours, so 6 dollars per hour. From 2 to 7 hours is 5 more hours: $22 + 6 \times 5 = 52$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"52","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope (34 - 22)/2 = 6; intercept 22 - 12 = 10; 10 + 6(7) = 52.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b462674-f0d3-4937-b59a-f2b2a6de9395', 'NC26.M1.RMM.1', 3, 'numeric', 'Analyse a model to predict or solve', 'Pool A holds 400 liters and fills at 30 liters a minute. Pool B holds 700 liters and drains at 20 liters a minute. After how many minutes do the two pools hold the same amount?', '[]', '6', '(700-400)/(30+20)', 'Set $400 + 30m = 700 - 20m$. Then $50m = 300$, so $m = 6$. Both pools then hold 580 liters.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"400 + 30t = 700 - 20t -> 50t = 300 -> t = 6 (both 580).","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fe2c67b-3982-455a-a975-adb67cae1792', 'NC26.M1.ANFR.1', 1, 'choice', 'Multiply powers with the same base', 'Simplify $x^3 \cdot x^4$.', '["$x^7$","$x^{12}$","$2x^7$","$x^{-1}$"]', '$x^7$', NULL, 'When you multiply powers with the same base, add the exponents: $x^3 \cdot x^4 = x^{3+4} = x^7$.', 'checked', '{"lint":[],"solve":{"answer":"$x^7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same base, add exponents: x^(3+4) = x^7.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07ae5de0-31ef-49f0-af8b-71093c795f26', 'NC26.M1.ANFR.1', 1, 'choice', 'Add polynomials', 'Add: $(2x + 5) + (4x + 3)$.', '["$6x + 8$","$6x^{2} + 8$","$6x + 15$","$14x$"]', '$6x + 8$', NULL, 'Add the $x$ terms: $2x + 4x = 6x$. Add the constants: $5 + 3 = 8$. The sum is $6x + 8$. The $x$ terms and the constants are different kinds of terms, so they stay separate.', 'checked', '{"lint":[],"solve":{"answer":"$6x + 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2x + 4x) + (5 + 3) = 6x + 8.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c3106cd-e717-455b-882d-6ef6a1475f84', 'NC26.M1.ANFR.1', 1, 'numeric', 'Rewrite an expression in an equivalent form', 'The expression $5(x + 2) - 3x$ is equivalent to $2x + k$. What is $k$?', '[]', '10', '5*2', 'Distribute the 5: $5x + 10 - 3x$. Combine the $x$ terms: $5x - 3x = 2x$. So the expression is $2x + 10$ and $k = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x + 10 - 3x = 2x + 10, k = 10.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('013027b5-a920-4892-b9d9-aea9aa5a9756', 'NC26.M1.ANFR.1', 2, 'choice', 'Raise a product or quotient to a power', 'Simplify $(-2a^{3}b^{2})^{4}$.', '["$-8a^{12}b^{8}$","$16a^{7}b^{6}$","$16a^{12}b^{8}$","$-16a^{12}b^{8}$"]', '$16a^{12}b^{8}$', NULL, 'Raise each factor to the 4th power. $(-2)^{4} = 16$, because an even power of a negative number is positive. $(a^{3})^{4} = a^{12}$ and $(b^{2})^{4} = b^{8}$. The result is $16a^{12}b^{8}$.', 'checked', '{"lint":[],"solve":{"answer":"$16a^{12}b^{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-2)^4 = 16; (a^3)^4 = a^12; (b^2)^4 = b^8. Result 16a^12b^8 (even power makes it positive).","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('13c6fd86-287d-4e36-aaf7-c52e4a2e2163', 'NC26.M1.ANFR.1', 2, 'choice', 'Multiply a monomial by a polynomial', 'Multiply: $-2x(3x^{2} - 4x + 5)$.', '["$-6x^{3} - 8x^{2} - 10x$","$-6x^{3} + 8x^{2} - 10x$","$-6x^{2} + 8x - 10$","$-6x^{3} + 8x^{2} - 10$"]', '$-6x^{3} + 8x^{2} - 10x$', NULL, 'Multiply $-2x$ by each term: $-2x \cdot 3x^{2} = -6x^{3}$; $-2x \cdot (-4x) = 8x^{2}$; $-2x \cdot 5 = -10x$. The result is $-6x^{3} + 8x^{2} - 10x$.', 'checked', '{"lint":[],"solve":{"answer":"$-6x^{3} + 8x^{2} - 10x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2x*3x^2 = -6x^3; -2x*(-4x) = 8x^2; -2x*5 = -10x. Result -6x^3 + 8x^2 - 10x.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2affa04e-cec5-4796-93e1-eaa4fab6f75c', 'NC26.M1.ANFR.1', 2, 'choice', 'Multiply a binomial by a trinomial, or three factors', 'Multiply: $(x + 2)(x^{2} - 3x + 1)$.', '["$x^{3} - x^{2} - 5x + 2$","$x^{3} - 5x^{2} - 5x + 2$","$x^{3} - x^{2} - 5x - 2$","$x^{3} - x^{2} - 6x + 2$"]', '$x^{3} - x^{2} - 5x + 2$', NULL, 'Multiply every term of the trinomial by $x$: $x^{3} - 3x^{2} + x$. Then by 2: $2x^{2} - 6x + 2$. Add and combine like terms: $x^{3} + (-3x^{2} + 2x^{2}) + (x - 6x) + 2 = x^{3} - x^{2} - 5x + 2$.', 'checked', '{"lint":[],"solve":{"answer":"$x^{3} - x^{2} - 5x + 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x(x^2 - 3x + 1) = x^3 - 3x^2 + x; 2(x^2 - 3x + 1) = 2x^2 - 6x + 2. Sum x^3 - x^2 - 5x + 2.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03ef80c7-1c1e-4e07-b2d1-2322bd2ccd20', 'NC26.M1.ANFR.1', 3, 'numeric', 'Combine several exponent properties', 'Find $n$ so that $\frac{x^{n} \cdot x^{-3}}{x^{2}} = x^{4}$ for every nonzero $x$.', '[]', '9', '4+2+3', 'The exponent on the left is $n + (-3) - 2 = n - 5$. Set it equal to 4: $n - 5 = 4$, so $n = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^(n-3-2) = x^4, so n - 5 = 4, n = 9.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00644427-499a-401f-8cdd-065d6f930bd1', 'NC26.M1.ANFR.1', 3, 'choice', 'Multiply a binomial by a trinomial, or three factors', 'Which expression is equal to $(x + 1)(x + 2)(x + 3)$?', '["$x^{3} + 3x^{2} + 2x + 6$","$x^{3} + 6x^{2} + 6x + 6$","$x^{3} + 6x^{2} + 11x$","$x^{3} + 6x^{2} + 11x + 6$"]', '$x^{3} + 6x^{2} + 11x + 6$', NULL, 'First multiply two of them: $(x + 1)(x + 2) = x^{2} + 3x + 2$. Then multiply by $(x + 3)$: $x^{3} + 3x^{2} + 3x^{2} + 9x + 2x + 6 = x^{3} + 6x^{2} + 11x + 6$.', 'checked', '{"lint":[],"solve":{"answer":"$x^{3} + 6x^{2} + 11x + 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x + 1)(x + 2) = x^2 + 3x + 2; times (x + 3): x^3 + 3x^2 + 2x + 3x^2 + 9x + 6 = x^3 + 6x^2 + 11x + 6.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02448768-30a8-4196-844c-33a48ee12f62', 'NC26.M1.ANFR.2', 1, 'choice', 'Tell linear from exponential in a table', 'The values of $y$ are 1, 3, 9, 27 when $x$ is 0, 1, 2, 3. How should this relationship be described?', '["Linear, because $y$ increases by 2 each time","Linear, because $y$ keeps increasing","Exponential, because $y$ increases by 3 each time","Exponential, because $y$ is multiplied by 3 each time"]', 'Exponential, because $y$ is multiplied by 3 each time', NULL, '$3 \div 1 = 3$, $9 \div 3 = 3$ and $27 \div 9 = 3$, so $y$ is multiplied by 3 each time. The differences are 2, 6, 18, which are not equal. A constant multiplier means the relationship is exponential.', 'checked', '{"lint":[],"solve":{"answer":"Exponential, because $y$ is multiplied by 3 each time","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1*3=3, 3*3=9, 9*3=27: constant ratio 3, so exponential because y is multiplied by 3 each time. Differences 2,6,18 are not constant, so not linear.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03826c3b-f3f8-40ff-81fc-de13e78aa52c', 'NC26.M1.ANFR.2', 1, 'choice', 'Geometric sequences: ratio, terms and formulas', 'What is the common ratio of the geometric sequence 80, 40, 20, 10, ...?', '["2","-40","0.5","0.25"]', '0.5', '40/80', 'Divide a term by the one before it: $40 \div 80 = 0.5$. Check: $20 \div 40 = 0.5$ and $10 \div 20 = 0.5$. The value 2 is the ratio read backwards, and $-40$ is the change from the first term to the second, not a ratio.', 'checked', '{"lint":[],"solve":{"answer":"0.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40/80=0.5, 20/40=0.5, 10/20=0.5. Common ratio 0.5.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('073b1e76-f497-461c-96c7-aaf4157b4479', 'NC26.M1.ANFR.2', 1, 'choice', 'Compare linear and exponential growth', 'Two savings plans each start with 2 dollars. Plan L adds 3 dollars each week. Plan E triples its amount each week. After 2 weeks, how do the plans compare?', '["Plan E has 10 dollars more than Plan L","Plan E has 4 dollars more than Plan L","Plan L has 2 dollars more than Plan E","Plan E has 28 dollars more than Plan L"]', 'Plan E has 10 dollars more than Plan L', NULL, 'Plan L: $2 \to 5 \to 8$, so 8 dollars. Plan E: $2 \to 6 \to 18$, so 18 dollars. Plan E has $18 - 8 = 10$ dollars more.', 'checked', '{"lint":[],"solve":{"answer":"Plan E has 10 dollars more than Plan L","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Plan L: 2 -> 5 -> 8 dollars after 2 weeks. Plan E: 2 -> 6 -> 18 dollars. 18-8=10, Plan E has 10 dollars more.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1189bdc5-335b-42d6-bc6f-f00d84d17d3e', 'NC26.M1.ANFR.2', 2, 'numeric', 'Tell linear from exponential in a table', 'The relationship between $x$ and $y$ is linear. When $x$ is 0, 5, 10 and 15, $y$ is 2, 12, 22 and 32. By how much does $y$ change each time $x$ increases by 1?', '[]', '2', '(12-2)/5', 'When $x$ goes up by 5, $y$ goes up by $12 - 2 = 10$. So for each increase of 1 in $x$, $y$ goes up by $10 \div 5 = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y rises by 10 for each increase of 5 in x (12-2, 22-12, 32-22). Rate = 10/5 = 2 per unit of x.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('014a36ac-062b-42ec-bc95-9fa66f18033e', 'NC26.M1.ANFR.2', 2, 'numeric', 'Arithmetic sequences: difference, terms and formulas', 'What is the 20th term of the arithmetic sequence 5, 8, 11, 14, ...?', '[]', '62', '5+19*3', 'The common difference is 3. The 20th term is the first term plus 19 differences: $5 + 19 \times 3 = 5 + 57 = 62$.', 'checked', '{"lint":[],"solve":{"answer":"62","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a1=5, d=3. a20 = 5 + 19*3 = 5 + 57 = 62.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('052f0569-3754-4e24-800f-c421856d1213', 'NC26.M1.ANFR.2', 2, 'numeric', 'Compare linear and exponential growth', 'Account A starts with 200 dollars and adds 25 dollars each year. Account B starts with 200 dollars and is multiplied by 1.1 each year. After 2 years, how many more dollars does Account A hold than Account B?', '[]', '8', '200+2*25-200*1.1^2', 'Account A: $200 + 2 \times 25 = 250$ dollars. Account B: $200 \times 1.1 \times 1.1 = 242$ dollars. Account A holds $250 - 242 = 8$ dollars more.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 200 + 2*25 = 250. B: 200*1.1^2 = 200*1.21 = 242. 250 - 242 = 8.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('050ceb24-0c2e-48c4-a584-d45d2bbd49b5', 'NC26.M1.ANFR.2', 3, 'choice', 'Tell linear from exponential in a situation or equation', 'Which situation is modeled by an exponential function?', '["The number of cases in an outbreak is 20% greater each day than the day before","A subscription costs 9 dollars the first month and 2 dollars more each month than the month before","A rope is shortened by 3 feet each time a piece is cut off","A pool is filled at 40 gallons per minute"]', 'The number of cases in an outbreak is 20% greater each day than the day before', NULL, 'Each day the number of cases is multiplied by 1.2, which is exponential. The subscription adds 2 dollars each month, the rope loses 3 feet each time, and the pool gains 40 gallons each minute; these all change by a fixed amount, so they are linear.', 'checked', '{"lint":[],"solve":{"answer":"The number of cases in an outbreak is 20% greater each day than the day before","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cases 20% greater each day: multiply by 1.2 daily -> exponential. Subscription +2 each month, rope -3 feet each cut, pool 40 gal/min: constant differences -> linear.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('045d65f3-bc87-400c-af20-f6e1f4cdf20b', 'NC26.M1.ANFR.2', 3, 'choice', 'Geometric sequences: ratio, terms and formulas', 'Which sequence is geometric with common ratio $-\frac{1}{2}$?', '["48, 24, 12, 6","-6, 12, -24, 48","48, 24, 0, -24","48, -24, 12, -6"]', '48, -24, 12, -6', NULL, 'Multiply by $-\frac{1}{2}$ each time: $48 \times \left(-\frac{1}{2}\right) = -24$, then $12$, then $-6$. The list 48, 24, 12, 6 has ratio $\frac{1}{2}$, the list $-6$, 12, $-24$, 48 has ratio $-2$, and the last list is arithmetic.', 'checked', '{"lint":[],"solve":{"answer":"48, -24, 12, -6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"48, -24, 12, -6: -24/48 = -1/2, 12/-24 = -1/2, -6/12 = -1/2. Correct. -6,12,-24,48 has ratio -2; 48,24,12,6 ratio 1/2; 48,24,0,-24 is arithmetic.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35814cec-22d2-423f-b410-0dea192baf73', 'NC26.M1.ANFR.3', 1, 'choice', 'Tell growth from decay', 'Which statement describes $f(x) = 5(0.8)^x$?', '["Exponential decay","Exponential growth","Linear increase","Linear decrease"]', 'Exponential decay', NULL, 'The variable is in the exponent, so the function is exponential. The base 0.8 is less than 1, so each step multiplies the value by 0.8 and it gets smaller: decay.', 'checked', '{"lint":[],"solve":{"answer":"Exponential decay","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Form a(b)^x with a = 5 > 0 and 0 < b = 0.8 < 1 -> exponential decay.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3005d5dd-176f-4f81-9e33-e77fcb5c58e3', 'NC26.M1.ANFR.3', 1, 'numeric', 'Find the domain of a function', 'A function has these input-output pairs: $(2, 7)$, $(4, 11)$, $(6, 15)$ and $(8, 19)$. What is the sum of the numbers in its domain?', '[]', '20', '2+4+6+8', 'The domain is the set of inputs, the first numbers of the pairs: 2, 4, 6 and 8. Their sum is $2 + 4 + 6 + 8 = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Domain = inputs {2, 4, 6, 8}; sum = 20.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0292716b-7546-4705-b2af-40c492b8c660', 'NC26.M1.ANFR.3', 1, 'choice', 'Find the domain of a function', 'The function $T(h) = 12h$ gives the pay, in dollars, for working $h$ hours, where $h$ can be any number from 0 to 8. Which number is NOT in the domain?', '["$0$","$3.5$","$8$","$-2$"]', '$-2$', NULL, 'The domain is the numbers from 0 to 8, including 0 and 8. The numbers 0, 3.5 and 8 are all in it. The number $-2$ is less than 0, so it is not.', 'checked', '{"lint":[],"solve":{"answer":"$-2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Domain is 0 <= h <= 8. 3.5, 0 and 8 are in it; -2 is not.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1340d717-16a0-42d9-8467-a6288724dcda', 'NC26.M1.ANFR.3', 2, 'numeric', 'Find an average rate of change', 'For a function $f$, $f(2) = 7$ and $f(6) = 19$. What is the average rate of change of $f$ from $x = 2$ to $x = 6$?', '[]', '3', '(19-7)/(6-2)', 'Average rate of change is the change in output divided by the change in input: $\frac{19 - 7}{6 - 2} = \frac{12}{4} = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(19 - 7)/(6 - 2) = 12/4 = 3.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('090f8a27-faa0-4983-8d2b-dbcc9c83a235', 'NC26.M1.ANFR.3', 2, 'choice', 'Decide whether a function is discrete or continuous', 'The function $f(n) = 25n$ gives the cost of $n$ tickets to a show. Which statement is true?', '["It is continuous, because the cost goes up by the same amount each time","It is discrete, because only whole numbers of tickets can be bought","It is continuous, because $n$ can be any real number","It is continuous, because its graph follows a straight line"]', 'It is discrete, because only whole numbers of tickets can be bought', NULL, 'The inputs are numbers of tickets, which are whole numbers: 0, 1, 2, and so on. Its graph is separate points, so the function is discrete.', 'checked', '{"lint":[],"solve":{"answer":"It is discrete, because only whole numbers of tickets can be bought","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tickets are bought in whole numbers, so n is 0, 1, 2, ... -> discrete. A straight-line pattern or constant increase does not make it continuous.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('024e36c0-e18a-49c4-8da7-faee8819b887', 'NC26.M1.ANFR.3', 2, 'choice', 'Decide whether a function is discrete or continuous', 'A scientist counts a bacteria colony only at the end of each whole hour. The count is $N(h) = 20(3)^h$ for $h = 0, 1, 2, \dots$ Which statement is true?', '["The function is discrete, because it is defined only at whole numbers of hours","The function is continuous, because every exponential function is continuous","The function is continuous, because time is always continuous","The function is continuous, because a colony grows all the time"]', 'The function is discrete, because it is defined only at whole numbers of hours', NULL, 'This function has inputs only at $h = 0, 1, 2, \dots$, so its graph is separate points. A function defined only at whole-number inputs is discrete, even though it comes from an exponential rule.', 'checked', '{"lint":[],"solve":{"answer":"The function is discrete, because it is defined only at whole numbers of hours","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The function is defined only at h = 0, 1, 2, ... (whole hours), so it is discrete even though the colony itself grows continuously.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04b8b277-7334-4320-a8d2-3e381acbd349', 'NC26.M1.ANFR.3', 3, 'choice', 'Decide whether a function is discrete or continuous', 'Which function has a graph made of separate points?', '["$d(t) = 4t$, the distance walked at any time $t$ from 0 to 2 hours","$W(n) = 3n$, the number of wheels on $n$ tricycles","$C(p) = 3p$, the cost of $p$ pounds of grapes, for any weight from 0 to 10 pounds","$h(t) = 2 + 5t$, the height of a plant at any time $t$ over 4 weeks"]', '$W(n) = 3n$, the number of wheels on $n$ tricycles', NULL, 'The number of tricycles must be a whole number, so $W$ has only separate inputs and its graph is separate points. Time, weight and plant height can take any value in a range, so the other three graphs are solid lines.', 'checked', '{"lint":[],"solve":{"answer":"$W(n) = 3n$, the number of wheels on $n$ tricycles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Number of tricycles n must be a whole number -> separate points. Walking time, weight of grapes and plant-growth time can be any value in an interval -> continuous.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('066592c1-cdb0-4a41-b210-c58baa38f80a', 'NC26.M1.ANFR.3', 3, 'numeric', 'Compare two functions', 'Function $f$ is linear with $f(0) = 5$ and $f(1) = 8$. Function $g$ is $g(x) = 2(3)^x$. How much greater is $g(3)$ than $f(3)$?', '[]', '40', '2*3^3-(5+3*3)', 'The rate of $f$ is $8 - 5 = 3$, so $f(3) = 5 + 3 \times 3 = 14$. Also $g(3) = 2 \times 3^3 = 54$. The difference is $54 - 14 = 40$.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(x) = 3x + 5, f(3) = 14. g(3) = 2 * 27 = 54. 54 - 14 = 40.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0091a8d7-2a8c-4886-8a41-afd9f643ddf1', 'NC26.M1.ANFR.4', 1, 'numeric', 'Write a linear function from a situation', 'A phone plan costs 15 dollars per month plus 0.10 dollars for each text. The monthly cost is a linear function of the number of texts. What is the cost, in dollars, for a month with 80 texts?', '[]', '23', '15+0.1*80', 'Texts cost $0.10 \cdot 80 = 8$ dollars. The total is $15 + 8 = 23$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"23","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 + 0.10*80 = 15 + 8 = 23.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1efec3df-2e4e-48d2-a76b-252a41a2eaff', 'NC26.M1.ANFR.4', 1, 'choice', 'Write and use an exponential function from a situation', 'A colony of insects has 5 members at the start and doubles in size every day. Which function gives the number $P$ of insects after $d$ days?', '["$P(d) = 2 \\cdot 5^d$","$P(d) = 5 \\cdot d^2$","$P(d) = 5 \\cdot 2^d$","$P(d) = 5d + 2$"]', '$P(d) = 5 \cdot 2^d$', NULL, 'The starting amount is 5 and it is multiplied by 2 each day: $P(d) = 5 \cdot 2^d$.', 'checked', '{"lint":[],"solve":{"answer":"$P(d) = 5 \\cdot 2^d$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Start 5, doubling daily: P(d) = 5*2^d.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0488ca01-d54e-4fce-a479-771b5074668a', 'NC26.M1.ANFR.4', 1, 'numeric', 'Write and use an explicit rule for a sequence', 'A geometric sequence has first term 5 and common ratio 3. What is the fourth term?', '[]', '135', '5*3^3', 'The fourth term is $5 \cdot 3^3 = 5 \cdot 27 = 135$.', 'checked', '{"lint":[],"solve":{"answer":"135","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5*3^3 = 135.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
