INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0372fb5b-7398-42d6-9b73-9303f404a7a7', 'NC26.M1.ANFR.4', 2, 'numeric', 'Write and use an exponential function from a situation', 'A new phone is worth 800 dollars and loses half of its value each year. How many dollars is it worth after 3 years?', '[]', '100', '800/2^3', 'Halve three times: 800, 400, 200, 100. After 3 years it is worth 100 dollars.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"800 -> 400 -> 200 -> 100 after 3 years.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
