INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07b371d7-aa28-485a-a395-239e82a4428a', 'NC26.M1.ANFR.4', 2, 'choice', 'Write a line in slope-intercept form', 'A line has slope 2 and passes through the point $(1, 4)$. Which is its equation?', '["$y = 2x + 4$","$y = 2x + 3$","$y = 2x + 2$","$y = 2x + 6$"]', '$y = 2x + 2$', NULL, 'Put $m = 2$, $x = 1$, $y = 4$ into $y = mx + b$: $4 = 2 + b$, so $b = 2$ and $y = 2x + 2$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 2x + 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 = 2*1 + b, b = 2. y = 2x + 2.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('195f395b-ae54-4815-a2db-36708e5cbbc3', 'NC26.M1.ANFR.4', 2, 'numeric', 'Write a line in slope-intercept form', 'A line passes through the points $(-1, 7)$ and $(2, -2)$. What is its slope?', '[]', '-3', '(-2-7)/(2-(-1))', 'Slope $= \frac{-2 - 7}{2 - (-1)} = \frac{-9}{3} = -3$.', 'checked', '{"lint":[],"solve":{"answer":"-3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-2 - 7)/(2 - (-1)) = -9/3 = -3.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01088cb5-dc3a-4c36-9b83-cecc124ec8ab', 'NC26.M1.ANFR.4', 3, 'choice', 'Choose the function that models a table of values', 'A table gives $y$ for $x = 0, 1, 2, 3$: the values of $y$ are 5, 15, 45, 135. Which function fits all four values?', '["$y = 5(3)^x$","$y = 5 + 10x$","$y = 3(5)^x$","$y = 15(3)^x$"]', '$y = 5(3)^x$', NULL, 'Each value is 3 times the one before, and $y = 5$ when $x = 0$, so $y = 5(3)^x$. The linear rule $5 + 10x$ gives 25 at $x = 2$, not 45. $15(3)^x$ gives 15 at $x = 0$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 5(3)^x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Start 5 at x = 0, ratio 3: y = 5(3)^x gives 5, 15, 45, 135. 5 + 10x gives 25 at x = 2; 15(3)^x gives 15 at x = 0; 3(5)^x gives 3 at x = 0.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('004aec33-35dd-4056-9c83-6f618c3b2c61', 'NC26.M1.ANFR.4', 3, 'choice', 'Write a linear function from a situation', 'Water drains from a tank at a constant rate. After 3 minutes the tank holds 90 liters, and after 5 minutes it holds 70 liters. Which function gives the liters $V$ in the tank after $t$ minutes?', '["$V(t) = 90 - 10t$","$V(t) = 120 + 10t$","$V(t) = 90 - 20t$","$V(t) = 120 - 10t$"]', '$V(t) = 120 - 10t$', NULL, 'The tank loses $90 - 70 = 20$ liters in 2 minutes, which is 10 liters per minute. Going back 3 minutes from $t = 3$ gives $90 + 30 = 120$ liters at the start. So $V(t) = 120 - 10t$.', 'checked', '{"lint":[],"solve":{"answer":"$V(t) = 120 - 10t$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rate (70-90)/(5-3) = -10 L/min. V(3) = 90 so V(0) = 90 + 30 = 120. V(t) = 120 - 10t. Check V(5) = 70.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
