INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d7b165a-e002-472b-91ea-4b4c63db7137', 'NC26.M1.ANFR.7', 2, 'numeric', 'Solve a system by substitution', 'A system has the equations $2x + y = 11$ and $y = x - 1$. What is $x$?', '[]', '4', '(11+1)/3', 'Replace $y$ by $x - 1$: $2x + x - 1 = 11$, so $3x = 12$ and $x = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x + x - 1 = 11, 3x = 12, x = 4.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('093d6dd5-938b-4bf0-a201-2ff1705a938d', 'NC26.M1.ANFR.7', 2, 'numeric', 'Solve a system from a situation', 'Club 1 charges 10 dollars to join and 4 dollars per movie. Club 2 charges 22 dollars to join and 1 dollar per movie. After how many movies do the two clubs cost the same in total?', '[]', '4', '(22-10)/(4-1)', 'The costs are $10 + 4m$ and $22 + m$. Setting them equal: $3m = 12$, so $m = 4$ movies (both cost 26 dollars).', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10+4m = 22+m, m = 4.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
