INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e66db08-a779-4c90-a922-71e5c1d92421', 'NC26.M1.ANFR.7', 3, 'numeric', 'Solve a system by substitution', 'Solve the system $x = 4y - 5$ and $2x + 3y = 23$. What is $x + y$?', '[]', '10', '4*3-5+3', 'Replace $x$ by $4y - 5$: $2(4y - 5) + 3y = 23$, so $11y - 10 = 23$ and $y = 3$. Then $x = 4(3) - 5 = 7$, and $x + y = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(4y-5)+3y=23, 11y=33, y=3, x=7, sum 10.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1351f39c-a5f0-4865-868b-ce2faaf62950', 'NC26.M1.ANFR.7', 3, 'numeric', 'Count the solutions of a system', 'One line passes through $(0, 1)$ and $(1, 3)$. Another line passes through $(0, 4)$ and $(1, 6)$. How many points do the two lines have in common?', '[]', '0', NULL, 'Both lines rise 2 for every 1 across, so they have the same slope 2. Their $y$-intercepts, 1 and 4, differ, so the lines are parallel and share no point.', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both slope 2, intercepts 1 and 4: parallel, no common points.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('103dfb4b-68a5-4319-a2f9-485ba1406fb4', 'NC26.M1.SGMR.1', 1, 'choice', 'Image of a point under a reflection', 'What is the image of the point $(5, 2)$ when it is reflected across the x-axis?', '["$(-5, 2)$","$(-5, -2)$","$(5, -2)$","$(2, 5)$"]', '$(5, -2)$', NULL, 'Reflecting across the x-axis keeps the x-coordinate and changes the sign of the y-coordinate: $(5, 2)$ becomes $(5, -2)$.', 'checked', '{"lint":[],"solve":{"answer":"$(5, -2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Across x-axis: (x, y) -> (x, -y). (5, -2).","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0401f0c9-613d-43a5-8101-553601005773', 'NC26.M1.SGMR.1', 1, 'numeric', 'Find the preimage of a point', 'A point is rotated 180 degrees about the origin, and its image is $(4, -7)$. What is the y-coordinate of the original point?', '[]', '7', '7', 'A 180 degree turn changes the sign of both coordinates, and turning the image another 180 degrees gives the original point $(-4, 7)$. Its y-coordinate is 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 rotation is its own inverse: (4, -7) -> (-4, 7). y = 7.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00c357f7-827a-483d-8276-b735eb99647f', 'NC26.M1.SGMR.1', 1, 'numeric', 'Show congruence by a sequence of moves', 'Triangle $ABC$ has vertices $A(0, 0)$, $B(3, 0)$ and $C(0, 2)$. Triangle $DEF$ has vertices $D(5, 1)$, $E(8, 1)$ and $F(5, 3)$. A translation maps $ABC$ onto $DEF$. How many units to the right does it move the triangle?', '[]', '5', '5-0', 'A moves to $D$, from $(0, 0)$ to $(5, 1)$. So the translation is 5 units right and 1 unit up. The other two vertices follow the same move, so the translation is 5 units to the right.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A(0,0) -> D(5,1): 5 right, 1 up. Check B(3,0) -> (8,1) = E. 5.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c8ab706-f1c8-406d-bde4-8b1d18373582', 'NC26.M1.SGMR.1', 2, 'choice', 'Identify the transformation that maps points to images', 'A single rigid transformation takes $(2, 3)$ to $(2, -3)$ and $(5, 1)$ to $(5, -1)$. Which transformation is it?', '["A reflection across the y-axis","A rotation of 180 degrees about the origin","A translation 6 units down","A reflection across the x-axis"]', 'A reflection across the x-axis', NULL, 'Each x-coordinate stays the same and each y-coordinate changes sign, which is a reflection across the x-axis. A rotation of 180 degrees would give $(-2, -3)$, a reflection across the y-axis would give $(-2, 3)$, and moving 6 units down would give $(5, -5)$ for the second point.', 'checked', '{"lint":[],"solve":{"answer":"A reflection across the x-axis","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x, y) -> (x, -y) fits both points: reflection across the x-axis. Translation 6 down sends (5,1) to (5,-5); 180 deg rotation sends (2,3) to (-2,-3); y-axis reflection changes x.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0082b075-b4cf-4ca9-bdf4-e033c9e33dc8', 'NC26.M1.SGMR.1', 2, 'choice', 'Transformations written in function notation', 'Which rule reflects every point across the y-axis?', '["$F(x, y) = (-x, y)$","$F(x, y) = (x, -y)$","$F(x, y) = (-x, -y)$","$F(x, y) = (y, x)$"]', '$F(x, y) = (-x, y)$', NULL, 'A reflection across the y-axis changes the sign of the x-coordinate and keeps the y-coordinate, so the rule is $F(x, y) = (-x, y)$.', 'checked', '{"lint":[],"solve":{"answer":"$F(x, y) = (-x, y)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Across y-axis: x changes sign, y stays.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07f03ea6-6057-43c1-aa45-2384719f4fc8', 'NC26.M1.SGMR.1', 2, 'choice', 'Use congruence to find lengths, angles and areas', 'Triangle $ABC$ has vertices $A(1, 1)$, $B(5, 1)$ and $C(1, 4)$. Triangle $A''B''C''$ is its image after a rotation. Which statement must be true?', '["Triangle $A''B''C''$ has a right angle at $B''$.","Triangle $A''B''C''$ has a right angle at $A''$.","Triangle $A''B''C''$ has a right angle at $C''$.","Triangle $A''B''C''$ has no right angle."]', 'Triangle $A''B''C''$ has a right angle at $A''$.', NULL, 'Side $AB$ is horizontal and side $AC$ is vertical, so $\angle A$ is a right angle. A rotation keeps angle measures, so $\angle A''$ is a right angle too.', 'checked', '{"lint":[],"solve":{"answer":"Triangle $A''B''C''$ has a right angle at $A''$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB is horizontal, AC vertical: right angle at A. Rotation preserves angles and correspondence, so the right angle is at A''.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a802011-ee24-4871-b289-aab5a80c8dac', 'NC26.M1.SGMR.1', 3, 'numeric', 'Properties kept by rigid transformations', 'Points $A$ and $B$ are 5 units apart. One rigid transformation maps $A$ to $A''$ and $B$ to $B''$. A second rigid transformation then maps $A''$ to $A''''$ and $B''$ to $B''''$. How far apart, in units, are $A''''$ and $B''''$?', '[]', '5', '5', 'Each rigid transformation keeps the distance between any two points. The distance stays 5 units after the first move and after the second move.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each rigid transformation preserves distance: AB = A''B'' = A''''B'''' = 5.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00addf65-eb56-401d-838a-8731397049c9', 'NC26.M1.SGMR.1', 3, 'numeric', 'Image of a point under a translation', 'A triangle has vertices $(2, 3)$, $(6, 3)$ and $(4, 7)$. After a translation, the vertex that was at $(6, 3)$ is at $(-1, 8)$. What is the x-coordinate of the image of the vertex that was at $(4, 7)$?', '[]', '-3', '4-7', 'The vertex went from $(6, 3)$ to $(-1, 8)$, which is 7 units left and 5 units up. Every point moves the same way, so $(4, 7)$ goes to $(4 - 7, 7 + 5) = (-3, 12)$. Its x-coordinate is $-3$.', 'checked', '{"lint":[],"solve":{"answer":"-3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vector = (-1-6, 8-3) = (-7, 5). (4,7) -> (-3, 12). x = -3.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01bf57d6-7915-46e7-9e86-0760f679b84f', 'NC26.M1.SGMR.2', 1, 'numeric', 'Corresponding sides of congruent triangles', 'Triangle $ABC$ is congruent to triangle $DEF$, with $A$ matching $D$, $B$ matching $E$, and $C$ matching $F$. In triangle $ABC$, $AB = 7$ cm, $BC = 9$ cm, and $AC = 11$ cm. What is the length of $EF$, in centimeters?', '[]', '9', '9', 'The letters match in order, so $B$ matches $E$ and $C$ matches $F$. That makes side $EF$ match side $BC$. Matching sides of congruent triangles are equal, so $EF = BC = 9$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Correspondence A-D, B-E, C-F, so EF corresponds to BC = 9 cm.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('26b8551b-ba5f-46f8-88f7-8e5274486f8b', 'NC26.M1.SGMR.2', 1, 'numeric', 'Solving for an unknown using congruent triangles', '$\triangle ABC \cong \triangle DEF$, with the vertices matching in the order written. $\angle B = (3x)^\circ$ and $\angle E = 36^\circ$. What is the value of $x$?', '[]', '12', '36/3', '$\angle B$ and $\angle E$ match, so $3x = 36$ and $x = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x = 36, x = 12.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('135bfe6c-6e74-41f3-8cec-f71364d1e6c0', 'NC26.M1.SGMR.2', 1, 'choice', 'Choosing the congruence criterion (SSS, SAS, ASA, AAS)', 'Two triangular garden beds each have one side of 30 feet and one side of 40 feet, with a right angle between those two sides. Which rule shows that the beds are congruent?', '["SSS (side-side-side)","ASA (angle-side-angle)","SAS (side-angle-side)","AAS (angle-angle-side)"]', 'SAS (side-angle-side)', NULL, 'Two sides and the angle between them are equal in both beds, so the rule is SAS.', 'checked', '{"lint":[],"solve":{"answer":"SAS (side-angle-side)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two sides with the included right angle: SAS.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c50e86b-2d6d-43b0-978d-65e0f7967df3', 'NC26.M1.SGMR.2', 2, 'numeric', 'Using congruence to find an unknown side', 'Triangle $ABC$ is congruent to triangle $DEF$, with $A$ matching $D$, $B$ matching $E$, and $C$ matching $F$. Side $AB$ has length $2x + 1$ and side $DE$ has length $13$. What is the value of $x$?', '[]', '6', '(13-1)/2', 'Matching sides of congruent triangles are equal, so $AB = DE$ and $2x + 1 = 13$. Subtract 1: $2x = 12$. Divide by 2: $x = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB corresponds to DE, so 2x + 1 = 13, 2x = 12, x = 6.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('079c756c-a59d-466d-ad2e-2482acb199d0', 'NC26.M1.SGMR.2', 2, 'choice', 'Arguing that two triangles are congruent', 'In $\triangle ABC$ and $\triangle DEF$, $AB = DE$ and $\angle B = \angle E$. Which extra fact would prove the triangles congruent by SAS?', '["$AC = DF$","$\\angle A = \\angle D$","$BC = EF$","$\\angle C = \\angle F$"]', '$BC = EF$', NULL, 'The angle $\angle B$ is between $AB$ and $BC$. To use SAS the other side next to that angle is needed: $BC = EF$.', 'checked', '{"lint":[],"solve":{"answer":"$BC = EF$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need the other side of angle B: BC = EF.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('044d076e-7a42-4281-913f-d6f5d7f53ec7', 'NC26.M1.SGMR.2', 2, 'choice', 'Arguing that two triangles are congruent', 'Segments $AD$ and $BE$ cross at $C$. In a proof that $\triangle ABC \cong \triangle DEC$, a student writes $\angle ACB = \angle DCE$. What is the reason?', '["They are a linear pair, so they add to $180^\\circ$","They are vertical angles, so they are equal","They are corresponding angles of parallel lines","They are complementary, so they add to $90^\\circ$"]', 'They are vertical angles, so they are equal', NULL, '$\angle ACB$ and $\angle DCE$ sit on opposite sides of the point where the segments cross. Vertical angles are equal.', 'checked', '{"lint":[],"solve":{"answer":"They are vertical angles, so they are equal","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angles ACB and DCE are vertical angles at C.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1998b7d2-530a-459b-be14-4af53b5b617b', 'NC26.M1.SGMR.2', 3, 'numeric', 'Solving for an unknown using congruent triangles', 'In $\triangle ABC$, $\angle A = (2x + 5)^\circ$, $\angle B = (3x)^\circ$ and $\angle C = 55^\circ$. Triangle $DEF$ is congruent to $\triangle ABC$, with the vertices matching in the order written. What is the measure of $\angle E$, in degrees?', '[]', '72', '3*(180-55-5)/5', '$(2x + 5) + 3x + 55 = 180$, so $5x = 120$ and $x = 24$. Then $\angle B = 3(24) = 72^\circ$, and $\angle E$ matches $\angle B$.', 'checked', '{"lint":[],"solve":{"answer":"72","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x+5+55 = 180, x = 24; B = 72 (A = 53); E = 72.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('123d72f6-6f76-4a5a-b6eb-73711c0cdc04', 'NC26.M1.SGMR.2', 3, 'numeric', 'Using the angle sum before arguing congruence', 'The exterior angle at $C$ of $\triangle ABC$ measures $130^\circ$, and $\angle A = 50^\circ$. Triangle $DEF$ is congruent to $\triangle ABC$, with $D$ matching $A$, $E$ matching $B$ and $F$ matching $C$. What is the measure of $\angle E$, in degrees?', '[]', '80', '130-50', 'An exterior angle equals the sum of the two remote interior angles: $130 = 50 + \angle B$, so $\angle B = 80^\circ$. $\angle E$ matches $\angle B$, so $\angle E = 80^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 180-130 = 50; B = 180-50-50 = 80 (or exterior = A + B: B = 80). E = 80.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05bf2975-9131-44bf-970f-530b5f734c32', 'NC26.M1.SGMR.3', 1, 'numeric', 'Midpoint of a segment', 'What is the $x$-coordinate of the midpoint of the segment with endpoints $(2, 4)$ and $(10, 8)$?', '[]', '6', '(2+10)/2', 'The midpoint''s $x$-coordinate is the average of the endpoints'' $x$-coordinates: $(2 + 10) \div 2 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x-midpoint = (2 + 10)/2 = 6.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0801b934-a9e4-4e93-b3bc-b4dda9d72f14', 'NC26.M1.SGMR.3', 1, 'choice', 'Classify a quadrilateral from its vertices', 'A quadrilateral has vertices $(0, 0)$, $(4, 0)$, $(4, 4)$ and $(0, 4)$. Which is the most specific name for it?', '["A square","A non-square rectangle","A non-square rhombus","A parallelogram with no right angles"]', 'A square', NULL, 'All four sides are 4 units long and they meet at right angles, because the sides are horizontal or vertical. A figure with four equal sides and four right angles is a square.', 'checked', '{"lint":[],"solve":{"answer":"A square","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"All sides 4, all angles right: square.","run_id":"claude-code","at":"2026-10-18T01:07:47.307Z"}}', 'ai', NULL, NULL)
