INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('176a862c-b3a3-4134-a332-a791826bc7f7', 'NC26.M1.SGMR.3', 2, 'numeric', 'Area from coordinates', 'A parallelogram has vertices $(0, 0)$, $(6, 0)$, $(8, 4)$ and $(2, 4)$. What is its area, in square units?', '[]', '24', '6*4', 'The base along the bottom is 6 units. The height is the vertical distance between the bottom and top sides: 4 units. The area is base times height: $6 \times 4 = 24$ square units. (The slanted side is not the height.)', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 6, height 4: area 24.","run_id":"claude-code","at":"2026-10-18T01:07:47.307Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a61f9bb-35e6-49ca-8a16-7007f24d2a14', 'NC26.M1.SGMR.3', 3, 'numeric', 'Slopes of perpendicular lines', 'What is the slope of a line perpendicular to the line $3x - 5y = 10$?', '[]', '-5/3', '-1/(3/5)', 'Solve for $y$: $-5y = -3x + 10$, so $y = \frac{3}{5}x - 2$ and the slope is $\frac{3}{5}$. The perpendicular slope is the negative reciprocal, $-\frac{5}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"-5/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x - 5y = 10 gives y = (3/5)x - 2, slope 3/5. Perpendicular slope -5/3.","run_id":"claude-code","at":"2026-10-18T01:07:47.307Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0144e1c0-d7e3-4941-a6ae-c1e403524507', 'NC26.M1.SGMR.3', 3, 'numeric', 'Midpoint of a segment', 'Point $M$ is the midpoint of segment $PQ$, where $P$ is $(-1, 6)$ and $Q$ is $(7, 2)$. What is the distance from $M$ to the origin, in units?', '[]', '5', '5', '$M = \left(\frac{-1 + 7}{2}, \frac{6 + 2}{2}\right) = (3, 4)$. The distance from the origin is $\sqrt{3^2 + 4^2} = \sqrt{25} = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"M = (3, 4). Distance to origin sqrt(9 + 16) = 5.","run_id":"claude-code","at":"2026-10-18T01:07:47.307Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0869d20d-c7d9-41a3-bf79-ac3ac3de530f', 'NC26.M1.SDSR.1', 1, 'numeric', 'Joint probability from a two-way table', 'A survey of 25 students found that 6 are in grade 7 and have a pet, 9 are in grade 7 and have no pet, 4 are in grade 8 and have a pet, and 6 are in grade 8 and have no pet. One student is chosen at random. What is the probability that the student is in grade 8 and has a pet? Write your answer as a fraction.', '[]', '4/25', '4/25', 'Exactly 4 of the 25 students are in grade 8 and have a pet, so the probability is $\frac{4}{25}$.', 'checked', '{"lint":[],"solve":{"answer":"4/25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Grade 8 with pet = 4; total 6+9+4+6 = 25; P = 4/25.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a6932be-c8a1-48ae-a689-28899597d013', 'NC26.M1.SDSR.1', 1, 'numeric', 'Marginal probability from a two-way table', 'A club has 40 members. In grade 9, 12 play chess and 8 do not. In grade 10, 6 play chess and 14 do not. One member is chosen at random. What is the probability that the member plays chess? Write your answer as a fraction.', '[]', '9/20', '9/20', 'Chess players: $12 + 6 = 18$ out of 40 members. $\frac{18}{40} = \frac{9}{20}$.', 'checked', '{"lint":[],"solve":{"answer":"9/20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Chess: 12 + 6 = 18; 18/40 = 9/20.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08f74382-4c3d-4612-b31c-ed0921d17a98', 'NC26.M1.SDSR.1', 1, 'numeric', 'Probability from a sample space', 'A spinner has 10 equal sections numbered 1 to 10. What is the probability that it lands on a multiple of 3? Write your answer as a fraction.', '[]', '3/10', '3/10', 'The multiples of 3 from 1 to 10 are 3, 6 and 9, so 3 of 10 equally likely outcomes work: $\frac{3}{10}$.', 'checked', '{"lint":[],"solve":{"answer":"3/10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiples of 3 in 1-10: 3, 6, 9; 3/10.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0aafa93f-8f16-4dec-92a9-b96f23d1a070', 'NC26.M1.SDSR.1', 2, 'numeric', 'Finding a missing entry in a two-way table', 'Of 40 students, 25 are girls. Of the girls, 15 like soccer. In all, 25 students like soccer. How many boys do NOT like soccer?', '[]', '5', '(40-25)-(25-15)', 'There are $40 - 25 = 15$ boys. Soccer fans who are boys: $25 - 15 = 10$. So $15 - 10 = 5$ boys do not like soccer.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Boys 15; boys liking soccer 25 - 15 = 10; boys not = 5.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c7cab40-fa7c-4161-b2f1-4840bc8134a7', 'NC26.M1.SDSR.1', 2, 'numeric', 'Probability of a union (or)', 'A spinner has 10 equal sections numbered 1 to 10. What is the probability that it lands on an even number or on a number greater than 7? Write your answer as a fraction.', '[]', '3/5', '3/5', 'Even: 2, 4, 6, 8, 10. Greater than 7: 8, 9, 10. Together (8 and 10 counted once): 2, 4, 6, 8, 9, 10, which is 6 numbers. $\frac{6}{10} = \frac{3}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"3/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Even: 2,4,6,8,10; >7: 8,9,10; union 2,4,6,8,9,10 = 6; 6/10 = 3/5.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('042b8a7f-fb24-458b-a84b-44d05271224f', 'NC26.M1.SDSR.1', 2, 'numeric', 'Summarising raw data in a table', 'Twelve students voted for a class pet: dog, cat, dog, fish, cat, dog, dog, cat, fish, dog, cat, dog. When the votes are put in a table, how many more votes does dog have than cat?', '[]', '2', '6-4', 'Counting: dog 6, cat 4, fish 2 (total 12). Dog has $6 - 4 = 2$ more votes than cat.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"dog at 1,3,6,7,10,12 = 6; cat at 2,5,8,11 = 4; fish 2 (sum 12). 6 - 4 = 2.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07680225-0d4d-477c-a007-c118f4ec95e8', 'NC26.M1.SDSR.1', 3, 'numeric', 'Probability from a sample space', 'Two fair six-sided dice are rolled. What is the probability that the sum of the two numbers is NOT 8? Write your answer as a fraction.', '[]', '31/36', '1-5/36', 'There are $6 \times 6 = 36$ equally likely outcomes. The sum is 8 for $(2,6)$, $(3,5)$, $(4,4)$, $(5,3)$ and $(6,2)$: 5 outcomes. So $P(\text{sum is } 8) = \frac{5}{36}$ and $P(\text{not } 8) = 1 - \frac{5}{36} = \frac{31}{36}$.', 'checked', '{"lint":[],"solve":{"answer":"31/36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36 equally likely outcomes. Sum 8: (2,6),(3,5),(4,4),(5,3),(6,2) = 5. P(not 8) = 1 - 5/36 = 31/36.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0aafec09-365e-4eb2-8ae4-53e881075b66', 'NC26.M1.SDSR.1', 3, 'numeric', 'Probability from a sample space', 'A card is drawn at random from cards numbered 1 to 20. What is the probability that the number is a multiple of 3 or a multiple of 5? Write your answer as a fraction.', '[]', '9/20', '(6+4-1)/20', 'Multiples of 3: 3, 6, 9, 12, 15, 18 (6 of them). Multiples of 5: 5, 10, 15, 20 (4 of them). 15 is in both, so together there are $6 + 4 - 1 = 9$. The probability is $\frac{9}{20}$.', 'checked', '{"lint":[],"solve":{"answer":"9/20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiples of 3: 6; of 5: 4; of 15: 1; 6 + 4 - 1 = 9; 9/20.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1484634f-52e4-4737-b54c-234ff8dceb87', 'NC26.M1.SDSR.2', 1, 'numeric', 'Matching questions to the variables a dataset holds', 'Sara has data on each classmate''s height and shoe size, and nothing else. (A) Do taller students tend to have larger shoe sizes? (B) Do taller students tend to run faster? (C) Do students with bigger feet tend to have more brothers and sisters? (D) How do shoe sizes vary in our class? How many of these four can she investigate with only her data?', '[]', '2', NULL, 'Question (A) uses height and shoe size. Question (D) uses shoe size. Question (B) needs running times and question (C) needs the number of siblings, which Sara does not have. So 2 can be investigated.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(A) height and shoe size: yes. (B) needs running speed: no. (C) needs siblings: no. (D) shoe sizes only: yes. Total 2.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('201a5470-fde3-4a38-b87f-c1e2991729b3', 'NC26.M1.SDSR.2', 1, 'choice', 'Voluntary response and non-response bias', 'Why are online polls that anyone may choose to answer often biased?', '["People who answer online polls always give false answers on purpose.","People with strong opinions are more likely to choose to answer.","Online polls always have many more questions than other kinds of surveys.","Everyone has exactly the same chance of being asked to take part."]', 'People with strong opinions are more likely to choose to answer.', NULL, 'When answering is up to each person, the people who feel most strongly are the ones who respond, so the answers do not match the whole group.', 'checked', '{"lint":[],"solve":{"answer":"People with strong opinions are more likely to choose to answer.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Self-selected respondents are mostly people with strong opinions: voluntary response bias.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1aca263e-b763-4329-9e3e-23554af8394f', 'NC26.M1.SDSR.2', 1, 'choice', 'Measurement and response bias', 'A class wants to know how much time students really spend on their phones each day. Which method is likely to give the most accurate numbers?', '["Reading the usage report that each student''s own phone keeps","Asking each student to guess from memory at the end of the month","Asking each student''s friends to guess the numbers","Asking the teacher to guess the numbers for each student"]', 'Reading the usage report that each student''s own phone keeps', NULL, 'A usage report records the time as it happens, so it depends less on memory or guessing. People are often poor at guessing their own phone time, and others are worse.', 'checked', '{"lint":[],"solve":{"answer":"Reading the usage report that each student''s own phone keeps","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The phone''s own usage report measures directly; guesses by friends, the teacher or memory are less accurate.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d1de826-2e48-48ca-aef7-9e97bbe50fd9', 'NC26.M1.SDSR.2', 2, 'numeric', 'Posing a statistical question for a context', 'Four questions are written about a school. (A) Is our school a good school? (B) How many hours a week do students at our school spend reading for fun? (C) Are the people in our town happy? (D) What is the typical time students at our school spend traveling to school? How many of the four are too vague to be answered by collecting data as they are written?', '[]', '2', NULL, 'Question (A) does not say what ''good'' means, and question (C) does not say what ''happy'' means or how to measure it, so data could not answer them as written. Questions (B) and (D) name a clear quantity to measure. So 2 are too vague.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(A) ''good school'' is undefined: vague. (B) hours reading: measurable. (C) ''happy'' undefined: vague. (D) travel time: measurable. Total 2.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('252133f4-a3a2-4817-bd59-92256c764e24', 'NC26.M1.SDSR.2', 2, 'choice', 'Sampling bias from who is included or left out', 'A city wants to know how often residents use its public parks. A worker interviews people only inside a park on weekday mornings. Why is this sample likely to be biased?', '["People inside the park will refuse to answer, so use will seem lower than it really is.","Weekday mornings have too many people at parks, so the survey will be far too large.","Interviews are always more biased than written surveys, no matter who is asked.","People who use parks are more likely to be included, so use will seem higher than it is."]', 'People who use parks are more likely to be included, so use will seem higher than it is.', NULL, 'Residents who never visit a park cannot be found in a park, and the people who do visit are the ones included. Park use will seem higher than it really is across all residents.', 'checked', '{"lint":[],"solve":{"answer":"People who use parks are more likely to be included, so use will seem higher than it is.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Interviewing only people already in a park includes only park users, so park use seems higher than it is.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('217c6ee4-aedf-4f65-b68b-ab0c42843270', 'NC26.M1.SDSR.2', 2, 'numeric', 'Measurement and response bias', 'Two polls ask teenagers whether they have ever skipped school. In an anonymous written poll of 200 teenagers, 30 percent said yes. In a face-to-face poll with an adult interviewer, 12 percent of another 200 teenagers said yes. How many fewer teenagers, out of 200, said yes in the face-to-face poll?', '[]', '36', '200*0.30-200*0.12', 'Anonymous poll: $200 \times 0.30 = 60$ said yes. Face-to-face poll: $200 \times 0.12 = 24$ said yes. The difference is $60 - 24 = 36$ teenagers. Teenagers may hide the truth when an adult is asking.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Anonymous: 0.30 x 200 = 60. Face to face: 0.12 x 200 = 24. Fewer: 60 - 24 = 36.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a2e05e2-9704-4155-9260-285ec0b34812', 'NC26.M1.SDSR.2', 3, 'choice', 'Choosing an unbiased sampling method', 'A school has 1,200 students. Which method is most likely to give an unbiased estimate of the average time students spend on homework?', '["Ask 100 students chosen at random from the full list of students","Ask all 30 members of the math club","Ask the first 50 students who arrive at school in the morning","Ask the 100 students who are in the library after school"]', 'Ask 100 students chosen at random from the full list of students', NULL, 'A random sample from the complete list gives every student an equal chance of being chosen. The other groups are likely to spend more or less time on homework than the typical student.', 'checked', '{"lint":[],"solve":{"answer":"Ask 100 students chosen at random from the full list of students","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A simple random sample from the full list is unbiased; early arrivals, library students and math club are convenience groups likely to differ in homework time.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('011c32e7-c2ca-4ca4-807b-cfe72ab83837', 'NC26.M1.SDSR.2', 3, 'choice', 'Sampling bias from who is included or left out', 'Which situation is an example of undercoverage?', '["A survey is sent to random households, but few reply and most replies come from people with strong opinions.","Names for a town survey are taken from a phone book, which leaves out households with no listed number.","A survey is posted online and anyone who wishes can answer it.","A survey asks, ''Don''t you agree that the park is wonderful?''"]', 'Names for a town survey are taken from a phone book, which leaves out households with no listed number.', NULL, 'Undercoverage happens when part of the group has no chance of being included. A phone book misses households without a listed number. The other situations describe non-response, voluntary response and a leading question.', 'checked', '{"lint":[],"solve":{"answer":"Names for a town survey are taken from a phone book, which leaves out households with no listed number.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Undercoverage means part of the population cannot be chosen: the phone book leaves out households with no listed number. A is non-response, B voluntary response, C a leading question.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07b8f6d6-2701-41d1-b964-ccbb2759b525', 'NC26.M1.SDSR.3', 1, 'choice', 'Choosing relevant variables', 'A student wants to predict the selling price of a house. Which variable is the LEAST useful for this?', '["the size of the house in square feet","the favorite color of the owner","the number of bedrooms","the neighborhood"]', 'the favorite color of the owner', NULL, 'Size, number of bedrooms and neighborhood all affect what buyers pay. The owner''s favorite color has no connection to the price.', 'checked', '{"lint":[],"solve":{"answer":"the favorite color of the owner","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Size, bedrooms and neighborhood all relate to price; the owner''s favorite color does not.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09656532-e854-4008-b3db-9a23b21bd84c', 'NC26.M1.SDSR.3', 1, 'choice', 'Recognizing a third (lurking) variable', 'Towns where more bicycle helmets are sold also report more bicycle injuries. Which third variable most likely affects both of these?', '["The brand name printed on the helmets","The average price of one helmet","The number of people who ride bikes","The color most helmets are painted"]', 'The number of people who ride bikes', NULL, 'A town with more bike riders sells more helmets and also has more injuries, so the number of riders affects both. The brand, the price and the color of helmets do not explain why injuries would rise along with sales.', 'checked', '{"lint":[],"solve":{"answer":"The number of people who ride bikes","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"More riders means more helmets bought and more injuries; the number of riders drives both. Color, brand and price do not plausibly drive injuries.","run_id":"claude-code","at":"2026-10-18T03:44:26.855Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d84e6cb-be56-482d-aa18-07aa1b17e8cb', 'NC26.M1.SDSR.3', 1, 'choice', 'Using a third variable to improve a model', 'A scatter plot shows plant height against days of growth. Plants grown in sun are drawn as blue dots and plants grown in shade as red dots. What does the color of a dot show?', '["The light the plant grew in","The number of days it has grown","The height the plant has reached","The amount of water it received"]', 'The light the plant grew in', NULL, 'Height and days of growth are already shown by where the dot sits. The color adds a third variable, the kind of light (sun or shade), so a separate pattern can be seen for each group.', 'checked', '{"lint":[],"solve":{"answer":"The light the plant grew in","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Blue = sun, red = shade, so color encodes the light condition (the third variable). Height and days are the axes; water is not shown.","run_id":"claude-code","at":"2026-10-18T03:44:26.855Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a794d9e-283b-4a14-9dc0-d3456eac048c', 'NC26.M1.SDSR.3', 2, 'choice', 'Choosing relevant variables', 'A school wants to predict, before the semester starts, whether a student will pass a course. Which variable could NOT be used for this?', '["The student''s grade in the previous math course","The student''s attendance last year","The student''s score on a placement quiz","The student''s final course grade"]', 'The student''s final course grade', NULL, 'The final grade is not known before the semester starts, so it cannot be used to predict the result.', 'checked', '{"lint":[],"solve":{"answer":"The student''s final course grade","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Final course grade is not known before the semester starts (and is essentially the outcome).","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
