INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0660d913-1741-4f41-84f0-5d633e32134e', 'NC26.M1.SDSR.5', 1, 'choice', 'Exponential models', 'Which equation shows exponential decay?', '["$y = 80(0.9)^x$","$y = 80(1.9)^x$","$y = 80 - 0.9x$","$y = 0.9(80)^x$"]', '$y = 80(0.9)^x$', NULL, 'Exponential decay has the form $y = a \cdot b^x$ with $0 < b < 1$. Here $b = 0.9$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 80(0.9)^x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base between 0 and 1: 80(0.9)^x.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3820e438-10d3-4fb6-8c0a-f54f0661dc26', 'NC26.M1.SDSR.5', 1, 'choice', 'Outliers and influential points', 'Ten-year-olds'' heights in centimeters are recorded as (age, height) pairs. Which pair is an outlier?', '["(10, 138)","(10, 60)","(10, 140)","(10, 142)"]', '(10, 60)', NULL, 'Most ten-year-olds are about 140 centimeters tall. A height of 60 centimeters is far from the others.', 'checked', '{"lint":[],"solve":{"answer":"(10, 60)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60 cm is far from ~140 cm.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
