INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0af26995-d280-4ed7-93f4-7fa5c2997778', 'NC26.M2.ANFR.5', 1, 'choice', 'Use technology: graphs and intersections', 'A student graphs $y=x^2-4x-5$ with a graphing tool and reads the $x$-values where the graph crosses the $x$-axis. Which equation do those $x$-values solve?', '["$x^2-4x-5=5$","$x^2-4x-5=0$","$x^2-4x-5=-5$","$x^2-4x+5=0$"]', '$x^2-4x-5=0$', NULL, 'Points on the $x$-axis have $y=0$. So the $x$-values solve $x^2-4x-5=0$.', 'checked', '{"lint":[],"solve":{"answer":"$x^2-4x-5=0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x-intercepts: y=0.","run_id":"claude-code","at":"2026-10-22T19:23:59.766Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ba95c01-698a-4ca9-abe2-6963e66167a3', 'NC26.M2.ANFR.5', 1, 'numeric', 'Solve a reciprocal equation', 'Solve $\frac{6}{x} + 2 = 5$.', '[]', '2', '6/3', 'Subtract 2: $\frac{6}{x} = 3$. So $x = \frac{6}{3} = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6/x=3, x=2.","run_id":"claude-code","at":"2026-10-22T19:38:53.415Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a0abb0d-3ef7-44c6-9096-58be6934aaf0', 'NC26.M2.ANFR.5', 1, 'choice', 'Interpret solutions in context', 'A ball is thrown up, and solving an equation for the time $t$, in seconds, after the throw gives $t = -2$ or $t = 5$. Which statement is correct?', '["$t = -2$ only, because it is the smaller of the two values","$t = 5$ only, since time cannot be negative","Both, because both of them solve the equation","Neither, because time must be a whole number of seconds"]', '$t = 5$ only, since time cannot be negative', NULL, 'Both numbers solve the equation, but a time after the throw cannot be negative. Only $t = 5$ makes sense.', 'checked', '{"lint":[],"solve":{"answer":"$t = 5$ only, since time cannot be negative","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Time after throw cannot be negative.","run_id":"claude-code","at":"2026-10-22T19:38:53.415Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01fc9682-5f38-4718-baa5-e5ff9f34e74f', 'NC26.M2.ANFR.5', 2, 'choice', 'Solve by completing the square', 'Solve $x^2 - 6x + 2 = 0$ by completing the square.', '["$x = -3 \\pm \\sqrt{7}$","$x = 3 \\pm \\sqrt{7}$","$x = 3 \\pm \\sqrt{11}$","$x = 3 \\pm \\sqrt{2}$"]', '$x = 3 \pm \sqrt{7}$', NULL, '$x^2 - 6x = -2$. Add 9: $(x - 3)^2 = 7$. So $x = 3 \pm \sqrt{7}$.', 'checked', '{"lint":[],"solve":{"answer":"$x = 3 \\pm \\sqrt{7}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2-6x=-2, add 9: (x-3)^2=7.","run_id":"claude-code","at":"2026-10-22T19:38:53.415Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f3ede7e-907c-45ef-9a8b-82bebda09fda', 'NC26.M2.ANFR.5', 2, 'numeric', 'Solve a reciprocal equation', 'Solve $\frac{x}{3} = \frac{12}{x}$. What is the positive solution?', '[]', '6', '6', 'Cross-multiply: $x^2 = 36$, so $x = 6$ or $x = -6$. The positive one is 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2=36, x=6.","run_id":"claude-code","at":"2026-10-22T19:38:53.415Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c764102-4547-4a72-a245-e21a925ac0df', 'NC26.M2.ANFR.5', 2, 'choice', 'Solve a quadratic inequality', 'Which inequality has the solution $-2 \le x \le 5$?', '["$x^2 - 3x - 10 \\ge 0$","$x^2 + 3x - 10 \\le 0$","$x^2 + 3x - 10 \\ge 0$","$x^2 - 3x - 10 \\le 0$"]', '$x^2 - 3x - 10 \le 0$', NULL, '$x^2 - 3x - 10 = (x - 5)(x + 2)$ has zeros $-2$ and 5, and it is at most 0 between them. The same expression with $\ge 0$ is true outside those zeros instead, and the other two have zeros at $-5$ and 2.', 'checked', '{"lint":[],"solve":{"answer":"$x^2 - 3x - 10 \\le 0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-5)(x+2)=x^2-3x-10<=0.","run_id":"claude-code","at":"2026-10-22T19:38:53.415Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e03d219-48a6-4f36-ac3f-e2c0dc7d69a7', 'NC26.M2.ANFR.5', 3, 'choice', 'Solve by square roots', 'Which are the solutions of $3(x - 4)^2 = 54$?', '["$x = -4 \\pm 3\\sqrt{2}$","$x = 4 \\pm 3\\sqrt{6}$","$x = 4 \\pm 6$","$x = 4 \\pm 3\\sqrt{2}$"]', '$x = 4 \pm 3\sqrt{2}$', NULL, 'Divide by 3: $(x - 4)^2 = 18$. Take square roots: $x - 4 = \pm\sqrt{18} = \pm 3\sqrt{2}$, so $x = 4 \pm 3\sqrt{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$x = 4 \\pm 3\\sqrt{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x-4)^2=18, x=4+/-3sqrt2.","run_id":"claude-code","at":"2026-10-22T19:38:53.415Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0769e63e-3a5d-413d-9f43-bfdb0bc8cf68', 'NC26.M2.ANFR.5', 3, 'choice', 'Write a quadratic equation from a context', 'The sum of the squares of two consecutive odd integers is 130. Let $n$ be the smaller. Which equation can be solved to find $n$?', '["$n^2 + (n + 1)^2 = 130$","$(n + (n + 2))^2 = 130$","$n^2 + n + 2 = 130$","$n^2 + (n + 2)^2 = 130$"]', '$n^2 + (n + 2)^2 = 130$', NULL, 'Consecutive odd integers differ by 2, so they are $n$ and $n + 2$. The sum of their squares is $n^2 + (n+2)^2 = 130$.', 'checked', '{"lint":[],"solve":{"answer":"$n^2 + (n + 2)^2 = 130$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Next odd integer n+2.","run_id":"claude-code","at":"2026-10-22T19:38:53.415Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('076345b8-d108-412c-888e-b281021f51b9', 'NC26.M2.ANFR.6', 1, 'numeric', 'Solve a system by substitution', 'The system $y = x^2$ and $y = 5x$ has two solutions. One has $x = 0$. What is the $x$-value of the other?', '[]', '5', '5', '$x^2 = 5x$ gives $x(x - 5) = 0$, so $x = 0$ or $x = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2=5x -> x(x-5)=0 -> x=0 or 5. Other x=5.","run_id":"claude-code","at":"2026-10-22T19:43:34.679Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11d0207b-c1bc-4fde-ae82-dd849c76c9c4', 'NC26.M2.ANFR.6', 1, 'choice', 'Build a linear-quadratic system from a context', 'A company''s revenue is $R = -x^2 + 20x$ and its cost is $C = 2x + 50$, where $x$ is the number of items made. Which equation can be solved to find when revenue equals cost?', '["$-x^2 + 20x = 50$","$-x^2 + 20x = 2x$","$-x^2 + 20x + 2x + 50 = 0$","$-x^2 + 20x = 2x + 50$"]', '$-x^2 + 20x = 2x + 50$', NULL, 'Revenue equals cost when $R = C$, so $-x^2 + 20x = 2x + 50$.', 'checked', '{"lint":[],"solve":{"answer":"$-x^2 + 20x = 2x + 50$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"R=C: -x^2+20x = 2x+50.","run_id":"claude-code","at":"2026-10-22T19:43:34.679Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d77524e-d692-470c-8d90-f1a6454e2af2', 'NC26.M2.ANFR.6', 1, 'numeric', 'Interpret a solution in context', 'A company''s revenue is $R = -x^2 + 14x$ and its cost is $C = 2x + 27$, both in thousands of dollars, where $x$ is the number of hundreds of items made. Solving $R = C$ gives $x = 3$ and $x = 9$. What is the revenue, in thousands of dollars, when the company breaks even at $x = 9$?', '[]', '45', '-9^2+14*9', '$R = -81 + 126 = 45$. The cost agrees: $2(9) + 27 = 45$.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"R(9) = -81+126 = 45 (check C(9)=18+27=45).","run_id":"claude-code","at":"2026-10-22T19:43:34.679Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('046a8ddc-9e8a-46f5-b673-9db9846dccbc', 'NC26.M2.ANFR.6', 2, 'numeric', 'Count the real solutions', 'How many real solutions does the system $y = x^2 + 3x$ and $y = -2x - 10$ have?', '[]', '0', NULL, '$x^2 + 3x = -2x - 10$ gives $x^2 + 5x + 10 = 0$. The discriminant is $25 - 40 = -15$, which is negative, so there are 0 real solutions.', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2+3x=-2x-10 -> x^2+5x+10=0, disc 25-40=-15<0: 0 real solutions.","run_id":"claude-code","at":"2026-10-22T19:43:34.679Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03db7b96-d8c9-4fa8-b353-2756f31101f4', 'NC26.M2.ANFR.6', 2, 'choice', 'Build a linear-quadratic system from a context', 'A rectangular pen has a perimeter of 30 meters and an area of 54 square meters. Let $L$ be its length and $w$ its width. Which system of equations models this?', '["$L + w = 30$ and $Lw = 54$","$2L + 2w = 54$ and $Lw = 30$","$2L + 2w = 30$ and $Lw = 54$","$2L + 2w = 30$ and $L + w = 54$"]', '$2L + 2w = 30$ and $Lw = 54$', NULL, 'The perimeter is $2L + 2w = 30$ and the area is $Lw = 54$.', 'checked', '{"lint":[],"solve":{"answer":"$2L + 2w = 30$ and $Lw = 54$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeter 2L+2w=30, area Lw=54.","run_id":"claude-code","at":"2026-10-22T19:43:34.679Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03704762-2105-448f-8780-97dce297968a', 'NC26.M2.ANFR.6', 2, 'choice', 'Interpret a solution in context', 'A ball''s height is $h = -5t^2 + 20t$ meters after $t$ seconds. A shelf is 15 meters high, and solving $-5t^2 + 20t = 15$ gives $t = 1$ and $t = 3$. When is the ball higher than the shelf?', '["Before 1 second and after 3 seconds","Only at 1 second and at 3 seconds","Between 1 and 3 seconds","Between 0 and 1 second"]', 'Between 1 and 3 seconds', NULL, 'The ball passes 15 meters going up at 1 second and coming down at 3 seconds, so it is higher than 15 meters between those times.', 'checked', '{"lint":[],"solve":{"answer":"Between 1 and 3 seconds","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"h-15=-5(t-1)(t-3)>0 between 1 and 3 seconds.","run_id":"claude-code","at":"2026-10-22T19:43:34.679Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21323561-c417-48eb-a143-66a3ef05e7b7', 'NC26.M2.ANFR.6', 3, 'numeric', 'Solve a system by substitution', 'The line $y = x + 6$ and the parabola $y = 2x^2 - 3x$ cross at two points. What is the sum of the $y$-coordinates of the two crossing points?', '[]', '14', '9+5', 'Set the $y$-values equal: $2x^2 - 3x = x + 6$, so $2x^2 - 4x - 6 = 0$, or $x^2 - 2x - 3 = 0$, which factors as $(x - 3)(x + 1) = 0$. So $x = 3$ or $x = -1$. The line gives $y = 9$ and $y = 5$. Their sum is $9 + 5 = 14$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 6 = 2x^2 - 3x gives 2x^2 - 4x - 6 = 0, x^2 - 2x - 3 = 0, x = 3 or -1. y = 9 and 5. Check parabola: 18 - 9 = 9; 2 + 3 = 5. Sum 14.","run_id":"claude-code","at":"2026-10-22T12:51:46.505Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('006385d6-d4d5-44f2-af32-b282018cad0e', 'NC26.M2.ANFR.6', 3, 'numeric', 'Find a value that gives a stated number of solutions', 'The line $y = 2x + k$ and the parabola $y = x^2 - 4x + 7$ have exactly one point in common. What is $k$?', '[]', '-2', '-8/4', 'Set $x^2 - 4x + 7 = 2x + k$, so $x^2 - 6x + (7 - k) = 0$. One solution means the discriminant is 0: $36 - 4(7 - k) = 8 + 4k = 0$, so $k = -2$. (Check: the common point is $x = 3$, where both give $y = 4$.)', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x + k = x^2 - 4x + 7 gives x^2 - 6x + (7 - k) = 0. Discriminant 36 - 4(7 - k) = 8 + 4k = 0, k = -2. Check: x^2 - 6x + 9 = (x - 3)^2, tangent at (3, 4).","run_id":"claude-code","at":"2026-10-22T12:51:46.505Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0325660c-8d4f-4152-840a-f7f486ee2b1a', 'NC26.M2.SGMR.1', 1, 'numeric', 'Rigid and non-rigid transformations', 'The segment from $(1, 2)$ to $(1, 7)$ is reflected across the $y$-axis. How long is the image of the segment?', '[]', '5', '7-2', 'A reflection keeps lengths the same. The original segment is $7 - 2 = 5$ units long, so the image is 5 units long.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reflection preserves length: 7-2=5.","run_id":"claude-code","at":"2026-10-22T19:43:34.723Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('093a3265-9dc1-4675-a764-48eb08e9a6e6', 'NC26.M2.SGMR.1', 1, 'choice', 'Rigid and non-rigid transformations', 'A transformation makes a figure larger or smaller but keeps its shape. What is it called?', '["A reflection","A dilation","A rotation","A translation"]', 'A dilation', NULL, 'A dilation multiplies all lengths by the same scale factor, so the shape stays the same while the size changes.', 'checked', '{"lint":[],"solve":{"answer":"A dilation","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A dilation changes size but keeps shape.","run_id":"claude-code","at":"2026-10-22T19:43:34.723Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a8158bc-0d81-4e34-ac44-cab7cfde14d9', 'NC26.M2.SGMR.1', 1, 'numeric', 'Properties of dilations', 'A triangle has angles of $40^\circ$, $60^\circ$ and $80^\circ$. It is dilated with a scale factor of 3. What is the measure, in degrees, of the largest angle of the image?', '[]', '80', '80', 'A dilation does not change angle measures, so the largest angle is still $80^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dilation preserves angles: 80.","run_id":"claude-code","at":"2026-10-22T19:43:34.723Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04dc7bd6-d0b7-4240-870c-134b11446c16', 'NC26.M2.SGMR.1', 2, 'numeric', 'Find the image of a point or figure', 'The point $(2, -5)$ is reflected across the $y$-axis and then translated 4 units right and 1 unit down. What is the sum of the two coordinates of the final point?', '[]', '-4', '2+(-6)', 'The reflection gives $(-2, -5)$. The translation gives $(-2 + 4,\ -5 - 1) = (2, -6)$. The sum is $2 + (-6) = -4$.', 'checked', '{"lint":[],"solve":{"answer":"-4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reflect y-axis: (-2,-5); translate: (2,-6); sum -4.","run_id":"claude-code","at":"2026-10-22T19:43:34.723Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d1de77e-4ba4-41de-a87c-e347dca58eb1', 'NC26.M2.SGMR.1', 2, 'numeric', 'Transformations in function notation', 'The dilation $D(x, y) = (1.5x,\ 1.5y)$ is applied to the point $(6, -8)$. What is the sum of the coordinates of the image?', '[]', '-3', '1.5*6+1.5*(-8)', '$D(6, -8) = (9, -12)$, and $9 + (-12) = -3$.', 'checked', '{"lint":[],"solve":{"answer":"-3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(9,-12); sum -3.","run_id":"claude-code","at":"2026-10-22T19:43:34.723Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('051e9ec2-4867-4f3f-8571-8356ffc5d8d8', 'NC26.M2.SGMR.1', 2, 'choice', 'Map one figure onto another', 'The triangle with vertices $(1, 1)$, $(3, 1)$ and $(3, 4)$ is mapped to the triangle with vertices $(-1, -1)$, $(-3, -1)$ and $(-3, -4)$, in that order. Which single transformation does this?', '["A reflection across the $y$-axis","A reflection across the $x$-axis","A rotation of $180^\\circ$ about the origin","A translation 2 units left and 2 units down"]', 'A rotation of $180^\circ$ about the origin', NULL, 'Both coordinates of every point change sign, which is a $180^\circ$ rotation about the origin.', 'checked', '{"lint":[],"solve":{"answer":"A rotation of $180^\\circ$ about the origin","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each point maps to (-x,-y): 180° rotation about origin. Translation fails for (3,1)->(-3,-1).","run_id":"claude-code","at":"2026-10-22T19:43:34.723Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18cc2917-5142-4961-894c-d548c1cdb01d', 'NC26.M2.SGMR.1', 3, 'choice', 'Center and scale factor of a dilation', 'A dilation centered at the origin maps the rectangle with vertices $(2, 1)$, $(6, 1)$, $(6, 4)$ and $(2, 4)$ onto the rectangle with vertices $(3, 1.5)$, $(9, 1.5)$, $(9, 6)$ and $(3, 6)$, in that order. What is the scale factor?', '["$\\frac{3}{2}$","$\\frac{2}{3}$","$2$","$3$"]', '$\frac{3}{2}$', NULL, 'Compare corresponding vertices: $(2, 1)\to(3, 1.5)$, and $3\div 2=1.5=\frac{3}{2}$. Every other coordinate is also multiplied by $\frac{3}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2,1)->(3,1.5): 3/2 = 1.5, 1.5/1 = 1.5; (6,4)->(9,6) also 1.5. Scale factor 3/2.","run_id":"claude-code","at":"2026-10-22T12:48:57.299Z"}}', 'ai', NULL, NULL)
