INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('040d83b1-0900-4ec1-a45b-fcf088c51fd5', 'PRE.01', 3, 'choice', 'Commutative and associative properties', 'Find $8 \times 125 \times 13 \times 5 \times 2$.', '["$13000$","$130000$","$1300000$","$260000$"]', '$130000$', '8*125*5*2*13', '$8 \times 125 = 1000$ and $5 \times 2 = 10$, so the product is $1000 \times 10 \times 13 = 130000$.', 'checked', '{"lint":[],"solve":{"answer":"$130000$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 x 125 = 1000; 5 x 2 = 10; 1000 x 10 x 13 = 130000.","run_id":"claude-code","at":"2026-10-19T01:37:28.538Z"}}', 'ai', NULL, NULL)
