INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15413e06-8dfb-44d0-8397-4a71f8c890a1', 'PRE.01', 3, 'choice', 'Multiplying and dividing negative numbers', 'Which expression has the smallest value?', '["$(-6) \\times 4$","$(-6) \\times (-4)$","$6 - 4$","$(-6) + (-4)$"]', '$(-6) \times 4$', NULL, 'The values are $-24$, $24$, $2$ and $-10$. The smallest is $(-6) \times 4 = -24$.', 'checked', '{"lint":[],"solve":{"answer":"$(-6) \\times 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24, 2, -24, -10. Smallest -24.","run_id":"claude-code","at":"2026-10-19T01:37:28.538Z"}}', 'ai', NULL, NULL)
