INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06aaf990-c89e-4d9d-9a45-c101c47ca10a', 'PRE.02', 1, 'choice', 'Product and quotient laws of exponents', 'Which is equal to $10^7 \div 10^2$?', '["$10^9$","$10^{14}$","$1^5$","$10^5$"]', '$10^5$', NULL, 'Keep the base and subtract the exponents: $7 - 2 = 5$. Adding gives $10^9$, multiplying gives $10^{14}$, and the base does not become 1.', 'checked', '{"lint":[],"solve":{"answer":"$10^5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10^(7-2) = 10^5.","run_id":"claude-code","at":"2026-10-19T01:37:28.576Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03e9dd2f-ae5d-4fc9-b5ec-daf30e87686b', 'PRE.02', 1, 'choice', 'Power of a power and power of a product', 'Which is equal to $(2 \times 5)^3$?', '["$2^3 \\times 5^3$","$2^3 + 5^3$","$2 \\times 5^3$","$2^3 \\times 5$"]', '$2^3 \times 5^3$', NULL, 'The exponent 3 applies to each factor: $(2 \times 5)^3 = 2^3 \times 5^3 = 8 \times 125 = 1000$.', 'checked', '{"lint":[],"solve":{"answer":"$2^3 \\times 5^3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(ab)^3 = a^3 b^3; 10^3 = 1000 = 8 x 125.","run_id":"claude-code","at":"2026-10-19T01:37:28.576Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('029fb746-232f-4176-b6ce-9450bc8753ce', 'PRE.02', 1, 'numeric', 'Order of operations', 'Evaluate $3 \times 2^2$. Remember that powers come before multiplication.', '[]', '12', '3*2^2', 'The exponent comes before the multiplication: $2^2 = 4$, then $3 \times 4 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^2 = 4; 3 x 4 = 12.","run_id":"claude-code","at":"2026-10-19T01:37:28.576Z"}}', 'ai', NULL, NULL)
