INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09eb93fb-0394-4a0b-9e57-2325f8983531', 'PRE.02', 2, 'numeric', 'Product and quotient laws of exponents', 'Find $3^4 \times 3^2 \div 3^3$ as an ordinary number.', '[]', '27', '3^(4+2-3)', '$3^4 \times 3^2 = 3^6$, and $3^6 \div 3^3 = 3^3 = 27$.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3^(4+2-3) = 3^3 = 27.","run_id":"claude-code","at":"2026-10-19T01:37:28.576Z"}}', 'ai', NULL, NULL)
