VALUES ('002e6c9b-f44f-4d7c-941c-59a521995f7e', 'PRE.02', 2, 'choice', 'Zero and negative exponents', 'Find $2^0 + 2^1 + 2^2 + 2^3$.', '["$15$","$16$","$8$","$31$"]', '$15$', '1+2+4+8', '$1 + 2 + 4 + 8 = 15$.', 'checked', '{"lint":[],"solve":{"answer":"$15$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 + 2 + 4 + 8 = 15.","run_id":"claude-code","at":"2026-10-19T01:37:28.576Z"}}', 'ai', NULL, NULL)
