VALUES ('0459cf59-5692-4e3b-ae90-6fb388b01a89', 'PRE.02', 2, 'numeric', 'Order of operations', 'Calculate $2 \times 3^2 - 4 \times 2$, doing the power before multiplying.', '[]', '10', '2*9-8', 'Powers first: $3^2 = 9$. Then $2 \times 9 = 18$ and $4 \times 2 = 8$, so $18 - 8 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 x 9 - 8 = 18 - 8 = 10.","run_id":"claude-code","at":"2026-10-19T01:37:28.576Z"}}', 'ai', NULL, NULL)
