INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01db71c0-0ff0-4e3b-aeda-e7b64762d910', 'PRE.03', 1, 'choice', 'Identify primes and composites', 'Which of these numbers is composite?', '["2","39","13","31"]', '39', NULL, 'A composite number has a divisor other than 1 and itself. $39=3\times 13$, so it is composite. The numbers 2, 13 and 31 are all prime.', 'checked', '{"lint":[],"solve":{"answer":"39","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"39=3*13 is composite; 31, 13, 2 are prime.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
