INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0734bb35-0a6c-4f9c-beaf-9517d016dc5c', 'PRE.03', 1, 'numeric', 'Greatest common divisor', 'What is the greatest whole number that divides evenly into both $15$ and $45$?', '[]', '15', '15', 'The number 45 is $3\times 15$, so 15 divides both 15 and 45. No number larger than 15 can divide 15, so the answer is 15.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 divides 45, so 15.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
