INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ad1a846-0957-4d59-865b-a0a6bc3e25e4', 'PRE.03', 1, 'choice', 'Least common multiple', 'What is the least common multiple of $3$ and $5$?', '["8","15","30","1"]', '15', '15', 'Neither 3 nor 5 divides the other, and they share no prime, so the LCM is their product, $3\times 5=15$. The number 8 is their sum, 30 is a common multiple that is not the least, and 1 is a common divisor.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"lcm(3,5)=15.","run_id":"claude-code","at":"2026-10-19T01:39:57.111Z"}}', 'ai', NULL, NULL)
