INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ce6ed41-6d2b-4456-bb53-9d18ddc3f829', 'PRE.05', 1, 'numeric', 'Write an equation for a word problem and solve it', 'Dana packs cookies into bags of 7. She fills some bags and uses 56 cookies in all. How many bags does she fill?', '[]', '8', '56/7', 'Let $b$ be the number of bags: $7b=56$. Divide by 7: $b=8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7b = 56, b = 8.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
