INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00fb785b-41f7-4bb4-b119-d2c3e9290920', 'PRE.05', 2, 'choice', 'Write an equation for a word problem and solve it', 'A gym charges a joining fee of 20 dollars and then 15 dollars a month. Mia has paid 110 dollars in total. How many months has she been a member?', '["$6$","$\\frac{22}{3}$","$\\frac{26}{3}$","$90$"]', '$6$', '(110-20)/15', 'Let $m$ be the months: $20+15m=110$. Subtract 20: $15m=90$. So $m=6$.', 'checked', '{"lint":[],"solve":{"answer":"$6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 + 15m = 110, m = 6.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07434adb-2d91-4add-aaa9-4f866d8ad140', 'PRE.05', 2, 'numeric', 'Write and solve an inequality for a word problem', 'Lia has 20 dollars. She buys a book for 6 dollars and then some stickers at 2 dollars each. What is the greatest number of stickers she can buy without spending more than 20 dollars?', '[]', '7', '(20-6)/2', 'Let $s$ be the stickers: $6+2s\le20$. Subtract 6: $2s\le14$. So $s\le7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 + 2s <= 20, s <= 7.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
