INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02b38bfa-95f2-44a4-808d-290893446e67', 'PRE.05', 2, 'numeric', 'Write and solve an inequality for a word problem', 'Tom scored 76 and 82 on his first two tests. He wants an average of at least 80 over three tests. What is the lowest score he can get on the third test?', '[]', '82', '3*80-76-82', 'The three scores must add to at least $3\times80=240$. So $76+82+x\ge240$, which gives $158+x\ge240$ and $x\ge82$.', 'checked', '{"lint":[],"solve":{"answer":"82","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(76 + 82 + t)/3 >= 80, t >= 240 - 158 = 82.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e4d7e41-6daf-4fa1-813b-3983506710a8', 'PRE.05', 3, 'numeric', 'Solve a one- or two-step equation', 'If $\frac{x}{5}-2=3$, what is the value of $x+10$?', '[]', '35', '(3+2)*5+10', 'Add 2 to both sides: $\frac{x}{5}=5$, so $x=25$. Then $x+10=35$.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x/5 = 5, x = 25, x+10 = 35.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e190727-24eb-479b-a533-f8b9d7a79974', 'PRE.05', 3, 'numeric', 'Write and solve an inequality for a word problem', 'A rectangle has a width of $w$ cm and a length that is 4 cm more than its width. Its perimeter must be less than 50 cm. What is the greatest whole number of centimeters the width can be?', '[]', '10', '10', 'The perimeter is $2(w+w+4)=4w+8$. We need $4w+8<50$, so $4w<42$ and $w<10.5$. The greatest whole number is 10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(w + w + 4) < 50, 4w + 8 < 50, w < 10.5, so 10.","run_id":"claude-code","at":"2026-10-19T01:39:03.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0098348d-3411-46d5-81eb-23dd0037fccb', 'PRE.06', 1, 'choice', 'Multiply decimals', 'What is $0.2\times0.3$?', '["$0.6$","$0.006$","$0.5$","$0.06$"]', '$0.06$', '0.2*0.3', '$2\times3=6$. There are two decimal places in all (one in each number), so the answer is $0.06$.', 'checked', '{"lint":[],"solve":{"answer":"$0.06$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2*3 = 6, two decimal places: 0.06.","run_id":"claude-code","at":"2026-10-19T01:39:03.825Z"}}', 'ai', NULL, NULL)
