VALUES ('17ada69c-cb62-4586-9b61-c1e364744b65', 'PRE.06', 3, 'numeric', 'Solve word problems with decimals', 'Mia has 15 dollars. She buys 4 notebooks at 2.95 dollars each, and then spends all the rest of her money on stickers that cost 0.40 dollars each. How many stickers does she buy?', '[]', '8', '(15-4*2.95)/0.4', 'The notebooks cost $4\times2.95=11.80$ dollars. That leaves $15-11.80=3.20$ dollars. $3.20\div0.40=8$ stickers.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4*2.95 = 11.80; 15 - 11.80 = 3.20; 3.20/0.40 = 8.","run_id":"claude-code","at":"2026-10-19T01:39:03.825Z"}}', 'ai', NULL, NULL)
