VALUES ('13e90443-7d63-407e-a814-9530a36cb266', 'PRE.07', 2, 'numeric', 'Speed, distance and time', 'A bus drives at 40 miles per hour for 1.5 hours and then at 60 miles per hour for 2 hours. How many miles does it drive in all?', '[]', '180', '40*1.5+60*2', 'First part: $40\times 1.5=60$ miles. Second part: $60\times 2=120$ miles. Total: $60+120=180$ miles.', 'checked', '{"lint":[],"solve":{"answer":"180","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40*1.5+60*2=60+120=180","run_id":"claude-code","at":"2026-10-19T01:39:00.614Z"}}', 'ai', NULL, NULL)
