VALUES ('57a18c78-1de5-4668-a97b-975ba03f1084', 'PRE.09', 2, 'choice', 'Simplifying square roots', 'Which of these is equal to $2\sqrt{15}$?', '["$\\sqrt{30}$","$\\sqrt{17}$","$\\sqrt{225}$","$\\sqrt{60}$"]', '$\sqrt{60}$', NULL, '$2\sqrt{15}=\sqrt{4\times 15}=\sqrt{60}$. The others come from 2×15, 2+15 and 15 squared.', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt{60}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2sqrt15=sqrt(4*15)=sqrt60.","run_id":"claude-code","at":"2026-10-19T01:39:11.399Z"}}', 'ai', NULL, NULL)
