VALUES ('1a6deb50-a913-4b4a-8994-91ebc02af1d0', 'PRE.09', 3, 'choice', 'Simplifying square roots', 'Sam wants to simplify $\sqrt{600}$. Which answer is correct and fully simplified?', '["$100\\sqrt{6}$","$6\\sqrt{10}$","$10\\sqrt{7}$","$10\\sqrt{6}$"]', '$10\sqrt{6}$', NULL, 'Find the biggest perfect square that divides 600: 600 = 100 × 6. Then $\sqrt{600}=\sqrt{100}\times\sqrt{6}=10\sqrt{6}$.', 'checked', '{"lint":[],"solve":{"answer":"$10\\sqrt{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"600=100*6 -> 10sqrt6.","run_id":"claude-code","at":"2026-10-19T01:39:11.399Z"}}', 'ai', NULL, NULL)
