VALUES ('2fb5f717-ab5d-4bfd-b045-35a6d96e16ee', 'PRE.10', 1, 'choice', 'Supplementary angles and angles on a line', 'Which two angles are supplementary?', '["$70^\\circ$ and $20^\\circ$","$70^\\circ$ and $110^\\circ$","$70^\\circ$ and $70^\\circ$","$70^\\circ$ and $290^\\circ$"]', '$70^\circ$ and $110^\circ$', NULL, 'Supplementary angles add to 180. $70+110=180$. The others add to 90, 140 and 360.', 'checked', '{"lint":[],"solve":{"answer":"$70^\\circ$ and $110^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"70+110=180.","run_id":"claude-code","at":"2026-10-19T01:39:11.436Z"}}', 'ai', NULL, NULL)
