VALUES ('2f271aff-7e40-4a78-ae29-af64026bc47c', 'PRE.11', 1, 'choice', 'Circumference and area of a circle', 'A circle has a radius of 5 centimeters. What is its area, in square centimeters?', '["$25\\pi$","$10\\pi$","$5\\pi$","$100\\pi$"]', '$25\pi$', NULL, 'Area $=\pi r^2=\pi\times 5^2=25\pi$. ($10\pi$ is the circumference.)', 'checked', '{"lint":[],"solve":{"answer":"$25\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"pi*25 = 25pi.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
