INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09628908-aada-4177-a9e3-86729d2f8897', 'PRE.11', 3, 'choice', 'Perimeter and area of a square', 'Each side of a square is made 3 times as long. The area of the new square is how many times the area of the old square?', '["9","3","6","12"]', '9', '3*3', 'If the old side is $s$, the new side is $3s$ and the new area is $(3s)^2=9s^2$. The area is 9 times as large.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scale 3, area scale 9.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
