INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b4aaa31-643f-407f-a2d2-c8555357fc7e', 'PRE.11', 3, 'numeric', 'Comparing perimeter and area', 'A rectangle has an area of 60 square centimeters and whole-number sides. What is the least perimeter it can have, in centimeters?', '[]', '32', '2*(6+10)', 'The side pairs are 1 and 60, 2 and 30, 3 and 20, 4 and 15, 5 and 12, 6 and 10. The sums are 61, 32, 23, 19, 17, 16, so the perimeters are 122, 64, 46, 38, 34 and 32. The least is 32.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Closest factor pair 6x10: P = 32.","run_id":"claude-code","at":"2026-10-19T01:40:17.852Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('151ed99f-3c34-4d17-ba41-2b0170612257', 'PRE.12', 1, 'numeric', 'Missing leg of a right triangle', 'The longest side of a right triangle is 15 inches. Another side is 12 inches. How long is the third side, in inches?', '[]', '9', '9', 'The longest side is the hypotenuse. $15^2-12^2=225-144=81$, and $\sqrt{81}=9$ inches.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(225-144) = 9.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
