INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e4f2f11-09d6-4abc-838e-f3830fb25d93', 'PRE.12', 2, 'numeric', 'Angles and properties of quadrilaterals', 'Two angles of a parallelogram that are next to each other are in the ratio 1 : 4. How many degrees is the smaller angle?', '[]', '36', '180/5', 'Next angles add to 180 degrees. The ratio parts add to 5, so one part is $180\div 5=36$ degrees. The smaller angle is 36 degrees.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 4x = 180, x = 36.","run_id":"claude-code","at":"2026-10-19T01:40:17.891Z"}}', 'ai', NULL, NULL)
