INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10d139fd-76b0-4498-8199-4cb754feeb43', 'PRE.13', 2, 'numeric', 'Mode of a list', 'In the list 3, 7, 7, 4, 4, 9, x the number x is chosen so that the list has just one mode, and that mode is 4. What is x?', '[]', '4', '4', 'Right now 7 and 4 both appear twice. To make 4 the only mode, 4 must appear a third time, so x is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Without x: 7 twice, 4 twice. For 4 to be the only mode, x=4 (then 4 thrice).","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
