INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08f32ff3-4974-4189-b8b3-452050d9b267', 'PRE.13', 3, 'numeric', 'Missing value for a given mean', 'Five numbers have a mean of 20. The largest is 36, and the other four are all equal. What is each of the other four?', '[]', '16', '(20*5-36)/4', 'The total is $5\times20=100$. Without 36, the other four total 64, so each is $64\div4=16$.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 100; 100-36=64; 64/4=16.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0122646b-1ca9-409d-b712-26cffa674c41', 'PRE.13', 3, 'numeric', 'Data given as counts', 'A survey of families found that 3 had 1 child, 4 had 2 children, some had 3 children and 1 had 4 children. The mean number of children per family was 2.25. How many families had 3 children?', '[]', '4', '(2.25*8-3-8-4)/(3-2.25)', 'Let k families have 3 children. Total children: $3+8+3k+4=15+3k$ for $8+k$ families. So $15+3k=2.25(8+k)=18+2.25k$, giving $0.75k=3$ and $k=4$. Check: $27\div12=2.25$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Children 3+8+3k+4=15+3k; families 8+k; 15+3k=2.25(8+k)=18+2.25k; 0.75k=3; k=4.","run_id":"claude-code","at":"2026-10-19T01:41:52.956Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0587b20e-f05d-400b-bf4d-da90be6df11a', 'PRE.14', 1, 'numeric', 'Casework', 'In how many ways can two whole numbers, both bigger than 0, add up to 5, if the order counts (so 1 + 4 and 4 + 1 are different)?', '[]', '4', '4', 'The pairs are 1 + 4, 2 + 3, 3 + 2 and 4 + 1. That is 4 ways.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1+4, 2+3, 3+2, 4+1: 4.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
