INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02da74a6-7e4e-4571-9400-2fed2d5fa16c', 'PRE.14', 1, 'choice', 'Arranging objects in a row', 'Three friends stand in a line for a photo. In how many different orders can they stand?', '["$3$","$9$","$6$","$12$"]', '$6$', '3*2*1', '3 choices for who is first, then 2, then 1: $3\times2\times1=6$.', 'checked', '{"lint":[],"solve":{"answer":"$6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3!=6.","run_id":"claude-code","at":"2026-10-19T01:41:52.993Z"}}', 'ai', NULL, NULL)
