INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04f406ef-f657-49f0-96cb-fa82d87a6b5f', 'PRE.15', 1, 'numeric', 'Make an organized list and count', 'How many different rectangles with whole-number side lengths have an area of 12 square units? A 2 by 6 rectangle is the same as a 6 by 2 rectangle.', '[]', '3', NULL, 'List the pairs of sides that multiply to 12: $1\times12$, $2\times6$, $3\times4$. That is 3 rectangles.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1x12, 2x6, 3x4: 3.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1330d024-2d8b-4eef-b09e-82439e4ff584', 'PRE.15', 2, 'numeric', 'Work backwards', 'I think of a number, multiply it by 3, subtract 7, and then divide by 2. The result is 10. What is my number?', '[]', '9', '((10*2)+7)/3', 'Undo each step in reverse order. Multiply by 2: $10\times2=20$. Add 7: $27$. Divide by 3: $9$. Check: $9\times3=27$, $27-7=20$, $20\div2=10$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10*2 = 20; 20 + 7 = 27; 27/3 = 9. Check (27-7)/2 = 10.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('168f0aad-cd2f-477b-b231-10bc750b30c6', 'PRE.15', 2, 'choice', 'Work backwards', 'From a full water tank, one-third of the water is removed. Then 20 more liters are removed. Now 40 liters remain. How many liters were in the full tank?', '["60","90","80","120"]', '90', '(40+20)*3/2', 'Before the last 20 liters were removed there were $40+20=60$ liters. That is two-thirds of the tank, so one-third is 30 liters and the full tank held $30\times3=90$ liters.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Before removing 20: 40 + 20 = 60, which is 2/3 of the tank; tank = 90. Check 90 - 30 - 20 = 40.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fb5706a-42ca-4e59-9c7b-ac2521bff10f', 'PRE.15', 2, 'numeric', 'Reason logically from clues', 'A farm has only chickens and cows. Together they have 10 heads and 28 legs. How many cows are there?', '[]', '4', '(28-20)/2', 'Try 4 cows and 6 chickens: heads $4+6=10$, legs $4\times4+6\times2=16+12=28$. It fits. (If all 10 were chickens there would be 20 legs; each cow instead of a chicken adds 2 legs, so $8\div2=4$ cows.)', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"All chickens: 20 legs; extra 8 legs, 2 per cow: 4 cows (6 chickens). Check 4*4 + 6*2 = 28.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('088115be-eec9-4931-95ef-578911fa68aa', 'PRE.15', 3, 'choice', 'Work backwards', 'A movie ends at 4:10 pm. The movie itself is 2 hours 25 minutes long, and before it there are 20 minutes of previews. At what time did the previews start?', '["1:45 pm","2:05 pm","1:25 pm","1:05 pm"]', '1:25 pm', NULL, 'The movie started 2 hours 25 minutes before 4:10 pm, which is 1:45 pm. The previews started 20 minutes before that, at 1:25 pm.', 'checked', '{"lint":[],"solve":{"answer":"1:25 pm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 2 h 45 min before 4:10 pm: 4:10 - 2:45 = 1:25 pm.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09213a74-9836-4641-95bd-a286b9e8229c', 'PRE.15', 3, 'choice', 'Find and extend a pattern', 'Notice that $1=1$, $1+3=4$, $1+3+5=9$, and $1+3+5+7=16$. Use the pattern to find the sum of all the odd numbers from 1 to 39: $1+3+5+\cdots+39$.', '["380","400","780","200"]', '400', '20*20', 'The sum of the first $n$ odd numbers is $n\times n$. The odd numbers from 1 to 39 are 20 numbers, so the sum is $20\times20=400$.', 'checked', '{"lint":[],"solve":{"answer":"400","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum of first n odd numbers is n^2; 1..39 has 20 odd numbers; 400.","run_id":"claude-code","at":"2026-10-19T07:04:01.134Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
